// wordform-data.js — Word-formation bank for the "Word form" tab.
// 600 questions: 500 multiple-choice (type:'mcq') + 100 typed (type:'text').
// Practice shuffles across all of them, so a student meets both formats.
// mcq: { id, type:'mcq', cat, base, q, options[4], correct, answer, vi, explanation }
