const WORDFORM_QUESTIONS = [
  {"type":"mcq","id":"wf-1","cat":"noun","base":"EDUCATE","q":"___ (EDUCATE) plays a very important role in preparing young people for their future careers.","options":["educate","educational","educationally","education"],"correct":3,"answer":"education","vi":"EDUCATE (giáo dục - động từ) → education — nền giáo dục (danh từ)","explanation":"Đứng đầu câu, làm CHỦ NGỮ trước động từ 'plays', cần một DANH TỪ. Động từ 'educate' → danh từ 'education' (thêm -ion). ✗ educate = động từ; ✗ educational = tính từ; ✗ educationally = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-2","cat":"noun","base":"EXPLAIN","q":"The teacher's clear ___ (EXPLAIN) helped the whole class understand the new grammar point.","options":["explanation","explain","explanatory","unexplained"],"correct":0,"answer":"explanation","vi":"EXPLAIN (giải thích - động từ) → explanation — lời giải thích (danh từ)","explanation":"Sau tính từ 'clear' và trước động từ 'helped', chỗ trống là CHỦ NGỮ nên cần một DANH TỪ. Động từ 'explain' → danh từ 'explanation' (thêm -ation). ✗ explain = động từ; ✗ explanatory = tính từ; ✗ unexplained = tính từ (tiền tố un-) — đều sai vị trí."},
  {"type":"mcq","id":"wf-3","cat":"noun","base":"RESPONSIBLE","q":"Completing homework on time is a basic ___ (RESPONSIBLE) of every student.","options":["responsible","responsibility","responsibly","irresponsible"],"correct":1,"answer":"responsibility","vi":"RESPONSIBLE (có trách nhiệm - tính từ) → responsibility — trách nhiệm (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'basic', trước giới từ 'of', cần một DANH TỪ. Tính từ 'responsible' → danh từ 'responsibility' (đổi -ible thành -ibility). ✗ responsible = tính từ; ✗ responsibly = trạng từ; ✗ irresponsible = tính từ phủ định — đều sai vị trí."},
  {"type":"mcq","id":"wf-4","cat":"noun","base":"ACHIEVE","q":"Passing the national exam with a high score was a remarkable ___ (ACHIEVE) for the whole class.","options":["achieve","achievable","achievement","unachievable"],"correct":2,"answer":"achievement","vi":"ACHIEVE (đạt được - động từ) → achievement — thành tích, thành tựu (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'remarkable', cần một DANH TỪ. Động từ 'achieve' → danh từ 'achievement' (thêm -ment). ✗ achieve = động từ; ✗ achievable = tính từ; ✗ unachievable = tính từ phủ định — đều sai vị trí."},
  {"type":"mcq","id":"wf-5","cat":"noun","base":"IMPORTANT","q":"Teachers often talk about the ___ (IMPORTANT) of reading books every day.","options":["important","importantly","unimportant","importance"],"correct":3,"answer":"importance","vi":"IMPORTANT (quan trọng - tính từ) → importance — tầm quan trọng (danh từ)","explanation":"Sau mạo từ 'the' và trước giới từ 'of', cần một DANH TỪ. Tính từ 'important' → danh từ 'importance' (đổi -ant thành -ance). ✗ important = tính từ; ✗ importantly = trạng từ; ✗ unimportant = tính từ phủ định — đều sai vị trí."},
  {"type":"mcq","id":"wf-6","cat":"noun","base":"CREATIVE","q":"Art and music lessons help students develop their ___ (CREATIVE) instead of just memorizing facts.","options":["creativity","create","creative","creatively"],"correct":0,"answer":"creativity","vi":"CREATIVE (sáng tạo - tính từ) → creativity — sự sáng tạo (danh từ)","explanation":"Sau tính từ sở hữu 'their', cần một DANH TỪ làm tân ngữ của 'develop'. Tính từ 'creative' → danh từ 'creativity' (đổi -ive thành -ivity). ✗ create = động từ; ✗ creative = tính từ (chính là từ gốc); ✗ creatively = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-7","cat":"adj","base":"KNOWLEDGE","q":"Our history teacher is very ___ (KNOWLEDGE) and can answer almost any question in class.","options":["know","knowledgeable","knowledge","knowledgeably"],"correct":1,"answer":"knowledgeable","vi":"KNOWLEDGE (kiến thức - danh từ) → knowledgeable — am hiểu, hiểu biết rộng (tính từ)","explanation":"Sau trạng từ 'very' và động từ 'to be' (is), cần một TÍNH TỪ. Danh từ 'knowledge' → tính từ 'knowledgeable' (thêm -able). ✗ know = động từ; ✗ knowledge = danh từ (từ gốc); ✗ knowledgeably = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-8","cat":"adj","base":"VALUE","q":"Field trips can be a ___ (VALUE) learning experience for students outside the classroom.","options":["value","valuation","valuable","devalue"],"correct":2,"answer":"valuable","vi":"VALUE (giá trị - danh từ) → valuable — có giá trị, quý giá (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'learning experience', cần một TÍNH TỪ bổ nghĩa. Danh từ 'value' → tính từ 'valuable' (thêm -able). ✗ value = danh từ/động từ (từ gốc); ✗ valuation = danh từ; ✗ devalue = động từ (tiền tố de-) — đều sai vị trí."},
  {"type":"mcq","id":"wf-9","cat":"adj","base":"USE","q":"The school library has a lot of ___ (USE) materials for students preparing for exams.","options":["use","usage","usefully","useful"],"correct":3,"answer":"useful","vi":"USE (sự sử dụng - danh từ) → useful — hữu ích (tính từ)","explanation":"Trước danh từ 'materials', cần một TÍNH TỪ bổ nghĩa. Danh từ 'use' → tính từ 'useful' (thêm -ful). ✗ use = danh từ/động từ (từ gốc); ✗ usage = danh từ; ✗ usefully = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-10","cat":"adj","base":"HELP","q":"Our English teacher is always ___ (HELP) whenever we have difficulty with pronunciation.","options":["help","helpful","helper","helpfully"],"correct":1,"answer":"helpful","vi":"HELP (sự giúp đỡ - danh/động từ) → helpful — hay giúp đỡ, hữu ích (tính từ)","explanation":"Sau động từ 'to be' (is) và trạng từ 'always', cần một TÍNH TỪ. Danh từ/động từ 'help' → tính từ 'helpful' (thêm -ful). ✗ help = danh từ/động từ (từ gốc); ✗ helper = danh từ chỉ người; ✗ helpfully = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-11","cat":"adj","base":"COMPETE","q":"Getting into this famous high school is extremely ___ (COMPETE) because so many students apply.","options":["compete","competition","competitive","competitively"],"correct":2,"answer":"competitive","vi":"COMPETE (cạnh tranh - động từ) → competitive — mang tính cạnh tranh (tính từ)","explanation":"Sau trạng từ 'extremely' và động từ 'to be' (is), cần một TÍNH TỪ. Động từ 'compete' → tính từ 'competitive' (thêm -itive). ✗ compete = động từ (từ gốc); ✗ competition = danh từ; ✗ competitively = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-12","cat":"adj","base":"UNDERSTAND","q":"The teacher's explanation was so ___ (UNDERSTAND) that even the weakest students could follow it.","options":["understand","understanding","understandably","understandable"],"correct":3,"answer":"understandable","vi":"UNDERSTAND (hiểu - động từ) → understandable — dễ hiểu (tính từ)","explanation":"Sau 'so' và động từ 'to be' (was), cần một TÍNH TỪ (cấu trúc so + adj + that). Động từ 'understand' → tính từ 'understandable' (thêm -able). ✗ understand = động từ (từ gốc); ✗ understanding = danh từ; ✗ understandably = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-13","cat":"adv","base":"ENCOURAGE","q":"The teacher smiled ___ (ENCOURAGE) at the shy student before she started her presentation.","options":["encouragingly","encourage","encouragement","encouraging"],"correct":0,"answer":"encouragingly","vi":"ENCOURAGE (khuyến khích - động từ) → encouragingly — một cách khích lệ (trạng từ)","explanation":"Bổ nghĩa cho động từ 'smiled', cần một TRẠNG TỪ. Động từ 'encourage' → tính từ 'encouraging' → trạng từ 'encouragingly' (thêm -ly). ✗ encourage = động từ (từ gốc); ✗ encouragement = danh từ; ✗ encouraging = tính từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-14","cat":"adv","base":"ATTEND","q":"Good students always listen ___ (ATTEND) when the teacher explains a new lesson.","options":["attend","attentively","attendance","attentive"],"correct":1,"answer":"attentively","vi":"ATTEND (chú ý, tham dự - động từ) → attentively — một cách chăm chú (trạng từ)","explanation":"Bổ nghĩa cho động từ 'listen', cần một TRẠNG TỪ. Động từ 'attend' → tính từ 'attentive' → trạng từ 'attentively' (thêm -ly). ✗ attend = động từ (từ gốc); ✗ attendance = danh từ; ✗ attentive = tính từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-15","cat":"adv","base":"ACCURATE","q":"Students should try to answer every question ___ (ACCURATE) during the final examination.","options":["accurate","accuracy","accurately","inaccurate"],"correct":2,"answer":"accurately","vi":"ACCURATE (chính xác - tính từ) → accurately — một cách chính xác (trạng từ)","explanation":"Bổ nghĩa cho động từ 'answer', cần một TRẠNG TỪ. Tính từ 'accurate' → trạng từ 'accurately' (thêm -ly). ✗ accurate = tính từ (từ gốc); ✗ accuracy = danh từ; ✗ inaccurate = tính từ phủ định — đều sai vị trí."},
  {"type":"mcq","id":"wf-16","cat":"adv","base":"PATIENT","q":"The teacher waited ___ (PATIENT) for the nervous student to finish his answer.","options":["patient","patience","impatient","patiently"],"correct":3,"answer":"patiently","vi":"PATIENT (kiên nhẫn - tính từ) → patiently — một cách kiên nhẫn (trạng từ)","explanation":"Bổ nghĩa cho động từ 'waited', cần một TRẠNG TỪ. Tính từ 'patient' → trạng từ 'patiently' (thêm -ly). ✗ patient = tính từ (từ gốc); ✗ patience = danh từ; ✗ impatient = tính từ phủ định — đều sai vị trí."},
  {"type":"mcq","id":"wf-17","cat":"adv","base":"CARE","q":"You should read the exam instructions ___ (CARE) before you start writing your answers.","options":["carefully","care","careful","careless"],"correct":0,"answer":"carefully","vi":"CARE (sự cẩn thận - danh/động từ) → carefully — một cách cẩn thận (trạng từ)","explanation":"Bổ nghĩa cho động từ 'read', cần một TRẠNG TỪ. Danh từ/động từ 'care' → tính từ 'careful' → trạng từ 'carefully' (thêm -ly). ✗ care = danh từ/động từ (từ gốc); ✗ careful = tính từ; ✗ careless = tính từ phủ định — đều sai vị trí."},
  {"type":"mcq","id":"wf-18","cat":"adv","base":"SUCCESS","q":"She studied hard every day and ___ (SUCCESS) passed the entrance exam to her dream high school.","options":["success","successfully","successful","succeed"],"correct":1,"answer":"successfully","vi":"SUCCESS (thành công - danh từ) → successfully — một cách thành công (trạng từ)","explanation":"Bổ nghĩa cho động từ 'passed', cần một TRẠNG TỪ. Danh từ 'success' → tính từ 'successful' → trạng từ 'successfully' (thêm -ly). ✗ success = danh từ (từ gốc); ✗ successful = tính từ; ✗ succeed = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-19","cat":"verb","base":"ABLE","q":"A good education can ___ (ABLE) students to achieve their dreams in the future.","options":["able","ability","enable","ably"],"correct":2,"answer":"enable","vi":"ABLE (có thể - tính từ) → enable — giúp cho có thể làm được (động từ)","explanation":"Sau chủ ngữ 'education' và trợ động từ khiếm khuyết 'can', cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'able' → động từ 'enable' (thêm tiền tố en-). ✗ able = tính từ (từ gốc); ✗ ability = danh từ; ✗ ably = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-20","cat":"verb","base":"MEMORY","q":"It is important to ___ (MEMORY) new vocabulary every day if you want to improve your English.","options":["memorize","memory","memorable","memorably"],"correct":0,"answer":"memorize","vi":"MEMORY (trí nhớ - danh từ) → memorize — ghi nhớ, học thuộc lòng (động từ)","explanation":"Sau 'to', cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'memory' → động từ 'memorize' (thêm -ize). ✗ memory = danh từ (từ gốc); ✗ memorable = tính từ; ✗ memorably = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-21","cat":"verb","base":"EXAMINATION","q":"The school will ___ (EXAMINATION) all students' speaking skills at the end of the course.","options":["examination","examine","examiner","unexamined"],"correct":1,"answer":"examine","vi":"EXAMINATION (kỳ thi, sự kiểm tra - danh từ) → examine — kiểm tra, khảo sát (động từ)","explanation":"Sau trợ động từ 'will', cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'examination' → động từ 'examine' (bỏ hậu tố -ation). ✗ examination = danh từ (từ gốc); ✗ examiner = danh từ chỉ người; ✗ unexamined = tính từ (tiền tố phủ định un-) — đều sai vị trí."},
  {"type":"mcq","id":"wf-22","cat":"verb","base":"PARTICIPANT","q":"All students are encouraged to ___ (PARTICIPANT) actively in extracurricular activities at school.","options":["participant","participation","participate","participatory"],"correct":2,"answer":"participate","vi":"PARTICIPANT (người tham gia - danh từ) → participate — tham gia (động từ)","explanation":"Sau 'to', cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'participant' → động từ 'participate' (đổi -ant thành -ate). ✗ participant = danh từ (từ gốc, chỉ người); ✗ participation = danh từ (chỉ sự việc); ✗ participatory = tính từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-23","cat":"verb","base":"WIDE","q":"Reading English newspapers can help students ___ (WIDE) their knowledge of the world.","options":["wide","width","widely","widen"],"correct":3,"answer":"widen","vi":"WIDE (rộng - tính từ) → widen — mở rộng (động từ)","explanation":"Sau cấu trúc 'help + tân ngữ (students)', cần một ĐỘNG TỪ nguyên mẫu không 'to'. Tính từ 'wide' → động từ 'widen' (thêm -en). ✗ wide = tính từ (từ gốc); ✗ width = danh từ; ✗ widely = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-24","cat":"verb","base":"SIMPLE","q":"Good teachers know how to ___ (SIMPLE) difficult grammar rules so that students can understand them easily.","options":["simplify","simple","simplicity","simply"],"correct":0,"answer":"simplify","vi":"SIMPLE (đơn giản - tính từ) → simplify — đơn giản hóa (động từ)","explanation":"Sau 'to', cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'simple' → động từ 'simplify' (thêm -ify). ✗ simple = tính từ (từ gốc); ✗ simplicity = danh từ; ✗ simply = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-25","cat":"verb","base":"HEALTH","q":"This special ointment can ___ (HEALTH) cuts and small wounds within a few days.","options":["health","heal","healthy","healthily"],"correct":1,"answer":"heal","vi":"HEALTH (sức khỏe) → heal — chữa lành (động từ)","explanation":"Sau động từ khiếm khuyết 'can' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'health' (sức khỏe) → động từ 'heal' (chữa lành). ✗ health = danh từ; ✗ healthy = tính từ; ✗ healthily = trạng từ — đều sai vị trí vì sau 'can' phải là một động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-26","cat":"adv","base":"MEDICINE","q":"The patient was ___ (MEDICINE) examined before the operation began.","options":["medicine","medical","medically","medicate"],"correct":2,"answer":"medically","vi":"MEDICINE (y học/thuốc) → medically — về mặt y khoa (trạng từ)","explanation":"Trạng từ 'medically' bổ nghĩa cho phân từ 'examined' (được khám), diễn tả cách thức khám bệnh, nên cần một TRẠNG TỪ. Danh từ 'medicine' → trạng từ 'medically' (thêm -ally). ✗ medicine = danh từ; ✗ medical = tính từ; ✗ medicate = động từ — đều sai vị trí vì cần trạng từ đứng trước phân từ 'examined'."},
  {"type":"mcq","id":"wf-27","cat":"adv","base":"NUTRITION","q":"Doctors recommend that children eat a ___ (NUTRITION) balanced diet every day.","options":["nutrition","nutritious","nutritional","nutritionally"],"correct":3,"answer":"nutritionally","vi":"NUTRITION (dinh dưỡng) → nutritionally — về mặt dinh dưỡng (trạng từ)","explanation":"Trước tính từ 'balanced' cần một TRẠNG TỪ để bổ nghĩa cho tính từ đó. Danh từ 'nutrition' → trạng từ 'nutritionally' (thêm -ally). ✗ nutrition = danh từ; ✗ nutritious = tính từ; ✗ nutritional = tính từ — đều sai vì vị trí trước tính từ 'balanced' chỉ có thể là trạng từ."},
  {"type":"mcq","id":"wf-28","cat":"noun","base":"STRONG","q":"Regular exercise and a healthy diet can improve your physical ___ (STRONG) over time.","options":["strength","strong","strongly","strengthen"],"correct":0,"answer":"strength","vi":"STRONG (mạnh) → strength — sức mạnh (danh từ)","explanation":"Sau tính từ 'physical' cần một DANH TỪ làm tân ngữ cho động từ 'improve'. Tính từ 'strong' → danh từ 'strength' (dạng bất quy tắc). ✗ strong = tính từ; ✗ strongly = trạng từ; ✗ strengthen = động từ — đều sai vị trí vì sau tính từ 'physical' cần một danh từ."},
  {"type":"mcq","id":"wf-29","cat":"verb","base":"WEAK","q":"Prolonged illness can gradually ___ (WEAK) the body's immune system.","options":["weak","weaken","weakness","weakly"],"correct":1,"answer":"weaken","vi":"WEAK (yếu) → weaken — làm suy yếu (động từ)","explanation":"Sau động từ khiếm khuyết 'can' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'weak' → động từ 'weaken' (thêm -en). ✗ weak = tính từ; ✗ weakness = danh từ; ✗ weakly = trạng từ — đều sai vị trí vì sau 'can' phải là động từ."},
  {"type":"mcq","id":"wf-30","cat":"adj","base":"ENERGY","q":"After a full night's sleep, she felt ___ (ENERGY) and ready to start the day.","options":["energy","energetically","energize","energetic"],"correct":3,"answer":"energetic","vi":"ENERGY (năng lượng) → energetic — tràn đầy năng lượng (tính từ)","explanation":"Sau động từ liên kết 'felt' cần một TÍNH TỪ bổ nghĩa cho chủ ngữ 'she'. Danh từ 'energy' → tính từ 'energetic' (thêm -etic). ✗ energy = danh từ; ✗ energetically = trạng từ; ✗ energize = động từ — đều sai vị trí vì sau động từ liên kết 'felt' cần tính từ."},
  {"type":"mcq","id":"wf-31","cat":"verb","base":"INFECTION","q":"Touching an open wound with dirty hands may ___ (INFECTION) it with bacteria.","options":["infect","infection","infectious","infectiously"],"correct":0,"answer":"infect","vi":"INFECTION (sự nhiễm trùng) → infect — làm nhiễm trùng (động từ)","explanation":"Sau động từ khiếm khuyết 'may' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'infection' → động từ 'infect' (bỏ hậu tố -ion). ✗ infection = danh từ; ✗ infectious = tính từ; ✗ infectiously = trạng từ — đều sai vị trí vì sau 'may' phải là động từ."},
  {"type":"mcq","id":"wf-32","cat":"adv","base":"PROTECT","q":"The nurse held the newborn baby ___ (PROTECT) against her chest.","options":["protect","protectively","protection","protective"],"correct":1,"answer":"protectively","vi":"PROTECT (bảo vệ) → protectively — một cách che chở (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'held' (cách thức ôm giữ đứa bé), nên cần một TRẠNG TỪ. Động từ 'protect' → trạng từ 'protectively' (thêm -ively). ✗ protect = động từ; ✗ protection = danh từ; ✗ protective = tính từ — đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ 'held'."},
  {"type":"mcq","id":"wf-33","cat":"noun","base":"PREVENT","q":"Doctors always emphasize that ___ (PREVENT) is better than treatment for serious diseases.","options":["prevent","preventive","prevention","preventively"],"correct":2,"answer":"prevention","vi":"PREVENT (phòng ngừa) → prevention — sự phòng ngừa (danh từ)","explanation":"Đứng làm chủ ngữ của mệnh đề (trước động từ 'is') cần một DANH TỪ. Động từ 'prevent' → danh từ 'prevention' (thêm -ion). ✗ prevent = động từ; ✗ preventive = tính từ; ✗ preventively = trạng từ — đều sai vị trí vì chủ ngữ của câu phải là danh từ."},
  {"type":"mcq","id":"wf-34","cat":"verb","base":"RECOVERY","q":"It may take several weeks for the patient to fully ___ (RECOVERY) after the surgery.","options":["recovery","recoverable","irrecoverably","recover"],"correct":3,"answer":"recover","vi":"RECOVERY (sự hồi phục) → recover — hồi phục (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu (to-infinitive). Danh từ 'recovery' → động từ 'recover'. ✗ recovery = danh từ; ✗ recoverable = tính từ; ✗ irrecoverably = trạng từ — đều sai vị trí vì sau 'to' phải là động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-35","cat":"noun","base":"DIAGNOSE","q":"The doctor's ___ (DIAGNOSE) showed that the patient had only a mild infection.","options":["diagnosis","diagnose","diagnostic","diagnostically"],"correct":0,"answer":"diagnosis","vi":"DIAGNOSE (chẩn đoán) → diagnosis — sự chẩn đoán (danh từ)","explanation":"Sau sở hữu cách 'the doctor's' cần một DANH TỪ làm chủ ngữ của câu. Động từ 'diagnose' → danh từ 'diagnosis' (đổi đuôi). ✗ diagnose = động từ; ✗ diagnostic = tính từ; ✗ diagnostically = trạng từ — đều sai vị trí vì sau sở hữu cách cần danh từ."},
  {"type":"mcq","id":"wf-36","cat":"verb","base":"OPERATION","q":"Surgeons must ___ (OPERATION) immediately if they want to save the patient's life.","options":["operation","operate","operational","operationally"],"correct":1,"answer":"operate","vi":"OPERATION (ca phẫu thuật) → operate — phẫu thuật/vận hành (động từ)","explanation":"Sau động từ khiếm khuyết 'must' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'operation' → động từ 'operate' (bỏ hậu tố -ion). ✗ operation = danh từ; ✗ operational = tính từ; ✗ operationally = trạng từ — đều sai vị trí vì sau 'must' phải là động từ."},
  {"type":"mcq","id":"wf-37","cat":"adj","base":"VACCINATE","q":"All students must be fully ___ (VACCINATE) before the new school term starts.","options":["vaccinate","vaccination","vaccinated","vaccine"],"correct":2,"answer":"vaccinated","vi":"VACCINATE (tiêm chủng) → vaccinated — đã được tiêm chủng (tính từ)","explanation":"Sau động từ 'be' trong cấu trúc bị động 'be fully ___' cần một TÍNH TỪ/phân từ chỉ trạng thái. Động từ 'vaccinate' → tính từ 'vaccinated' (thêm -ed). ✗ vaccinate = động từ nguyên mẫu; ✗ vaccination = danh từ; ✗ vaccine = danh từ — đều sai vị trí vì sau 'be' cần một tính từ chỉ trạng thái."},
  {"type":"mcq","id":"wf-38","cat":"adj","base":"ADDICTION","q":"Doctors warn that some painkillers can be highly ___ (ADDICTION) if used for too long.","options":["addiction","addictively","addict","addictive"],"correct":3,"answer":"addictive","vi":"ADDICTION (sự nghiện) → addictive — gây nghiện (tính từ)","explanation":"Sau trạng từ 'highly' và động từ 'be' cần một TÍNH TỪ. Danh từ 'addiction' → tính từ 'addictive' (thêm -ive). ✗ addiction = danh từ; ✗ addictively = trạng từ; ✗ addict = động từ — đều sai vị trí vì sau 'highly' + 'be' cần tính từ."},
  {"type":"mcq","id":"wf-39","cat":"adv","base":"PAIN","q":"The injured player fell to the ground and cried out ___ (PAIN) as the coach rushed over.","options":["painfully","pain","painful","painless"],"correct":0,"answer":"painfully","vi":"PAIN (nỗi đau) → painfully — một cách đau đớn (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'cried out' (cách thức kêu lên), nên cần một TRẠNG TỪ. Danh từ 'pain' → trạng từ 'painfully' (thêm -fully). ✗ pain = danh từ; ✗ painful = tính từ; ✗ painless = tính từ — đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ 'cried out'."},
  {"type":"mcq","id":"wf-40","cat":"adv","base":"COMFORT","q":"Make sure the patient is sitting ___ (COMFORT) before the injection begins.","options":["comfort","comfortable","comfortably","discomfort"],"correct":2,"answer":"comfortably","vi":"COMFORT (sự thoải mái) → comfortably — một cách thoải mái (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'sitting' (tư thế ngồi), nên cần một TRẠNG TỪ. Danh từ 'comfort' → trạng từ 'comfortably' (thêm -ably). ✗ comfort = danh từ; ✗ comfortable = tính từ; ✗ discomfort = danh từ — đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ 'sitting'."},
  {"type":"mcq","id":"wf-41","cat":"verb","base":"DANGER","q":"Smoking and heavy drinking can seriously ___ (DANGER) your long-term health.","options":["danger","dangerous","dangerously","endanger"],"correct":3,"answer":"endanger","vi":"DANGER (sự nguy hiểm) → endanger — gây nguy hiểm cho (động từ)","explanation":"Sau động từ khiếm khuyết 'can' (và trạng từ 'seriously') cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'danger' → động từ 'endanger' (thêm tiền tố en-). ✗ danger = danh từ; ✗ dangerous = tính từ; ✗ dangerously = trạng từ — đều sai vị trí vì sau 'can' phải là động từ."},
  {"type":"mcq","id":"wf-42","cat":"noun","base":"BREATHE","q":"The doctor asked the patient to take a deep ___ (BREATHE) before the X-ray.","options":["breath","breathe","breathless","breathlessly"],"correct":0,"answer":"breath","vi":"BREATHE (thở) → breath — hơi thở (danh từ)","explanation":"Sau tính từ 'deep' cần một DANH TỪ làm tân ngữ của 'take'. Động từ 'breathe' → danh từ 'breath' (bỏ chữ 'e' cuối). ✗ breathe = động từ; ✗ breathless = tính từ; ✗ breathlessly = trạng từ — đều sai vị trí vì sau tính từ 'deep' cần danh từ."},
  {"type":"mcq","id":"wf-43","cat":"adv","base":"TIRE","q":"After the long night shift, the nurse said ___ (TIRE), 'I just want to go home and sleep.'","options":["tire","tiredly","tired","tiredness"],"correct":1,"answer":"tiredly","vi":"TIRE (làm mệt mỏi) → tiredly — một cách mệt mỏi (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'said' (cách thức nói), nên cần một TRẠNG TỪ. Động từ 'tire' → trạng từ 'tiredly' (qua dạng 'tired' + -ly). ✗ tire = động từ; ✗ tired = tính từ; ✗ tiredness = danh từ — đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ 'said'."},
  {"type":"mcq","id":"wf-44","cat":"adj","base":"DIGEST","q":"Eating too much fatty food can upset your ___ (DIGEST) system.","options":["digest","digestion","digestive","digestively"],"correct":2,"answer":"digestive","vi":"DIGEST (tiêu hóa) → digestive — thuộc về tiêu hóa (tính từ)","explanation":"Trước danh từ 'system' cần một TÍNH TỪ bổ nghĩa. Động từ 'digest' → tính từ 'digestive' (thêm -ive). ✗ digest = động từ; ✗ digestion = danh từ; ✗ digestively = trạng từ — đều sai vị trí vì trước danh từ 'system' cần tính từ."},
  {"type":"mcq","id":"wf-45","cat":"noun","base":"INJURE","q":"The football player suffered a serious ___ (INJURE) to his left knee during the match.","options":["injure","injured","injuriously","injury"],"correct":3,"answer":"injury","vi":"INJURE (làm bị thương) → injury — chấn thương (danh từ)","explanation":"Sau tính từ 'serious' cần một DANH TỪ làm tân ngữ của 'suffered'. Động từ 'injure' → danh từ 'injury' (đổi -e thành -y). ✗ injure = động từ; ✗ injured = tính từ; ✗ injuriously = trạng từ — đều sai vị trí vì sau tính từ 'serious' cần danh từ."},
  {"type":"mcq","id":"wf-46","cat":"adj","base":"ALLERGY","q":"My little brother is ___ (ALLERGY) to peanuts, so he must avoid them completely.","options":["allergic","allergy","allergically","allergen"],"correct":0,"answer":"allergic","vi":"ALLERGY (dị ứng) → allergic — bị dị ứng (tính từ)","explanation":"Sau động từ liên kết 'is' cần một TÍNH TỪ bổ nghĩa cho chủ ngữ. Danh từ 'allergy' → tính từ 'allergic' (thêm -ic). ✗ allergy = danh từ; ✗ allergically = trạng từ; ✗ allergen = danh từ — đều sai vị trí vì sau động từ 'is' cần tính từ."},
  {"type":"mcq","id":"wf-47","cat":"noun","base":"EXHAUST","q":"The doctor said her constant tiredness was simply a sign of ___ (EXHAUST).","options":["exhaust","exhaustion","exhausted","exhaustively"],"correct":1,"answer":"exhaustion","vi":"EXHAUST (làm kiệt sức) → exhaustion — sự kiệt sức (danh từ)","explanation":"Sau giới từ 'of' cần một DANH TỪ. Động từ 'exhaust' → danh từ 'exhaustion' (thêm -ion). ✗ exhaust = động từ; ✗ exhausted = tính từ; ✗ exhaustively = trạng từ — đều sai vị trí vì sau giới từ 'of' cần danh từ."},
  {"type":"mcq","id":"wf-48","cat":"adj","base":"SURGERY","q":"The hospital has just bought a new piece of ___ (SURGERY) equipment for the operating room.","options":["surgery","surgically","surgical","surgeon"],"correct":2,"answer":"surgical","vi":"SURGERY (phẫu thuật) → surgical — thuộc về phẫu thuật (tính từ)","explanation":"Trước danh từ 'equipment' cần một TÍNH TỪ bổ nghĩa. Danh từ 'surgery' → tính từ 'surgical' (thêm -al). ✗ surgery = danh từ; ✗ surgically = trạng từ; ✗ surgeon = danh từ — đều sai vị trí vì trước danh từ 'equipment' cần tính từ."},
  {"type":"mcq","id":"wf-49","cat":"adj","base":"GLOBE","q":"The world is becoming a ___ (GLOBE) village thanks to the Internet and modern transportation.","options":["globe","globally","globalize","global"],"correct":3,"answer":"global","vi":"GLOBE (quả địa cầu) → global – toàn cầu (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'village' cần một TÍNH TỪ. Danh từ 'globe' → tính từ 'global' (thêm -al). ✗ globe = danh từ; ✗ globally = trạng từ; ✗ globalize = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-50","cat":"noun","base":"POLLUTE","q":"Air ___ (POLLUTE) in big cities is getting worse every year.","options":["pollute","pollution","polluted","polluting"],"correct":1,"answer":"pollution","vi":"POLLUTE (làm ô nhiễm) → pollution – sự ô nhiễm (danh từ)","explanation":"Sau danh từ 'Air', cụm này làm chủ ngữ của động từ 'is' nên cần một DANH TỪ. Động từ 'pollute' → danh từ 'pollution' (thêm -ion). ✗ pollute = động từ; ✗ polluted = tính từ (bị ô nhiễm); ✗ polluting = dạng V-ing — đều sai vị trí, không thể làm chủ ngữ chính."},
  {"type":"mcq","id":"wf-51","cat":"adv","base":"DANGER","q":"The level of pollution in this city is rising ___ (DANGER), and something must be done soon.","options":["danger","dangerous","dangerously","endanger"],"correct":2,"answer":"dangerously","vi":"DANGER (sự nguy hiểm) → dangerously – một cách nguy hiểm (trạng từ)","explanation":"Bổ nghĩa cho động từ 'rising' cần một TRẠNG TỪ. Danh từ 'danger' → tính từ 'dangerous' → trạng từ 'dangerously' (thêm -ly). ✗ danger = danh từ; ✗ dangerous = tính từ; ✗ endanger = động từ (gây nguy hiểm cho) — đều sai vị trí, không thể bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-52","cat":"adv","base":"ENVIRONMENT","q":"Riding a bicycle instead of driving a car is a more ___ (ENVIRONMENT) friendly way to travel.","options":["environment","environmental","environmentalist","environmentally"],"correct":3,"answer":"environmentally","vi":"ENVIRONMENT (môi trường) → environmentally – về mặt môi trường (trạng từ, đi với tính từ 'friendly')","explanation":"Đứng trước tính từ 'friendly' cần một TRẠNG TỪ bổ nghĩa (cụm 'environmentally friendly' = thân thiện với môi trường). Danh từ 'environment' → tính từ 'environmental' → trạng từ 'environmentally'. ✗ environment = danh từ; ✗ environmental = tính từ; ✗ environmentalist = danh từ (nhà môi trường học) — đều sai vị trí trước tính từ."},
  {"type":"mcq","id":"wf-53","cat":"adj","base":"POISON","q":"The gases released by this factory are extremely ___ (POISON) and can cause serious health problems for nearby residents.","options":["poisonous","poison","poisonously","poisoning"],"correct":0,"answer":"poisonous","vi":"POISON (chất độc) → poisonous – độc hại (tính từ)","explanation":"Sau trạng từ chỉ mức độ 'extremely' và động từ liên kết 'are', cần một TÍNH TỪ bổ nghĩa cho chủ ngữ 'the gases' (cấu trúc be + extremely + adj). Danh từ 'poison' → tính từ 'poisonous' (thêm -ous). ✗ poison = danh từ/động từ, không đứng sau 'extremely'; ✗ poisonously = trạng từ, không bổ nghĩa được cho chủ ngữ sau 'be'; ✗ poisoning = danh động từ/phân từ hiện tại — đều sai vị trí trong cấu trúc này."},
  {"type":"mcq","id":"wf-54","cat":"adv","base":"WASTE","q":"Many households in the city use electricity very ___ (WASTE), which puts extra pressure on power plants.","options":["waste","wastefully","wasteful","wastage"],"correct":1,"answer":"wastefully","vi":"WASTE (sự lãng phí) → wastefully – một cách lãng phí (trạng từ)","explanation":"Sau 'very' và bổ nghĩa cho động từ 'use' cần một TRẠNG TỪ. Tính từ 'wasteful' → trạng từ 'wastefully' (thêm -ly). ✗ waste = danh từ/động từ; ✗ wasteful = tính từ; ✗ wastage = danh từ (sự hao hụt) — đều sai từ loại."},
  {"type":"mcq","id":"wf-55","cat":"noun","base":"CONSERVE","q":"Wildlife ___ (CONSERVE) is essential to protect endangered animals from extinction.","options":["conserve","conservative","conservation","conservatively"],"correct":2,"answer":"conservation","vi":"CONSERVE (bảo tồn) → conservation – sự bảo tồn (danh từ)","explanation":"Sau danh từ 'Wildlife', cụm này làm chủ ngữ của động từ 'is' nên cần một DANH TỪ. Động từ 'conserve' → danh từ 'conservation' (thêm -ation). ✗ conserve = động từ; ✗ conservative = tính từ (bảo thủ); ✗ conservatively = trạng từ — đều sai từ loại."},
  {"type":"mcq","id":"wf-56","cat":"noun","base":"DESTROY","q":"The ___ (DESTROY) of tropical rainforests is one of the main causes of climate change.","options":["destroy","destructive","destructively","destruction"],"correct":3,"answer":"destruction","vi":"DESTROY (phá hủy) → destruction – sự phá hủy (danh từ)","explanation":"Sau mạo từ 'The' cần một DANH TỪ làm chủ ngữ của câu. Động từ 'destroy' → danh từ 'destruction' (thêm -ion). ✗ destroy = động từ; ✗ destructive = tính từ; ✗ destructively = trạng từ — đều sai vị trí sau mạo từ."},
  {"type":"mcq","id":"wf-57","cat":"noun","base":"PROTECT","q":"Wearing sunscreen gives your skin ___ (PROTECT) from harmful UV rays.","options":["protection","protect","protective","protectively"],"correct":0,"answer":"protection","vi":"PROTECT (bảo vệ) → protection – sự bảo vệ (danh từ)","explanation":"Cấu trúc 'give + tân ngữ gián tiếp (your skin) + tân ngữ trực tiếp' cần một DANH TỪ làm tân ngữ trực tiếp của động từ 'gives'. Động từ 'protect' → danh từ 'protection' (thêm -ion). ✗ protect = động từ; ✗ protective = tính từ; ✗ protectively = trạng từ — đều sai từ loại, không thể làm tân ngữ."},
  {"type":"mcq","id":"wf-58","cat":"noun","base":"SUSTAIN","q":"Companies today must think carefully about the ___ (SUSTAIN) of their production methods.","options":["sustain","sustainability","unsustainable","sustainably"],"correct":1,"answer":"sustainability","vi":"SUSTAIN (duy trì) → sustainability – tính bền vững (danh từ)","explanation":"Sau mạo từ 'the' cần một DANH TỪ. Động từ 'sustain' → danh từ 'sustainability' (thêm -ability). ✗ sustain = động từ; ✗ unsustainable = tính từ (không bền vững, thêm tiền tố phủ định un-); ✗ sustainably = trạng từ — đều sai từ loại."},
  {"type":"mcq","id":"wf-59","cat":"noun","base":"VARY","q":"Rainforests are home to an enormous ___ (VARY) of plant and animal species.","options":["vary","various","variety","variously"],"correct":2,"answer":"variety","vi":"VARY (khác nhau/biến đổi) → variety – sự đa dạng (danh từ)","explanation":"Sau tính từ 'enormous' và mạo từ 'an' cần một DANH TỪ (cụm 'a variety of' = một sự đa dạng của). Động từ 'vary' → danh từ 'variety'. ✗ vary = động từ; ✗ various = tính từ (đứng trực tiếp trước danh từ số nhiều, không dùng sau mạo từ 'an'); ✗ variously = trạng từ — đều sai từ loại/vị trí."},
  {"type":"mcq","id":"wf-60","cat":"adv","base":"RESPONSIBLE","q":"Some factories dispose of chemical waste ___ (RESPONSIBLE), causing serious harm to rivers and lakes nearby.","options":["irresponsibly","responsible","responsibility","irresponsible"],"correct":0,"answer":"irresponsibly","vi":"RESPONSIBLE (có trách nhiệm) → irresponsibly – một cách thiếu trách nhiệm (trạng từ, thêm tiền tố phủ định ir-)","explanation":"Bổ nghĩa cho động từ 'dispose' và ngữ cảnh mang nghĩa tiêu cực (gây hại cho sông hồ) nên cần một TRẠNG TỪ mang nghĩa phủ định. Tính từ 'responsible' thêm tiền tố phủ định 'ir-' → 'irresponsible', rồi thêm '-ly' → trạng từ 'irresponsibly'. ✗ responsible = tính từ (nghĩa tích cực, không hợp ngữ cảnh); ✗ responsibility = danh từ; ✗ irresponsible = tính từ (chưa phải trạng từ) — đều sai từ loại/vị trí."},
  {"type":"mcq","id":"wf-61","cat":"adv","base":"NATURE","q":"Bamboo grows ___ (NATURE) in many parts of Southeast Asia without needing special care.","options":["nature","naturally","natural","naturalize"],"correct":1,"answer":"naturally","vi":"NATURE (tự nhiên) → naturally – một cách tự nhiên (trạng từ)","explanation":"Bổ nghĩa cho động từ 'grows' cần một TRẠNG TỪ. Danh từ 'nature' → tính từ 'natural' → trạng từ 'naturally' (thêm -ly). ✗ nature = danh từ; ✗ natural = tính từ; ✗ naturalize = động từ (nhập tịch/thuần hóa một loài trong môi trường mới) — đều sai từ loại."},
  {"type":"mcq","id":"wf-62","cat":"adv","base":"ECOLOGY","q":"Farmers are now encouraged to farm ___ (ECOLOGY) to protect the soil and local wildlife.","options":["ecology","ecological","ecologically","ecologist"],"correct":2,"answer":"ecologically","vi":"ECOLOGY (sinh thái học) → ecologically – về mặt sinh thái (trạng từ)","explanation":"Bổ nghĩa cho động từ 'farm' cần một TRẠNG TỪ. Danh từ 'ecology' → tính từ 'ecological' → trạng từ 'ecologically' (thêm -ly). ✗ ecology = danh từ; ✗ ecological = tính từ; ✗ ecologist = danh từ (nhà sinh thái học) — đều sai từ loại."},
  {"type":"mcq","id":"wf-63","cat":"adj","base":"INDUSTRY","q":"Dumping ___ (INDUSTRY) waste into rivers has killed thousands of fish in this area.","options":["industry","industrialize","industrialization","industrial"],"correct":3,"answer":"industrial","vi":"INDUSTRY (công nghiệp) → industrial – thuộc về công nghiệp (tính từ)","explanation":"Trước danh từ 'waste' cần một TÍNH TỪ bổ nghĩa. Danh từ 'industry' → tính từ 'industrial' (thêm -al). ✗ industry = danh từ; ✗ industrialize = động từ; ✗ industrialization = danh từ — đều sai từ loại/vị trí."},
  {"type":"mcq","id":"wf-64","cat":"adj","base":"AGRICULTURE","q":"Using too many chemicals in ___ (AGRICULTURE) production can seriously damage the soil.","options":["agricultural","agriculture","agriculturally","agriculturist"],"correct":0,"answer":"agricultural","vi":"AGRICULTURE (nông nghiệp) → agricultural – thuộc về nông nghiệp (tính từ)","explanation":"Trước danh từ 'production' cần một TÍNH TỪ. Danh từ 'agriculture' → tính từ 'agricultural' (thêm -al). ✗ agriculture = danh từ; ✗ agriculturally = trạng từ; ✗ agriculturist = danh từ (nhà nông học) — đều sai từ loại/vị trí."},
  {"type":"mcq","id":"wf-65","cat":"adj","base":"RENEW","q":"Wind and solar power are two examples of ___ (RENEW) energy.","options":["renew","renewable","renewal","renewably"],"correct":1,"answer":"renewable","vi":"RENEW (làm mới/gia hạn) → renewable – có thể tái tạo (tính từ)","explanation":"Trước danh từ 'energy' cần một TÍNH TỪ. Động từ 'renew' → tính từ 'renewable' (thêm -able). ✗ renew = động từ; ✗ renewal = danh từ; ✗ renewably = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-66","cat":"adj","base":"HARM","q":"Cutting down too many trees is extremely ___ (HARM) to the environment.","options":["harm","harmfully","harmful","harming"],"correct":2,"answer":"harmful","vi":"HARM (sự nguy hại) → harmful – có hại (tính từ)","explanation":"Sau 'extremely' và động từ 'to be' (is), bổ nghĩa cho chủ ngữ nên cần một TÍNH TỪ. Danh từ/động từ 'harm' → tính từ 'harmful' (thêm -ful). ✗ harm = danh từ/động từ; ✗ harmfully = trạng từ; ✗ harming = dạng V-ing — đều sai vị trí."},
  {"type":"mcq","id":"wf-67","cat":"verb","base":"FERTILE","q":"Farmers often ___ (FERTILE) their fields with chemical products to help crops grow faster.","options":["fertile","fertility","fertilizer","fertilize"],"correct":3,"answer":"fertilize","vi":"FERTILE (màu mỡ) → fertilize – bón phân (động từ)","explanation":"Sau chủ ngữ 'Farmers' và trạng từ 'often', câu cần một ĐỘNG TỪ chính. Tính từ 'fertile' → động từ 'fertilize' (thêm -ize). ✗ fertile = tính từ; ✗ fertility = danh từ (độ phì nhiêu); ✗ fertilizer = danh từ (phân bón) — đều sai từ loại, không thể làm động từ chính."},
  {"type":"mcq","id":"wf-68","cat":"verb","base":"THREAT","q":"Rising sea levels ___ (THREAT) many coastal cities around the world.","options":["threaten","threat","threatening","threateningly"],"correct":0,"answer":"threaten","vi":"THREAT (mối đe dọa) → threaten – đe dọa (động từ)","explanation":"Sau chủ ngữ 'Rising sea levels', câu cần một ĐỘNG TỪ chính. Danh từ 'threat' → động từ 'threaten' (thêm -en). ✗ threat = danh từ; ✗ threatening = tính từ (dạng V-ing); ✗ threateningly = trạng từ — đều sai từ loại."},
  {"type":"mcq","id":"wf-69","cat":"verb","base":"PURE","q":"This machine can ___ (PURE) polluted water and make it safe enough to drink.","options":["impure","purify","purity","purely"],"correct":1,"answer":"purify","vi":"PURE (trong sạch) → purify – làm sạch/tinh lọc (động từ)","explanation":"Sau trợ động từ 'can' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'pure' → động từ 'purify' (thêm -ify). ✗ impure = tính từ (không tinh khiết, thêm tiền tố phủ định im-); ✗ purity = danh từ; ✗ purely = trạng từ — đều sai từ loại sau 'can'."},
  {"type":"mcq","id":"wf-70","cat":"verb","base":"ACID","q":"Pollution in the air can ___ (ACID) rainwater, making it harmful to plants and buildings.","options":["acid","acidic","acidity","acidify"],"correct":3,"answer":"acidify","vi":"ACID (a-xít) → acidify – a-xít hóa/làm chua (động từ)","explanation":"Sau trợ động từ 'can' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'acid' → động từ 'acidify' (thêm -ify). ✗ acid = danh từ; ✗ acidic = tính từ; ✗ acidity = danh từ (độ a-xít) — đều sai từ loại sau 'can'."},
  {"type":"mcq","id":"wf-71","cat":"verb","base":"WARM","q":"Global ___ (WARM) is causing sea levels to rise and extreme weather to occur more often.","options":["warming","warm","warmth","warmly"],"correct":0,"answer":"warming","vi":"WARM (ấm) → warming – sự nóng lên (danh động từ/V-ing)","explanation":"Sau tính từ 'Global', cụm này làm chủ ngữ của động từ 'is' nên cần một danh động từ (V-ing, xếp vào nhóm động từ). Tính từ/động từ 'warm' → 'warming' (thêm -ing); 'global warming' = sự nóng lên toàn cầu. ✗ warm = tính từ/động từ gốc; ✗ warmth = danh từ (hơi ấm); ✗ warmly = trạng từ — đều sai từ loại/vị trí."},
  {"type":"mcq","id":"wf-72","cat":"verb","base":"MINIMUM","q":"Recycling paper and plastic helps ___ (MINIMUM) the amount of waste sent to landfills.","options":["minimum","minimize","minimal","minimally"],"correct":1,"answer":"minimize","vi":"MINIMUM (tối thiểu) → minimize – giảm thiểu (động từ)","explanation":"Sau động từ 'helps' cần một ĐỘNG TỪ nguyên mẫu (help + V). Danh từ/tính từ 'minimum' → động từ 'minimize' (thêm -ize). ✗ minimum = danh từ/tính từ; ✗ minimal = tính từ; ✗ minimally = trạng từ — đều sai từ loại."},
  {"type":"mcq","id":"wf-73","cat":"noun","base":"INVENT","q":"The smartphone is considered a remarkable ___ (INVENT) of modern technology.","options":["invent","inventive","invention","inventively"],"correct":2,"answer":"invention","vi":"INVENT (phát minh ra) → invention — phát minh (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'remarkable', cần một DANH TỪ số ít làm bổ ngữ. Động từ 'invent' → danh từ 'invention' (thêm hậu tố -ion). ✗ invent là động từ nguyên mẫu, không đứng sau tính từ; ✗ inventive là tính từ, cần một danh từ đứng sau nó chứ không thay thế được nó; ✗ inventively là trạng từ, chỉ bổ nghĩa cho động từ, không làm bổ ngữ ở vị trí này."},
  {"type":"mcq","id":"wf-74","cat":"noun","base":"INFORM","q":"The Internet gives students instant access to a huge amount of ___ (INFORM).","options":["inform","informative","informatively","information"],"correct":3,"answer":"information","vi":"INFORM (thông báo) → information — thông tin (danh từ)","explanation":"Sau tính từ 'huge' và giới từ 'of', cần một DANH TỪ không đếm được làm tân ngữ của giới từ. Động từ 'inform' → danh từ 'information' (thêm -ation). ✗ inform là động từ, không đứng sau giới từ 'of'; ✗ informative là tính từ, cần danh từ theo sau; ✗ informatively là trạng từ, chỉ bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-75","cat":"noun","base":"PRODUCE","q":"Mass ___ (PRODUCE) of computer chips has made electronic devices much cheaper.","options":["production","produce","productive","productively"],"correct":0,"answer":"production","vi":"PRODUCE (sản xuất) → production — sự sản xuất (danh từ)","explanation":"Cụm 'Mass ___ of computer chips' làm chủ ngữ của câu, cần một DANH TỪ trung tâm sau tính từ 'mass'. Động từ 'produce' → danh từ 'production' (thêm -tion). ✗ produce là động từ, không làm chủ ngữ ở dạng này; ✗ productive là tính từ, cần một danh từ đứng sau; ✗ productively là trạng từ, không thể làm chủ ngữ."},
  {"type":"mcq","id":"wf-76","cat":"noun","base":"COMMUNICATE","q":"Smartphones have completely changed the way we handle daily ___ (COMMUNICATE).","options":["communicate","communication","communicative","communicatively"],"correct":1,"answer":"communication","vi":"COMMUNICATE (giao tiếp) → communication — sự giao tiếp (danh từ)","explanation":"Sau tính từ 'daily', cần một DANH TỪ làm tân ngữ của động từ 'handle'. Động từ 'communicate' → danh từ 'communication' (thêm -ion). ✗ communicate là động từ, không đứng sau tính từ; ✗ communicative là tính từ, cần danh từ theo sau; ✗ communicatively là trạng từ, chỉ bổ nghĩa động từ."},
  {"type":"mcq","id":"wf-77","cat":"noun","base":"OPERATE","q":"Engineers checked whether the new robot was ready for full ___ (OPERATE).","options":["operate","operational","operation","operationally"],"correct":2,"answer":"operation","vi":"OPERATE (vận hành) → operation — sự vận hành (danh từ)","explanation":"Sau giới từ 'for' và tính từ 'full', cần một DANH TỪ làm tân ngữ của giới từ. Động từ 'operate' → danh từ 'operation' (thêm -ion). ✗ operate là động từ, không đứng sau giới từ; ✗ operational là tính từ, cần danh từ theo sau; ✗ operationally là trạng từ, chỉ bổ nghĩa động từ/tính từ."},
  {"type":"mcq","id":"wf-78","cat":"noun","base":"COMPUTE","q":"Every classroom in the school now has at least one ___ (COMPUTE) connected to the Internet.","options":["compute","computational","computationally","computer"],"correct":3,"answer":"computer","vi":"COMPUTE (tính toán) → computer — máy vi tính (danh từ)","explanation":"Sau lượng từ 'one', cần một DANH TỪ số ít làm tân ngữ của động từ 'has'. Động từ 'compute' → danh từ 'computer' (thêm hậu tố -er, chỉ vật thực hiện hành động). ✗ compute là động từ nguyên mẫu, không đứng sau 'one'; ✗ computational là tính từ, cần danh từ theo sau chứ không thay thế được nó; ✗ computationally là trạng từ, không thể làm tân ngữ."},
  {"type":"mcq","id":"wf-79","cat":"adj","base":"TECHNOLOGY","q":"Our daily lives have changed thanks to rapid ___ (TECHNOLOGY) development.","options":["technological","technology","technologically","technologist"],"correct":0,"answer":"technological","vi":"TECHNOLOGY (công nghệ) → technological — thuộc về công nghệ (tính từ)","explanation":"Trước danh từ 'development', cần một TÍNH TỪ bổ nghĩa cho nó. Danh từ 'technology' → tính từ 'technological' (thêm -ical). ✗ technology là danh từ, không đứng liền trước danh từ khác theo cách này; ✗ technologically là trạng từ, không đứng trước danh từ; ✗ technologist là danh từ chỉ người (nhà công nghệ), sai vị trí và nghĩa."},
  {"type":"mcq","id":"wf-80","cat":"adj","base":"CREATE","q":"Building a good mobile app requires a ___ (CREATE) mind and strong programming skills.","options":["create","creation","creative","creatively"],"correct":2,"answer":"creative","vi":"CREATE (sáng tạo ra) → creative — sáng tạo (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'mind', cần một TÍNH TỪ. Động từ 'create' → tính từ 'creative' (thêm -ive). ✗ create là động từ, không đứng sau mạo từ; ✗ creation là danh từ, không thể đứng liền trước danh từ 'mind' theo cách này; ✗ creatively là trạng từ, không đứng trước danh từ."},
  {"type":"mcq","id":"wf-81","cat":"adj","base":"RELY","q":"Customers want software that is fast and ___ (RELY), with no sudden crashes.","options":["rely","reliance","reliably","reliable"],"correct":3,"answer":"reliable","vi":"RELY (tin cậy vào) → reliable — đáng tin cậy (tính từ)","explanation":"Sau 'is fast and', cần một TÍNH TỪ song song với tính từ 'fast', làm bổ ngữ cho chủ ngữ 'software'. Động từ 'rely' → tính từ 'reliable' (thêm -able). ✗ rely là động từ, không làm bổ ngữ sau 'is'; ✗ reliance là danh từ, không song song với tính từ 'fast'; ✗ reliably là trạng từ, không làm bổ ngữ chủ ngữ."},
  {"type":"mcq","id":"wf-82","cat":"adj","base":"ACCESS","q":"Cloud storage makes your files ___ (ACCESS) from any computer or phone.","options":["accessible","access","accessibility","accessibly"],"correct":0,"answer":"accessible","vi":"ACCESS (sự truy cập) → accessible — có thể truy cập được (tính từ)","explanation":"Cấu trúc 'make + tân ngữ + tính từ' (khiến cho... trở nên) cần một TÍNH TỪ sau tân ngữ 'your files'. 'access' → tính từ 'accessible' (thêm -ible). ✗ access là danh từ/động từ, không làm bổ ngữ tính từ; ✗ accessibility là danh từ, không phù hợp cấu trúc 'make + O + adj'; ✗ accessibly là trạng từ, không bổ nghĩa cho tân ngữ."},
  {"type":"mcq","id":"wf-83","cat":"adj","base":"ELECTRON","q":"Most homework is now submitted in ___ (ELECTRON) form instead of on paper.","options":["electron","electronic","electronics","electronically"],"correct":1,"answer":"electronic","vi":"ELECTRON (hạt điện tử) → electronic — thuộc về điện tử (tính từ)","explanation":"Trước danh từ 'form', cần một TÍNH TỪ bổ nghĩa. 'electron' → tính từ 'electronic' (thêm -ic). ✗ electron là danh từ (hạt điện tử trong vật lý), không đứng trước danh từ theo cách này; ✗ electronics là danh từ (ngành/thiết bị điện tử), sai vị trí; ✗ electronically là trạng từ, không đứng trước danh từ."},
  {"type":"mcq","id":"wf-84","cat":"adv","base":"AUTOMATE","q":"Most modern apps update ___ (AUTOMATE) as soon as a new version is released.","options":["automate","automation","automatically","automatic"],"correct":2,"answer":"automatically","vi":"AUTOMATE (tự động hóa) → automatically — một cách tự động (trạng từ)","explanation":"Bổ nghĩa cho động từ 'update' (cách thức thực hiện hành động), cần một TRẠNG TỪ. Động từ 'automate' → trạng từ 'automatically' (qua tính từ automatic + -ally). ✗ automate là động từ, không bổ nghĩa cho động từ khác; ✗ automation là danh từ; ✗ automatic là tính từ, không đứng sau động từ để bổ nghĩa cho nó."},
  {"type":"mcq","id":"wf-85","cat":"adv","base":"DIGIT","q":"Photos and documents can now be stored ___ (DIGIT) instead of printed on paper.","options":["digital","digitize","digitization","digitally"],"correct":3,"answer":"digitally","vi":"DIGIT (chữ số) → digitally — một cách kỹ thuật số (trạng từ)","explanation":"Bổ nghĩa cho động từ 'stored' (cách thức lưu trữ), cần một TRẠNG TỪ. 'digit' → tính từ 'digital' → trạng từ 'digitally' (thêm -ly). ✗ digital là tính từ, không bổ nghĩa được cho động từ; ✗ digitize là động từ (số hóa), sai vị trí vì đã có động từ 'stored'; ✗ digitization là danh từ."},
  {"type":"mcq","id":"wf-86","cat":"adv","base":"EFFICIENT","q":"A good computer helps you complete your work more ___ (EFFICIENT) and quickly.","options":["efficiently","efficient","efficiency","inefficient"],"correct":0,"answer":"efficiently","vi":"EFFICIENT (hiệu quả) → efficiently — một cách hiệu quả (trạng từ)","explanation":"Sau 'more' và song song với trạng từ 'quickly' (bổ nghĩa cho động từ 'complete'), cần một TRẠNG TỪ. Tính từ 'efficient' → trạng từ 'efficiently' (thêm -ly). ✗ efficient là tính từ, không song song với 'quickly'; ✗ efficiency là danh từ; ✗ inefficient là tính từ mang tiền tố phủ định in-, vẫn sai vì cần trạng từ."},
  {"type":"mcq","id":"wf-87","cat":"adv","base":"SECURE","q":"Always make sure your online accounts are protected ___ (SECURE), using strong passwords.","options":["secure","securely","security","insecure"],"correct":1,"answer":"securely","vi":"SECURE (an toàn) → securely — một cách an toàn (trạng từ)","explanation":"Bổ nghĩa cho động từ bị động 'are protected' (cách thức được bảo vệ), cần một TRẠNG TỪ. 'secure' → trạng từ 'securely' (thêm -ly). ✗ secure là tính từ/động từ, không bổ nghĩa được cho động từ theo cách này; ✗ security là danh từ (sự bảo mật); ✗ insecure là tính từ mang tiền tố phủ định in-, vẫn sai vị trí."},
  {"type":"mcq","id":"wf-88","cat":"adv","base":"WIDE","q":"Tablets are now ___ (WIDE) used in classrooms for interactive learning.","options":["wide","widen","widely","width"],"correct":2,"answer":"widely","vi":"WIDE (rộng) → widely — rộng rãi, phổ biến (trạng từ)","explanation":"Bổ nghĩa cho động từ bị động 'are used' (mức độ/phạm vi sử dụng), cần một TRẠNG TỪ. Tính từ 'wide' → trạng từ 'widely' (thêm -ly). ✗ wide là tính từ, không bổ nghĩa được cho động từ; ✗ widen là động từ (mở rộng ra); ✗ width là danh từ (chiều rộng) — cả hai đều sai từ loại và vị trí."},
  {"type":"mcq","id":"wf-89","cat":"adv","base":"FREQUENT","q":"Software companies release security updates very ___ (FREQUENT) to fix new bugs.","options":["frequent","frequency","infrequent","frequently"],"correct":3,"answer":"frequently","vi":"FREQUENT (thường xuyên) → frequently — một cách thường xuyên (trạng từ)","explanation":"Sau 'very' và bổ nghĩa cho động từ 'release' (tần suất thực hiện hành động), cần một TRẠNG TỪ. Tính từ 'frequent' → trạng từ 'frequently' (thêm -ly). ✗ frequent là tính từ, không bổ nghĩa được cho động từ; ✗ frequency là danh từ (tần suất); ✗ infrequent là tính từ mang tiền tố phủ định in-, vẫn sai vì cần trạng từ."},
  {"type":"mcq","id":"wf-90","cat":"verb","base":"ANALYSIS","q":"Data scientists need special software to ___ (ANALYSIS) huge amounts of information quickly.","options":["analysis","analyze","analytical","analytically"],"correct":1,"answer":"analyze","vi":"ANALYSIS (sự phân tích) → analyze — phân tích (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu có 'to', làm tân ngữ của 'need... to'), cần một ĐỘNG TỪ. Danh từ 'analysis' → động từ 'analyze' (đổi đuôi -sis thành -ze). ✗ analysis là danh từ, không đứng sau 'to' làm động từ chính; ✗ analytical là tính từ, cần danh từ theo sau chứ không thay thế được động từ; ✗ analytically là trạng từ, chỉ bổ nghĩa cho động từ khác, không tự làm động từ chính."},
  {"type":"mcq","id":"wf-91","cat":"verb","base":"MODERN","q":"Schools are trying to ___ (MODERN) their teaching methods by using tablets and smart boards.","options":["modern","modernization","modernize","modernity"],"correct":2,"answer":"modernize","vi":"MODERN (hiện đại) → modernize — hiện đại hóa (động từ)","explanation":"Sau 'to' và trước tân ngữ 'their teaching methods', cần một ĐỘNG TỪ. Tính từ 'modern' → động từ 'modernize' (thêm -ize). ✗ modern là tính từ, không đứng sau 'to' làm động từ; ✗ modernization là danh từ; ✗ modernity là danh từ (tính hiện đại) — cả hai đều sai vị trí ngữ pháp."},
  {"type":"mcq","id":"wf-92","cat":"verb","base":"STANDARD","q":"Engineers try to ___ (STANDARD) the size of USB ports so devices from different brands can connect.","options":["standard","standardization","standardized","standardize"],"correct":3,"answer":"standardize","vi":"STANDARD (tiêu chuẩn) → standardize — tiêu chuẩn hóa (động từ)","explanation":"Sau 'to' và trước tân ngữ 'the size of USB ports', cần một ĐỘNG TỪ. Danh từ 'standard' → động từ 'standardize' (thêm -ize). ✗ standard là danh từ/tính từ, không làm động từ chính sau 'to'; ✗ standardization là danh từ; ✗ standardized là tính từ (dạng phân từ) — cả hai đều sai vị trí ngữ pháp."},
  {"type":"mcq","id":"wf-93","cat":"verb","base":"AUTHENTIC","q":"The system will ___ (AUTHENTIC) your identity by scanning your fingerprint.","options":["authenticate","authentic","authentication","authentically"],"correct":0,"answer":"authenticate","vi":"AUTHENTIC (xác thực/chính xác) → authenticate — xác thực (động từ)","explanation":"Sau trợ động từ 'will', cần một ĐỘNG TỪ nguyên thể. Tính từ 'authentic' → động từ 'authenticate' (thêm -ate). ✗ authentic là tính từ, không đứng sau 'will'; ✗ authentication là danh từ (sự xác thực); ✗ authentically là trạng từ — cả hai đều không thể đứng sau trợ động từ làm động từ chính."},
  {"type":"mcq","id":"wf-94","cat":"verb","base":"PRIORITY","q":"This email app lets you ___ (PRIORITY) important messages so you see them first.","options":["priority","prioritize","prioritization","prioritized"],"correct":1,"answer":"prioritize","vi":"PRIORITY (sự ưu tiên) → prioritize — ưu tiên (động từ)","explanation":"Cấu trúc 'let + tân ngữ + động từ nguyên mẫu không to' (let you ___), cần một ĐỘNG TỪ. Danh từ 'priority' → động từ 'prioritize' (thêm -ize). ✗ priority là danh từ, không đứng sau tân ngữ trong cấu trúc 'let sb + V'; ✗ prioritization là danh từ; ✗ prioritized là tính từ (dạng phân từ quá khứ) — cả hai đều sai vị trí ngữ pháp."},
  {"type":"mcq","id":"wf-95","cat":"noun","base":"EMPLOY","q":"The government has introduced new policies to reduce ___ (EMPLOY) among young people.","options":["employ","employed","unemployment","unemployed"],"correct":2,"answer":"unemployment","vi":"EMPLOY (thuê, sử dụng lao động) → unemployment — tình trạng thất nghiệp (danh từ, tiền tố phủ định un- + hậu tố -ment)","explanation":"Sau động từ 'reduce' cần một DANH TỪ làm tân ngữ. Động từ 'employ' + tiền tố phủ định 'un-' + hậu tố '-ment' → danh từ 'unemployment' (tình trạng thất nghiệp). ✗ employ = động từ nguyên gốc; ✗ employed = tính từ (đang có việc làm); ✗ unemployed = tính từ (thất nghiệp, chỉ người, không đứng một mình làm tân ngữ trừu tượng của 'reduce' nếu thiếu 'the') — cả ba đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-96","cat":"noun","base":"MANAGE","q":"Good ___ (MANAGE) is essential for a company to run smoothly and grow.","options":["manage","manageable","managerial","management"],"correct":3,"answer":"management","vi":"MANAGE (quản lý) → management — sự quản lý (danh từ)","explanation":"Sau tính từ 'good' cần một DANH TỪ làm chủ ngữ của câu. Động từ 'manage' + hậu tố '-ment' → danh từ 'management' (sự quản lý). ✗ manage = động từ; ✗ manageable = tính từ (có thể quản lý được); ✗ managerial = tính từ (thuộc về quản lý) — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-97","cat":"noun","base":"DECIDE","q":"Making the right ___ (DECIDE) about your career path can change your whole life.","options":["decision","decide","decisive","decisively"],"correct":0,"answer":"decision","vi":"DECIDE (quyết định - động từ) → decision — quyết định (danh từ)","explanation":"Sau tính từ 'right' và làm tân ngữ của 'making' cần một DANH TỪ. Động từ 'decide' → danh từ 'decision' (bỏ '-de', thêm '-sion'). ✗ decide = động từ; ✗ decisive = tính từ (dứt khoát); ✗ decisively = trạng từ — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-98","cat":"noun","base":"SATISFY","q":"Job ___ (SATISFY) is one of the main reasons employees stay loyal to a company.","options":["satisfy","satisfaction","satisfied","satisfactorily"],"correct":1,"answer":"satisfaction","vi":"SATISFY (làm hài lòng - động từ) → satisfaction — sự hài lòng (danh từ)","explanation":"Đứng sau danh từ 'Job' (ghép danh từ) và làm chủ ngữ của câu cần một DANH TỪ. Động từ 'satisfy' → danh từ 'satisfaction' (đổi '-fy' thành '-faction'). ✗ satisfy = động từ; ✗ satisfied = tính từ (cảm thấy hài lòng); ✗ satisfactorily = trạng từ — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-99","cat":"adj","base":"QUALIFY","q":"She is highly ___ (QUALIFY) to work as a software engineer.","options":["qualify","qualification","qualified","qualifier"],"correct":2,"answer":"qualified","vi":"QUALIFY (đủ điều kiện - động từ) → qualified — có trình độ, đủ tiêu chuẩn (tính từ)","explanation":"Sau trạng từ 'highly' và động từ 'to be' (is) cần một TÍNH TỪ làm bổ ngữ chủ ngữ. Động từ 'qualify' → tính từ 'qualified' (thêm '-ed'). ✗ qualify = động từ nguyên gốc; ✗ qualification = danh từ (bằng cấp, trình độ); ✗ qualifier = danh từ (người/vòng đấu loại) — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-100","cat":"adj","base":"PRODUCE","q":"Employees feel more ___ (PRODUCE) when they work in a comfortable environment.","options":["produce","production","productively","productive"],"correct":3,"answer":"productive","vi":"PRODUCE (sản xuất - động từ) → productive — có năng suất (tính từ)","explanation":"Sau trạng từ 'more' và động từ 'feel' cần một TÍNH TỪ làm bổ ngữ. Động từ 'produce' + hậu tố '-ive' → tính từ 'productive'. ✗ produce = động từ; ✗ production = danh từ (sự sản xuất); ✗ productively = trạng từ — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-101","cat":"adj","base":"SKILL","q":"The factory is looking to hire more ___ (SKILL) workers to operate the new machines.","options":["skilled","skill","skillfully","skillfulness"],"correct":0,"answer":"skilled","vi":"SKILL (kỹ năng - danh từ) → skilled — lành nghề, có tay nghề (tính từ)","explanation":"Trước danh từ 'workers' cần một TÍNH TỪ bổ nghĩa. Danh từ 'skill' + hậu tố '-ed' → tính từ 'skilled'. ✗ skill = danh từ; ✗ skillfully = trạng từ (một cách khéo léo); ✗ skillfulness = danh từ (sự khéo léo) — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-102","cat":"adv","base":"CONFIDENT","q":"She answered every interview question ___ (CONFIDENT) and got the job.","options":["confidence","confidently","confident","overconfident"],"correct":1,"answer":"confidently","vi":"CONFIDENT (tự tin - tính từ) → confidently — một cách tự tin (trạng từ)","explanation":"Sau động từ 'answered' và tân ngữ, cần một TRẠNG TỪ bổ nghĩa cho cách thức của hành động. Tính từ 'confident' + hậu tố '-ly' → trạng từ 'confidently'. ✗ confidence = danh từ (sự tự tin); ✗ confident = tính từ; ✗ overconfident = tính từ (quá tự tin) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-103","cat":"adv","base":"PROFESSION","q":"Employees are expected to behave ___ (PROFESSION) when dealing with clients.","options":["profession","professional","professionally","professionalism"],"correct":2,"answer":"professionally","vi":"PROFESSION (nghề nghiệp - danh từ) → professionally — một cách chuyên nghiệp (trạng từ)","explanation":"Sau động từ 'behave' cần một TRẠNG TỪ bổ nghĩa cho cách thức hành động. Danh từ 'profession' → tính từ 'professional' → thêm '-ly' → trạng từ 'professionally'. ✗ profession = danh từ (nghề nghiệp); ✗ professional = tính từ (chuyên nghiệp); ✗ professionalism = danh từ (tính chuyên nghiệp) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-104","cat":"adv","base":"PUNCTUAL","q":"All staff members are required to arrive at work ___ (PUNCTUAL) every morning.","options":["punctual","punctuality","unpunctual","punctually"],"correct":3,"answer":"punctually","vi":"PUNCTUAL (đúng giờ - tính từ) → punctually — một cách đúng giờ (trạng từ)","explanation":"Sau động từ 'arrive' cần một TRẠNG TỪ chỉ cách thức. Tính từ 'punctual' + hậu tố '-ly' → trạng từ 'punctually'. ✗ punctual = tính từ; ✗ punctuality = danh từ (tính đúng giờ); ✗ unpunctual = tính từ (không đúng giờ) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-105","cat":"adv","base":"COOPERATE","q":"The staff worked ___ (COOPERATE) to finish the project before the deadline.","options":["cooperatively","cooperate","cooperation","cooperative"],"correct":0,"answer":"cooperatively","vi":"COOPERATE (hợp tác - động từ) → cooperatively — một cách hợp tác (trạng từ)","explanation":"Sau động từ 'worked' cần một TRẠNG TỪ bổ nghĩa cho cách thức làm việc. Động từ 'cooperate' → tính từ 'cooperative' → thêm '-ly' → trạng từ 'cooperatively'. ✗ cooperate = động từ; ✗ cooperation = danh từ (sự hợp tác); ✗ cooperative = tính từ — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-106","cat":"verb","base":"STRONG","q":"Team-building activities help ___ (STRONG) cooperation among colleagues.","options":["strong","strengthen","strength","strongly"],"correct":1,"answer":"strengthen","vi":"STRONG (mạnh - tính từ) → strengthen — làm mạnh lên, củng cố (động từ)","explanation":"Sau động từ 'help' cần một ĐỘNG TỪ nguyên mẫu (help + V). Tính từ 'strong' + hậu tố '-en' → động từ 'strengthen'. ✗ strong = tính từ; ✗ strength = danh từ (sức mạnh); ✗ strongly = trạng từ — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-107","cat":"verb","base":"SHORT","q":"Automation can ___ (SHORT) the time needed to complete repetitive tasks at work.","options":["short","shortage","shorten","shortly"],"correct":2,"answer":"shorten","vi":"SHORT (ngắn - tính từ) → shorten — rút ngắn (động từ)","explanation":"Sau động từ khuyết thiếu 'can' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'short' + hậu tố '-en' → động từ 'shorten' (rút ngắn). ✗ short = tính từ; ✗ shortage = danh từ (sự thiếu hụt); ✗ shortly = trạng từ (chẳng bao lâu nữa) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-108","cat":"verb","base":"GLOBAL","q":"Many corporations want to ___ (GLOBAL) their business operations to reach new markets.","options":["global","globalization","globally","globalize"],"correct":3,"answer":"globalize","vi":"GLOBAL (toàn cầu - tính từ) → globalize — toàn cầu hóa (động từ)","explanation":"Sau 'want to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'global' + hậu tố '-ize' → động từ 'globalize' (toàn cầu hóa). ✗ global = tính từ; ✗ globalization = danh từ (sự toàn cầu hóa); ✗ globally = trạng từ — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-109","cat":"noun","base":"ATTRACT","q":"Sapa is a famous tourist ___ (ATTRACT) in northern Vietnam, drawing thousands of trekkers every year.","options":["attraction","attract","attractive","attractively"],"correct":0,"answer":"attraction","vi":"ATTRACT (thu hút - động từ) → attraction — điểm thu hút, điểm tham quan (danh từ)","explanation":"Sau mạo từ 'a', tính từ 'famous' và danh từ 'tourist' (bổ nghĩa), cần một DANH TỪ trung tâm làm bổ ngữ cho chủ ngữ 'Sapa'. Động từ 'attract' (thu hút) → danh từ 'attraction' (đổi đuôi -t thành -tion, nghĩa 'điểm thu hút, điểm tham quan'). ✗ attract = động từ; ✗ attractive = tính từ; ✗ attractively = trạng từ — đều sai vì vị trí này cần danh từ, không phải động từ, tính từ hay trạng từ."},
  {"type":"mcq","id":"wf-110","cat":"noun","base":"IMPRESS","q":"The ancient temples of Angkor Wat left a lasting ___ (IMPRESS) on every visitor.","options":["impress","impressive","impression","impressively"],"correct":2,"answer":"impression","vi":"IMPRESS (gây ấn tượng - động từ) → impression — ấn tượng (danh từ)","explanation":"Sau tính từ 'lasting', làm tân ngữ của động từ 'left' cần một DANH TỪ. Động từ 'impress' → danh từ 'impression' (đổi đuôi -ess thành -ession). ✗ impress = động từ; ✗ impressive = tính từ; ✗ impressively = trạng từ — đều sai vị trí vì cần danh từ sau tính từ 'lasting'."},
  {"type":"mcq","id":"wf-111","cat":"noun","base":"HOSPITABLE","q":"Local people are famous for their warm ___ (HOSPITABLE) to foreign visitors.","options":["hospitable","hospitably","inhospitable","hospitality"],"correct":3,"answer":"hospitality","vi":"HOSPITABLE (hiếu khách - tính từ) → hospitality — lòng hiếu khách, sự mến khách (danh từ)","explanation":"Sau sở hữu cách 'their' và tính từ 'warm', làm tân ngữ của giới từ 'for' cần một DANH TỪ. Tính từ 'hospitable' → danh từ 'hospitality' (đổi -able thành -ality). ✗ hospitable = tính từ; ✗ hospitably = trạng từ; ✗ inhospitable = tính từ (dạng phủ định) — đều sai vì cần danh từ, không phải tính từ hay trạng từ."},
  {"type":"mcq","id":"wf-112","cat":"adj","base":"NATURE","q":"Ha Long Bay's ___ (NATURE) beauty attracts millions of tourists every year.","options":["natural","nature","naturally","naturalize"],"correct":0,"answer":"natural","vi":"NATURE (thiên nhiên - danh từ) → natural — tự nhiên (tính từ)","explanation":"Trước danh từ 'beauty' (sau sở hữu cách 's) cần một TÍNH TỪ bổ nghĩa. Danh từ 'nature' → tính từ 'natural' (thêm hậu tố -al). ✗ nature = danh từ; ✗ naturally = trạng từ; ✗ naturalize = động từ — đều sai vì cần tính từ đứng trước danh từ 'beauty'."},
  {"type":"mcq","id":"wf-113","cat":"adj","base":"DANGER","q":"Trekking alone in the jungle without a guide can be extremely ___ (DANGER).","options":["danger","dangerous","dangerously","endanger"],"correct":1,"answer":"dangerous","vi":"DANGER (sự nguy hiểm - danh từ) → dangerous — nguy hiểm (tính từ)","explanation":"Sau trạng từ chỉ mức độ 'extremely' và động từ liên kết 'can be' cần một TÍNH TỪ làm bổ ngữ. Danh từ 'danger' → tính từ 'dangerous' (thêm hậu tố -ous). ✗ danger = danh từ; ✗ dangerously = trạng từ; ✗ endanger = động từ — đều sai vì cần tính từ sau động từ 'to be'."},
  {"type":"mcq","id":"wf-114","cat":"adj","base":"COMFORT","q":"The overnight bus ride was long and ___ (COMFORT), leaving passengers exhausted.","options":["comfort","discomfort","uncomfortable","comfortably"],"correct":2,"answer":"uncomfortable","vi":"COMFORT (sự thoải mái - danh từ) → uncomfortable — không thoải mái, khó chịu (tính từ)","explanation":"Sau 'was long and' cần một TÍNH TỪ song song với 'long'; ngữ cảnh 'leaving passengers exhausted' mang nghĩa tiêu cực nên cần tiền tố phủ định 'un-'. Danh từ 'comfort' → tính từ 'uncomfortable' (thêm -able rồi thêm 'un-'). ✗ comfort = danh từ; ✗ discomfort = danh từ (phủ định); ✗ comfortably = trạng từ — đều sai vì cần tính từ."},
  {"type":"mcq","id":"wf-115","cat":"adj","base":"EXPECT","q":"The sudden storm was completely ___ (EXPECT) and ruined our beach day.","options":["expectation","expect","expectantly","unexpected"],"correct":3,"answer":"unexpected","vi":"EXPECT (mong đợi - động từ) → unexpected — bất ngờ, không lường trước (tính từ)","explanation":"Sau 'was completely' cần một TÍNH TỪ làm bổ ngữ; nghĩa câu (cơn bão xảy đến bất ngờ làm hỏng cả ngày) đòi hỏi tiền tố phủ định 'un-'. Động từ 'expect' → tính từ 'unexpected' (thêm -ed rồi thêm 'un-'). ✗ expectation = danh từ; ✗ expect = động từ; ✗ expectantly = trạng từ."},
  {"type":"mcq","id":"wf-116","cat":"adj","base":"FORGET","q":"Climbing Mount Fuji at sunrise was an ___ (FORGET) experience for all of us.","options":["unforgettable","forgetfulness","forget","forgetfully"],"correct":0,"answer":"unforgettable","vi":"FORGET (quên - động từ) → unforgettable — không thể quên, đáng nhớ (tính từ)","explanation":"Sau mạo từ 'an' và trước danh từ 'experience' cần một TÍNH TỪ. Động từ 'forget' → tính từ 'unforgettable' (thêm 'un-' + '-able', nghĩa 'không thể quên'). ✗ forgetfulness = danh từ; ✗ forget = động từ; ✗ forgetfully = trạng từ."},
  {"type":"mcq","id":"wf-117","cat":"adj","base":"LUXURY","q":"The resort offers a ___ (LUXURY) spa experience for honeymooners.","options":["luxury","luxurious","luxuriously","luxuriate"],"correct":1,"answer":"luxurious","vi":"LUXURY (sự sang trọng - danh từ) → luxurious — sang trọng, xa hoa (tính từ)","explanation":"Trước cụm danh từ 'spa experience' cần một TÍNH TỪ bổ nghĩa. Danh từ 'luxury' → tính từ 'luxurious' (đổi -y thành -ious). ✗ luxury = danh từ; ✗ luxuriously = trạng từ; ✗ luxuriate = động từ."},
  {"type":"mcq","id":"wf-118","cat":"adv","base":"ECONOMY","q":"Budget travelers try to plan their trips as ___ (ECONOMY) as possible.","options":["economy","economical","economically","economize"],"correct":2,"answer":"economically","vi":"ECONOMY (nền kinh tế, sự tiết kiệm - danh từ) → economically — một cách tiết kiệm (trạng từ)","explanation":"Cấu trúc 'as ___ as possible' bổ nghĩa cho động từ 'plan' cần một TRẠNG TỪ chỉ cách thức. Danh từ 'economy' → trạng từ 'economically' (qua tính từ 'economical' rồi thêm -ly). ✗ economy = danh từ; ✗ economical = tính từ; ✗ economize = động từ."},
  {"type":"mcq","id":"wf-119","cat":"adv","base":"SAFETY","q":"Always store your passport ___ (SAFETY) while traveling abroad.","options":["safety","safe","safeguard","safely"],"correct":3,"answer":"safely","vi":"SAFETY (sự an toàn - danh từ) → safely — một cách an toàn (trạng từ)","explanation":"Sau cụm động từ 'store your passport' cần một TRẠNG TỪ chỉ cách thức thực hiện hành động. Danh từ 'safety' → trạng từ 'safely' (qua tính từ 'safe' rồi thêm -ly). ✗ safety = danh từ; ✗ safe = tính từ; ✗ safeguard = động từ."},
  {"type":"mcq","id":"wf-120","cat":"adv","base":"FAME","q":"The Eiffel Tower is ___ (FAME) known as the symbol of Paris.","options":["fame","famously","famous","infamous"],"correct":1,"answer":"famously","vi":"FAME (danh tiếng - danh từ) → famously — nổi tiếng là (trạng từ)","explanation":"Trước động từ dạng bị động 'known' cần một TRẠNG TỪ bổ nghĩa cho cách nó được biết đến. Danh từ 'fame' → trạng từ 'famously' (qua tính từ 'famous' rồi thêm -ly). ✗ fame = danh từ; ✗ famous = tính từ; ✗ infamous = tính từ (nghĩa 'khét tiếng xấu') — đều sai vì cần trạng từ."},
  {"type":"mcq","id":"wf-121","cat":"adv","base":"CONVENIENCE","q":"The hotel is ___ (CONVENIENCE) located near both the airport and the train station.","options":["convenience","convenient","conveniently","inconvenience"],"correct":2,"answer":"conveniently","vi":"CONVENIENCE (sự tiện lợi - danh từ) → conveniently — một cách tiện lợi (trạng từ)","explanation":"Trước phân từ 'located' cần một TRẠNG TỪ bổ nghĩa cho cách thức. Danh từ 'convenience' → trạng từ 'conveniently' (qua tính từ 'convenient' rồi thêm -ly). ✗ convenience = danh từ; ✗ convenient = tính từ; ✗ inconvenience = động từ."},
  {"type":"mcq","id":"wf-122","cat":"adv","base":"RELY","q":"Our tour guide ___ (RELY) provided accurate information throughout the trip.","options":["rely","reliable","reliability","reliably"],"correct":3,"answer":"reliably","vi":"RELY (tin cậy, dựa vào - động từ) → reliably — một cách đáng tin cậy (trạng từ)","explanation":"Trước động từ chính 'provided' cần một TRẠNG TỪ chỉ cách thức. Động từ 'rely' → trạng từ 'reliably' (qua tính từ 'reliable' rồi thêm -ly). ✗ rely = động từ; ✗ reliable = tính từ; ✗ reliability = danh từ."},
  {"type":"mcq","id":"wf-123","cat":"adv","base":"EXCITE","q":"The children waved ___ (EXCITE) at the cruise ship as it left the harbor.","options":["excitedly","excite","excitement","exciting"],"correct":0,"answer":"excitedly","vi":"EXCITE (làm phấn khích - động từ) → excitedly — một cách phấn khích, hào hứng (trạng từ)","explanation":"Sau động từ 'waved' cần một TRẠNG TỪ chỉ cách thức của hành động. Động từ 'excite' → trạng từ 'excitedly' (qua tính từ 'excited' rồi thêm -ly). ✗ excite = động từ; ✗ excitement = danh từ; ✗ exciting = tính từ."},
  {"type":"mcq","id":"wf-124","cat":"verb","base":"BROAD","q":"Traveling to different countries helps ___ (BROAD) your understanding of other cultures.","options":["broad","broaden","breadth","broadly"],"correct":1,"answer":"broaden","vi":"BROAD (rộng - tính từ) → broaden — mở rộng (động từ)","explanation":"Sau 'helps' (theo sau bởi động từ nguyên mẫu không 'to') cần một ĐỘNG TỪ. Tính từ 'broad' → động từ 'broaden' (thêm hậu tố -en). ✗ broad = tính từ; ✗ breadth = danh từ; ✗ broadly = trạng từ."},
  {"type":"mcq","id":"wf-125","cat":"verb","base":"FAMILIAR","q":"Before your trip, take time to ___ (FAMILIAR) yourself with local customs and etiquette.","options":["familiarity","familiar","familiarize","familiarly"],"correct":2,"answer":"familiarize","vi":"FAMILIAR (quen thuộc - tính từ) → familiarize — làm cho quen thuộc, làm quen (động từ)","explanation":"Sau giới từ 'to' (trong cụm 'take time to') cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'familiar' → động từ 'familiarize' (thêm hậu tố -ize). ✗ familiarity = danh từ; ✗ familiar = tính từ; ✗ familiarly = trạng từ."},
  {"type":"mcq","id":"wf-126","cat":"verb","base":"ACTIVE","q":"The app will automatically ___ (ACTIVE) your travel insurance once you arrive at the airport.","options":["activity","active","actively","activate"],"correct":3,"answer":"activate","vi":"ACTIVE (năng động, đang hoạt động - tính từ) → activate — kích hoạt (động từ)","explanation":"Sau trợ động từ 'will' (dù có trạng từ 'automatically' chen giữa) cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'active' → động từ 'activate' (thêm hậu tố -ate). ✗ activity = danh từ; ✗ active = tính từ; ✗ actively = trạng từ."},
  {"type":"mcq","id":"wf-127","cat":"adj","base":"SCIENCE","q":"Every experiment must follow a strict ___ (SCIENCE) method in order to produce reliable results.","options":["scientific","science","scientifically","scientist"],"correct":0,"answer":"scientific","vi":"SCIENCE (khoa học) → scientific — thuộc về khoa học (tính từ)","explanation":"Sau tính từ 'strict' và trước danh từ 'method' cần một TÍNH TỪ bổ nghĩa cho 'method' (cụm cố định 'scientific method' - phương pháp khoa học; 'science method' không được dùng trong tiếng Anh). Danh từ 'science' → tính từ 'scientific' (đổi -ce thành -tific). ✗ science = danh từ (môn khoa học); ✗ scientifically = trạng từ; ✗ scientist = danh từ chỉ người (nhà khoa học) — cả ba đều sai vị trí vì cần tính từ đứng trước danh từ 'method'."},
  {"type":"mcq","id":"wf-128","cat":"noun","base":"DISCOVER","q":"The ___ (DISCOVER) of a new vaccine took the research team almost ten years.","options":["discover","discovery","undiscovered","discoverable"],"correct":1,"answer":"discovery","vi":"DISCOVER (khám phá) → discovery — sự khám phá (danh từ)","explanation":"Sau mạo từ 'The' và làm chủ ngữ của câu (trước 'of'), cần một DANH TỪ. Động từ 'discover' → danh từ 'discovery' (đổi -er thành -ery). ✗ discover = động từ; ✗ undiscovered = tính từ (chưa được khám phá); ✗ discoverable = tính từ (có thể khám phá được) — cả ba đều sai vị trí vì câu cần danh từ làm chủ ngữ."},
  {"type":"mcq","id":"wf-129","cat":"noun","base":"OBSERVE","q":"Careful ___ (OBSERVE) of the animals' behavior helped researchers reach their conclusion.","options":["observe","observant","observation","observable"],"correct":2,"answer":"observation","vi":"OBSERVE (quan sát) → observation — sự quan sát (danh từ)","explanation":"Từ 'careful' là tính từ đứng trước và bổ nghĩa cho một DANH TỪ làm chủ ngữ của câu. Động từ 'observe' → danh từ 'observation' (thêm -ation). ✗ observe = động từ; ✗ observant = tính từ (hay để ý); ✗ observable = tính từ (có thể quan sát được) — cả ba đều sai vị trí vì cần danh từ làm chủ ngữ."},
  {"type":"mcq","id":"wf-130","cat":"noun","base":"CONCLUDE","q":"After months of experiments, the scientists finally reached a firm ___ (CONCLUDE).","options":["conclusion","conclude","conclusive","conclusively"],"correct":0,"answer":"conclusion","vi":"CONCLUDE (kết luận) → conclusion — kết luận (danh từ)","explanation":"Sau tính từ 'firm' và động từ 'reached', cần một DANH TỪ làm tân ngữ. Động từ 'conclude' → danh từ 'conclusion' (đổi -clude thành -clusion). ✗ conclude = động từ; ✗ conclusive = tính từ (có tính thuyết phục); ✗ conclusively = trạng từ — cả ba đều sai vị trí vì cần danh từ."},
  {"type":"mcq","id":"wf-131","cat":"noun","base":"PREDICT","q":"Weather experts made an accurate ___ (PREDICT) about the storm's path.","options":["predict","prediction","predictable","predictably"],"correct":1,"answer":"prediction","vi":"PREDICT (dự đoán) → prediction — dự đoán, lời tiên đoán (danh từ)","explanation":"Sau tính từ 'accurate' và mạo từ 'an', cần một DANH TỪ làm tân ngữ của 'made'. Động từ 'predict' → danh từ 'prediction' (thêm -ion). ✗ predict = động từ; ✗ predictable = tính từ (có thể đoán trước); ✗ predictably = trạng từ — cả ba đều sai vị trí vì cần danh từ."},
  {"type":"mcq","id":"wf-132","cat":"adj","base":"CHEMISTRY","q":"The lab technician wore gloves to handle the dangerous ___ (CHEMISTRY) substance safely.","options":["chemistry","chemically","chemical","chemist"],"correct":2,"answer":"chemical","vi":"CHEMISTRY (hóa học) → chemical — thuộc về hóa học, hóa chất (tính từ)","explanation":"Sau tính từ 'dangerous' và trước danh từ 'substance', cần một TÍNH TỪ. Danh từ 'chemistry' → tính từ 'chemical' (bỏ -stry, thêm -ical). ✗ chemistry = danh từ; ✗ chemically = trạng từ; ✗ chemist = danh từ chỉ người (nhà hóa học) — cả ba đều sai vị trí vì cần tính từ đứng trước danh từ."},
  {"type":"mcq","id":"wf-133","cat":"adj","base":"BIOLOGY","q":"The professor explained the ___ (BIOLOGY) process of photosynthesis in great detail.","options":["biology","biologically","biologist","biological"],"correct":3,"answer":"biological","vi":"BIOLOGY (sinh học) → biological — thuộc về sinh học (tính từ)","explanation":"Sau mạo từ 'the' và trước danh từ 'process', cần một TÍNH TỪ bổ nghĩa cho 'process'. Danh từ 'biology' → tính từ 'biological' (thêm -ical). ✗ biology = danh từ; ✗ biologically = trạng từ; ✗ biologist = danh từ chỉ người (nhà sinh học) — cả ba đều sai vị trí vì cần tính từ."},
  {"type":"mcq","id":"wf-134","cat":"adj","base":"HYPOTHESIS","q":"The report only describes a ___ (HYPOTHESIS) situation, not something that actually happened.","options":["hypothetical","hypothesis","hypothetically","hypothesize"],"correct":0,"answer":"hypothetical","vi":"HYPOTHESIS (giả thuyết) → hypothetical — mang tính giả định (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'situation', cần một TÍNH TỪ. Danh từ 'hypothesis' → tính từ 'hypothetical' (đổi đuôi -is thành -ical). ✗ hypothesis = danh từ; ✗ hypothetically = trạng từ; ✗ hypothesize = động từ (đưa ra giả thuyết) — cả ba đều sai vị trí vì cần tính từ đứng trước danh từ."},
  {"type":"mcq","id":"wf-135","cat":"adj","base":"DEPEND","q":"Good researchers must stay ___ (DEPEND) and never let sponsors influence their results.","options":["depend","independent","dependence","independently"],"correct":1,"answer":"independent","vi":"DEPEND (phụ thuộc) → independent — độc lập (tính từ)","explanation":"Sau động từ liên kết 'stay' cần một TÍNH TỪ làm bổ ngữ. Động từ 'depend' → tính từ 'independent' (thêm tiền tố phủ định 'in-' và hậu tố -ent, nghĩa 'không phụ thuộc' — phù hợp với ý 'không để nhà tài trợ ảnh hưởng'). ✗ depend = động từ; ✗ dependence = danh từ (sự phụ thuộc); ✗ independently = trạng từ — cả ba đều sai vị trí vì sau động từ liên kết cần tính từ."},
  {"type":"mcq","id":"wf-136","cat":"adv","base":"SIGNIFICANT","q":"The new treatment ___ (SIGNIFICANT) improved the recovery rate of the patients.","options":["signify","significant","significantly","significance"],"correct":2,"answer":"significantly","vi":"SIGNIFICANT (đáng kể) → significantly — một cách đáng kể (trạng từ)","explanation":"Từ cần điền đứng trước động từ 'improved' để bổ nghĩa cho nó, nên cần một TRẠNG TỪ. Tính từ 'significant' → trạng từ 'significantly' (thêm -ly). ✗ signify = động từ (biểu thị, có nghĩa là); ✗ significant = tính từ; ✗ significance = danh từ (tầm quan trọng) — cả ba đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-137","cat":"adv","base":"REGULAR","q":"The researchers ___ (REGULAR) recorded the data throughout the six-month study.","options":["regulate","regular","regularity","regularly"],"correct":3,"answer":"regularly","vi":"REGULAR (đều đặn) → regularly — một cách đều đặn (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'recorded', nên cần một TRẠNG TỪ. Tính từ 'regular' → trạng từ 'regularly' (thêm -ly). ✗ regulate = động từ (điều chỉnh, quản lý); ✗ regular = tính từ; ✗ regularity = danh từ (tính đều đặn) — cả ba đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-138","cat":"adv","base":"ANALYZE","q":"A good scientist must think ___ (ANALYZE) when solving a complex problem.","options":["analytically","analyze","analysis","analytical"],"correct":0,"answer":"analytically","vi":"ANALYZE (phân tích) → analytically — một cách phân tích (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'think', nên cần một TRẠNG TỪ. Động từ 'analyze' → trạng từ 'analytically' (qua tính từ 'analytical' + -ly). ✗ analyze = động từ; ✗ analysis = danh từ (sự phân tích); ✗ analytical = tính từ — cả ba đều sai vị trí vì cần trạng từ bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-139","cat":"verb","base":"VALID","q":"The team ran a second experiment to ___ (VALID) their original results.","options":["valid","validate","validity","validly"],"correct":1,"answer":"validate","vi":"VALID (hợp lệ) → validate — xác nhận, kiểm chứng (động từ)","explanation":"Sau 'to' (to-infinitive) cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'valid' → động từ 'validate' (thêm -ate). ✗ valid = tính từ; ✗ validity = danh từ (tính hợp lệ); ✗ validly = trạng từ — cả ba đều sai vị trí vì sau 'to' cần động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-140","cat":"verb","base":"SOLID","q":"As the liquid metal cools down, it will gradually ___ (SOLID) into a hard shape.","options":["solid","solidity","solidly","solidify"],"correct":3,"answer":"solidify","vi":"SOLID (rắn, đặc) → solidify — hóa rắn, đông đặc (động từ)","explanation":"Sau trợ động từ 'will' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'solid' → động từ 'solidify' (thêm -ify). ✗ solid = tính từ; ✗ solidity = danh từ (tính rắn chắc); ✗ solidly = trạng từ — cả ba đều sai vị trí vì sau 'will' cần động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-141","cat":"verb","base":"THEORY","q":"Some scientists ___ (THEORY) that the universe will keep expanding forever.","options":["theorize","theory","theoretical","theoretically"],"correct":0,"answer":"theorize","vi":"THEORY (lý thuyết) → theorize — đưa ra giả thuyết, lý luận rằng (động từ)","explanation":"Sau chủ ngữ số nhiều 'scientists' cần một ĐỘNG TỪ chia thì hiện tại đơn làm vị ngữ chính của câu. Danh từ 'theory' → động từ 'theorize' (thêm -ize). ✗ theory = danh từ; ✗ theoretical = tính từ (mang tính lý thuyết); ✗ theoretically = trạng từ — cả ba đều sai vị trí vì câu cần một động từ làm vị ngữ."},
  {"type":"mcq","id":"wf-142","cat":"adj","base":"ART","q":"The mural on the school wall shows great ___ (ART) talent and imagination.","options":["art","artistic","artist","artistically"],"correct":1,"answer":"artistic","vi":"ART (nghệ thuật) → artistic — thuộc về nghệ thuật, có tính nghệ thuật (tính từ)","explanation":"Chỗ trống đứng trước danh từ 'talent' nên cần một TÍNH TỪ bổ nghĩa cho danh từ đó, tạo thành cụm quen thuộc 'artistic talent' (năng khiếu nghệ thuật). Danh từ 'art' (nghệ thuật) → tính từ 'artistic' (thêm đuôi -istic). ✗ art = chính danh từ gốc; ✗ artist = danh từ chỉ người (nghệ sĩ); ✗ artistically = trạng từ — cả ba đều không thể đứng trước danh từ để bổ nghĩa như tính từ."},
  {"type":"mcq","id":"wf-143","cat":"adv","base":"MUSIC","q":"She hums old folk tunes so ___ (MUSIC) that even passers-by stop to listen.","options":["music","musical","musically","musician"],"correct":2,"answer":"musically","vi":"MUSIC (âm nhạc) → musically — một cách du dương, đầy chất nhạc (trạng từ)","explanation":"Chỗ trống đứng sau 'so' và bổ nghĩa cho động từ 'hums' (mô tả CÁCH cô ấy ngân nga), cần một TRẠNG TỪ. Danh từ 'music' → tính từ 'musical' → trạng từ 'musically' (thêm -ly). ✗ music = danh từ; ✗ musical = tính từ (phải đứng trước danh từ, không bổ nghĩa cho động từ); ✗ musician = danh từ chỉ người (nhạc sĩ)."},
  {"type":"mcq","id":"wf-144","cat":"noun","base":"EXPRESS","q":"Music is a powerful form of ___ (EXPRESS) that touches people's emotions deeply.","options":["express","expressive","expressively","expression"],"correct":3,"answer":"expression","vi":"EXPRESS (diễn đạt - động từ) → expression — sự biểu đạt, cách thể hiện (danh từ)","explanation":"Sau 'a form of' cần một DANH TỪ làm tân ngữ của giới từ 'of'. Động từ 'express' (diễn đạt) → danh từ 'expression' (thêm -ion). ✗ express = động từ; ✗ expressive = tính từ (giàu biểu cảm); ✗ expressively = trạng từ — không thể làm tân ngữ cho giới từ."},
  {"type":"mcq","id":"wf-145","cat":"verb","base":"POPULAR","q":"This TV talent show has helped ___ (POPULAR) traditional folk music among young people.","options":["popularize","popular","popularity","popularly"],"correct":0,"answer":"popularize","vi":"POPULAR (phổ biến - tính từ) → popularize — phổ biến hóa, làm cho phổ biến (động từ)","explanation":"Sau động từ 'helped' cần một ĐỘNG TỪ nguyên mẫu không 'to' (bare infinitive) làm tân ngữ. Tính từ 'popular' (phổ biến) → động từ 'popularize' (làm cho phổ biến, thêm -ize). ✗ popular = tính từ gốc; ✗ popularity = danh từ (sự phổ biến); ✗ popularly = trạng từ — cả ba không thể đứng sau 'helped' làm động từ chính."},
  {"type":"mcq","id":"wf-146","cat":"adj","base":"BEAUTY","q":"The painting captures the ___ (BEAUTY) scenery of the countryside in autumn.","options":["beauty","beautiful","beautify","beautifully"],"correct":1,"answer":"beautiful","vi":"BEAUTY (vẻ đẹp - danh từ) → beautiful — đẹp (tính từ)","explanation":"Chỗ trống đứng sau mạo từ 'the' và trước danh từ 'scenery', cần một TÍNH TỪ. Danh từ 'beauty' (vẻ đẹp) → tính từ 'beautiful' (thêm -ful). ✗ beauty = danh từ; ✗ beautify = động từ (làm cho đẹp hơn); ✗ beautifully = trạng từ — không thể đứng trước danh từ."},
  {"type":"mcq","id":"wf-147","cat":"adv","base":"SKILL","q":"The guitarist played the solo so ___ (SKILL) that the whole audience burst into applause.","options":["skill","skillful","skillfully","skilled"],"correct":2,"answer":"skillfully","vi":"SKILL (kỹ năng - danh từ) → skillfully — một cách khéo léo, điêu luyện (trạng từ)","explanation":"Chỗ trống đứng sau 'so' và bổ nghĩa cho động từ 'played', cần một TRẠNG TỪ. Danh từ 'skill' (kỹ năng) → tính từ 'skillful' → trạng từ 'skillfully' (thêm -ly). ✗ skill = danh từ; ✗ skillful = tính từ; ✗ skilled = tính từ (có tay nghề) — cả ba đều không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-148","cat":"noun","base":"IMAGINE","q":"A good children's book needs colorful pictures and a lot of ___ (IMAGINE).","options":["imagine","imaginative","imaginatively","imagination"],"correct":3,"answer":"imagination","vi":"IMAGINE (tưởng tượng - động từ) → imagination — trí tưởng tượng (danh từ)","explanation":"Sau 'a lot of' cần một DANH TỪ không đếm được. Động từ 'imagine' (tưởng tượng) → danh từ 'imagination' (thêm -ation). ✗ imagine = động từ; ✗ imaginative = tính từ (giàu trí tưởng tượng); ✗ imaginatively = trạng từ — không đứng sau 'a lot of'."},
  {"type":"mcq","id":"wf-149","cat":"adv","base":"EMOTION","q":"The singer performed the ballad so ___ (EMOTION) that many people in the audience began to cry.","options":["emotionally","emotion","emotional","emotionless"],"correct":0,"answer":"emotionally","vi":"EMOTION (cảm xúc - danh từ) → emotionally — một cách đầy cảm xúc (trạng từ)","explanation":"Chỗ trống đứng sau 'so' và bổ nghĩa cho động từ 'performed', cần một TRẠNG TỪ. Danh từ 'emotion' (cảm xúc) → tính từ 'emotional' → trạng từ 'emotionally' (thêm -ly). ✗ emotion = danh từ; ✗ emotional = tính từ; ✗ emotionless = tính từ (vô cảm) — cả ba đều không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-150","cat":"verb","base":"HARMONY","q":"The choir members practiced hard to ___ (HARMONY) their voices perfectly.","options":["harmony","harmonious","harmonize","harmoniously"],"correct":2,"answer":"harmonize","vi":"HARMONY (sự hòa hợp - danh từ) → harmonize — hòa hợp/hòa âm (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'harmony' (sự hòa hợp) → động từ 'harmonize' (hòa hợp, thêm -ize). ✗ harmony = danh từ; ✗ harmonious = tính từ; ✗ harmoniously = trạng từ — cả ba không thể đứng sau 'to' làm động từ."},
  {"type":"mcq","id":"wf-151","cat":"adj","base":"DRAMA","q":"The final scene of the play had a very ___ (DRAMA) ending that left the audience in tears.","options":["drama","dramatically","dramatize","dramatic"],"correct":3,"answer":"dramatic","vi":"DRAMA (kịch, tuồng - danh từ) → dramatic — đầy kịch tính (tính từ)","explanation":"Chỗ trống đứng sau 'very' và trước danh từ 'ending', cần một TÍNH TỪ. Danh từ 'drama' (kịch) → tính từ 'dramatic' (thêm -tic). ✗ drama = danh từ; ✗ dramatically = trạng từ; ✗ dramatize = động từ (chuyển thể thành kịch) — không thể đứng trước danh từ."},
  {"type":"mcq","id":"wf-152","cat":"adv","base":"PASSION","q":"The young violinist played ___ (PASSION), pouring all her feelings into the music.","options":["passionately","passion","passionate","impassioned"],"correct":0,"answer":"passionately","vi":"PASSION (đam mê - danh từ) → passionately — một cách say mê, nhiệt huyết (trạng từ)","explanation":"Chỗ trống bổ nghĩa cho động từ 'played' (mô tả cách chơi đàn), cần một TRẠNG TỪ. Danh từ 'passion' (đam mê) → tính từ 'passionate' → trạng từ 'passionately' (thêm -ly). ✗ passion = danh từ; ✗ passionate = tính từ; ✗ impassioned = tính từ (đầy nhiệt huyết) — cả ba đều không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-153","cat":"noun","base":"SUCCEED","q":"The young singer's debut album was a huge ___ (SUCCEED) with fans across the country.","options":["succeed","success","successful","successfully"],"correct":1,"answer":"success","vi":"SUCCEED (thành công - động từ) → success — sự thành công (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'huge', cần một DANH TỪ làm bổ ngữ cho chủ ngữ 'album'. Động từ 'succeed' (thành công) → danh từ 'success'. ✗ succeed = động từ; ✗ successful = tính từ; ✗ successfully = trạng từ."},
  {"type":"mcq","id":"wf-154","cat":"verb","base":"DECORATION","q":"Local artists were invited to ___ (DECORATION) the town hall walls with colorful murals.","options":["decoration","decorative","decorate","decoratively"],"correct":2,"answer":"decorate","vi":"DECORATION (sự trang trí - danh từ) → decorate — trang trí (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'decoration' (sự trang trí) → động từ 'decorate' (trang trí, bỏ đuôi -ion). ✗ decoration = danh từ gốc; ✗ decorative = tính từ (mang tính trang trí); ✗ decoratively = trạng từ — không thể làm động từ chính sau 'to'."},
  {"type":"mcq","id":"wf-155","cat":"adj","base":"ORIGIN","q":"Instead of copying other artists, she always tries to create ___ (ORIGIN) works of art.","options":["origin","originate","originally","original"],"correct":3,"answer":"original","vi":"ORIGIN (nguồn gốc - danh từ) → original — độc đáo, nguyên bản (tính từ)","explanation":"Chỗ trống đứng trước danh từ 'works', cần một TÍNH TỪ. Danh từ 'origin' (nguồn gốc) → tính từ 'original' (thêm -al). ✗ origin = danh từ; ✗ originate = động từ (bắt nguồn từ); ✗ originally = trạng từ — không thể đứng trước danh từ."},
  {"type":"mcq","id":"wf-156","cat":"adv","base":"PERFECT","q":"After months of practice, the dancers performed the routine ___ (PERFECT) without a single mistake.","options":["perfectly","perfect","perfection","imperfect"],"correct":0,"answer":"perfectly","vi":"PERFECT (hoàn hảo - tính từ) → perfectly — một cách hoàn hảo (trạng từ)","explanation":"Chỗ trống bổ nghĩa cho động từ 'performed' (mô tả cách biểu diễn), cần một TRẠNG TỪ. Tính từ 'perfect' (hoàn hảo) → trạng từ 'perfectly' (thêm -ly). ✗ perfect = tính từ; ✗ perfection = danh từ (sự hoàn hảo); ✗ imperfect = tính từ (không hoàn hảo) — không thể bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-157","cat":"noun","base":"ENTERTAIN","q":"Live concerts provide great ___ (ENTERTAIN) for people of all ages.","options":["entertain","entertainment","entertaining","entertainingly"],"correct":1,"answer":"entertainment","vi":"ENTERTAIN (giải trí - động từ) → entertainment — sự giải trí (danh từ)","explanation":"Sau tính từ 'great', cần một DANH TỪ làm tân ngữ của động từ 'provide'. Động từ 'entertain' (giải trí) → danh từ 'entertainment' (thêm -ment). ✗ entertain = động từ; ✗ entertaining = tính từ (mang tính giải trí); ✗ entertainingly = trạng từ."},
  {"type":"mcq","id":"wf-158","cat":"verb","base":"VARIETY","q":"A good radio station should ___ (VARIETY) its music selection to please different listeners.","options":["variety","various","vary","variously"],"correct":2,"answer":"vary","vi":"VARIETY (sự đa dạng - danh từ) → vary — thay đổi/đa dạng hóa (động từ)","explanation":"Sau động từ khiếm khuyết 'should' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'variety' (sự đa dạng) → động từ 'vary' (thay đổi, đa dạng hóa). ✗ variety = danh từ gốc; ✗ various = tính từ (đa dạng, nhiều loại); ✗ variously = trạng từ — cả ba không thể đứng sau 'should'."},
  {"type":"mcq","id":"wf-159","cat":"adj","base":"COLOR","q":"The costumes in the folk dance performance were extremely ___ (COLOR) and eye-catching.","options":["color","colorfully","colorize","colorful"],"correct":3,"answer":"colorful","vi":"COLOR (màu sắc - danh từ) → colorful — sặc sỡ, nhiều màu sắc (tính từ)","explanation":"Chỗ trống đứng sau trạng từ 'extremely' và làm bổ ngữ cho chủ ngữ 'costumes' (sau động từ liên kết 'were'), song song với tính từ 'eye-catching', cần một TÍNH TỪ. Danh từ 'color' (màu sắc) → tính từ 'colorful' (thêm -ful). ✗ color = danh từ; ✗ colorfully = trạng từ; ✗ colorize = động từ (tô màu cho phim/ảnh cũ) — đều sai vị trí."},
  {"type":"mcq","id":"wf-160","cat":"adv","base":"RHYTHM","q":"The drummer tapped his sticks ___ (RHYTHM) to keep the whole band in time.","options":["rhythm","rhythmically","rhythmic","rhythmical"],"correct":1,"answer":"rhythmically","vi":"RHYTHM (nhịp điệu - danh từ) → rhythmically — một cách nhịp nhàng (trạng từ)","explanation":"Chỗ trống bổ nghĩa cho động từ 'tapped' (mô tả cách gõ), cần một TRẠNG TỪ. Danh từ 'rhythm' (nhịp điệu) → tính từ 'rhythmic'/'rhythmical' → trạng từ 'rhythmically' (thêm -ly). ✗ rhythm = danh từ; ✗ rhythmic = tính từ; ✗ rhythmical = tính từ (dạng khác của rhythmic) — cả ba đều không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-161","cat":"noun","base":"INSPIRE","q":"The composer said the sound of ocean waves was his main ___ (INSPIRE) for the symphony.","options":["inspire","inspiring","inspiration","inspired"],"correct":2,"answer":"inspiration","vi":"INSPIRE (truyền cảm hứng - động từ) → inspiration — nguồn cảm hứng (danh từ)","explanation":"Sau tính từ sở hữu 'his' và tính từ 'main', cần một DANH TỪ làm bổ ngữ cho động từ 'was'. Động từ 'inspire' (truyền cảm hứng) → danh từ 'inspiration' (thêm -ation). ✗ inspire = động từ; ✗ inspiring = tính từ (gây cảm hứng); ✗ inspired = tính từ (được truyền cảm hứng) — cả hai là tính từ, không phải danh từ."},
  {"type":"mcq","id":"wf-162","cat":"verb","base":"COMPOSITION","q":"Beethoven began to ___ (COMPOSITION) music at a very young age, despite his difficult childhood.","options":["composition","composer","compositional","compose"],"correct":3,"answer":"compose","vi":"COMPOSITION (tác phẩm/sự sáng tác - danh từ) → compose — sáng tác (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'composition' (tác phẩm/sự sáng tác) → động từ 'compose' (sáng tác, bỏ đuôi -ition). ✗ composition = danh từ gốc; ✗ composer = danh từ chỉ người (nhà soạn nhạc); ✗ compositional = tính từ (thuộc về sáng tác) — cả ba không thể làm động từ sau 'to'."},
  {"type":"mcq","id":"wf-163","cat":"adj","base":"ATHLETE","q":"She has always had an ___ (ATHLETE) build and enjoys every kind of sport.","options":["athletic","athlete","athletically","athleticism"],"correct":0,"answer":"athletic","vi":"ATHLETE (vận động viên) → athletic — có thể chất/vóc dáng thể thao (tính từ)","explanation":"Sau mạo từ 'an' và trước danh từ 'build' cần một TÍNH TỪ để bổ nghĩa cho danh từ đó. Danh từ 'athlete' → tính từ 'athletic' (thêm đuôi -ic). ✗ athlete = danh từ (vận động viên); ✗ athletically = trạng từ; ✗ athleticism = danh từ (tính chất thể thao) — cả ba đều không thể đứng trước danh từ 'build' để bổ nghĩa như một tính từ."},
  {"type":"mcq","id":"wf-164","cat":"verb","base":"STRENGTH","q":"Lifting weights three times a week will ___ (STRENGTH) your arm and leg muscles.","options":["strength","strengthen","strong","strongly"],"correct":1,"answer":"strengthen","vi":"STRENGTH (sức mạnh) → strengthen — làm cho mạnh hơn (động từ)","explanation":"Sau trợ động từ 'will' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'strength' → động từ 'strengthen' (thêm đuôi -en). ✗ strength = danh từ; ✗ strong = tính từ; ✗ strongly = trạng từ — không thể đứng sau 'will' vì vị trí này chỉ nhận động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-165","cat":"adv","base":"HEALTH","q":"Serious athletes try to eat ___ (HEALTH) so their bodies can recover fast after training.","options":["health","healthy","healthily","healthiness"],"correct":2,"answer":"healthily","vi":"HEALTH (sức khỏe) → healthily — một cách lành mạnh (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'eat', diễn tả CÁCH ăn uống, nên cần một TRẠNG TỪ. Danh từ 'health' → trạng từ 'healthily' (thêm đuôi -ily). ✗ health = danh từ; ✗ healthy = tính từ (chỉ đứng trước danh từ hoặc sau to be); ✗ healthiness = danh từ — không thể bổ nghĩa cho động từ 'eat'."},
  {"type":"mcq","id":"wf-166","cat":"adv","base":"FLEXIBLE","q":"A skilled gymnast must be able to move ___ (FLEXIBLE) through every position in a routine.","options":["flexible","flexibility","flex","flexibly"],"correct":3,"answer":"flexibly","vi":"FLEXIBLE (linh hoạt/dẻo dai) → flexibly — một cách linh hoạt (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'move', diễn tả CÁCH di chuyển, nên cần một TRẠNG TỪ. Tính từ 'flexible' → trạng từ 'flexibly' (thêm -ly). ✗ flexible = tính từ (đứng trước danh từ, không bổ nghĩa cho động từ); ✗ flexibility = danh từ; ✗ flex = động từ (co duỗi) — đều sai vị trí ngữ pháp."},
  {"type":"mcq","id":"wf-167","cat":"noun","base":"ENDURE","q":"Marathon runners need incredible ___ (ENDURE) to keep going for over 42 kilometers.","options":["endurance","endure","enduring","endurable"],"correct":0,"answer":"endurance","vi":"ENDURE (chịu đựng) → endurance — sức bền, khả năng chịu đựng (danh từ)","explanation":"Sau tính từ 'incredible' cần một DANH TỪ làm tân ngữ cho động từ 'need'. Động từ 'endure' → danh từ 'endurance' (đổi đuôi thành -ance). ✗ endure = động từ nguyên mẫu; ✗ enduring = tính từ (bền bỉ, lâu dài); ✗ endurable = tính từ (có thể chịu đựng được) — không phải danh từ nên không thể làm tân ngữ ở đây."},
  {"type":"mcq","id":"wf-168","cat":"adv","base":"COMPETE","q":"In the final match, both teams played extremely ___ (COMPETE), fighting hard for every single point.","options":["competition","competitively","competitive","competitor"],"correct":1,"answer":"competitively","vi":"COMPETE (thi đấu) → competitively — một cách quyết liệt/cạnh tranh (trạng từ)","explanation":"Từ cần điền được bổ nghĩa bởi trạng từ chỉ mức độ 'extremely' và cùng bổ nghĩa cho động từ 'played', nên cần một TRẠNG TỪ. Động từ 'compete' → tính từ 'competitive' rồi thêm -ly → trạng từ 'competitively'. ✗ competition = danh từ; ✗ competitive = tính từ; ✗ competitor = danh từ (người thi đấu) — không thể đứng sau 'extremely' để bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-169","cat":"adj","base":"TRAIN","q":"Young athletes need to be highly ___ (TRAIN) if they want to reach the Olympics one day.","options":["train","training","trained","trainer"],"correct":2,"answer":"trained","vi":"TRAIN (huấn luyện) → trained — được huấn luyện bài bản, thuần thục (tính từ dạng quá khứ phân từ)","explanation":"Sau động từ liên kết 'to be' và trạng từ chỉ mức độ 'highly' cần một TÍNH TỪ miêu tả đặc điểm của vận động viên. Động từ 'train' → tính từ 'trained' (dùng dạng quá khứ phân từ -ed làm tính từ, giống cụm quen thuộc 'highly trained athletes'). ✗ train = động từ nguyên mẫu, không thể làm bổ ngữ sau 'be'; ✗ training = danh từ (việc huấn luyện), không phù hợp sau 'be highly'; ✗ trainer = danh từ chỉ người (huấn luyện viên) — cả ba đều sai vì vị trí này cần một tính từ."},
  {"type":"mcq","id":"wf-170","cat":"adj","base":"SUCCESS","q":"She has become one of the most ___ (SUCCESS) swimmers her country has ever produced.","options":["successful","success","succeed","successfully"],"correct":0,"answer":"successful","vi":"SUCCESS (thành công) → successful — thành công (tính từ)","explanation":"Sau cấu trúc so sánh nhất 'the most' và trước danh từ 'swimmers' cần một TÍNH TỪ. Danh từ 'success' → tính từ 'successful' (thêm -ful). ✗ success = danh từ; ✗ succeed = động từ; ✗ successfully = trạng từ — không thể đứng sau 'the most' để bổ nghĩa cho danh từ 'swimmers'."},
  {"type":"mcq","id":"wf-171","cat":"noun","base":"MOTIVATE","q":"Winning her first medal gave her the ___ (MOTIVATE) to train even harder every day.","options":["motivate","motivation","motivated","motivational"],"correct":1,"answer":"motivation","vi":"MOTIVATE (thúc đẩy, tạo động lực) → motivation — động lực (danh từ)","explanation":"Sau mạo từ 'the' cần một DANH TỪ làm tân ngữ cho động từ 'gave'. Động từ 'motivate' → danh từ 'motivation' (thêm -ion). ✗ motivate = động từ; ✗ motivated = tính từ (có động lực, dùng cho người); ✗ motivational = tính từ (mang tính khích lệ) — không thể đứng sau 'the' làm danh từ trung tâm."},
  {"type":"mcq","id":"wf-172","cat":"adj","base":"PERSIST","q":"Coaches always say that ___ (PERSIST) athletes improve faster than talented but lazy ones.","options":["persist","persistence","persistent","persistently"],"correct":2,"answer":"persistent","vi":"PERSIST (kiên trì) → persistent — kiên trì, bền bỉ (tính từ)","explanation":"Trước danh từ 'athletes' cần một TÍNH TỪ để bổ nghĩa. Động từ 'persist' → tính từ 'persistent' (thêm -ent). ✗ persist = động từ; ✗ persistence = danh từ; ✗ persistently = trạng từ — không thể đứng trước danh từ để bổ nghĩa như một tính từ."},
  {"type":"mcq","id":"wf-173","cat":"noun","base":"COORDINATE","q":"Playing table tennis well requires excellent hand-eye ___ (COORDINATE).","options":["coordinate","coordinated","coordinating","coordination"],"correct":3,"answer":"coordination","vi":"COORDINATE (phối hợp) → coordination — sự phối hợp (danh từ)","explanation":"Sau tính từ 'excellent' và cụm danh từ ghép 'hand-eye' cần một DANH TỪ làm tân ngữ cho 'requires'. Động từ 'coordinate' → danh từ 'coordination' (thêm -ion). ✗ coordinate = động từ (hoặc danh từ toán học, không hợp nghĩa); ✗ coordinated = tính từ (được phối hợp nhịp nhàng); ✗ coordinating = tính từ/danh động từ (như trong 'coordinating conjunction') — cả hai đều là tính từ, sai vị trí vì đây cần danh từ."},
  {"type":"mcq","id":"wf-174","cat":"verb","base":"STABLE","q":"Core exercises like planks help ___ (STABLE) your whole body during any sport movement.","options":["stabilize","stable","stability","stably"],"correct":0,"answer":"stabilize","vi":"STABLE (ổn định/vững) → stabilize — làm cho ổn định, giữ vững (động từ)","explanation":"Sau động từ 'help' cần một ĐỘNG TỪ (nguyên mẫu, có hoặc không có 'to'). Tính từ 'stable' → động từ 'stabilize' (thêm -ize). ✗ stable = tính từ; ✗ stability = danh từ; ✗ stably = trạng từ — không thể đứng sau 'help' để đóng vai trò động từ chính."},
  {"type":"mcq","id":"wf-175","cat":"verb","base":"ENERGY","q":"A good breakfast can ___ (ENERGY) your body before an important competition.","options":["energy","energize","energetic","energetically"],"correct":1,"answer":"energize","vi":"ENERGY (năng lượng) → energize — tiếp năng lượng, làm tràn đầy sức sống (động từ)","explanation":"Sau trợ động từ 'can' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'energy' → động từ 'energize' (thêm -ize). ✗ energy = danh từ; ✗ energetic = tính từ; ✗ energetically = trạng từ — không thể đứng sau 'can' làm động từ chính."},
  {"type":"mcq","id":"wf-176","cat":"verb","base":"INTENSE","q":"As the final round approached, both boxers began to ___ (INTENSE) their attacks.","options":["intense","intensity","intensify","intensely"],"correct":2,"answer":"intensify","vi":"INTENSE (mãnh liệt/dữ dội) → intensify — làm cho mạnh mẽ/dữ dội hơn (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'intense' → động từ 'intensify' (thêm -ify). ✗ intense = tính từ; ✗ intensity = danh từ (cường độ); ✗ intensely = trạng từ — không thể đứng sau 'to' làm động từ."},
  {"type":"mcq","id":"wf-177","cat":"noun","base":"RECOVER","q":"Doctors say a full ___ (RECOVER) from this kind of knee injury can take up to six months.","options":["recover","recovered","recoverable","recovery"],"correct":3,"answer":"recovery","vi":"RECOVER (hồi phục) → recovery — sự hồi phục (danh từ)","explanation":"Sau tính từ 'full' và mạo từ 'a' cần một DANH TỪ làm chủ ngữ. Động từ 'recover' → danh từ 'recovery' (đổi -er thành -ery). ✗ recover = động từ; ✗ recovered = tính từ/quá khứ phân từ (đã hồi phục); ✗ recoverable = tính từ (có thể phục hồi được) — không thể đứng sau 'a full' làm danh từ chính của câu."},
  {"type":"mcq","id":"wf-178","cat":"adv","base":"PROFESSIONAL","q":"Even at fifteen years old, she already plays tennis ___ (PROFESSIONAL), just like the adults on TV.","options":["professionally","profession","professionalism","professional"],"correct":0,"answer":"professionally","vi":"PROFESSIONAL (chuyên nghiệp) → professionally — một cách chuyên nghiệp (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'plays', diễn tả CÁCH chơi, nên cần một TRẠNG TỪ. Tính từ 'professional' → trạng từ 'professionally' (thêm -ly). ✗ profession = danh từ (nghề nghiệp); ✗ professionalism = danh từ (tính chuyên nghiệp); ✗ professional = tính từ (đứng trước danh từ, không bổ nghĩa cho động từ ở đây) — sai vị trí."},
  {"type":"mcq","id":"wf-179","cat":"verb","base":"QUALIFY","q":"If a runner is caught using banned drugs, officials will immediately ___ (QUALIFY) them from the race.","options":["qualification","disqualify","qualified","qualifying"],"correct":1,"answer":"disqualify","vi":"QUALIFY (đủ điều kiện) → disqualify — truất quyền thi đấu, loại bỏ tư cách (động từ, tiền tố phủ định dis-)","explanation":"Sau trợ động từ 'will' và trạng từ 'immediately' cần một ĐỘNG TỪ nguyên mẫu, và ngữ cảnh 'bị bắt dùng doping' đòi hỏi nghĩa PHỦ ĐỊNH (loại bỏ tư cách thi đấu). Thêm tiền tố 'dis-' vào 'qualify' → 'disqualify'. ✗ qualification = danh từ; ✗ qualified = tính từ/quá khứ phân từ; ✗ qualifying = tính từ/danh động từ (vòng loại) — không thể đứng sau 'will immediately' làm động từ chính."},
  {"type":"mcq","id":"wf-180","cat":"noun","base":"DETERMINE","q":"Winning the championship required incredible ___ (DETERMINE) and months of hard training.","options":["determine","determined","determinedly","determination"],"correct":3,"answer":"determination","vi":"DETERMINE (quyết định) → determination — sự quyết tâm (danh từ)","explanation":"Sau tính từ 'incredible' cần một DANH TỪ làm tân ngữ cho động từ 'required'. Động từ 'determine' → danh từ 'determination' (thêm -ation). ✗ determine = động từ nguyên mẫu; ✗ determined = tính từ (quyết tâm, dùng cho người: 'she looked determined'); ✗ determinedly = trạng từ — không thể đứng sau 'incredible' vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-181","cat":"adv","base":"CONSISTENT","q":"Training ___ (CONSISTENT) — hard one week, then skipping the next — will not help you improve.","options":["inconsistently","consistent","consistency","consist"],"correct":0,"answer":"inconsistently","vi":"CONSISTENT (đều đặn/nhất quán) → inconsistently — một cách thiếu đều đặn, thất thường (trạng từ, tiền tố phủ định in-)","explanation":"Từ cần điền bổ nghĩa cho danh động từ 'Training', diễn tả CÁCH tập luyện, nên cần một TRẠNG TỪ; ngữ cảnh 'lúc nặng lúc bỏ' cho thấy nghĩa PHỦ ĐỊNH. Thêm tiền tố 'in-' vào tính từ 'consistent' rồi thêm '-ly' → 'inconsistently'. ✗ consistent = tính từ; ✗ consistency = danh từ; ✗ consist = động từ (bao gồm) — sai từ loại và không mang nghĩa phủ định phù hợp."},
  {"type":"mcq","id":"wf-182","cat":"adv","base":"AGGRESSION","q":"The boxer attacked ___ (AGGRESSION) in the final round, throwing punch after punch at his opponent.","options":["aggression","aggressively","aggressive","aggressor"],"correct":1,"answer":"aggressively","vi":"AGGRESSION (sự hung hăng/tấn công dữ dội) → aggressively — một cách hung hăng, dữ dội (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'attacked', diễn tả CÁCH tấn công, nên cần một TRẠNG TỪ. Danh từ 'aggression' → tính từ 'aggressive' rồi thêm '-ly' → trạng từ 'aggressively'. ✗ aggression = danh từ; ✗ aggressive = tính từ; ✗ aggressor = danh từ chỉ người (kẻ tấn công) — không thể bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-183","cat":"adj","base":"VICTORY","q":"The whole team returned home feeling ___ (VICTORY) after winning the national championship.","options":["victory","victoriously","victorious","victor"],"correct":2,"answer":"victorious","vi":"VICTORY (chiến thắng) → victorious — chiến thắng, đắc thắng (tính từ)","explanation":"Sau động từ liên kết 'feeling' cần một TÍNH TỪ để miêu tả cảm giác của chủ ngữ. Danh từ 'victory' → tính từ 'victorious' (thêm -ous). ✗ victory = danh từ; ✗ victoriously = trạng từ; ✗ victor = danh từ chỉ người (người chiến thắng) — không thể đứng sau 'feeling' làm tính từ bổ nghĩa."},
  {"type":"mcq","id":"wf-184","cat":"adj","base":"NUTRITION","q":"Fresh vegetables and fruit are ___ (NUTRITION) foods that keep our bodies healthy.","options":["nutrition","nutritionally","nutritionist","nutritious"],"correct":3,"answer":"nutritious","vi":"NUTRITION (dinh dưỡng) → nutritious – bổ dưỡng (tính từ)","explanation":"Sau động từ liên kết 'are' và ngay trước danh từ 'foods', cần một TÍNH TỪ bổ nghĩa cho danh từ. Danh từ 'nutrition' → tính từ 'nutritious' (thêm đuôi -ous). ✗ nutrition = danh từ (chính là từ gốc); ✗ nutritionally = trạng từ (bổ nghĩa cho động từ/tính từ, không đứng trước danh từ); ✗ nutritionist = danh từ chỉ người (chuyên gia dinh dưỡng) — cả hai đều sai vì trước danh từ 'foods' phải là tính từ."},
  {"type":"mcq","id":"wf-185","cat":"adv","base":"TASTE","q":"The dessert table was ___ (TASTE) decorated with fresh flowers and colorful fruit.","options":["tastefully","taste","tasty","taster"],"correct":0,"answer":"tastefully","vi":"TASTE (vị, nếm) → tastefully – một cách tao nhã, có gu thẩm mỹ (trạng từ)","explanation":"Trong câu bị động 'was ___ decorated', cần TRẠNG TỪ bổ nghĩa cho phân từ 'decorated' (được trang trí như thế nào). Danh từ/động từ 'taste' → trạng từ 'tastefully' (thêm -ful rồi -ly). ✗ taste = danh từ/động từ gốc; ✗ tasty = tính từ (ngon miệng, không bổ nghĩa cho động từ ở dạng bị động này); ✗ taster = danh từ chỉ người/thiết bị nếm thử — đều sai vị trí."},
  {"type":"mcq","id":"wf-186","cat":"noun","base":"DIGEST","q":"Eating slowly and chewing your food well can improve your ___ (DIGEST) after meals.","options":["digest","digestion","digestive","indigestible"],"correct":1,"answer":"digestion","vi":"DIGEST (tiêu hóa - động từ) → digestion – sự tiêu hóa (danh từ)","explanation":"Sau tính từ sở hữu 'your' và làm tân ngữ của động từ 'improve', cần DANH TỪ. Động từ 'digest' → danh từ 'digestion' (thêm -ion). ✗ digest = động từ gốc; ✗ digestive = tính từ (thuộc về tiêu hóa); ✗ indigestible = tính từ mang tiền tố phủ định in- (khó tiêu hóa) — cả hai là tính từ, không thể làm tân ngữ ở vị trí này."},
  {"type":"mcq","id":"wf-187","cat":"noun","base":"NOURISH","q":"Home-cooked meals made with fresh ingredients usually provide more ___ (NOURISH) than fast food does.","options":["nourish","nourishing","nourishment","nourished"],"correct":2,"answer":"nourishment","vi":"NOURISH (nuôi dưỡng - động từ) → nourishment – sự nuôi dưỡng, dinh dưỡng (danh từ)","explanation":"Sau 'more' và trước 'than' trong cấu trúc so sánh hơn với danh từ không đếm được, cần một DANH TỪ. Động từ 'nourish' → danh từ 'nourishment' (thêm -ment). ✗ nourish = động từ gốc, không thể đứng một mình sau 'more'; ✗ nourishing = tính từ (bổ dưỡng, dùng để miêu tả thức ăn, không phải danh từ để so sánh bằng 'more'); ✗ nourished = tính từ dạng phân từ quá khứ (được nuôi dưỡng, vd 'a well-nourished child') — cả hai đều là tính từ, không thể làm danh từ đứng sau 'more' ở đây."},
  {"type":"mcq","id":"wf-188","cat":"noun","base":"PRESERVE","q":"Proper ___ (PRESERVE) of food, such as refrigeration and salting, helps prevent spoilage and waste.","options":["preserve","preserved","preservable","preservation"],"correct":3,"answer":"preservation","vi":"PRESERVE (bảo quản - động từ) → preservation – sự bảo quản (danh từ)","explanation":"Đứng đầu câu làm CHỦ NGỮ, sau tính từ 'proper' và trước giới từ 'of', cần DANH TỪ. Động từ 'preserve' → danh từ 'preservation' (thêm -ation). ✗ preserve = động từ gốc; ✗ preserved = tính từ (đã được bảo quản, vd preserved fruit); ✗ preservable = tính từ (có thể bảo quản được) — cả hai là tính từ, không thể làm chủ ngữ chính ở vị trí này."},
  {"type":"mcq","id":"wf-189","cat":"adj","base":"CONSUME","q":"Although some wild mushrooms are poisonous, many others are perfectly ___ (CONSUME) and even delicious.","options":["consumable","consume","consumption","consumer"],"correct":0,"answer":"consumable","vi":"CONSUME (tiêu thụ - động từ) → consumable – có thể ăn/dùng được (tính từ)","explanation":"Sau động từ liên kết 'are' và trạng từ chỉ mức độ 'perfectly', cần một TÍNH TỪ bổ nghĩa cho chủ ngữ 'others' (những loại nấm khác). Động từ 'consume' → tính từ 'consumable' (thêm -able, nghĩa 'có thể...được'). ✗ consume = động từ gốc, không thể đứng sau 'are perfectly'; ✗ consumption = danh từ (sự tiêu thụ); ✗ consumer = danh từ chỉ người tiêu dùng — cả hai là danh từ, không thể làm vị ngữ tính từ sau 'are perfectly'."},
  {"type":"mcq","id":"wf-190","cat":"adv","base":"APPETITE","q":"The chef arranged the food ___ (APPETITE) on the plate so that everyone wanted to try it immediately.","options":["appetite","appetizing","appetizingly","appetizer"],"correct":2,"answer":"appetizingly","vi":"APPETITE (sự thèm ăn) → appetizingly – một cách hấp dẫn (trạng từ)","explanation":"Sau động từ 'arranged', cần TRẠNG TỪ chỉ cách thức. Danh từ 'appetite' → tính từ 'appetizing' → trạng từ 'appetizingly' (thêm -ly). ✗ appetite = danh từ gốc; ✗ appetizing = tính từ (hấp dẫn, ngon miệng); ✗ appetizer = danh từ (món khai vị) — đều sai vì cần trạng từ bổ nghĩa cho động từ 'arranged'."},
  {"type":"mcq","id":"wf-191","cat":"adj","base":"HYGIENE","q":"Restaurant kitchens must be kept clean and ___ (HYGIENE) at all times to prevent food poisoning.","options":["hygiene","hygienically","hygienist","hygienic"],"correct":3,"answer":"hygienic","vi":"HYGIENE (vệ sinh) → hygienic – hợp vệ sinh (tính từ)","explanation":"Trong cấu trúc song song 'clean and ___', cần TÍNH TỪ tương xứng với tính từ 'clean'. Danh từ 'hygiene' → tính từ 'hygienic' (thêm -ic). ✗ hygiene = danh từ gốc; ✗ hygienically = trạng từ; ✗ hygienist = danh từ chỉ người (chuyên viên vệ sinh) — cả hai không thể đứng song song với tính từ 'clean'."},
  {"type":"mcq","id":"wf-192","cat":"noun","base":"STARVE","q":"During the war, many families suffered from severe ___ (STARVE) due to a lack of food.","options":["starvation","starve","starving","starved"],"correct":0,"answer":"starvation","vi":"STARVE (chết đói - động từ) → starvation – nạn đói (danh từ)","explanation":"Sau giới từ 'from' và tính từ 'severe', cần DANH TỪ. Động từ 'starve' → danh từ 'starvation' (thêm -ation). ✗ starve = động từ gốc; ✗ starving = tính từ (đang đói); ✗ starved = tính từ (bị bỏ đói) — cả hai là tính từ, không thể đứng ở vị trí danh từ sau 'severe'."},
  {"type":"mcq","id":"wf-193","cat":"adj","base":"DEHYDRATE","q":"___ (DEHYDRATE) fruits like raisins and dried mango can be stored for months without spoiling.","options":["dehydrate","dehydrated","dehydration","dehydrator"],"correct":1,"answer":"dehydrated","vi":"DEHYDRATE (sấy khô - động từ) → dehydrated – đã sấy khô (tính từ)","explanation":"Đứng ngay trước danh từ 'fruits' làm chủ ngữ, cần TÍNH TỪ (dạng quá khứ phân từ) bổ nghĩa cho danh từ. Động từ 'dehydrate' → tính từ 'dehydrated' (thêm -ed). ✗ dehydrate = động từ gốc; ✗ dehydration = danh từ (sự mất nước); ✗ dehydrator = danh từ (máy sấy khô) — cả hai là danh từ, không thể đứng trước danh từ 'fruits' như tính từ."},
  {"type":"mcq","id":"wf-194","cat":"verb","base":"FERMENTATION","q":"Many Asian cuisines use bacteria to ___ (FERMENTATION) vegetables, creating dishes such as kimchi and pickles.","options":["fermentation","fermented","ferment","fermenter"],"correct":2,"answer":"ferment","vi":"FERMENTATION (sự lên men) → ferment – lên men (động từ)","explanation":"Sau 'to' trong cấu trúc 'use bacteria to + V', cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'fermentation' → động từ gốc 'ferment' (bỏ đuôi -ation). ✗ fermentation = danh từ (chính là từ gốc); ✗ fermented = tính từ (đã lên men); ✗ fermenter = danh từ (thiết bị lên men) — cả hai không thể đứng sau 'to' làm động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-195","cat":"verb","base":"POISONOUS","q":"If not prepared correctly, certain parts of the pufferfish can ___ (POISONOUS) anyone who eats them.","options":["poisonous","poisonously","poisoner","poison"],"correct":3,"answer":"poison","vi":"POISONOUS (độc) → poison – đầu độc (động từ)","explanation":"Sau động từ khuyết thiếu 'can', cần ĐỘNG TỪ nguyên mẫu. Tính từ 'poisonous' → động từ gốc 'poison' (bỏ đuôi -ous). ✗ poisonous = tính từ (chính là từ gốc trong ngoặc); ✗ poisonously = trạng từ; ✗ poisoner = danh từ (kẻ đầu độc) — cả hai không thể đứng ngay sau 'can'."},
  {"type":"mcq","id":"wf-196","cat":"verb","base":"SEASONING","q":"Professional chefs often ___ (SEASONING) their dishes with salt, pepper, and fresh herbs.","options":["season","seasoning","seasonal","seasonally"],"correct":0,"answer":"season","vi":"SEASONING (gia vị) → season – nêm gia vị (động từ)","explanation":"Chủ ngữ 'chefs' số nhiều, sau trạng từ tần suất 'often' cần ĐỘNG TỪ chính ở dạng nguyên mẫu. Danh từ 'seasoning' → động từ gốc 'season' (bỏ đuôi -ing). ✗ seasoning = danh từ (chính là từ gốc); ✗ seasonal = tính từ (theo mùa); ✗ seasonally = trạng từ — cả hai không thể làm động từ chính của câu."},
  {"type":"mcq","id":"wf-197","cat":"verb","base":"ENRICHMENT","q":"Food companies often add vitamins and minerals to ___ (ENRICHMENT) their products nutritionally.","options":["enrichment","enrich","enriched","enriching"],"correct":1,"answer":"enrich","vi":"ENRICHMENT (sự bổ sung dưỡng chất) → enrich – làm giàu dưỡng chất (động từ)","explanation":"Sau 'to' chỉ mục đích, cần ĐỘNG TỪ nguyên mẫu. Danh từ 'enrichment' → động từ gốc 'enrich' (bỏ đuôi -ment). ✗ enrichment = danh từ (chính là từ gốc); ✗ enriched = tính từ (đã được bổ sung); ✗ enriching = tính từ/danh động từ — cả hai không thể đứng sau 'to' làm động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-198","cat":"verb","base":"CRISPY","q":"___ (CRISPY) the bacon in a hot pan for about five minutes until it turns golden brown.","options":["crispy","crispness","crisp","crisply"],"correct":2,"answer":"crisp","vi":"CRISPY (giòn) → crisp – làm giòn (động từ)","explanation":"Đây là câu mệnh lệnh, đứng đầu câu cần ĐỘNG TỪ nguyên mẫu. Tính từ 'crispy' → động từ gốc 'crisp' (bỏ đuôi -y). ✗ crispy = tính từ (chính là từ gốc, giòn); ✗ crispness = danh từ (độ giòn); ✗ crisply = trạng từ — cả hai không thể làm động từ mở đầu câu mệnh lệnh."},
  {"type":"mcq","id":"wf-199","cat":"verb","base":"JUICY","q":"Many people like to ___ (JUICY) fresh oranges every morning to make a healthy drink.","options":["juicy","juiciness","juicer","juice"],"correct":3,"answer":"juice","vi":"JUICY (mọng nước) → juice – ép lấy nước (động từ)","explanation":"Sau 'to' trong cấu trúc 'like to + V', cần ĐỘNG TỪ nguyên mẫu. Tính từ 'juicy' → động từ gốc 'juice' (bỏ đuôi -y). ✗ juicy = tính từ (chính là từ gốc, mọng nước); ✗ juiciness = danh từ (độ mọng nước); ✗ juicer = danh từ (máy ép trái cây) — cả hai không thể đứng sau 'to' làm động từ."},
  {"type":"mcq","id":"wf-200","cat":"adv","base":"SWEET","q":"After we finished our meal, the waiter ___ (SWEET) offered us a free dessert as a surprise.","options":["sweetly","sweet","sweetness","sweeten"],"correct":0,"answer":"sweetly","vi":"SWEET (ngọt) → sweetly – một cách ngọt ngào, tử tế (trạng từ)","explanation":"Đứng trước động từ 'offered' và bổ nghĩa cho cách thức hành động, cần TRẠNG TỪ. Tính từ 'sweet' → trạng từ 'sweetly' (thêm -ly). ✗ sweet = tính từ gốc (ngọt); ✗ sweetness = danh từ (vị ngọt); ✗ sweeten = động từ (làm cho ngọt) — cả hai không thể bổ nghĩa cho động từ 'offered' như trạng từ."},
  {"type":"mcq","id":"wf-201","cat":"adv","base":"BITTER","q":"After tasting the burnt coffee, he complained ___ (BITTER) about the barista's mistake.","options":["bitter","bitterly","bitterness","embitter"],"correct":1,"answer":"bitterly","vi":"BITTER (đắng, cay đắng) → bitterly – một cách gay gắt (trạng từ)","explanation":"Sau động từ 'complained', cần TRẠNG TỪ chỉ cách thức (cụm cố định 'complain bitterly'). Tính từ 'bitter' → trạng từ 'bitterly' (thêm -ly). ✗ bitter = tính từ gốc (đắng); ✗ bitterness = danh từ (vị đắng, sự cay đắng); ✗ embitter = động từ (làm cay đắng) — cả hai không thể bổ nghĩa cho động từ 'complained' như trạng từ."},
  {"type":"mcq","id":"wf-202","cat":"verb","base":"EXCITE","q":"Meeting her favorite singer in person will really ___ (EXCITE) Lan.","options":["excitement","excited","excite","excitedly"],"correct":2,"answer":"excite","vi":"EXCITE (kích thích) → excite — làm ai đó phấn khích (động từ)","explanation":"Sau trợ động từ 'will' (và trạng từ 'really' chen giữa) cần một ĐỘNG TỪ nguyên mẫu có tân ngữ 'Lan'. Từ gốc 'excite' vốn đã là động từ, giữ nguyên dạng. ✗ excitement = danh từ; ✗ excited = tính từ; ✗ excitedly = trạng từ — đều không thể đứng ngay sau trợ động từ 'will'."},
  {"type":"mcq","id":"wf-203","cat":"verb","base":"FRIGHTEN","q":"Loud thunderstorms always ___ (FRIGHTEN) my little brother.","options":["fright","frightened","frighteningly","frighten"],"correct":3,"answer":"frighten","vi":"FRIGHTEN (làm sợ hãi) → frighten — làm ai đó sợ hãi (động từ)","explanation":"Chủ ngữ số nhiều 'thunderstorms' + trạng từ tần suất 'always' cần một ĐỘNG TỪ làm vị ngữ chính, có tân ngữ 'my little brother'. Từ gốc 'frighten' vốn đã là động từ, giữ nguyên. ✗ fright = danh từ; ✗ frightened = tính từ; ✗ frighteningly = trạng từ — đều không thể làm động từ chính của câu."},
  {"type":"mcq","id":"wf-204","cat":"verb","base":"AMAZE","q":"The magician's tricks never fail to ___ (AMAZE) the audience.","options":["amaze","amazement","amazed","amazingly"],"correct":0,"answer":"amaze","vi":"AMAZE (làm kinh ngạc) → amaze — làm ai đó kinh ngạc (động từ)","explanation":"Sau 'to' trong cụm 'fail to' cần một ĐỘNG TỪ nguyên mẫu, có tân ngữ 'the audience'. Từ gốc 'amaze' vốn là động từ, giữ nguyên. ✗ amazement = danh từ; ✗ amazed = tính từ; ✗ amazingly = trạng từ — đều sai vị trí sau 'to'."},
  {"type":"mcq","id":"wf-205","cat":"adj","base":"ASTONISH","q":"Everyone in the room was ___ (ASTONISH) at how quickly she solved the puzzle.","options":["astonishment","astonished","astonish","astonishingly"],"correct":1,"answer":"astonished","vi":"ASTONISH (làm sửng sốt) → astonished — cảm thấy sửng sốt (tính từ)","explanation":"Sau động từ liên kết 'was' cần một TÍNH TỪ mô tả cảm xúc của chủ ngữ 'everyone' (đúng cụm cố định 'astonished at'). Động từ 'astonish' + đuôi '-ed' → tính từ 'astonished'. ✗ astonishment = danh từ; ✗ astonish = động từ; ✗ astonishingly = trạng từ — đều sai vị trí sau 'was'."},
  {"type":"mcq","id":"wf-206","cat":"noun","base":"FASCINATE","q":"Marco Polo's writings revealed his deep ___ (FASCINATE) with Asian cultures.","options":["fascinate","fascinated","fascination","fascinatingly"],"correct":2,"answer":"fascination","vi":"FASCINATE (làm say mê) → fascination — sự say mê (danh từ)","explanation":"Sau tính từ sở hữu 'his' và tính từ 'deep' cần một DANH TỪ làm tân ngữ của 'revealed'. Động từ 'fascinate' + hậu tố '-ion' → danh từ 'fascination'. ✗ fascinate = động từ; ✗ fascinated = tính từ; ✗ fascinatingly = trạng từ — đều sai vị trí sau 'his deep'."},
  {"type":"mcq","id":"wf-207","cat":"noun","base":"DEPRESS","q":"Losing his job pushed him into a deep ___ (DEPRESS).","options":["depress","depressed","depressingly","depression"],"correct":3,"answer":"depression","vi":"DEPRESS (làm chán nản) → depression — sự trầm cảm (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'deep' cần một DANH TỪ. Động từ 'depress' + hậu tố '-ion' → danh từ 'depression'. ✗ depress = động từ; ✗ depressed = tính từ; ✗ depressingly = trạng từ — đều không thể đứng sau 'a deep'."},
  {"type":"mcq","id":"wf-208","cat":"noun","base":"EMBARRASS","q":"To his great ___ (EMBARRASS), Nam forgot his lines during the school play.","options":["embarrassment","embarrass","embarrassed","embarrassingly"],"correct":0,"answer":"embarrassment","vi":"EMBARRASS (làm xấu hổ) → embarrassment — sự xấu hổ (danh từ)","explanation":"Sau tính từ sở hữu 'his' và tính từ 'great' cần một DANH TỪ (cụm cố định 'to one's embarrassment' diễn tả cảm xúc). Động từ 'embarrass' + hậu tố '-ment' → danh từ 'embarrassment'. ✗ embarrass = động từ; ✗ embarrassed = tính từ; ✗ embarrassingly = trạng từ — đều sai vị trí sau 'his great'."},
  {"type":"mcq","id":"wf-209","cat":"verb","base":"DISAPPOINT","q":"I really hope this result won't ___ (DISAPPOINT) your parents.","options":["disappointment","disappoint","disappointed","disappointingly"],"correct":1,"answer":"disappoint","vi":"DISAPPOINT (làm thất vọng) → disappoint — làm ai đó thất vọng (động từ)","explanation":"Sau trợ động từ phủ định 'won't' cần một ĐỘNG TỪ nguyên mẫu, có tân ngữ 'your parents'. Từ gốc 'disappoint' đã là động từ, giữ nguyên. ✗ disappointment = danh từ; ✗ disappointed = tính từ; ✗ disappointingly = trạng từ — đều không đứng được sau 'won't'."},
  {"type":"mcq","id":"wf-210","cat":"adv","base":"SATISFY","q":"The mystery novel ended ___ (SATISFY), with every clue finally explained.","options":["satisfy","satisfaction","satisfied","satisfyingly"],"correct":3,"answer":"satisfyingly","vi":"SATISFY (làm hài lòng) → satisfyingly — một cách thỏa mãn (trạng từ)","explanation":"Sau động từ thường 'ended' cần một TRẠNG TỪ bổ nghĩa cho cách thức (câu chuyện tự nó không thể 'cảm thấy' hài lòng nên không dùng tính từ). Động từ 'satisfy' + đuôi '-ing' + '-ly' → trạng từ 'satisfyingly'. ✗ satisfy = động từ; ✗ satisfaction = danh từ; ✗ satisfied = tính từ (diễn tả cảm giác của người, không hợp với chủ ngữ 'the novel') — đều sai vị trí sau 'ended'."},
  {"type":"mcq","id":"wf-211","cat":"noun","base":"ENCOURAGE","q":"With constant ___ (ENCOURAGE) from her coach, she finally won the race.","options":["encouragement","encourage","encouraged","encouragingly"],"correct":0,"answer":"encouragement","vi":"ENCOURAGE (khích lệ) → encouragement — sự khích lệ (danh từ)","explanation":"Sau giới từ 'with' và tính từ 'constant' cần một DANH TỪ. Động từ 'encourage' + hậu tố '-ment' → danh từ 'encouragement'. ✗ encourage = động từ; ✗ encouraged = tính từ; ✗ encouragingly = trạng từ — đều sai vị trí sau giới từ 'with'."},
  {"type":"mcq","id":"wf-212","cat":"adv","base":"DISCOURAGE","q":"The coach spoke ___ (DISCOURAGE) about the team's chances of winning.","options":["discourage","discouragingly","discouragement","discouraged"],"correct":1,"answer":"discouragingly","vi":"DISCOURAGE (làm nản lòng) → discouragingly — một cách khiến người khác nản lòng (trạng từ)","explanation":"Sau động từ 'spoke' cần một TRẠNG TỪ bổ nghĩa cho cách nói (lời nói của huấn luyện viên khiến người nghe nản lòng). Động từ 'discourage' + đuôi '-ing' + '-ly' → trạng từ 'discouragingly'. ✗ discourage = động từ; ✗ discouragement = danh từ; ✗ discouraged = tính từ — đều sai vị trí sau 'spoke'."},
  {"type":"mcq","id":"wf-213","cat":"adj","base":"CONFUSE","q":"I was completely ___ (CONFUSE) by the teacher's instructions.","options":["confuse","confusion","confused","confusingly"],"correct":2,"answer":"confused","vi":"CONFUSE (làm bối rối) → confused — cảm thấy bối rối (tính từ)","explanation":"Sau động từ liên kết 'was' và trạng từ 'completely' cần một TÍNH TỪ mô tả cảm xúc của 'I'. Động từ 'confuse' + đuôi '-ed' → tính từ 'confused'. ✗ confuse = động từ; ✗ confusion = danh từ; ✗ confusingly = trạng từ — đều sai vị trí sau 'was completely'."},
  {"type":"mcq","id":"wf-214","cat":"adj","base":"IMPRESS","q":"The judges were very ___ (IMPRESS) with her singing performance.","options":["impress","impression","impressively","impressed"],"correct":3,"answer":"impressed","vi":"IMPRESS (gây ấn tượng) → impressed — cảm thấy ấn tượng (tính từ)","explanation":"Sau 'very' và động từ liên kết 'were' cần một TÍNH TỪ mô tả cảm xúc của chủ ngữ 'the judges'. Động từ 'impress' + đuôi '-ed' → tính từ 'impressed'. ✗ impress = động từ; ✗ impression = danh từ; ✗ impressively = trạng từ — đều sai vị trí sau 'very'."},
  {"type":"mcq","id":"wf-215","cat":"adj","base":"BORE","q":"The students looked ___ (BORE) during the two-hour lecture.","options":["bored","bore","boredom","boringly"],"correct":0,"answer":"bored","vi":"BORE (làm chán) → bored — cảm thấy chán (tính từ)","explanation":"Sau động từ liên kết 'looked' cần một TÍNH TỪ mô tả cảm giác của chủ ngữ 'the students'. Động từ 'bore' + đuôi '-ed' → tính từ 'bored'. ✗ bore = động từ/danh từ; ✗ boredom = danh từ; ✗ boringly = trạng từ — đều sai vị trí sau 'looked'."},
  {"type":"mcq","id":"wf-216","cat":"noun","base":"TERRIFY","q":"The children screamed in ___ (TERRIFY) when they saw the snake.","options":["terrify","terror","terrified","terrifyingly"],"correct":1,"answer":"terror","vi":"TERRIFY (làm kinh hoàng) → terror — nỗi kinh hoàng (danh từ)","explanation":"Sau giới từ 'in' cần một DANH TỪ (cụm cố định 'in terror' = trong sự kinh hoàng). Động từ 'terrify' có danh từ tương ứng là 'terror'. ✗ terrify = động từ; ✗ terrified = tính từ; ✗ terrifyingly = trạng từ — đều sai vị trí sau giới từ 'in'."},
  {"type":"mcq","id":"wf-217","cat":"adv","base":"HORRIFY","q":"The witness described the accident ___ (HORRIFY), leaving everyone speechless.","options":["horrify","horror","horrifyingly","horrified"],"correct":2,"answer":"horrifyingly","vi":"HORRIFY (làm kinh hãi) → horrifyingly — một cách kinh hãi (trạng từ)","explanation":"Sau động từ 'described' cần một TRẠNG TỪ bổ nghĩa cho cách thức miêu tả. Động từ 'horrify' + đuôi '-ing' + '-ly' → trạng từ 'horrifyingly'. ✗ horrify = động từ; ✗ horror = danh từ; ✗ horrified = tính từ (mô tả cảm giác của người, không thể đứng ngay sau 'described the accident') — đều sai vị trí sau 'described'."},
  {"type":"mcq","id":"wf-218","cat":"adv","base":"ANNOY","q":"My neighbor ___ (ANNOY) plays loud music late every night.","options":["annoy","annoyance","annoyed","annoyingly"],"correct":3,"answer":"annoyingly","vi":"ANNOY (làm khó chịu) → annoyingly — một cách khó chịu (trạng từ)","explanation":"Trước động từ thường 'plays' cần một TRẠNG TỪ chỉ thái độ của người nói về hành động đó. Động từ 'annoy' + đuôi '-ing' + '-ly' → trạng từ 'annoyingly'. ✗ annoy = động từ; ✗ annoyance = danh từ; ✗ annoyed = tính từ (không thể đứng trước động từ chia 'plays' mà không có động từ liên kết) — đều sai vị trí trước 'plays'."},
  {"type":"mcq","id":"wf-219","cat":"adj","base":"IRRITATE","q":"My mother gets ___ (IRRITATE) when we leave dirty dishes in the sink.","options":["irritated","irritate","irritation","irritatingly"],"correct":0,"answer":"irritated","vi":"IRRITATE (làm khó chịu, bực bội) → irritated — cảm thấy khó chịu (tính từ)","explanation":"Sau động từ liên kết 'gets' cần một TÍNH TỪ mô tả cảm xúc của chủ ngữ 'my mother'. Động từ 'irritate' + đuôi '-ed' → tính từ 'irritated'. ✗ irritate = động từ; ✗ irritation = danh từ; ✗ irritatingly = trạng từ — đều sai vị trí sau 'gets'."},
  {"type":"mcq","id":"wf-220","cat":"adv","base":"FRUSTRATE","q":"The internet connection was ___ (FRUSTRATE) slow, so she couldn't submit her homework on time.","options":["frustrate","frustration","frustratingly","frustrated"],"correct":2,"answer":"frustratingly","vi":"FRUSTRATE (làm bực bội) → frustratingly — một cách gây bực bội (trạng từ)","explanation":"Trước tính từ 'slow' cần một TRẠNG TỪ bổ nghĩa mức độ/cách thức, tạo cụm quen thuộc 'frustratingly slow' (chậm đến mức gây bực bội). Động từ 'frustrate' + đuôi '-ing' + '-ly' → trạng từ 'frustratingly'. ✗ frustrate = động từ; ✗ frustration = danh từ; ✗ frustrated = tính từ diễn tả cảm giác bực bội của MỘT NGƯỜI (đường truyền internet không thể 'cảm thấy' bực bội) nên không thể đứng trước 'slow' — cả ba đều sai vị trí."},
  {"type":"mcq","id":"wf-221","cat":"noun","base":"TIRE","q":"A feeling of ___ (TIRE) swept over her after the marathon.","options":["tire","tired","tiringly","tiredness"],"correct":3,"answer":"tiredness","vi":"TIRE (làm mệt) → tiredness — cảm giác mệt mỏi (danh từ)","explanation":"Sau giới từ 'of' cần một DANH TỪ. Động từ 'tire' + hậu tố '-dness' → danh từ 'tiredness'. ✗ tire = động từ; ✗ tired = tính từ; ✗ tiringly = trạng từ — đều sai vị trí sau giới từ 'of'."},
  {"type":"mcq","id":"wf-222","cat":"adj","base":"ADMIRE","q":"Her courage during the crisis was truly ___ (ADMIRE).","options":["admirable","admire","admiration","admiringly"],"correct":0,"answer":"admirable","vi":"ADMIRE (ngưỡng mộ) → admirable — đáng ngưỡng mộ (tính từ)","explanation":"Sau trạng từ 'truly' và động từ liên kết 'was' cần một TÍNH TỪ. Động từ 'admire' + hậu tố '-able' → tính từ 'admirable' (đáng được ngưỡng mộ). ✗ admire = động từ; ✗ admiration = danh từ; ✗ admiringly = trạng từ — đều sai vị trí sau 'was truly'."},
  {"type":"mcq","id":"wf-223","cat":"adv","base":"SYMPATHY","q":"The nurse listened ___ (SYMPATHY) to the frightened patient's story.","options":["sympathize","sympathetically","sympathy","sympathetic"],"correct":1,"answer":"sympathetically","vi":"SYMPATHY (sự cảm thông) → sympathetically — một cách cảm thông (trạng từ)","explanation":"Sau động từ 'listened' cần một TRẠNG TỪ bổ nghĩa cho cách thức lắng nghe. Danh từ gốc 'sympathy' → tính từ 'sympathetic' → trạng từ 'sympathetically'. ✗ sympathize = động từ; ✗ sympathy = danh từ; ✗ sympathetic = tính từ — đều sai vị trí sau động từ 'listened' (cần trạng từ, không phải tính từ)."},
  {"type":"mcq","id":"wf-224","cat":"verb","base":"PLEASE","q":"She always tries her best to ___ (PLEASE) her teachers and classmates.","options":["pleasure","pleasant","please","pleasantly"],"correct":2,"answer":"please","vi":"PLEASE (làm hài lòng) → please — làm ai đó hài lòng (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu, có tân ngữ 'her teachers and classmates'. Từ gốc 'please' vốn là động từ, giữ nguyên. ✗ pleasure = danh từ; ✗ pleasant = tính từ; ✗ pleasantly = trạng từ — đều sai vị trí sau 'to'."},
  {"type":"mcq","id":"wf-225","cat":"verb","base":"SAD","q":"The tragic news of the accident ___ (SAD) the whole neighborhood.","options":["sadness","sad","sadly","saddened"],"correct":3,"answer":"saddened","vi":"SAD (buồn) → saddened — làm ai đó buồn (động từ)","explanation":"Chủ ngữ số ít 'the tragic news' cần một ĐỘNG TỪ làm vị ngữ chính, có tân ngữ 'the whole neighborhood'. Tính từ gốc 'sad' + hậu tố '-en' → động từ 'sadden' (chia quá khứ: saddened). ✗ sadness = danh từ; ✗ sad = tính từ; ✗ sadly = trạng từ — đều không thể làm vị ngữ chính của câu."},
  {"type":"mcq","id":"wf-226","cat":"adj","base":"INFORM","q":"The new science channel is extremely ___ (INFORM); I learned so much from just one episode.","options":["informative","information","inform","informatively"],"correct":0,"answer":"informative","vi":"INFORM (thông báo) → informative - giàu thông tin, bổ ích (tính từ)","explanation":"Sau động từ 'to be' (is) và trạng từ chỉ mức độ 'extremely' cần một TÍNH TỪ để mô tả chủ ngữ 'channel'. Động từ 'inform' → tính từ 'informative' (thêm hậu tố -ative). ✗ information = danh từ; ✗ inform = động từ; ✗ informatively = trạng từ — đều sai vì sau 'to be + extremely' phải là tính từ."},
  {"type":"mcq","id":"wf-227","cat":"adv","base":"PERSUADE","q":"The salesman spoke so ___ (PERSUADE) that everyone in the room decided to buy the product.","options":["persuasion","persuasively","persuade","persuasive"],"correct":1,"answer":"persuasively","vi":"PERSUADE (thuyết phục) → persuasively - một cách thuyết phục (trạng từ)","explanation":"Cấu trúc 'so + ___ + that' bổ nghĩa cho động từ 'spoke' nên cần một TRẠNG TỪ. Tính từ 'persuasive' → trạng từ 'persuasively' (thêm đuôi -ly). ✗ persuasion = danh từ; ✗ persuade = động từ; ✗ persuasive = tính từ — đều sai vì không thể bổ nghĩa cho động từ 'spoke' ở vị trí này."},
  {"type":"mcq","id":"wf-228","cat":"verb","base":"EXPRESS","q":"During the interview, try to ___ (EXPRESS) your ideas clearly and confidently.","options":["expression","expressive","express","expressively"],"correct":2,"answer":"express","vi":"EXPRESS (diễn đạt) → express - diễn đạt, bày tỏ (động từ)","explanation":"Sau 'to' trong cấu trúc 'try to + V' luôn cần một ĐỘNG TỪ NGUYÊN MẪU. 'Express' là dạng động từ gốc. ✗ expression = danh từ; ✗ expressive = tính từ; ✗ expressively = trạng từ — đều sai vì sau 'to' chỉ nhận động từ."},
  {"type":"mcq","id":"wf-229","cat":"adj","base":"EDUCATE","q":"Many parents choose cartoons that are both fun and ___ (EDUCATE) for their children.","options":["education","educate","educationally","educational"],"correct":3,"answer":"educational","vi":"EDUCATE (giáo dục) → educational - mang tính giáo dục (tính từ)","explanation":"Sau liên từ 'and', song song với tính từ 'fun', cần một TÍNH TỪ để mô tả 'cartoons'. Động từ 'educate' → tính từ 'educational' (thêm hậu tố -al). ✗ education = danh từ; ✗ educate = động từ; ✗ educationally = trạng từ — đều sai vì phải song song từ loại với 'fun'."},
  {"type":"mcq","id":"wf-230","cat":"adv","base":"INTERACT","q":"Children today learn ___ (INTERACT) by using touch-screen apps instead of reading books.","options":["interaction","interactively","interact","interactive"],"correct":1,"answer":"interactively","vi":"INTERACT (tương tác) → interactively - một cách tương tác (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'learn' (học NHƯ THẾ NÀO) nên cần một TRẠNG TỪ. Tính từ 'interactive' → trạng từ 'interactively' (thêm đuôi -ly). ✗ interaction = danh từ; ✗ interact = động từ; ✗ interactive = tính từ — đều sai vì không thể bổ nghĩa cho động từ ở vị trí này."},
  {"type":"mcq","id":"wf-231","cat":"noun","base":"POPULAR","q":"The ___ (POPULAR) of social media has completely changed the way young people communicate.","options":["popular","popularize","popularity","popularly"],"correct":2,"answer":"popularity","vi":"POPULAR (phổ biến) → popularity - sự phổ biến (danh từ)","explanation":"Sau mạo từ 'The' và làm chủ ngữ của câu (trước 'of') cần một DANH TỪ. Tính từ 'popular' → danh từ 'popularity' (thêm hậu tố -ity). ✗ popular = tính từ; ✗ popularize = động từ; ✗ popularly = trạng từ — đều sai vì sau mạo từ 'the' cần danh từ."},
  {"type":"mcq","id":"wf-232","cat":"noun","base":"REACT","q":"The company was surprised by the public's negative ___ (REACT) to its new advertisement.","options":["react","reactive","reactively","reaction"],"correct":3,"answer":"reaction","vi":"REACT (phản ứng) → reaction - phản ứng (danh từ)","explanation":"Sau tính từ sở hữu 'the public's' và tính từ 'negative' cần một DANH TỪ làm tân ngữ của giới từ 'by'. Động từ 'react' → danh từ 'reaction' (thêm hậu tố -ion). ✗ react = động từ; ✗ reactive = tính từ; ✗ reactively = trạng từ — đều sai vì cụm này cần danh từ."},
  {"type":"mcq","id":"wf-233","cat":"adj","base":"RESPOND","q":"A good journalist must be ___ (RESPOND) to breaking news and update the story quickly.","options":["responsive","response","respond","responsively"],"correct":0,"answer":"responsive","vi":"RESPOND (phản hồi) → responsive - phản ứng nhanh nhạy (tính từ)","explanation":"Sau động từ 'to be' (must be) cần một TÍNH TỪ bổ nghĩa cho chủ ngữ 'journalist'. Động từ 'respond' → tính từ 'responsive' (thêm hậu tố -ive). ✗ response = danh từ; ✗ respond = động từ; ✗ responsively = trạng từ — đều sai vì sau 'to be' cần tính từ."},
  {"type":"mcq","id":"wf-234","cat":"verb","base":"TRANSLATE","q":"This app can ___ (TRANSLATE) messages into more than 100 languages instantly.","options":["translation","translate","translator","translatable"],"correct":1,"answer":"translate","vi":"TRANSLATE (dịch) → translate - dịch (động từ)","explanation":"Sau động từ khiếm khuyết 'can' luôn cần một ĐỘNG TỪ NGUYÊN MẪU. 'Translate' là dạng động từ gốc. ✗ translation = danh từ; ✗ translator = danh từ (người dịch); ✗ translatable = tính từ — đều sai vì sau 'can' chỉ nhận động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-235","cat":"verb","base":"PUBLISH","q":"The magazine will ___ (PUBLISH) the interview in its next issue.","options":["publication","publisher","publish","published"],"correct":2,"answer":"publish","vi":"PUBLISH (xuất bản) → publish - xuất bản (động từ)","explanation":"Sau trợ động từ 'will' cần một ĐỘNG TỪ NGUYÊN MẪU. 'Publish' là dạng động từ gốc. ✗ publication = danh từ; ✗ publisher = danh từ (nhà xuất bản); ✗ published = tính từ/quá khứ phân từ — đều sai vì sau 'will' chỉ nhận động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-236","cat":"verb","base":"ADVERTISE","q":"Many companies ___ (ADVERTISE) their products on social media instead of on television.","options":["advertisement","advertised","advertiser","advertise"],"correct":3,"answer":"advertise","vi":"ADVERTISE (quảng cáo) → advertise - quảng cáo (động từ)","explanation":"Chủ ngữ số nhiều 'companies' cần một ĐỘNG TỪ chia hiện tại đơn làm vị ngữ chính, đứng trước tân ngữ 'their products'. 'Advertise' là động từ gốc. ✗ advertisement = danh từ; ✗ advertised = tính từ/quá khứ phân từ; ✗ advertiser = danh từ (nhà quảng cáo) — đều sai vì câu cần một động từ."},
  {"type":"mcq","id":"wf-237","cat":"adv","base":"VISION","q":"Complicated data is often presented ___ (VISION) in charts so that viewers can understand it at a glance.","options":["visually","vision","visualize","visual"],"correct":0,"answer":"visually","vi":"VISION (thị giác) → visually - về mặt hình ảnh (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ bị động 'is presented' (được trình bày NHƯ THẾ NÀO) nên cần một TRẠNG TỪ. Tính từ 'visual' → trạng từ 'visually' (thêm đuôi -ly). ✗ vision = danh từ; ✗ visualize = động từ; ✗ visual = tính từ — đều sai vì không thể bổ nghĩa cho động từ ở vị trí này."},
  {"type":"mcq","id":"wf-238","cat":"noun","base":"CREDIBLE","q":"Readers should check the ___ (CREDIBLE) of a news source before sharing an article online.","options":["credible","credibility","credibly","discredit"],"correct":1,"answer":"credibility","vi":"CREDIBLE (đáng tin) → credibility - độ tin cậy (danh từ)","explanation":"Sau mạo từ 'the' và làm tân ngữ của động từ 'check' (trước 'of') cần một DANH TỪ. Tính từ 'credible' → danh từ 'credibility' (đổi đuôi -le thành -ility). ✗ credible = tính từ; ✗ credibly = trạng từ; ✗ discredit = động từ (làm mất uy tín) — đều sai vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-239","cat":"verb","base":"EXAGGERATE","q":"Some tabloid newspapers ___ (EXAGGERATE) small events to make their headlines more shocking.","options":["exaggeration","exaggerated","exaggerate","exaggeratedly"],"correct":2,"answer":"exaggerate","vi":"EXAGGERATE (phóng đại) → exaggerate - phóng đại (động từ)","explanation":"Chủ ngữ số nhiều 'newspapers' cần một ĐỘNG TỪ chia hiện tại đơn làm vị ngữ chính. 'Exaggerate' là động từ gốc. ✗ exaggeration = danh từ; ✗ exaggerated = tính từ (quá khứ phân từ); ✗ exaggeratedly = trạng từ — đều sai vì câu cần một động từ."},
  {"type":"mcq","id":"wf-240","cat":"adj","base":"JOURNAL","q":"She writes in a very ___ (JOURNAL) style, always checking her facts before publishing.","options":["journalistic","journalism","journalist","journal"],"correct":0,"answer":"journalistic","vi":"JOURNAL (tạp chí/nhật báo) → journalistic - mang phong cách báo chí (tính từ)","explanation":"Sau trạng từ 'very' và trước danh từ 'style' cần một TÍNH TỪ. Danh từ 'journal' → tính từ 'journalistic' (thêm hậu tố -istic). ✗ journalism = danh từ (nghề báo); ✗ journalist = danh từ (nhà báo); ✗ journal = danh từ (tạp chí) — đều sai vì vị trí này cần tính từ đứng trước danh từ 'style'."},
  {"type":"mcq","id":"wf-241","cat":"verb","base":"SUBSCRIBE","q":"If you want to watch new episodes every week, you need to ___ (SUBSCRIBE) to the channel.","options":["subscription","subscribe","subscriber","subscribed"],"correct":1,"answer":"subscribe","vi":"SUBSCRIBE (đăng ký theo dõi) → subscribe - đăng ký (động từ)","explanation":"Sau 'to' trong cấu trúc 'need to + V' cần một ĐỘNG TỪ NGUYÊN MẪU. 'Subscribe' là động từ gốc. ✗ subscription = danh từ; ✗ subscriber = danh từ (người đăng ký); ✗ subscribed = tính từ/quá khứ phân từ — đều sai vì sau 'to' chỉ nhận động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-242","cat":"adj","base":"INFLUENCE","q":"Social media stars can be extremely ___ (INFLUENCE) in shaping what teenagers buy and wear.","options":["influence","influencer","influential","influentially"],"correct":2,"answer":"influential","vi":"INFLUENCE (ảnh hưởng) → influential - có sức ảnh hưởng lớn (tính từ)","explanation":"Sau động từ 'to be' (can be) và trạng từ 'extremely' cần một TÍNH TỪ bổ nghĩa cho chủ ngữ. Danh từ/động từ 'influence' → tính từ 'influential' (thêm hậu tố -ial). ✗ influence = danh từ/động từ; ✗ influencer = danh từ (người có sức ảnh hưởng); ✗ influentially = trạng từ — đều sai vì sau 'extremely + to be' cần tính từ."},
  {"type":"mcq","id":"wf-243","cat":"noun","base":"CONNECT","q":"A stable internet ___ (CONNECT) is necessary for online video calls.","options":["connect","connected","disconnect","connection"],"correct":3,"answer":"connection","vi":"CONNECT (kết nối) → connection - sự kết nối (danh từ)","explanation":"Đứng làm chủ ngữ chính của câu, sau tính từ 'stable' và danh từ bổ nghĩa 'internet', cần một DANH TỪ. Động từ 'connect' → danh từ 'connection' (thêm hậu tố -ion). ✗ connect = động từ; ✗ connected = tính từ; ✗ disconnect = động từ (ngắt kết nối) — đều sai vì vị trí chủ ngữ cần danh từ."},
  {"type":"mcq","id":"wf-244","cat":"adv","base":"TECHNOLOGY","q":"The way we get news has changed ___ (TECHNOLOGY) over the last twenty years.","options":["technologically","technology","technological","technologist"],"correct":0,"answer":"technologically","vi":"TECHNOLOGY (công nghệ) → technologically - về mặt công nghệ (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'has changed' (thay đổi NHƯ THẾ NÀO/VỀ MẶT GÌ) nên cần một TRẠNG TỪ. Danh từ 'technology' → tính từ 'technological' + đuôi -ly → trạng từ 'technologically'. ✗ technology = danh từ; ✗ technological = tính từ; ✗ technologist = danh từ (nhà công nghệ học) — đều sai vì không thể bổ nghĩa cho động từ ở vị trí này."},
  {"type":"mcq","id":"wf-245","cat":"verb","base":"RICH","q":"The company's rapid growth eventually ___ (RICH) many of its early investors.","options":["rich","enriched","richly","riches"],"correct":1,"answer":"enriched","vi":"RICH (giàu có) → enrich – làm giàu cho (động từ)","explanation":"Đây là ĐỘNG TỪ chính (vị ngữ) của câu, đứng sau trạng từ 'eventually', chia ở dạng quá khứ vì câu kể lại việc đã xảy ra. Tính từ 'rich' thêm tiền tố en- thành động từ 'enrich' (làm giàu), chia quá khứ 'enriched'. ✗ rich = tính từ (gốc); ✗ richly = trạng từ; ✗ riches = danh từ (của cải) — đều sai vị trí vì câu cần động từ."},
  {"type":"mcq","id":"wf-246","cat":"verb","base":"LARGE","q":"The bank decided to ___ (LARGE) its network of branches to serve more customers across the country.","options":["large","largely","enlarge","enlargement"],"correct":2,"answer":"enlarge","vi":"LARGE (lớn) → enlarge – mở rộng, làm to hơn (động từ)","explanation":"Sau 'decided to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'large' thêm tiền tố en- thành động từ 'enlarge' (mở rộng quy mô, số lượng — hợp với 'mạng lưới chi nhánh'). ✗ large = tính từ (gốc); ✗ largely = trạng từ (phần lớn); ✗ enlargement = danh từ (sự mở rộng) — đều sai vị trí vì cần động từ sau 'to'."},
  {"type":"mcq","id":"wf-247","cat":"noun","base":"MANAGE","q":"She was promoted to become the store's new ___ (MANAGE) last month.","options":["manage","manageable","managerial","manager"],"correct":3,"answer":"manager","vi":"MANAGE (quản lý) → manager – người quản lý (danh từ)","explanation":"Sau cụm sở hữu 'the store's new' cần một DANH TỪ chỉ người, làm bổ ngữ cho 'become'. Động từ 'manage' thêm hậu tố -er thành danh từ 'manager'. ✗ manage = động từ (gốc); ✗ manageable = tính từ (có thể quản lý được); ✗ managerial = tính từ (thuộc về quản lý) — đều sai vị trí vì câu cần danh từ."},
  {"type":"mcq","id":"wf-248","cat":"noun","base":"EXPAND","q":"The company is planning a rapid ___ (EXPAND) into overseas markets next year.","options":["expansion","expand","expansive","expansively"],"correct":0,"answer":"expansion","vi":"EXPAND (mở rộng) → expansion – sự mở rộng (danh từ)","explanation":"Sau tính từ 'rapid' cần một DANH TỪ làm tân ngữ của 'planning'. Động từ 'expand' đổi thành danh từ 'expansion'. ✗ expand = động từ (gốc); ✗ expansive = tính từ (rộng lớn, cởi mở); ✗ expansively = trạng từ — đều sai vị trí vì câu cần danh từ."},
  {"type":"mcq","id":"wf-249","cat":"noun","base":"QUALIFY","q":"Every applicant must have the right educational ___ (QUALIFY) for this managerial position.","options":["qualify","qualifications","qualified","qualifying"],"correct":1,"answer":"qualifications","vi":"QUALIFY (đủ điều kiện, đạt tiêu chuẩn) → qualifications – bằng cấp, tiêu chuẩn (danh từ, thường dùng số nhiều)","explanation":"Sau các tính từ 'right educational' cần một DANH TỪ làm tân ngữ của 'have'; khi nói về bằng cấp/tiêu chuẩn cần có cho một công việc, tiếng Anh thường dùng dạng số nhiều 'qualifications'. Động từ 'qualify' đổi thành danh từ 'qualification(s)'. ✗ qualify = động từ (gốc); ✗ qualified = tính từ (đã đạt tiêu chuẩn); ✗ qualifying = tính từ (mang tính vòng loại/điều kiện) — đều sai vị trí vì câu cần danh từ."},
  {"type":"mcq","id":"wf-250","cat":"adj","base":"ECONOMY","q":"The country's ___ (ECONOMY) situation improved significantly after the reforms.","options":["economy","economically","economize","economic"],"correct":3,"answer":"economic","vi":"ECONOMY (nền kinh tế) → economic – thuộc về kinh tế (tính từ)","explanation":"Sau sở hữu cách 'the country's' và trước danh từ 'situation' cần một TÍNH TỪ. Danh từ 'economy' thêm hậu tố -ic thành tính từ 'economic'. ✗ economy = danh từ (gốc); ✗ economically = trạng từ; ✗ economize = động từ (nghĩa: tiết kiệm) — đều sai vị trí vì câu cần tính từ đứng trước danh từ."},
  {"type":"mcq","id":"wf-251","cat":"adj","base":"FINANCE","q":"Before signing the contract, the company carried out a careful ___ (FINANCE) analysis of the deal.","options":["financial","finance","financially","financier"],"correct":0,"answer":"financial","vi":"FINANCE (tài chính) → financial – thuộc về tài chính (tính từ)","explanation":"Sau tính từ 'careful' và trước danh từ 'analysis' cần một TÍNH TỪ. Danh từ/động từ 'finance' thêm hậu tố -ial thành tính từ 'financial'. ✗ finance = danh từ/động từ (gốc); ✗ financially = trạng từ; ✗ financier = danh từ chỉ người (nhà tài trợ vốn) — đều sai vị trí."},
  {"type":"mcq","id":"wf-252","cat":"adj","base":"ADEQUATE","q":"The small company's ___ (ADEQUATE) marketing budget led to disappointing sales figures.","options":["adequacy","inadequate","adequately","inadequacy"],"correct":1,"answer":"inadequate","vi":"ADEQUATE (đủ, thoả đáng) → inadequate – không đủ, không thoả đáng (tính từ, tiền tố phủ định in-)","explanation":"Sau sở hữu cách 'the small company's' và trước cụm danh từ 'marketing budget' cần một TÍNH TỪ. Vì ngân sách khiến doanh số ĐÁNG THẤT VỌNG, cần nghĩa phủ định: thêm tiền tố in- vào 'adequate' → 'inadequate' (không đủ). ✗ adequacy = danh từ (sự đầy đủ); ✗ adequately = trạng từ; ✗ inadequacy = danh từ (sự thiếu hụt) — đều sai vị trí vì câu cần tính từ."},
  {"type":"mcq","id":"wf-253","cat":"adj","base":"ORGANIZE","q":"An ___ (ORGANIZE) filing system helps employees find important documents quickly.","options":["organize","organization","organized","organizer"],"correct":2,"answer":"organized","vi":"ORGANIZE (tổ chức, sắp xếp) → organized – có tổ chức, ngăn nắp (tính từ)","explanation":"Sau mạo từ 'An' (dùng 'an' vì 'organized' bắt đầu bằng âm nguyên âm) và trước cụm danh từ 'filing system' cần một TÍNH TỪ. Động từ 'organize' thêm đuôi -d thành tính từ dạng phân từ 'organized'. ✗ organize = động từ (gốc); ✗ organization = danh từ (tổ chức); ✗ organizer = danh từ (người/vật tổ chức) — đều sai vị trí vì câu cần tính từ."},
  {"type":"mcq","id":"wf-254","cat":"adv","base":"PROFIT","q":"The small startup managed to run its business ___ (PROFIT) despite the tough market conditions.","options":["profit","profitable","profiteer","profitably"],"correct":3,"answer":"profitably","vi":"PROFIT (lợi nhuận) → profitably – một cách có lợi nhuận (trạng từ)","explanation":"Bổ nghĩa cho động từ 'run' (điều hành) cần một TRẠNG TỪ. Danh từ 'profit' thêm hậu tố -ably thành trạng từ 'profitably'. ✗ profit = danh từ/động từ (gốc); ✗ profitable = tính từ; ✗ profiteer = danh từ (kẻ trục lợi) — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-255","cat":"adv","base":"SIGNIFY","q":"Online shopping has ___ (SIGNIFY) changed the way small businesses reach their customers.","options":["significantly","signify","significant","significance"],"correct":0,"answer":"significantly","vi":"SIGNIFY (biểu thị, có ý nghĩa) → significantly – một cách đáng kể (trạng từ)","explanation":"Đứng giữa trợ động từ 'has' và động từ chính 'changed' cần một TRẠNG TỪ. Động từ 'signify' đổi thành trạng từ 'significantly'. ✗ signify = động từ (gốc); ✗ significant = tính từ; ✗ significance = danh từ (tầm quan trọng) — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-256","cat":"adv","base":"LEGAL","q":"The company must handle all its contracts ___ (LEGAL) to avoid future disputes.","options":["legal","legally","legality","legalize"],"correct":1,"answer":"legally","vi":"LEGAL (hợp pháp) → legally – một cách hợp pháp (trạng từ)","explanation":"Bổ nghĩa cho động từ 'handle' cần một TRẠNG TỪ. Tính từ 'legal' thêm hậu tố -ly thành trạng từ 'legally'. ✗ legal = tính từ (gốc); ✗ legality = danh từ (tính hợp pháp); ✗ legalize = động từ (hợp pháp hoá) — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-257","cat":"adv","base":"HONEST","q":"The manager was fired for ___ (HONEST) reporting the company's financial losses to investors.","options":["honest","honesty","dishonestly","dishonest"],"correct":2,"answer":"dishonestly","vi":"HONEST (trung thực) → dishonestly – một cách không trung thực (trạng từ, tiền tố phủ định dis-)","explanation":"Bổ nghĩa cho danh động từ 'reporting' cần một TRẠNG TỪ. Vì người quản lý bị sa thải do hành vi sai trái, cần trạng từ mang nghĩa phủ định: thêm tiền tố dis- vào 'honestly' → 'dishonestly'. ✗ honest = tính từ (gốc, nghĩa tích cực nên không hợp ngữ cảnh); ✗ honesty = danh từ; ✗ dishonest = tính từ (không phải trạng từ) — đều sai vị trí hoặc từ loại."},
  {"type":"mcq","id":"wf-258","cat":"adv","base":"CONVENIENT","q":"The new shopping mall is ___ (CONVENIENT) located right next to the bus station.","options":["convenient","convenience","inconvenient","conveniently"],"correct":3,"answer":"conveniently","vi":"CONVENIENT (thuận tiện) → conveniently – một cách thuận tiện (trạng từ)","explanation":"Bổ nghĩa cho phân từ 'located' cần một TRẠNG TỪ. Tính từ 'convenient' thêm hậu tố -ly thành trạng từ 'conveniently'. ✗ convenient = tính từ (gốc); ✗ convenience = danh từ (sự tiện lợi); ✗ inconvenient = tính từ phủ định (bất tiện) — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-259","cat":"adj","base":"HISTORY","q":"The old citadel in Hue is a ___ (HISTORY) site visited by thousands of tourists every year.","options":["historical","history","historically","historian"],"correct":0,"answer":"historical","vi":"HISTORY (lịch sử) → historical — thuộc về lịch sử (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'site' cần một TÍNH TỪ để bổ nghĩa. Danh từ 'history' → tính từ 'historical' (thêm đuôi -ical). ✗ history = danh từ (lịch sử); ✗ historically = trạng từ (về mặt lịch sử); ✗ historian = danh từ chỉ người (nhà sử học) — đều sai từ loại, không thể đứng trước danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-260","cat":"noun","base":"CIVIL","q":"Ancient Egyptian ___ (CIVIL) made great contributions to mathematics and architecture.","options":["civil","civilize","civilization","civilly"],"correct":2,"answer":"civilization","vi":"CIVIL (dân sự, thuộc về công dân - gốc) → civilization — nền văn minh (danh từ)","explanation":"Từ 'Egyptian' cần đi kèm một DANH TỪ để làm chủ ngữ của động từ 'made'. Tính từ gốc 'civil' → danh từ 'civilization' (thêm hậu tố -ization). ✗ civil = tính từ (thuộc về dân sự); ✗ civilize = động từ (khai hóa văn minh); ✗ civilly = trạng từ — đều không thể làm chủ ngữ của câu."},
  {"type":"mcq","id":"wf-261","cat":"adv","base":"TRADITION","q":"Vietnamese people ___ (TRADITION) celebrate Tet with family reunions and ancestral worship.","options":["tradition","traditional","traditionalist","traditionally"],"correct":3,"answer":"traditionally","vi":"TRADITION (truyền thống) → traditionally — theo truyền thống (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'celebrate', đứng giữa chủ ngữ 'Vietnamese people' và động từ, cần một TRẠNG TỪ. Danh từ 'tradition' → tính từ 'traditional' → trạng từ 'traditionally' (thêm -ly). ✗ tradition = danh từ; ✗ traditional = tính từ; ✗ traditionalist = danh từ (người theo chủ nghĩa truyền thống) — đều không thể bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-262","cat":"adj","base":"COLONY","q":"Many African countries were once under ___ (COLONY) rule before gaining independence.","options":["colonial","colony","colonize","colonization"],"correct":0,"answer":"colonial","vi":"COLONY (thuộc địa) → colonial — thuộc về thời thuộc địa (tính từ)","explanation":"Sau giới từ 'under' và trước danh từ 'rule' cần một TÍNH TỪ bổ nghĩa. Danh từ 'colony' → tính từ 'colonial' (thêm -al, đổi y→i). ✗ colony = danh từ; ✗ colonize = động từ (đô hộ, biến thành thuộc địa); ✗ colonization = danh từ (sự đô hộ) — đều không thể đứng trước danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-263","cat":"verb","base":"REVOLUTION","q":"The invention of the internet completely ___ (REVOLUTION) the way people access historical information.","options":["revolution","revolutionized","revolutionary","revolutionist"],"correct":1,"answer":"revolutionized","vi":"REVOLUTION (cuộc cách mạng - danh từ gốc) → revolutionized — đã cách mạng hóa (động từ, quá khứ)","explanation":"Câu cần một ĐỘNG TỪ chính ở thì quá khứ làm vị ngữ (theo sau trạng từ 'completely'). Danh từ 'revolution' → động từ 'revolutionize' (thêm -ize), chia quá khứ 'revolutionized'. ✗ revolution = danh từ; ✗ revolutionary = tính từ; ✗ revolutionist = danh từ chỉ người (người theo chủ nghĩa cách mạng) — đều không thể làm vị ngữ chính của câu."},
  {"type":"mcq","id":"wf-264","cat":"adj","base":"EMPIRE","q":"The Great Wall was built to protect the ___ (EMPIRE) capital from northern invaders.","options":["empire","imperialism","imperial","imperially"],"correct":2,"answer":"imperial","vi":"EMPIRE (đế chế) → imperial — thuộc về đế chế (tính từ)","explanation":"Trước danh từ 'capital' cần một TÍNH TỪ bổ nghĩa. Danh từ 'empire' → tính từ 'imperial' (dạng tính từ đặc biệt cùng gốc Latin 'imperium', không thêm hậu tố trực tiếp vào 'empire'). ✗ empire = danh từ; ✗ imperialism = danh từ (chủ nghĩa đế quốc); ✗ imperially = trạng từ — đều không thể đứng trước danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-265","cat":"noun","base":"EXPLORE","q":"The ___ (EXPLORE) of the New World in the 15th century changed the course of history.","options":["explore","exploratory","unexplored","exploration"],"correct":3,"answer":"exploration","vi":"EXPLORE (khám phá, thám hiểm - động từ gốc) → exploration — cuộc thám hiểm (danh từ)","explanation":"Sau mạo từ 'The', từ cần điền làm CHỦ NGỮ của động từ 'changed', nên cần một DANH TỪ. Động từ 'explore' → danh từ 'exploration' (thêm -ation). ✗ explore = động từ; ✗ exploratory = tính từ (có tính thăm dò); ✗ unexplored = tính từ (chưa được khám phá) — đều không thể làm chủ ngữ."},
  {"type":"mcq","id":"wf-266","cat":"adv","base":"GRADUAL","q":"Human civilization ___ (GRADUAL) evolved from small farming communities into complex societies over thousands of years.","options":["gradually","gradual","gradation","gradualness"],"correct":0,"answer":"gradually","vi":"GRADUAL (dần dần - tính từ gốc) → gradually — một cách dần dần (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'evolved', đứng giữa chủ ngữ và động từ chính, cần TRẠNG TỪ. Tính từ 'gradual' → trạng từ 'gradually' (thêm -ly). ✗ gradual = tính từ; ✗ gradation = danh từ (sự chuyển biến từng bậc); ✗ gradualness = danh từ (tính chất dần dần) — đều sai từ loại để bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-267","cat":"adj","base":"GLORY","q":"The ancient kingdom enjoyed a ___ (GLORY) period of peace and prosperity for two centuries.","options":["glory","glorious","gloriously","glorify"],"correct":1,"answer":"glorious","vi":"GLORY (vinh quang) → glorious — huy hoàng, vinh quang (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'period' cần một TÍNH TỪ. Danh từ 'glory' → tính từ 'glorious' (đổi y→i, thêm -ous). ✗ glory = danh từ; ✗ gloriously = trạng từ; ✗ glorify = động từ (tôn vinh) — đều sai từ loại cho vị trí này."},
  {"type":"mcq","id":"wf-268","cat":"adv","base":"CONTINUE","q":"This ancient festival has been ___ (CONTINUE) celebrated for over five hundred years.","options":["continue","continuous","continuously","continuity"],"correct":2,"answer":"continuously","vi":"CONTINUE (tiếp tục - động từ gốc) → continuously — một cách liên tục (trạng từ)","explanation":"Trạng từ đứng giữa 'been' và phân từ 'celebrated' để bổ nghĩa cho phân từ đó, cần TRẠNG TỪ. Động từ 'continue' → tính từ 'continuous' → trạng từ 'continuously' (thêm -ly). ✗ continue = động từ; ✗ continuous = tính từ; ✗ continuity = danh từ (tính liên tục) — đều sai từ loại ở vị trí bổ nghĩa cho phân từ."},
  {"type":"mcq","id":"wf-269","cat":"verb","base":"ORIGIN","q":"Many modern democratic ideas ___ (ORIGIN) from ancient Greek civilization.","options":["origin","original","originally","originate"],"correct":3,"answer":"originate","vi":"ORIGIN (nguồn gốc - danh từ gốc) → originate — bắt nguồn (động từ)","explanation":"Câu cần một ĐỘNG TỪ chính chia theo chủ ngữ số nhiều 'ideas' (không thêm -s). Danh từ 'origin' → động từ 'originate' (thêm -ate). ✗ origin = danh từ; ✗ original = tính từ; ✗ originally = trạng từ — đều không thể làm vị ngữ chính của câu."},
  {"type":"mcq","id":"wf-270","cat":"adj","base":"FAME","q":"Angkor Wat is a ___ (FAME) historical monument known all over the world.","options":["fame","famous","famously","infamy"],"correct":1,"answer":"famous","vi":"FAME (danh tiếng) → famous — nổi tiếng (tính từ)","explanation":"Sau mạo từ 'a' cần một TÍNH TỪ đứng trước cụm danh từ 'historical monument'. Danh từ 'fame' → tính từ 'famous' (thêm -ous). ✗ fame = danh từ; ✗ famously = trạng từ; ✗ infamy = danh từ (mang nghĩa tai tiếng, khác nghĩa) — đều không phải tính từ nên không thể bổ nghĩa cho danh từ."},
  {"type":"mcq","id":"wf-271","cat":"adv","base":"EVENT","q":"After years of struggle, the colony ___ (EVENT) gained its independence.","options":["event","eventual","eventually","eventuality"],"correct":2,"answer":"eventually","vi":"EVENT (sự kiện) → eventually — cuối cùng, rốt cuộc (trạng từ)","explanation":"Trạng từ bổ nghĩa cho động từ 'gained', đứng giữa chủ ngữ 'the colony' và động từ, cần TRẠNG TỪ. Danh từ 'event' → tính từ 'eventual' → trạng từ 'eventually' (thêm -ly). ✗ event = danh từ; ✗ eventual = tính từ; ✗ eventuality = danh từ (khả năng xảy ra) — đều sai từ loại để bổ nghĩa cho động từ."},
  {"type":"mcq","id":"wf-272","cat":"verb","base":"SHORT","q":"New archaeological findings have ___ (SHORT) the estimated timeline of human civilization by several thousand years.","options":["short","shortly","shortness","shortened"],"correct":3,"answer":"shortened","vi":"SHORT (ngắn - tính từ gốc) → shortened — đã rút ngắn (động từ, quá khứ phân từ)","explanation":"Sau trợ động từ 'have' cần một ĐỘNG TỪ ở dạng quá khứ phân từ để tạo thì hiện tại hoàn thành. Tính từ 'short' → động từ 'shorten' (thêm -en), phân từ 'shortened'. ✗ short = tính từ; ✗ shortly = trạng từ (chẳng bao lâu nữa); ✗ shortness = danh từ (sự ngắn gọn) — đều không thể đứng sau 'have' để chia thì hoàn thành."},
  {"type":"mcq","id":"wf-273","cat":"adj","base":"MYTH","q":"The story of Atlantis is often considered a ___ (MYTH) tale rather than real history.","options":["mythical","myth","mythology","mythologize"],"correct":0,"answer":"mythical","vi":"MYTH (thần thoại, huyền thoại) → mythical — mang tính huyền thoại (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'tale' cần một TÍNH TỪ. Danh từ 'myth' → tính từ 'mythical' (thêm -ical). ✗ myth = danh từ; ✗ mythology = danh từ (thần thoại học); ✗ mythologize = động từ (thần thoại hóa) — đều không thể đứng trước danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-274","cat":"noun","base":"DEPEND","q":"The colony finally achieved its ___ (DEPEND) from foreign rule in 1954.","options":["depend","independence","dependent","dependently"],"correct":1,"answer":"independence","vi":"DEPEND (phụ thuộc - động từ gốc) → independence — nền độc lập (danh từ, tiền tố phủ định in-)","explanation":"Sau tính từ sở hữu 'its' cần một DANH TỪ làm tân ngữ của động từ 'achieved'. Động từ 'depend' → danh từ 'independence' (thêm tiền tố phủ định in- và hậu tố -ence). ✗ depend = động từ; ✗ dependent = tính từ (phụ thuộc); ✗ dependently = trạng từ — đều sai từ loại cho vị trí sau 'its'."},
  {"type":"mcq","id":"wf-275","cat":"adv","base":"PERMANENT","q":"The ancient monument was ___ (PERMANENT) damaged during the war and could never be fully restored.","options":["permanent","permanence","permanently","impermanent"],"correct":2,"answer":"permanently","vi":"PERMANENT (vĩnh viễn - tính từ gốc) → permanently — một cách vĩnh viễn (trạng từ)","explanation":"Trạng từ đứng giữa 'was' và phân từ 'damaged' để bổ nghĩa cho phân từ đó, cần TRẠNG TỪ. Tính từ 'permanent' → trạng từ 'permanently' (thêm -ly). ✗ permanent = tính từ; ✗ permanence = danh từ (tính vĩnh viễn); ✗ impermanent = tính từ mang nghĩa phủ định (không vĩnh viễn) — đều sai từ loại ở vị trí này."},
  {"type":"mcq","id":"wf-276","cat":"verb","base":"SYMBOL","q":"The fall of the ancient wall ___ (SYMBOL) the end of a long historical era.","options":["symbol","symbolic","symbolically","symbolized"],"correct":3,"answer":"symbolized","vi":"SYMBOL (biểu tượng - danh từ gốc) → symbolized — đã tượng trưng cho (động từ, quá khứ)","explanation":"Câu cần một ĐỘNG TỪ chính ở thì quá khứ làm vị ngữ (chủ ngữ là 'The fall of the ancient wall'). Danh từ 'symbol' → động từ 'symbolize' (thêm -ize), chia quá khứ 'symbolized'. ✗ symbol = danh từ; ✗ symbolic = tính từ; ✗ symbolically = trạng từ — đều không thể làm vị ngữ chính của câu."},
  {"type":"mcq","id":"wf-277","cat":"noun","base":"EQUAL","q":"Fighting for gender ___ (EQUAL) has become one of the most important goals of modern society.","options":["equality","equal","equally","equalize"],"correct":0,"answer":"equality","vi":"EQUAL (bình đẳng - tính từ) → equality - sự bình đẳng (danh từ)","explanation":"Sau danh từ ghép 'gender' và làm tân ngữ của giới từ 'for' cần một DANH TỪ ('gender equality' = sự bình đẳng giới). Tính từ gốc 'equal' → thêm hậu tố '-ity' thành danh từ 'equality'. ✗ equal = tính từ; ✗ equally = trạng từ; ✗ equalize = động từ — đều sai vì không thể làm tân ngữ danh từ ở vị trí này."},
  {"type":"mcq","id":"wf-278","cat":"noun","base":"DIVERSE","q":"___ (DIVERSE) is one of the greatest strengths of a multicultural community.","options":["diverse","diversity","diversely","diversify"],"correct":1,"answer":"diversity","vi":"DIVERSE (đa dạng - tính từ) → diversity - sự đa dạng (danh từ)","explanation":"Từ đứng đầu câu, làm CHỦ NGỮ của động từ 'is' nên cần một DANH TỪ. Tính từ gốc 'diverse' → thêm hậu tố '-ity' thành danh từ 'diversity'. ✗ diverse = tính từ; ✗ diversely = trạng từ; ✗ diversify = động từ — đều không thể làm chủ ngữ ở vị trí này."},
  {"type":"mcq","id":"wf-279","cat":"noun","base":"TOLERATE","q":"Schools should teach students ___ (TOLERATE) towards people from different backgrounds.","options":["tolerate","tolerant","tolerance","tolerantly"],"correct":2,"answer":"tolerance","vi":"TOLERATE (khoan dung, chịu đựng - động từ) → tolerance - sự khoan dung (danh từ)","explanation":"Sau cấu trúc 'teach sb + tân ngữ' (dạy ai đó điều gì) cần một DANH TỪ làm tân ngữ trực tiếp. Động từ gốc 'tolerate' → đổi đuôi '-ate' thành '-ance' để có danh từ 'tolerance'. ✗ tolerate = động từ; ✗ tolerant = tính từ; ✗ tolerantly = trạng từ — đều sai vị trí vì đây là tân ngữ danh từ."},
  {"type":"mcq","id":"wf-280","cat":"noun","base":"HUMAN","q":"Volunteers showed great ___ (HUMAN) by helping flood victims rebuild their homes.","options":["humanity","human","humanly","humanize"],"correct":0,"answer":"humanity","vi":"HUMAN (con người - danh từ/tính từ) → humanity - lòng nhân đạo (danh từ)","explanation":"Sau động từ 'showed' cần một DANH TỪ làm tân ngữ ('show + noun' = thể hiện điều gì). Từ gốc 'human' → thêm hậu tố '-ity' thành danh từ 'humanity' (lòng nhân đạo). ✗ human = tính từ/danh từ chỉ người; ✗ humanly = trạng từ (vd 'humanly possible'); ✗ humanize = động từ — đều sai vì không thể là tân ngữ trực tiếp ở đây."},
  {"type":"mcq","id":"wf-281","cat":"adj","base":"SOCIETY","q":"Older people often suffer from ___ (SOCIETY) isolation when they live far from their families.","options":["society","social","socially","socialize"],"correct":1,"answer":"social","vi":"SOCIETY (xã hội - danh từ) → social - thuộc về xã hội (tính từ)","explanation":"Đứng trước danh từ 'isolation' cần một TÍNH TỪ để bổ nghĩa cho danh từ đó ('social isolation' = sự cô lập xã hội). Danh từ gốc 'society' → đổi thành tính từ 'social'. ✗ society = danh từ; ✗ socially = trạng từ; ✗ socialize = động từ — đều sai vì không thể đứng trước danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-282","cat":"adj","base":"NATION","q":"The government launched a ___ (NATION) campaign to encourage community recycling programs.","options":["nation","nationally","national","nationalize"],"correct":2,"answer":"national","vi":"NATION (quốc gia - danh từ) → national - mang tính quốc gia (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'campaign' cần một TÍNH TỪ. Danh từ gốc 'nation' → thêm hậu tố '-al' thành tính từ 'national'. ✗ nation = danh từ; ✗ nationally = trạng từ; ✗ nationalize = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-283","cat":"adj","base":"RESPECT","q":"It is important to be ___ (RESPECT) towards elderly members of the community.","options":["respect","respectfully","disrespect","respectful"],"correct":3,"answer":"respectful","vi":"RESPECT (tôn trọng - danh từ/động từ) → respectful - biết tôn trọng (tính từ)","explanation":"Sau động từ liên kết 'be' (to be) cần một TÍNH TỪ làm vị ngữ. Danh từ/động từ gốc 'respect' → thêm hậu tố '-ful' thành tính từ 'respectful'. ✗ respect = danh từ/động từ; ✗ respectfully = trạng từ; ✗ disrespect = danh từ/động từ (nghĩa ngược lại) — đều sai vì cần tính từ sau 'be'."},
  {"type":"mcq","id":"wf-284","cat":"adj","base":"EMPLOY","q":"Many young people in the area became ___ (EMPLOY) after the local factory shut down.","options":["unemployed","employment","employer","employ"],"correct":0,"answer":"unemployed","vi":"EMPLOY (thuê, tuyển dụng - động từ) → unemployed - thất nghiệp (tính từ)","explanation":"Sau động từ liên kết 'became' cần một TÍNH TỪ làm vị ngữ. Động từ gốc 'employ' → thêm tiền tố phủ định 'un-' và hậu tố '-ed' thành tính từ 'unemployed' (thất nghiệp). ✗ employment = danh từ; ✗ employer = danh từ (người sử dụng lao động); ✗ employ = động từ — đều sai vì cần tính từ sau 'became'."},
  {"type":"mcq","id":"wf-285","cat":"adj","base":"SAFE","q":"Some residents feel their neighborhood has become ___ (SAFE) due to rising crime rates.","options":["safety","unsafe","safely","safeguard"],"correct":1,"answer":"unsafe","vi":"SAFE (an toàn - tính từ) → unsafe - không an toàn (tính từ)","explanation":"Sau động từ liên kết 'become' cần một TÍNH TỪ. Tính từ gốc 'safe' → thêm tiền tố phủ định 'un-' thành 'unsafe' (không an toàn). ✗ safety = danh từ; ✗ safely = trạng từ; ✗ safeguard = động từ — đều sai vì cần tính từ sau 'become'."},
  {"type":"mcq","id":"wf-286","cat":"adv","base":"FORMAL","q":"The two community groups have discussed the project, but nothing has been ___ (FORMAL) agreed yet.","options":["formality","formal","formally","formalize"],"correct":2,"answer":"formally","vi":"FORMAL (chính thức - tính từ) → formally - một cách chính thức (trạng từ)","explanation":"Bổ nghĩa cho động từ 'agreed' (thể bị động 'has been ___ agreed') nên cần một TRẠNG TỪ. Tính từ gốc 'formal' → thêm hậu tố '-ly' thành trạng từ 'formally'. ✗ formality = danh từ; ✗ formal = tính từ; ✗ formalize = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-287","cat":"adv","base":"ACTIVE","q":"Residents are encouraged to take part ___ (ACTIVE) in neighborhood clean-up campaigns.","options":["active","activity","activate","actively"],"correct":3,"answer":"actively","vi":"ACTIVE (năng động - tính từ) → actively - một cách tích cực (trạng từ)","explanation":"Bổ nghĩa cho cụm động từ 'take part' nên cần một TRẠNG TỪ. Tính từ gốc 'active' → thêm hậu tố '-ly' thành trạng từ 'actively'. ✗ active = tính từ; ✗ activity = danh từ; ✗ activate = động từ — đều sai vì cần trạng từ."},
  {"type":"mcq","id":"wf-288","cat":"verb","base":"CRIME","q":"Some local authorities want to ___ (CRIME) begging in public areas of the city.","options":["criminalize","crime","criminal","criminally"],"correct":0,"answer":"criminalize","vi":"CRIME (tội phạm - danh từ) → criminalize - hình sự hóa (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ. Danh từ gốc 'crime' → hình thành động từ 'criminalize' (hình sự hóa, biến thành hành vi phạm tội). ✗ crime = danh từ; ✗ criminal = tính từ/danh từ; ✗ criminally = trạng từ — đều sai vì cần động từ sau 'to'."},
  {"type":"mcq","id":"wf-289","cat":"noun","base":"VARY","q":"There is a great deal of ___ (VARY) in rainfall from one season to another.","options":["vary","variation","variable","variably"],"correct":1,"answer":"variation","vi":"VARY (thay đổi) → variation — sự biến đổi (danh từ)","explanation":"Sau cụm từ chỉ số lượng \"a great deal of\" và làm tân ngữ của giới từ \"of\" cần một DANH TỪ. Động từ gốc \"vary\" (thay đổi) + hậu tố -iation → danh từ \"variation\" (sự biến đổi/dao động). ✗ vary = động từ (chưa chia); ✗ variable = tính từ (dễ thay đổi); ✗ variably = trạng từ — đều sai vị trí vì sau \"of\" cần danh từ."},
  {"type":"mcq","id":"wf-290","cat":"noun","base":"HUMID","q":"The high ___ (HUMID) in tropical regions makes the air feel hotter than it actually is.","options":["humid","humidify","dehumidify","humidity"],"correct":3,"answer":"humidity","vi":"HUMID (ẩm ướt) → humidity — độ ẩm (danh từ)","explanation":"Sau tính từ \"high\" và làm chủ ngữ của câu cần một DANH TỪ. Tính từ gốc \"humid\" + hậu tố -ity → danh từ \"humidity\" (độ ẩm). ✗ humid = tính từ (chính là từ gốc); ✗ humidify = động từ (làm ẩm); ✗ dehumidify = động từ (khử ẩm) — đều sai vị trí vì cần danh từ làm chủ ngữ."},
  {"type":"mcq","id":"wf-291","cat":"noun","base":"ADAPT","q":"Constant ___ (ADAPT) to changing weather patterns is essential for farmers today.","options":["adaptation","adapt","adaptable","adaptably"],"correct":0,"answer":"adaptation","vi":"ADAPT (thích nghi) → adaptation — sự thích nghi (danh từ)","explanation":"Sau tính từ \"constant\" và làm chủ ngữ của câu cần một DANH TỪ. Động từ gốc \"adapt\" + hậu tố -ation → danh từ \"adaptation\" (sự thích nghi/thích ứng). ✗ adapt = động từ; ✗ adaptable = tính từ (có thể thích nghi); ✗ adaptably = trạng từ — đều sai vị trí vì cần danh từ làm chủ ngữ."},
  {"type":"mcq","id":"wf-292","cat":"noun","base":"EVAPORATE","q":"___ (EVAPORATE) of ocean water increases significantly as global temperatures rise.","options":["evaporate","evaporation","evaporative","evaporated"],"correct":1,"answer":"evaporation","vi":"EVAPORATE (bốc hơi) → evaporation — sự bốc hơi (danh từ)","explanation":"Đứng đầu câu làm chủ ngữ, trước cụm \"of ocean water\", cần một DANH TỪ. Động từ gốc \"evaporate\" + hậu tố -ion → danh từ \"evaporation\" (sự bốc hơi). ✗ evaporate = động từ; ✗ evaporative = tính từ; ✗ evaporated = tính từ (dạng phân từ quá khứ) — đều không thể làm chủ ngữ."},
  {"type":"mcq","id":"wf-293","cat":"adj","base":"PREDICT","q":"Mountain weather is often ___ (PREDICT), changing from sunshine to snow within hours.","options":["predict","prediction","unpredictable","predictably"],"correct":2,"answer":"unpredictable","vi":"PREDICT (dự đoán) → unpredictable — khó lường trước (tính từ, phủ định)","explanation":"Sau động từ liên kết \"is\" (và trạng từ \"often\") cần một TÍNH TỪ làm bổ ngữ cho chủ ngữ \"weather\". Động từ gốc \"predict\" + hậu tố -able → \"predictable\", thêm tiền tố phủ định \"un-\" → \"unpredictable\" (khó lường trước, phù hợp với ý \"thay đổi trong vài giờ\"). ✗ predict = động từ; ✗ prediction = danh từ; ✗ predictably = trạng từ — đều sai vị trí vì sau \"is\" cần tính từ."},
  {"type":"mcq","id":"wf-294","cat":"adj","base":"DESTROY","q":"Tropical storms can be extremely ___ (DESTROY), flattening houses and uprooting trees.","options":["destroy","destruction","destructively","destructive"],"correct":3,"answer":"destructive","vi":"DESTROY (phá hủy) → destructive — có tính phá hoại (tính từ)","explanation":"Sau trạng từ chỉ mức độ \"extremely\" và động từ \"be\" cần một TÍNH TỪ. Động từ gốc \"destroy\" + hậu tố -ive → tính từ \"destructive\" (mang tính phá hủy). ✗ destroy = động từ; ✗ destruction = danh từ; ✗ destructively = trạng từ — đều sai vị trí vì sau \"extremely\" cần tính từ."},
  {"type":"mcq","id":"wf-295","cat":"adj","base":"THREAT","q":"The sky turned dark and ___ (THREAT) just before the thunderstorm hit the coastal town.","options":["threatening","threat","threaten","threateningly"],"correct":0,"answer":"threatening","vi":"THREAT (mối đe dọa) → threatening — có vẻ đe dọa (tính từ)","explanation":"Đứng sau \"and\", song song với tính từ \"dark\" để bổ nghĩa cho \"the sky\" (động từ liên kết \"turned\" + tính từ), cần một TÍNH TỪ. Danh từ gốc \"threat\" chuyển thành tính từ \"threatening\" (có vẻ đe dọa, báo hiệu điều xấu). ✗ threat = danh từ; ✗ threaten = động từ; ✗ threateningly = trạng từ — đều sai vị trí vì cần tính từ song song với \"dark\"."},
  {"type":"mcq","id":"wf-296","cat":"adj","base":"POLLUTE","q":"The air in many big cities has become dangerously ___ (POLLUTE) due to traffic and factories.","options":["pollute","polluted","pollution","pollutant"],"correct":1,"answer":"polluted","vi":"POLLUTE (làm ô nhiễm) → polluted — bị ô nhiễm (tính từ)","explanation":"Sau động từ \"has become\" và trạng từ \"dangerously\" cần một TÍNH TỪ làm bổ ngữ cho \"the air\". Động từ gốc \"pollute\" chia ở dạng quá khứ phân từ \"polluted\" dùng như tính từ (bị ô nhiễm). ✗ pollute = động từ; ✗ pollution = danh từ; ✗ pollutant = danh từ (chất gây ô nhiễm) — đều sai vị trí vì sau \"become\" cần tính từ."},
  {"type":"mcq","id":"wf-297","cat":"adv","base":"EXTREME","q":"Temperatures in the Sahara Desert can be ___ (EXTREME) high during the daytime.","options":["extreme","extremist","extremely","extremity"],"correct":2,"answer":"extremely","vi":"EXTREME (cực độ) → extremely — vô cùng/cực kỳ (trạng từ)","explanation":"Đứng trước tính từ \"high\" để bổ nghĩa cho tính từ đó, cần một TRẠNG TỪ. Tính từ gốc \"extreme\" + đuôi -ly → trạng từ \"extremely\" (vô cùng, cực kỳ). ✗ extreme = tính từ (chính là từ gốc); ✗ extremist = danh từ (người cực đoan); ✗ extremity = danh từ (điểm cực điểm) — đều sai vị trí vì trước tính từ cần trạng từ."},
  {"type":"mcq","id":"wf-298","cat":"adv","base":"DRAMA","q":"Temperatures in desert regions can change ___ (DRAMA) between day and night.","options":["drama","dramatic","dramatize","dramatically"],"correct":3,"answer":"dramatically","vi":"DRAMA (kịch tính) → dramatically — một cách kịch tính/đột ngột (trạng từ)","explanation":"Bổ nghĩa cho động từ \"change\", cần một TRẠNG TỪ. Danh từ gốc \"drama\" + hậu tố -tic + -ally → trạng từ \"dramatically\" (một cách kịch tính, rõ rệt). ✗ drama = danh từ; ✗ dramatic = tính từ; ✗ dramatize = động từ — đều sai vị trí vì cần trạng từ bổ nghĩa cho \"change\"."},
  {"type":"mcq","id":"wf-299","cat":"verb","base":"SURVIVAL","q":"Polar bears are struggling to ___ (SURVIVAL) as their icy habitat continues to melt away.","options":["survive","survival","surviving","survivor"],"correct":0,"answer":"survive","vi":"SURVIVAL (sự sống sót) → survive — sống sót/tồn tại (động từ)","explanation":"Sau \"to\" (động từ nguyên mẫu) cần một ĐỘNG TỪ. Danh từ gốc \"survival\" chuyển về động từ gốc \"survive\" (sống sót, tồn tại). ✗ survival = danh từ; ✗ surviving = tính từ (đang tồn tại, vd \"surviving relatives\"); ✗ survivor = danh từ (người sống sót) — đều sai vị trí vì sau \"to\" cần động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-300","cat":"noun","base":"HAPPY","q":"___ (HAPPY) in a family often depends on good communication between parents and children.","options":["happy","happiness","happily","unhappy"],"correct":1,"answer":"happiness","vi":"HAPPY (hạnh phúc - tính từ) → happiness — niềm hạnh phúc (danh từ)","explanation":"Đầu câu, làm CHỦ NGỮ của động từ 'depends' nên cần một DANH TỪ. Tính từ 'happy' đổi y→i, thêm '-ness' → danh từ 'happiness'. ✗ happy = tính từ; ✗ happily = trạng từ; ✗ unhappy = tính từ mang nghĩa phủ định — cả ba đều không thể làm chủ ngữ ở vị trí danh từ này."},
  {"type":"mcq","id":"wf-301","cat":"noun","base":"GENEROUS","q":"My grandmother's ___ (GENEROUS) is well known in our neighborhood because she always shares her food with others.","options":["generous","generously","generosity","ungenerous"],"correct":2,"answer":"generosity","vi":"GENEROUS (hào phóng - tính từ) → generosity — lòng hào phóng (danh từ)","explanation":"Sau cụm sở hữu cách 'My grandmother's' cần một DANH TỪ làm chủ ngữ của động từ 'is'. Tính từ 'generous' đổi '-ous' thành '-osity' → danh từ 'generosity'. ✗ generous = tính từ; ✗ generously = trạng từ; ✗ ungenerous = tính từ phủ định — đều không thể làm chủ ngữ ở đây."},
  {"type":"mcq","id":"wf-302","cat":"noun","base":"LOYAL","q":"___ (LOYAL) between family members helps them overcome difficult times together.","options":["loyal","loyally","disloyal","loyalty"],"correct":3,"answer":"loyalty","vi":"LOYAL (trung thành - tính từ) → loyalty — lòng trung thành (danh từ)","explanation":"Đầu câu, làm CHỦ NGỮ của động từ 'helps' nên cần một DANH TỪ. Tính từ 'loyal' thêm '-ty' → danh từ 'loyalty'. ✗ loyal = tính từ; ✗ loyally = trạng từ; ✗ disloyal = tính từ phủ định (không trung thành) — cả ba đều không phải danh từ."},
  {"type":"mcq","id":"wf-303","cat":"noun","base":"APPRECIATE","q":"Children should show their ___ (APPRECIATE) for everything their parents do for them.","options":["appreciation","appreciate","appreciative","appreciatively"],"correct":0,"answer":"appreciation","vi":"APPRECIATE (trân trọng - động từ) → appreciation — sự trân trọng, lòng biết ơn (danh từ)","explanation":"Sau tính từ sở hữu 'their', làm tân ngữ cho động từ 'show' cần một DANH TỪ. Động từ 'appreciate' bỏ 'e' cuối, thêm '-ion' → danh từ 'appreciation'. ✗ appreciate = động từ; ✗ appreciative = tính từ; ✗ appreciatively = trạng từ — đều sai vị trí sau 'their'."},
  {"type":"mcq","id":"wf-304","cat":"noun","base":"ARGUE","q":"A small ___ (ARGUE) between the two siblings turned into a big family conflict.","options":["argue","argument","argumentative","arguably"],"correct":1,"answer":"argument","vi":"ARGUE (tranh cãi - động từ) → argument — cuộc tranh cãi (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'small' cần một DANH TỪ làm chủ ngữ của 'turned'. Động từ 'argue' bỏ 'e', thêm '-ment' → danh từ 'argument'. ✗ argue = động từ; ✗ argumentative = tính từ (hay cãi cọ); ✗ arguably = trạng từ — đều sai vị trí danh từ."},
  {"type":"mcq","id":"wf-305","cat":"adj","base":"CARE","q":"Being a ___ (CARE) father, he always checks that the doors are locked before his children go to sleep.","options":["care","carefully","careful","cared"],"correct":2,"answer":"careful","vi":"CARE (sự chăm sóc/cẩn thận - danh từ) → careful — cẩn thận, chu đáo (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'father' cần một TÍNH TỪ bổ nghĩa. Danh từ 'care' thêm '-ful' → tính từ 'careful'. ✗ care = danh từ/động từ; ✗ carefully = trạng từ; ✗ cared = động từ dạng quá khứ/phân từ (chỉ dùng trong cấu trúc bị động như 'well cared for', không đứng trước danh từ làm tính từ) — đều sai vị trí trước danh từ."},
  {"type":"mcq","id":"wf-306","cat":"adj","base":"AFFECTION","q":"She gave her son an ___ (AFFECTION) smile before leaving for work every morning.","options":["affection","affectionately","affect","affectionate"],"correct":3,"answer":"affectionate","vi":"AFFECTION (tình cảm - danh từ) → affectionate — trìu mến, yêu thương (tính từ)","explanation":"Sau mạo từ 'an' và trước danh từ 'smile' cần một TÍNH TỪ. Danh từ 'affection' thêm '-ate' → tính từ 'affectionate'. ✗ affection = danh từ; ✗ affectionately = trạng từ; ✗ affect = động từ — đều không đứng trước danh từ ở vị trí này."},
  {"type":"mcq","id":"wf-307","cat":"adj","base":"SUPPORT","q":"A ___ (SUPPORT) family always stands by you during the most difficult times in life.","options":["supportive","support","supportively","supporter"],"correct":0,"answer":"supportive","vi":"SUPPORT (sự hỗ trợ - danh từ/động từ) → supportive — biết ủng hộ, hỗ trợ (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'family' cần một TÍNH TỪ. 'Support' thêm '-ive' → tính từ 'supportive'. ✗ support = danh từ/động từ; ✗ supportively = trạng từ; ✗ supporter = danh từ (người ủng hộ) — đều sai từ loại."},
  {"type":"mcq","id":"wf-308","cat":"adj","base":"OBEY","q":"Vietnamese culture often expects children to be ___ (OBEY) to their parents and grandparents.","options":["obey","obedient","obedience","obediently"],"correct":1,"answer":"obedient","vi":"OBEY (vâng lời - động từ) → obedient — biết vâng lời, ngoan ngoãn (tính từ)","explanation":"Sau động từ 'to be' cần một TÍNH TỪ làm bổ ngữ chủ ngữ. Động từ 'obey' chuyển thành tính từ 'obedient' (dạng đặc biệt). ✗ obey = động từ; ✗ obedience = danh từ; ✗ obediently = trạng từ — đều không theo sau 'be' ở vị trí tính từ."},
  {"type":"mcq","id":"wf-309","cat":"adj","base":"HARMONY","q":"They always try to keep a ___ (HARMONY) relationship with their parents-in-law.","options":["harmony","harmoniously","harmonious","harmonize"],"correct":2,"answer":"harmonious","vi":"HARMONY (sự hòa thuận - danh từ) → harmonious — hòa thuận, hòa hợp (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'relationship' cần một TÍNH TỪ. Danh từ 'harmony' bỏ 'y', thêm '-ious' → tính từ 'harmonious'. ✗ harmony = danh từ; ✗ harmoniously = trạng từ; ✗ harmonize = động từ — đều sai vị trí trước danh từ."},
  {"type":"mcq","id":"wf-310","cat":"adv","base":"HONEST","q":"You should always speak ___ (HONEST) to your parents about the problems you are facing.","options":["honestly","honest","honesty","dishonest"],"correct":0,"answer":"honestly","vi":"HONEST (trung thực - tính từ) → honestly — một cách trung thực (trạng từ)","explanation":"Đứng sau động từ 'speak', bổ nghĩa cho cách nói nên cần TRẠNG TỪ. Tính từ 'honest' thêm '-ly' → trạng từ 'honestly'. ✗ honest = tính từ; ✗ honesty = danh từ; ✗ dishonest = tính từ phủ định — đều sai vị trí sau động từ."},
  {"type":"mcq","id":"wf-311","cat":"adv","base":"RESPECT","q":"Younger family members are taught to speak ___ (RESPECT) to their elders at all times.","options":["respect","respectfully","respectful","disrespectful"],"correct":1,"answer":"respectfully","vi":"RESPECT (sự tôn trọng - danh từ/động từ) → respectfully — một cách tôn trọng, lễ phép (trạng từ)","explanation":"Sau động từ 'speak' cần một TRẠNG TỪ bổ nghĩa cách thức. 'Respect' thêm '-ful' rồi '-ly' → 'respectfully'. ✗ respect = danh từ/động từ; ✗ respectful = tính từ; ✗ disrespectful = tính từ phủ định — đều không phải trạng từ."},
  {"type":"mcq","id":"wf-312","cat":"adv","base":"WARM","q":"The mother welcomed her son home ___ (WARM) after his long trip abroad.","options":["warm","warmth","warmly","warmed"],"correct":2,"answer":"warmly","vi":"WARM (ấm áp - tính từ) → warmly — một cách nồng nhiệt, ấm áp (trạng từ)","explanation":"Bổ nghĩa cho động từ 'welcomed' (cách thức chào đón) nên cần TRẠNG TỪ. Tính từ 'warm' thêm '-ly' → 'warmly'. ✗ warm = tính từ; ✗ warmth = danh từ (sự ấm áp); ✗ warmed = động từ dạng quá khứ — đều sai vị trí."},
  {"type":"mcq","id":"wf-313","cat":"adv","base":"CLOSE","q":"The two sisters have always worked ___ (CLOSE) together to take care of their elderly parents.","options":["close","closeness","closed","closely"],"correct":3,"answer":"closely","vi":"CLOSE (gần gũi - tính từ) → closely — chặt chẽ, gắn bó (trạng từ)","explanation":"Bổ nghĩa cho động từ 'worked' (cách thức làm việc cùng nhau) nên cần TRẠNG TỪ. Tính từ 'close' thêm '-ly' → 'closely'. ✗ close = tính từ; ✗ closeness = danh từ; ✗ closed = động từ/tính từ dạng quá khứ — đều sai vị trí và nghĩa."},
  {"type":"mcq","id":"wf-314","cat":"adv","base":"FAITH","q":"A good husband should always act ___ (FAITH) toward his wife and children.","options":["faithfully","faith","faithful","unfaithful"],"correct":0,"answer":"faithfully","vi":"FAITH (lòng chung thủy/niềm tin - danh từ) → faithfully — một cách chung thủy (trạng từ)","explanation":"Bổ nghĩa cho động từ 'act' (cách hành xử) nên cần TRẠNG TỪ. Danh từ 'faith' thêm '-ful' rồi '-ly' → 'faithfully'. ✗ faith = danh từ; ✗ faithful = tính từ; ✗ unfaithful = tính từ phủ định (không chung thủy) — đều không phải trạng từ."},
  {"type":"mcq","id":"wf-315","cat":"verb","base":"COURAGE","q":"Parents should ___ (COURAGE) their children to become independent and confident adults.","options":["courage","encourage","courageous","courageously"],"correct":1,"answer":"encourage","vi":"COURAGE (lòng can đảm - danh từ) → encourage — khuyến khích, động viên (động từ)","explanation":"Sau chủ ngữ 'Parents' và động từ khiếm khuyết 'should' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'courage' thêm tiền tố 'en-' → động từ 'encourage'. ✗ courage = danh từ; ✗ courageous = tính từ; ✗ courageously = trạng từ — đều sai vị trí sau 'should'."},
  {"type":"mcq","id":"wf-316","cat":"verb","base":"UNITY","q":"Facing hardships together can often ___ (UNITY) family members even more closely.","options":["unity","united","unite","disunity"],"correct":2,"answer":"unite","vi":"UNITY (sự đoàn kết - danh từ) → unite — đoàn kết, gắn kết (động từ)","explanation":"Sau 'can often' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'unity' có dạng động từ tương ứng là 'unite'. ✗ unity = danh từ; ✗ united = tính từ/phân từ (đã đoàn kết, cần có 'be' đứng trước); ✗ disunity = danh từ phủ định (sự chia rẽ) — đều không thể đứng ở vị trí động từ nguyên mẫu này."},
  {"type":"mcq","id":"wf-317","cat":"verb","base":"DEEP","q":"Spending quality time together every weekend can ___ (DEEP) the emotional connection between family members.","options":["deep","deeply","depth","deepen"],"correct":3,"answer":"deepen","vi":"DEEP (sâu sắc - tính từ) → deepen — làm sâu sắc hơn (động từ)","explanation":"Sau động từ khiếm khuyết 'can' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'deep' thêm '-en' → động từ 'deepen'. ✗ deep = tính từ; ✗ deeply = trạng từ; ✗ depth = danh từ (độ sâu) — đều sai vị trí sau 'can'."},
  {"type":"mcq","id":"wf-318","cat":"noun","base":"CONSTRUCT","q":"Workers have been busy with the ___ (CONSTRUCT) of a new shopping mall downtown for over a year.","options":["construction","construct","constructive","constructively"],"correct":0,"answer":"construction","vi":"CONSTRUCT (xây dựng - động từ) → construction — sự xây dựng, công trình (danh từ)","explanation":"Sau mạo từ 'the' và trước giới từ 'of' cần một DANH TỪ (cụm 'the ___ of a new shopping mall' làm tân ngữ của giới từ 'with'). Động từ gốc 'construct' → danh từ 'construction' (thêm -ion). ✗ construct = động từ; ✗ constructive = tính từ; ✗ constructively = trạng từ — đều sai vị trí vì câu cần danh từ."},
  {"type":"mcq","id":"wf-319","cat":"adj","base":"RESIDE","q":"Many young families prefer to buy a house in a quiet ___ (RESIDE) area away from the city center.","options":["reside","residential","residence","resident"],"correct":1,"answer":"residential","vi":"RESIDE (cư trú, sinh sống - động từ) → residential — thuộc khu dân cư (tính từ)","explanation":"Trước danh từ 'area' và sau tính từ 'quiet' cần một TÍNH TỪ để bổ nghĩa cho danh từ. Động từ gốc 'reside' → tính từ 'residential' (thêm -ial). ✗ reside = động từ; ✗ residence = danh từ (nơi ở); ✗ resident = danh từ (người cư trú) — đều sai vị trí vì câu cần tính từ đứng trước danh từ."},
  {"type":"mcq","id":"wf-320","cat":"verb","base":"INDUSTRY","q":"The government plans to ___ (INDUSTRY) this rural region within the next ten years, building factories and new roads.","options":["industry","industrial","industrially","industrialize"],"correct":3,"answer":"industrialize","vi":"INDUSTRY (công nghiệp - danh từ) → industrialize — công nghiệp hóa (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu) cần một ĐỘNG TỪ. Danh từ gốc 'industry' → động từ 'industrialize' (thêm -ize). ✗ industry = danh từ; ✗ industrial = tính từ; ✗ industrially = trạng từ — đều sai vị trí vì sau 'to' cần động từ."},
  {"type":"mcq","id":"wf-321","cat":"verb","base":"MODERN","q":"The old town hall was completely ___ (MODERN) last year to include better facilities for visitors.","options":["modernized","modern","modernization","modernity"],"correct":0,"answer":"modernized","vi":"MODERN (hiện đại - tính từ) → modernized — được hiện đại hóa (động từ, dạng bị động)","explanation":"Sau trợ động từ 'was' (câu bị động) và trạng từ 'completely' cần một ĐỘNG TỪ ở dạng quá khứ phân từ. Tính từ gốc 'modern' → động từ 'modernize' → 'modernized' (thêm -ize rồi -ed). ✗ modern = tính từ; ✗ modernization = danh từ; ✗ modernity = danh từ — đều sai vị trí vì câu bị động cần động từ (V3/-ed)."},
  {"type":"mcq","id":"wf-322","cat":"noun","base":"POPULATE","q":"The rapid growth in ___ (POPULATE) has put enormous pressure on the city's housing and transport systems.","options":["populate","population","populous","populated"],"correct":1,"answer":"population","vi":"POPULATE (làm cho có dân cư - động từ) → population — dân số (danh từ)","explanation":"Sau giới từ 'in' cần một DANH TỪ làm tân ngữ của giới từ. Động từ gốc 'populate' → danh từ 'population' (thêm -ion). ✗ populate = động từ; ✗ populous = tính từ (đông dân cư); ✗ populated = tính từ/quá khứ phân từ (đã có người sinh sống, như trong 'a densely populated area') — đều sai vị trí vì câu cần danh từ, không phải động từ hay tính từ."},
  {"type":"mcq","id":"wf-323","cat":"adv","base":"SAFE","q":"New traffic lights were installed so that pedestrians could cross the busy street ___ (SAFE).","options":["safe","safety","safely","safeguard"],"correct":2,"answer":"safely","vi":"SAFE (an toàn - tính từ) → safely — một cách an toàn (trạng từ)","explanation":"Sau động từ 'cross' cần một TRẠNG TỪ để bổ nghĩa cho cách thức băng qua đường. Tính từ gốc 'safe' → trạng từ 'safely' (thêm -ly). ✗ safe = tính từ; ✗ safety = danh từ; ✗ safeguard = động từ (bảo vệ) — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-324","cat":"adj","base":"COMFORT","q":"Modern apartments are designed to make city living more ___ (COMFORT) for busy office workers.","options":["comfort","comfortably","discomfort","comfortable"],"correct":3,"answer":"comfortable","vi":"COMFORT (sự thoải mái - danh từ) → comfortable — thoải mái, tiện nghi (tính từ)","explanation":"Sau 'more' và trong cấu trúc 'make + tân ngữ + tính từ' cần một TÍNH TỪ. Danh từ gốc 'comfort' → tính từ 'comfortable' (thêm -able). ✗ comfort = danh từ; ✗ comfortably = trạng từ; ✗ discomfort = danh từ (sự khó chịu) — đều sai vị trí vì câu cần tính từ."},
  {"type":"mcq","id":"wf-325","cat":"adv","base":"HISTORY","q":"The Old Quarter is ___ (HISTORY) important and attracts thousands of tourists every year.","options":["historically","history","historic","historian"],"correct":0,"answer":"historically","vi":"HISTORY (lịch sử - danh từ) → historically — về mặt lịch sử (trạng từ)","explanation":"Trước tính từ 'important' cần một TRẠNG TỪ bổ nghĩa cho tính từ đó. Danh từ gốc 'history' → tính từ 'historical' → trạng từ 'historically' (thêm -ly). ✗ history = danh từ; ✗ historic = tính từ; ✗ historian = danh từ (nhà sử học) — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-326","cat":"verb","base":"BEAUTY","q":"The city council has planted more trees along the avenues to ___ (BEAUTY) the main streets.","options":["beauty","beautify","beautiful","beautifully"],"correct":1,"answer":"beautify","vi":"BEAUTY (vẻ đẹp - danh từ) → beautify — làm đẹp (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu) cần một ĐỘNG TỪ. Danh từ gốc 'beauty' → động từ 'beautify' (thêm -ify). ✗ beauty = danh từ; ✗ beautiful = tính từ; ✗ beautifully = trạng từ — đều sai vị trí vì sau 'to' cần động từ."},
  {"type":"mcq","id":"wf-327","cat":"noun","base":"DIFFER","q":"There is a big ___ (DIFFER) between life in a small town and life in a big city.","options":["differ","different","difference","differently"],"correct":2,"answer":"difference","vi":"DIFFER (khác nhau - động từ) → difference — sự khác biệt (danh từ)","explanation":"Sau tính từ 'big' và trong cấu trúc 'there is a big ___' cần một DANH TỪ. Động từ gốc 'differ' → danh từ 'difference' (thêm -ence). ✗ differ = động từ; ✗ different = tính từ; ✗ differently = trạng từ — đều sai vị trí vì câu cần danh từ."},
  {"type":"mcq","id":"wf-328","cat":"noun","base":"SECURE","q":"The new apartment complex has installed cameras and guards to improve ___ (SECURE) for its residents.","options":["secure","securely","insecure","security"],"correct":3,"answer":"security","vi":"SECURE (an toàn/bảo đảm - tính từ, động từ) → security — an ninh (danh từ)","explanation":"Sau động từ 'improve' cần một DANH TỪ làm tân ngữ. Tính từ/động từ gốc 'secure' → danh từ 'security' (thêm -ity). ✗ secure = tính từ/động từ; ✗ securely = trạng từ; ✗ insecure = tính từ phủ định — đều sai vị trí vì câu cần danh từ."},
  {"type":"mcq","id":"wf-329","cat":"adj","base":"RELY","q":"Despite recent improvements, the old subway system remains ___ (RELY), often arriving late or breaking down.","options":["unreliable","rely","reliability","reliably"],"correct":0,"answer":"unreliable","vi":"RELY (dựa vào, tin cậy - động từ) → unreliable — không đáng tin cậy (tính từ)","explanation":"Sau động từ liên kết 'remains' cần một TÍNH TỪ làm bổ ngữ, và ngữ cảnh phía sau ('often arriving late or breaking down') cho thấy nghĩa phủ định. Động từ gốc 'rely' → tính từ 'reliable' + tiền tố phủ định un- → 'unreliable'. ✗ rely = động từ; ✗ reliability = danh từ; ✗ reliably = trạng từ — đều sai vị trí vì câu cần tính từ."},
  {"type":"mcq","id":"wf-330","cat":"verb","base":"CONVENIENCE","q":"The endless construction noise has ___ (CONVENIENCE) many residents living near the site, forcing some to move out temporarily.","options":["convenience","convenient","inconvenienced","conveniently"],"correct":2,"answer":"inconvenienced","vi":"CONVENIENCE (sự tiện lợi - danh từ) → inconvenienced — gây phiền phức, bất tiện cho (động từ)","explanation":"Sau trợ động từ 'has' (thì hiện tại hoàn thành) cần một ĐỘNG TỪ ở dạng quá khứ phân từ. Danh từ gốc 'convenience' + tiền tố phủ định in- → động từ 'inconvenience' → 'inconvenienced' (thêm -ed). ✗ convenience = danh từ; ✗ convenient = tính từ; ✗ conveniently = trạng từ — đều sai vị trí vì câu cần động từ chia dạng -ed."},
  {"type":"mcq","id":"wf-331","cat":"verb","base":"DEVELOP","q":"This coastal town has ___ (DEVELOP) into a busy commercial city within just one decade.","options":["development","developer","underdeveloped","developed"],"correct":3,"answer":"developed","vi":"DEVELOP (phát triển - động từ) → developed — đã phát triển (động từ, quá khứ phân từ)","explanation":"Sau trợ động từ 'has' (thì hiện tại hoàn thành) và trước giới từ 'into' cần một ĐỘNG TỪ ở dạng quá khứ phân từ. Động từ gốc 'develop' → 'developed' (thêm -ed). ✗ development = danh từ; ✗ developer = danh từ (nhà phát triển); ✗ underdeveloped = tính từ (kém phát triển) — đều sai vị trí vì câu cần động từ chia dạng -ed."},
  {"type":"mcq","id":"wf-332","cat":"adv","base":"CENTER","q":"The new bus terminal is ___ (CENTER) located, so commuters from every district can reach it easily.","options":["centrally","center","central","centralize"],"correct":0,"answer":"centrally","vi":"CENTER (trung tâm - danh từ) → centrally — ở vị trí trung tâm (trạng từ)","explanation":"Trước tính từ/phân từ 'located' cần một TRẠNG TỪ bổ nghĩa cho nó. Danh từ gốc 'center' → tính từ 'central' → trạng từ 'centrally' (thêm -ly). ✗ center = danh từ; ✗ central = tính từ; ✗ centralize = động từ — đều sai vị trí vì câu cần trạng từ."},
  {"type":"mcq","id":"wf-333","cat":"adj","base":"SPACE","q":"The newly designed apartments are surprisingly ___ (SPACE) for a downtown building.","options":["space","spacious","spaciously","spaciousness"],"correct":1,"answer":"spacious","vi":"SPACE (không gian - danh từ) → spacious — rộng rãi (tính từ)","explanation":"Sau trạng từ 'surprisingly' cần một TÍNH TỪ làm bổ ngữ cho chủ ngữ 'the apartments'. Danh từ gốc 'space' → tính từ 'spacious' (thêm -ious). ✗ space = danh từ; ✗ spaciously = trạng từ; ✗ spaciousness = danh từ — đều sai vị trí vì câu cần tính từ."},
  {"type":"mcq","id":"wf-334","cat":"noun","base":"SAFE","q":"Wearing a seatbelt is one of the simplest ways to improve road ___ (SAFE).","options":["safe","safely","safety","unsafe"],"correct":2,"answer":"safety","vi":"SAFE (an toàn) → safety — sự an toàn (danh từ).","explanation":"Sau danh từ ghép 'road' và làm tân ngữ của 'improve', cần một DANH TỪ. Tính từ gốc 'safe' thêm hậu tố '-ty' thành danh từ 'safety'. ✗ safe = tính từ; ✗ safely = trạng từ (một cách an toàn); ✗ unsafe = tính từ phủ định (không an toàn, thêm tiền tố 'un-') — đều sai vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-335","cat":"adv","base":"HARM","q":"Toxic chemicals from the factory affect the surrounding environment ___ (HARM), killing fish and plants nearby.","options":["harm","harmful","harmless","harmfully"],"correct":3,"answer":"harmfully","vi":"HARM (sự nguy hại) → harmfully — một cách có hại (trạng từ).","explanation":"Từ cần điền bổ nghĩa cho động từ 'affect' (ảnh hưởng như thế nào), nên cần TRẠNG TỪ. Danh từ gốc 'harm' thêm '-ful' thành tính từ 'harmful' rồi thêm '-ly' thành trạng từ 'harmfully'. ✗ harm = danh từ/động từ; ✗ harmful = tính từ (có hại); ✗ harmless = tính từ (vô hại) — đều sai vì vị trí này cần trạng từ."},
  {"type":"mcq","id":"wf-336","cat":"verb","base":"PREVENTION","q":"Simple safety measures like wearing a helmet can ___ (PREVENTION) serious head injuries in an accident.","options":["prevent","prevention","preventive","preventively"],"correct":0,"answer":"prevent","vi":"PREVENTION (sự phòng ngừa) → prevent — ngăn ngừa, phòng tránh (động từ).","explanation":"Sau động từ khiếm khuyết 'can' cần ĐỘNG TỪ nguyên mẫu. Danh từ gốc 'prevention' trở về dạng động từ 'prevent'. ✗ prevention = danh từ; ✗ preventive = tính từ (có tính phòng ngừa); ✗ preventively = trạng từ (một cách phòng ngừa) — đều sai vì sau 'can' phải là động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-337","cat":"adj","base":"CAUTION","q":"Drivers should be extremely ___ (CAUTION) when driving through thick fog on the highway.","options":["caution","cautious","cautiously","precaution"],"correct":1,"answer":"cautious","vi":"CAUTION (sự thận trọng) → cautious — thận trọng, cẩn trọng (tính từ).","explanation":"Sau động từ 'be' và trạng từ chỉ mức độ 'extremely' cần một TÍNH TỪ. Danh từ gốc 'caution' thêm hậu tố '-ous' thành tính từ 'cautious'. ✗ caution = danh từ; ✗ cautiously = trạng từ (một cách thận trọng); ✗ precaution = danh từ khác (biện pháp đề phòng) — đều sai vì vị trí này cần tính từ."},
  {"type":"mcq","id":"wf-338","cat":"adv","base":"ALARM","q":"The number of traffic accidents in the city has increased ___ (ALARM) over the past two years.","options":["alarm","alarming","alarmingly","alarmed"],"correct":2,"answer":"alarmingly","vi":"ALARM (báo động) → alarmingly — một cách đáng báo động (trạng từ).","explanation":"Từ cần điền bổ nghĩa cho động từ 'has increased' (tăng như thế nào), nên cần TRẠNG TỪ. Danh từ gốc 'alarm' chuyển thành tính từ 'alarming' rồi thêm '-ly' thành trạng từ 'alarmingly'. ✗ alarm = danh từ/động từ; ✗ alarming = tính từ (đáng báo động); ✗ alarmed = tính từ (cảm thấy lo sợ) — đều sai vì vị trí này cần trạng từ."},
  {"type":"mcq","id":"wf-339","cat":"verb","base":"OBEDIENCE","q":"Cyclists must ___ (OBEDIENCE) traffic signals at all times to stay safe on busy roads.","options":["obedience","obedient","obediently","obey"],"correct":3,"answer":"obey","vi":"OBEDIENCE (sự vâng lời) → obey — tuân theo, vâng lời (động từ).","explanation":"Sau động từ khiếm khuyết 'must' cần ĐỘNG TỪ nguyên mẫu. Danh từ gốc 'obedience' trở về dạng động từ 'obey'. ✗ obedience = danh từ; ✗ obedient = tính từ (biết vâng lời); ✗ obediently = trạng từ (một cách ngoan ngoãn) — đều sai vì sau 'must' phải là động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-340","cat":"verb","base":"EQUIPMENT","q":"Every school should ___ (EQUIPMENT) its buildings with fire extinguishers and clear emergency exits.","options":["equipment","equip","equipped","unequipped"],"correct":1,"answer":"equip","vi":"EQUIPMENT (thiết bị) → equip — trang bị (động từ).","explanation":"Sau động từ khiếm khuyết 'should' cần ĐỘNG TỪ nguyên mẫu. Danh từ gốc 'equipment' trở về dạng động từ 'equip'. ✗ equipment = danh từ; ✗ equipped = tính từ/quá khứ phân từ (đã được trang bị); ✗ unequipped = tính từ phủ định (chưa được trang bị) — đều sai vì sau 'should' phải là động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-341","cat":"adj","base":"SURVIVE","q":"Thanks to modern safety features, the high-speed crash was ___ (SURVIVE) for everyone in the car.","options":["survive","survival","survivable","survivor"],"correct":2,"answer":"survivable","vi":"SURVIVE (sống sót) → survivable — có thể sống sót qua được (tính từ).","explanation":"Sau động từ 'be' (was), cần một TÍNH TỪ làm bổ ngữ cho chủ ngữ 'the crash'. Động từ gốc 'survive' thêm hậu tố '-able' thành tính từ 'survivable'. ✗ survive = động từ; ✗ survival = danh từ (sự sống sót); ✗ survivor = danh từ (người sống sót) — đều sai vì vị trí sau 'was' cần tính từ."},
  {"type":"mcq","id":"wf-342","cat":"noun","base":"VULNERABLE","q":"Old buildings without proper reinforcement show a high level of ___ (VULNERABLE) to earthquake damage.","options":["vulnerable","vulnerably","invulnerable","vulnerability"],"correct":3,"answer":"vulnerability","vi":"VULNERABLE (dễ bị tổn thương) → vulnerability — tính dễ bị tổn thương (danh từ).","explanation":"Trong cụm 'a high level of ___', sau giới từ 'of' cần một DANH TỪ. Tính từ gốc 'vulnerable' thêm hậu tố '-ity' thành danh từ 'vulnerability'. ✗ vulnerable = tính từ; ✗ vulnerably = trạng từ (hiếm dùng); ✗ invulnerable = tính từ phủ định (không thể bị tổn thương) — đều sai vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-343","cat":"noun","base":"VIOLENT","q":"Many action films have been criticized for glorifying ___ (VIOLENT) among young viewers.","options":["violence","violent","violently","nonviolent"],"correct":0,"answer":"violence","vi":"VIOLENT (bạo lực - tính từ) → violence — sự bạo lực (danh từ).","explanation":"Sau động từ 'glorifying' cần một DANH TỪ làm tân ngữ. Tính từ gốc 'violent' đổi đuôi '-ent' thành '-ence' để thành danh từ 'violence'. ✗ violent = tính từ; ✗ violently = trạng từ (một cách bạo lực); ✗ nonviolent = tính từ phủ định (không bạo lực) — đều sai vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-344","cat":"adv","base":"CRIME","q":"Leaving a loaded gun within a child's reach is considered ___ (CRIME) negligent by the law.","options":["crime","criminally","criminal","incriminate"],"correct":1,"answer":"criminally","vi":"CRIME (tội phạm) → criminally — một cách phạm pháp (trạng từ).","explanation":"Từ cần điền đứng trước và bổ nghĩa cho tính từ 'negligent', nên cần một TRẠNG TỪ. Danh từ gốc 'crime' chuyển thành tính từ 'criminal' rồi thêm '-ly' thành trạng từ 'criminally'. ✗ crime = danh từ; ✗ criminal = tính từ (thuộc về tội phạm); ✗ incriminate = động từ (buộc tội) — đều sai vì vị trí bổ nghĩa cho tính từ cần trạng từ."},
  {"type":"mcq","id":"wf-345","cat":"adj","base":"VICTIM","q":"Children who are constantly bullied at school often feel ___ (VICTIM) and afraid to speak up.","options":["victim","victimize","victimized","victimization"],"correct":2,"answer":"victimized","vi":"VICTIM (nạn nhân) → victimized — cảm thấy như nạn nhân, bị ngược đãi (tính từ).","explanation":"Sau động từ 'feel' cần một TÍNH TỪ làm bổ ngữ cho chủ ngữ 'children'. Danh từ gốc 'victim' chuyển thành động từ 'victimize' rồi ở dạng quá khứ phân từ 'victimized' dùng như tính từ. ✗ victim = danh từ; ✗ victimize = động từ; ✗ victimization = danh từ (sự ngược đãi) — đều sai vì sau 'feel' cần tính từ."},
  {"type":"mcq","id":"wf-346","cat":"adv","base":"GUARD","q":"When reporters asked about the factory explosion, the manager answered ___ (GUARD), avoiding any direct details.","options":["guard","guarded","guardian","guardedly"],"correct":3,"answer":"guardedly","vi":"GUARD (canh gác, bảo vệ) → guardedly — một cách thận trọng, dè dặt (trạng từ).","explanation":"Từ cần điền bổ nghĩa cho động từ 'answered' (trả lời như thế nào), nên cần TRẠNG TỪ. Danh từ/động từ gốc 'guard' thêm '-ed' thành tính từ 'guarded' rồi thêm '-ly' thành trạng từ 'guardedly'. ✗ guard = danh từ/động từ; ✗ guarded = tính từ (thận trọng); ✗ guardian = danh từ (người giám hộ) — đều sai vì vị trí này cần trạng từ."},
  {"type":"mcq","id":"wf-347","cat":"adj","base":"DEFEND","q":"Taking a ___ (DEFEND) driving course can teach you how to avoid accidents caused by other drivers.","options":["defensive","defend","defense","defensively"],"correct":0,"answer":"defensive","vi":"DEFEND (phòng thủ, bảo vệ) → defensive — có tính phòng thủ (tính từ).","explanation":"Trước danh từ 'driving course' cần một TÍNH TỪ. Động từ gốc 'defend' thêm hậu tố '-ive' thành tính từ 'defensive'. ✗ defend = động từ; ✗ defense = danh từ (sự phòng thủ); ✗ defensively = trạng từ (một cách phòng thủ) — đều sai vì vị trí trước danh từ cần tính từ."},
  {"type":"mcq","id":"wf-348","cat":"verb","base":"AVOIDANCE","q":"You should ___ (AVOIDANCE) walking alone in poorly lit streets late at night for your own safety.","options":["avoidance","avoid","avoidable","unavoidable"],"correct":1,"answer":"avoid","vi":"AVOIDANCE (sự tránh né) → avoid — tránh, tránh né (động từ).","explanation":"Sau động từ khiếm khuyết 'should' cần ĐỘNG TỪ nguyên mẫu. Danh từ gốc 'avoidance' trở về dạng động từ 'avoid'. ✗ avoidance = danh từ; ✗ avoidable = tính từ (có thể tránh được); ✗ unavoidable = tính từ phủ định (không thể tránh khỏi) — đều sai vì sau 'should' phải là động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-349","cat":"adj","base":"FRIGHTEN","q":"Being trapped inside a lift during a power cut can be a truly ___ (FRIGHTEN) experience.","options":["frighten","fright","frightening","frighteningly"],"correct":2,"answer":"frightening","vi":"FRIGHTEN (làm sợ hãi) → frightening — đáng sợ (tính từ).","explanation":"Sau trạng từ 'truly' và trước danh từ 'experience', cần một TÍNH TỪ. Động từ gốc 'frighten' thêm hậu tố '-ing' thành tính từ 'frightening'. ✗ frighten = động từ; ✗ fright = danh từ (sự sợ hãi); ✗ frighteningly = trạng từ (một cách đáng sợ) — đều sai vì vị trí trước danh từ cần tính từ."},
  {"type":"mcq","id":"wf-350","cat":"noun","base":"RELY","q":"In an emergency, people often place great ___ (RELY) on the quick response of rescue teams.","options":["reliance","rely","reliable","reliably"],"correct":0,"answer":"reliance","vi":"RELY (dựa vào, tin cậy) → reliance — sự tin cậy, sự phụ thuộc (danh từ).","explanation":"Sau tính từ 'great' và làm tân ngữ của động từ 'place', cần một DANH TỪ. Động từ gốc 'rely' thêm hậu tố '-ance' thành danh từ 'reliance'. ✗ rely = động từ; ✗ reliable = tính từ (đáng tin cậy); ✗ reliably = trạng từ (một cách đáng tin cậy) — đều sai vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-351","cat":"adj","base":"AMBITION","q":"He is an ___ (AMBITION) student who dreams of studying medicine at a top university.","options":["ambition","ambitious","ambitiously","ambitiousness"],"correct":1,"answer":"ambitious","vi":"AMBITION (tham vọng, hoài bão) → ambitious — đầy tham vọng, hoài bão (tính từ)","explanation":"Sau mạo từ 'an' và trước danh từ 'student', chỗ trống cần một TÍNH TỪ để bổ nghĩa cho danh từ đó ('an' vì 'ambitious' bắt đầu bằng âm nguyên âm). Danh từ 'ambition' → tính từ 'ambitious' (thêm -ous). ✗ ambition = danh từ; ✗ ambitiously = trạng từ; ✗ ambitiousness = danh từ (cách nói khác của 'ambition') — đều sai vị trí vì không phải tính từ."},
  {"type":"mcq","id":"wf-352","cat":"adv","base":"CONFIDENCE","q":"She spoke ___ (CONFIDENCE) about her future plans during the university interview.","options":["confidence","confident","confidently","confide"],"correct":2,"answer":"confidently","vi":"CONFIDENCE (sự tự tin) → confidently — một cách tự tin (trạng từ)","explanation":"Chỗ trống đứng sau động từ 'spoke' để bổ nghĩa cho cách thức hành động, nên cần một TRẠNG TỪ. Danh từ 'confidence' → tính từ 'confident' → trạng từ 'confidently' (thêm -ly). ✗ confidence = danh từ; ✗ confident = tính từ; ✗ confide = động từ (tin tưởng, thổ lộ) — đều sai vì không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-353","cat":"verb","base":"MOTIVE","q":"Good coaches know how to ___ (MOTIVE) their players before an important championship match.","options":["motive","motivation","motivational","motivate"],"correct":3,"answer":"motivate","vi":"MOTIVE (động cơ) → motivate — tạo động lực, thúc đẩy (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu), chỗ trống cần một ĐỘNG TỪ. Danh từ 'motive' → động từ 'motivate' (thêm -ate). ✗ motive = danh từ; ✗ motivation = danh từ (sự động viên); ✗ motivational = tính từ — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-354","cat":"adv","base":"PRIDE","q":"The champion raised her trophy ___ (PRIDE) as the crowd cheered for her victory.","options":["proudly","pride","proud","prideful"],"correct":0,"answer":"proudly","vi":"PRIDE (niềm tự hào) → proudly — một cách tự hào (trạng từ)","explanation":"Chỗ trống bổ nghĩa cho động từ 'raised' (cách thức nâng cúp), nên cần một TRẠNG TỪ. Danh từ 'pride' → tính từ 'proud' → trạng từ 'proudly' (thêm -ly). ✗ pride = danh từ/động từ; ✗ proud = tính từ; ✗ prideful = tính từ (kiêu hãnh) — đều sai vì không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-355","cat":"noun","base":"COMPETE","q":"The ___ (COMPETE) for the top scholarship was extremely fierce this year.","options":["compete","competition","competitive","competitively"],"correct":1,"answer":"competition","vi":"COMPETE (cạnh tranh, thi đấu) → competition — cuộc thi, sự cạnh tranh (danh từ)","explanation":"Sau mạo từ 'The' và trước giới từ 'for', chỗ trống làm chủ ngữ của câu nên cần một DANH TỪ. Động từ 'compete' → danh từ 'competition' (thêm -ition). ✗ compete = động từ; ✗ competitive = tính từ; ✗ competitively = trạng từ — đều sai vì cần danh từ làm chủ ngữ."},
  {"type":"mcq","id":"wf-356","cat":"adj","base":"COURAGE","q":"It took a ___ (COURAGE) decision for her to leave her stable job and pursue her dream of becoming an artist.","options":["courage","courageously","courageous","encourage"],"correct":2,"answer":"courageous","vi":"COURAGE (lòng can đảm) → courageous — can đảm, dũng cảm (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'decision', chỗ trống cần một TÍNH TỪ. Danh từ 'courage' → tính từ 'courageous' (thêm -ous). ✗ courage = danh từ; ✗ courageously = trạng từ; ✗ encourage = động từ (khuyến khích) — đều sai vị trí vì không phải tính từ."},
  {"type":"mcq","id":"wf-357","cat":"adv","base":"CONSISTENT","q":"To achieve long-term success, you must study and practice English ___ (CONSISTENT) every day.","options":["consistency","consistent","consist","consistently"],"correct":3,"answer":"consistently","vi":"CONSISTENT (nhất quán, kiên định) → consistently — một cách đều đặn, nhất quán (trạng từ)","explanation":"Chỗ trống bổ nghĩa cho động từ 'study and practice', nên cần một TRẠNG TỪ. Tính từ 'consistent' → trạng từ 'consistently' (thêm -ly). ✗ consistency = danh từ (tính nhất quán); ✗ consistent = tính từ; ✗ consist = động từ (bao gồm, cấu thành) — đều sai vì không bổ nghĩa được cho động từ (không phải trạng từ)."},
  {"type":"mcq","id":"wf-358","cat":"verb","base":"SUCCESS","q":"If you keep working hard and stay determined, you will surely ___ (SUCCESS) in reaching your dreams.","options":["succeed","success","successful","successfully"],"correct":0,"answer":"succeed","vi":"SUCCESS (thành công) → succeed — thành công, đạt được (động từ)","explanation":"Sau trợ động từ 'will' (và trạng từ 'surely'), chỗ trống cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'success' → động từ 'succeed' (đổi dạng). ✗ success = danh từ; ✗ successful = tính từ; ✗ successfully = trạng từ — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-359","cat":"noun","base":"RECOGNIZE","q":"Her outstanding performance at the competition finally earned her international ___ (RECOGNIZE).","options":["recognize","recognition","recognizable","recognizably"],"correct":1,"answer":"recognition","vi":"RECOGNIZE (công nhận, nhận ra) → recognition — sự công nhận (danh từ)","explanation":"Sau tính từ 'international', chỗ trống làm tân ngữ của 'earned her', nên cần một DANH TỪ. Động từ 'recognize' → danh từ 'recognition' (thêm -ition). ✗ recognize = động từ; ✗ recognizable = tính từ (có thể nhận ra); ✗ recognizably = trạng từ — đều sai vì cần danh từ."},
  {"type":"mcq","id":"wf-360","cat":"adj","base":"QUALIFY","q":"Without any proper training or experience, he felt completely ___ (QUALIFY) for the demanding position.","options":["qualify","qualification","disqualify","unqualified"],"correct":3,"answer":"unqualified","vi":"QUALIFY (đủ điều kiện, đạt tiêu chuẩn) → unqualified — không đủ tiêu chuẩn (tính từ, phủ định)","explanation":"Sau động từ liên kết 'felt' và trạng từ 'completely', chỗ trống cần một TÍNH TỪ làm vị ngữ; ngữ cảnh 'without training or experience' cho biết cần dạng PHỦ ĐỊNH. Động từ 'qualify' → tính từ phủ định 'unqualified' (thêm tiền tố un- vào dạng qualified). ✗ qualify = động từ; ✗ qualification = danh từ (bằng cấp, tiêu chuẩn); ✗ disqualify = động từ (loại khỏi cuộc thi) — đều sai vì không phải tính từ phù hợp ngữ cảnh."},
  {"type":"mcq","id":"wf-361","cat":"verb","base":"GLORY","q":"Winning the Olympic gold medal helped ___ (GLORY) the athlete's home country on the world stage.","options":["glorify","glory","glorious","gloriously"],"correct":0,"answer":"glorify","vi":"GLORY (vinh quang) → glorify — tôn vinh, ca ngợi (động từ)","explanation":"Sau 'helped' theo cấu trúc 'help/helped + động từ nguyên mẫu', chỗ trống cần một ĐỘNG TỪ. Danh từ 'glory' → động từ 'glorify' (thêm -ify). ✗ glory = danh từ; ✗ glorious = tính từ (vẻ vang); ✗ gloriously = trạng từ — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-362","cat":"noun","base":"PROSPER","q":"Education is often seen as the key to future ___ (PROSPER) for both individuals and society.","options":["prosper","prosperity","prosperous","prosperously"],"correct":1,"answer":"prosperity","vi":"PROSPER (thịnh vượng, phát đạt) → prosperity — sự thịnh vượng (danh từ)","explanation":"Sau tính từ 'future' và giới từ 'to', chỗ trống cần một DANH TỪ. Động từ 'prosper' → danh từ 'prosperity' (thêm -ity). ✗ prosper = động từ; ✗ prosperous = tính từ; ✗ prosperously = trạng từ — đều sai vì cần danh từ."},
  {"type":"mcq","id":"wf-363","cat":"adv","base":"HONOR","q":"He completed the extremely difficult task ___ (HONOR), earning great respect from his teachers and classmates.","options":["honor","honorable","honorably","honorary"],"correct":2,"answer":"honorably","vi":"HONOR (danh dự) → honorably — một cách đáng kính trọng, vẻ vang (trạng từ)","explanation":"Chỗ trống bổ nghĩa cho động từ 'completed' (cách thức hoàn thành nhiệm vụ), nên cần một TRẠNG TỪ. Danh từ 'honor' → tính từ 'honorable' → trạng từ 'honorably' (thêm -ly). ✗ honor = danh từ/động từ; ✗ honorable = tính từ; ✗ honorary = tính từ (danh dự, mang tính vinh danh) — đều sai vì không bổ nghĩa được cho động từ."},
  {"type":"mcq","id":"wf-364","cat":"adj","base":"ATTRACT","q":"Wearing mismatched socks and a stained shirt made him look ___ (ATTRACT) at the party.","options":["attract","attraction","attractively","unattractive"],"correct":3,"answer":"unattractive","vi":"ATTRACT (thu hút) → unattractive — không hấp dẫn, không thu hút (tính từ, thêm tiền tố phủ định un-)","explanation":"Sau động từ liên kết 'look' cần một TÍNH TỪ để miêu tả ngoại hình. Động từ 'attract' + hậu tố '-ive' → 'attractive', thêm tiền tố phủ định 'un-' → tính từ 'unattractive' (không hấp dẫn), phù hợp vì ngữ cảnh ăn mặc luộm thuộm. ✗ attract = động từ nguyên mẫu; ✗ attraction = danh từ; ✗ attractively = trạng từ — đều sai vị trí vì sau 'look' phải là tính từ."},
  {"type":"mcq","id":"wf-365","cat":"adj","base":"FASHION","q":"Wearing platform shoes today might seem ___ (FASHION) to some young people.","options":["unfashionable","fashion","fashionably","refashion"],"correct":0,"answer":"unfashionable","vi":"FASHION (thời trang) → unfashionable — lỗi mốt, không hợp thời (tính từ, thêm un-)","explanation":"Sau động từ liên kết 'seem' cần một TÍNH TỪ. Danh từ 'fashion' + hậu tố '-able' → 'fashionable', thêm tiền tố phủ định 'un-' → tính từ 'unfashionable' (lỗi mốt). ✗ fashion = danh từ; ✗ fashionably = trạng từ; ✗ refashion = động từ (làm lại kiểu khác) — đều sai vì cần tính từ sau 'seem'."},
  {"type":"mcq","id":"wf-366","cat":"adj","base":"SATISFY","q":"Many customers felt ___ (SATISFY) after buying a cheap jacket that fell apart in a week.","options":["satisfy","dissatisfied","satisfaction","satisfactorily"],"correct":1,"answer":"dissatisfied","vi":"SATISFY (làm hài lòng) → dissatisfied — không hài lòng (tính từ, thêm dis-)","explanation":"Sau động từ liên kết 'felt' cần một TÍNH TỪ chỉ cảm xúc. Động từ 'satisfy' + đuôi '-ed' → 'satisfied', thêm tiền tố phủ định 'dis-' → tính từ 'dissatisfied' (không hài lòng), hợp ngữ cảnh áo bị hỏng. ✗ satisfy = động từ; ✗ satisfaction = danh từ; ✗ satisfactorily = trạng từ — đều sai vị trí sau 'felt'."},
  {"type":"mcq","id":"wf-367","cat":"adj","base":"DIFFER","q":"Fashion trends can be very ___ (DIFFER) from one country to another.","options":["differ","difference","different","differently"],"correct":2,"answer":"different","vi":"DIFFER (khác nhau - động từ) → different — khác biệt (tính từ)","explanation":"Sau 'very' và động từ 'to be' (can be) cần một TÍNH TỪ (cấu trúc 'different from'). Động từ 'differ' + hậu tố '-ent' → tính từ 'different'. ✗ differ = động từ; ✗ difference = danh từ; ✗ differently = trạng từ — đều sai vì không thể đứng ngay sau 'very' làm bổ ngữ của 'be'."},
  {"type":"mcq","id":"wf-368","cat":"adj","base":"GRACE","q":"The model walked down the runway in a ___ (GRACE) way, impressing everyone.","options":["grace","gracefully","graced","graceful"],"correct":3,"answer":"graceful","vi":"GRACE (sự duyên dáng - danh từ) → graceful — duyên dáng, uyển chuyển (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'way' cần một TÍNH TỪ. Danh từ 'grace' + hậu tố '-ful' → tính từ 'graceful'. ✗ grace = danh từ; ✗ gracefully = trạng từ; ✗ graced = động từ (thì quá khứ của 'to grace' — tôn vinh, làm rạng rỡ) — đều sai vì cần tính từ đứng trước danh từ 'way'."},
  {"type":"mcq","id":"wf-369","cat":"noun","base":"CREATE","q":"Fashion design requires a lot of ___ (CREATE) to come up with new styles every season.","options":["creativity","create","creative","creatively"],"correct":0,"answer":"creativity","vi":"CREATE (sáng tạo - động từ) → creativity — sự sáng tạo (danh từ)","explanation":"Sau 'a lot of' cần một DANH TỪ không đếm được. Động từ 'create' + hậu tố '-ivity' → danh từ 'creativity'. ✗ create = động từ; ✗ creative = tính từ; ✗ creatively = trạng từ — đều sai vì sau 'a lot of' phải là danh từ."},
  {"type":"mcq","id":"wf-370","cat":"noun","base":"DECORATE","q":"The wedding dress was covered with beautiful lace ___ (DECORATE).","options":["decorate","decorative","decorations","decoratively"],"correct":2,"answer":"decorations","vi":"DECORATE (trang trí - động từ) → decorations — họa tiết/đồ trang trí (danh từ)","explanation":"Trong cụm 'lace ___', danh từ 'lace' đứng trước bổ nghĩa cho từ cần điền (như một danh từ ghép), và cả cụm 'beautiful lace ___' làm tân ngữ của giới từ 'with' (covered with). Vì vậy chỗ trống cần một DANH TỪ. Động từ 'decorate' + hậu tố '-ion' (+s) → danh từ 'decorations'. ✗ decorate = động từ; ✗ decorative = tính từ; ✗ decoratively = trạng từ — đều sai vì câu cần danh từ làm tân ngữ."},
  {"type":"mcq","id":"wf-371","cat":"noun","base":"APPEAR","q":"Your ___ (APPEAR) plays an important role in how others judge you at a job interview.","options":["appear","apparent","apparently","appearance"],"correct":3,"answer":"appearance","vi":"APPEAR (trông có vẻ - động từ) → appearance — vẻ ngoài, diện mạo (danh từ)","explanation":"Sau tính từ sở hữu 'Your' và làm CHỦ NGỮ cần một DANH TỪ. Động từ 'appear' + hậu tố '-ance' → danh từ 'appearance'. ✗ appear = động từ; ✗ apparent = tính từ; ✗ apparently = trạng từ — đều sai vì không thể đứng sau 'Your' làm chủ ngữ."},
  {"type":"mcq","id":"wf-372","cat":"noun","base":"SIMPLE","q":"She always dresses with ___ (SIMPLE) rather than wearing too many accessories.","options":["simplicity","simple","simplify","simply"],"correct":0,"answer":"simplicity","vi":"SIMPLE (đơn giản - tính từ) → simplicity — sự đơn giản (danh từ)","explanation":"Sau giới từ 'with' cần một DANH TỪ. Tính từ 'simple' + hậu tố '-icity' → danh từ 'simplicity'. ✗ simple = tính từ; ✗ simplify = động từ; ✗ simply = trạng từ — đều sai vì sau giới từ cần danh từ."},
  {"type":"mcq","id":"wf-373","cat":"noun","base":"ORIGINAL","q":"This young designer is admired for the ___ (ORIGINAL) of her clothing designs.","options":["original","originality","originate","originally"],"correct":1,"answer":"originality","vi":"ORIGINAL (độc đáo/gốc - tính từ) → originality — tính độc đáo (danh từ)","explanation":"Sau mạo từ 'the' và giới từ 'for' cần một DANH TỪ. Tính từ 'original' + hậu tố '-ity' → danh từ 'originality'. ✗ original = tính từ; ✗ originate = động từ; ✗ originally = trạng từ — đều sai vì cần danh từ đứng sau 'the'."},
  {"type":"mcq","id":"wf-374","cat":"adv","base":"IMPRESS","q":"The designer dressed her models so ___ (IMPRESS) that the audience gave a standing ovation.","options":["impress","impression","impressively","impressive"],"correct":2,"answer":"impressively","vi":"IMPRESS (gây ấn tượng - động từ) → impressively — một cách ấn tượng (trạng từ)","explanation":"Sau 'so' bổ nghĩa cho động từ 'dressed' cần một TRẠNG TỪ. Động từ 'impress' + hậu tố '-ively' → trạng từ 'impressively'. ✗ impress = động từ; ✗ impression = danh từ; ✗ impressive = tính từ — đều sai vì cần trạng từ bổ nghĩa động từ."},
  {"type":"mcq","id":"wf-375","cat":"adv","base":"EXPRESS","q":"She styled her outfit ___ (EXPRESS) to show her unique personality.","options":["express","expression","expressive","expressively"],"correct":3,"answer":"expressively","vi":"EXPRESS (thể hiện - động từ) → expressively — một cách biểu cảm (trạng từ)","explanation":"Bổ nghĩa cho động từ 'styled' cần một TRẠNG TỪ. Động từ 'express' + hậu tố '-ively' → trạng từ 'expressively'. ✗ express = động từ; ✗ expression = danh từ; ✗ expressive = tính từ — đều sai vì cần trạng từ bổ nghĩa động từ."},
  {"type":"mcq","id":"wf-376","cat":"adv","base":"COMPARE","q":"Today's street style is, ___ (COMPARE) speaking, far more daring than it was ten years ago.","options":["comparatively","compare","comparison","comparative"],"correct":0,"answer":"comparatively","vi":"COMPARE (so sánh - động từ) → comparatively — tương đối, so ra thì (trạng từ)","explanation":"Bổ nghĩa cho 'speaking' (V-ing) trong cụm cố định 'comparatively speaking' cần một TRẠNG TỪ. Động từ 'compare' + hậu tố '-atively' → trạng từ 'comparatively'. ✗ compare = động từ; ✗ comparison = danh từ; ✗ comparative = tính từ — đều sai vì cần trạng từ đứng trước 'speaking'."},
  {"type":"mcq","id":"wf-377","cat":"adv","base":"VARY","q":"At the fashion show, models were dressed ___ (VARY), some in traditional costumes and others in ultra-modern designs.","options":["vary","variously","variety","various"],"correct":1,"answer":"variously","vi":"VARY (khác nhau, đa dạng - động từ) → variously — một cách đa dạng (trạng từ)","explanation":"Bổ nghĩa cho cụm động từ bị động 'were dressed' cần một TRẠNG TỪ chỉ cách thức. Động từ 'vary' → tính từ 'various' → trạng từ 'variously' (thêm -ly). ✗ vary = động từ; ✗ variety = danh từ; ✗ various = tính từ — đều sai vì cần trạng từ bổ nghĩa động từ."},
  {"type":"mcq","id":"wf-378","cat":"verb","base":"GLAMOUR","q":"Fashion magazines often ___ (GLAMOUR) simple outfits by styling them with expensive jewelry.","options":["glamour","glamorous","glamorize","glamorously"],"correct":2,"answer":"glamorize","vi":"GLAMOUR (sự hào nhoáng - danh từ) → glamorize — làm cho hào nhoáng, tôn lên vẻ sang trọng (động từ)","explanation":"Sau 'often' và làm động từ chính của câu (chủ ngữ số nhiều 'magazines') cần một ĐỘNG TỪ. Danh từ 'glamour' + hậu tố '-ize' → động từ 'glamorize'. ✗ glamour = danh từ; ✗ glamorous = tính từ; ✗ glamorously = trạng từ — đều sai vì câu cần động từ chính."},
  {"type":"mcq","id":"wf-379","cat":"verb","base":"BRIGHT","q":"Adding a colorful scarf can ___ (BRIGHT) any dull, plain outfit.","options":["bright","brightness","brightly","brighten"],"correct":3,"answer":"brighten","vi":"BRIGHT (sáng, tươi - tính từ) → brighten — làm cho sáng/tươi lên (động từ)","explanation":"Sau trợ động từ 'can' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'bright' + hậu tố '-en' → động từ 'brighten'. ✗ bright = tính từ; ✗ brightness = danh từ; ✗ brightly = trạng từ — đều sai vì sau 'can' cần động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-380","cat":"verb","base":"SOFT","q":"This new fabric ___ (SOFT) after every wash, making the clothes more comfortable.","options":["soft","softens","softness","softly"],"correct":1,"answer":"softens","vi":"SOFT (mềm - tính từ) → soften(s) — làm cho mềm ra (động từ)","explanation":"Chủ ngữ số ít 'fabric' cần một ĐỘNG TỪ chia thì hiện tại đơn (thêm -s). Tính từ 'soft' + hậu tố '-en' → động từ 'soften' → 'softens'. ✗ soft = tính từ; ✗ softness = danh từ; ✗ softly = trạng từ — đều sai vì câu cần động từ làm vị ngữ chính."},
  {"type":"mcq","id":"wf-381","cat":"noun","base":"ELECT","q":"The presidential ___ (ELECT) will take place in December this year.","options":["elect","electoral","election","elective"],"correct":2,"answer":"election","vi":"ELECT (bầu cử - động từ) → election — cuộc bầu cử (danh từ).","explanation":"Sau tính từ 'presidential' và làm chủ ngữ của động từ 'will take place' → cần DANH TỪ. Động từ gốc 'elect' → danh từ 'election' (thêm hậu tố -ion). ✗ elect = động từ (bầu chọn); ✗ electoral = tính từ (thuộc về bầu cử, vd 'electoral college'); ✗ elective = tính từ (được bầu ra/tự chọn) — cả ba đều sai vì không phải danh từ làm chủ ngữ."},
  {"type":"mcq","id":"wf-382","cat":"noun","base":"CORRUPT","q":"The new president promised to fight against ___ (CORRUPT) in government offices.","options":["corrupt","corruptly","corruptible","corruption"],"correct":3,"answer":"corruption","vi":"CORRUPT (tham nhũng - tính từ) → corruption — nạn tham nhũng (danh từ).","explanation":"Sau giới từ 'against' cần một DANH TỪ làm tân ngữ. Tính từ gốc 'corrupt' → danh từ 'corruption' (thêm hậu tố -ion). ✗ corrupt = tính từ (tham nhũng); ✗ corruptly = trạng từ (một cách tham nhũng); ✗ corruptible = tính từ (có thể bị mua chuộc) — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-383","cat":"noun","base":"PUNISH","q":"Severe ___ (PUNISH) is given to those who commit bribery.","options":["punishment","punish","punishable","punitive"],"correct":0,"answer":"punishment","vi":"PUNISH (trừng phạt - động từ) → punishment — sự trừng phạt (danh từ).","explanation":"Sau tính từ 'Severe' và làm chủ ngữ của động từ 'is' → cần DANH TỪ. Động từ gốc 'punish' → danh từ 'punishment' (thêm hậu tố -ment). ✗ punish = động từ; ✗ punishable = tính từ (đáng bị trừng phạt); ✗ punitive = tính từ (mang tính trừng phạt) — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-384","cat":"noun","base":"INVESTIGATE","q":"The police launched an ___ (INVESTIGATE) into the bribery scandal.","options":["investigate","investigation","investigative","investigatory"],"correct":1,"answer":"investigation","vi":"INVESTIGATE (điều tra - động từ) → investigation — cuộc điều tra (danh từ).","explanation":"Sau mạo từ 'an' cần một DANH TỪ. Động từ gốc 'investigate' → danh từ 'investigation' (thêm hậu tố -ion). ✗ investigate = động từ; ✗ investigative = tính từ (thuộc về điều tra); ✗ investigatory = tính từ (mang tính điều tra) — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-385","cat":"noun","base":"INDEPENDENT","q":"Vietnam declared its ___ (INDEPENDENT) on September 2nd, 1945.","options":["independent","independently","independence","dependent"],"correct":2,"answer":"independence","vi":"INDEPENDENT (độc lập - tính từ) → independence — nền độc lập (danh từ).","explanation":"Sau tính từ sở hữu 'its' cần một DANH TỪ. Tính từ gốc 'independent' → danh từ 'independence' (đổi đuôi -ent thành -ence). ✗ independent = tính từ; ✗ independently = trạng từ (một cách độc lập); ✗ dependent = tính từ (phụ thuộc, trái nghĩa cùng gốc 'depend') — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-386","cat":"noun","base":"ENFORCE","q":"Strict ___ (ENFORCE) of traffic laws has reduced accidents significantly.","options":["enforce","enforceable","unenforceable","enforcement"],"correct":3,"answer":"enforcement","vi":"ENFORCE (thực thi - động từ) → enforcement — sự thực thi (danh từ).","explanation":"Sau tính từ 'Strict' và làm chủ ngữ của động từ 'has reduced' → cần DANH TỪ. Động từ gốc 'enforce' → danh từ 'enforcement' (thêm hậu tố -ment). ✗ enforce = động từ; ✗ enforceable = tính từ (có thể thực thi được); ✗ unenforceable = tính từ (không thể thực thi, tiền tố phủ định un-) — đều sai vì không phải danh từ."},
  {"type":"mcq","id":"wf-387","cat":"adj","base":"DEMOCRACY","q":"Vietnam is striving to build a more ___ (DEMOCRACY) society.","options":["democratic","democracy","democratically","democratize"],"correct":0,"answer":"democratic","vi":"DEMOCRACY (nền dân chủ - danh từ) → democratic — dân chủ (tính từ).","explanation":"Sau 'more' và trước danh từ 'society' cần một TÍNH TỪ. Danh từ gốc 'democracy' → tính từ 'democratic' (đổi đuôi -acy thành -atic). ✗ democracy = danh từ; ✗ democratically = trạng từ; ✗ democratize = động từ (dân chủ hóa) — đều sai vì không phải tính từ đứng trước danh từ."},
  {"type":"mcq","id":"wf-388","cat":"adj","base":"JUSTICE","q":"Many citizens protested against the ___ (JUSTICE) treatment of minority groups.","options":["justice","unjust","justly","justify"],"correct":1,"answer":"unjust","vi":"JUSTICE (công lý - danh từ) → unjust — bất công (tính từ, tiền tố phủ định un-).","explanation":"Sau mạo từ 'the' và trước danh từ 'treatment' cần một TÍNH TỪ. Danh từ gốc 'justice' liên quan tính từ 'just', thêm tiền tố phủ định 'un-' → 'unjust' (bất công). ✗ justice = danh từ; ✗ justly = trạng từ (một cách công bằng); ✗ justify = động từ (biện minh) — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-389","cat":"adj","base":"POLITICS","q":"She has never been interested in ___ (POLITICS) issues.","options":["politics","politically","political","politicize"],"correct":2,"answer":"political","vi":"POLITICS (chính trị - danh từ) → political — thuộc về chính trị (tính từ).","explanation":"Trước danh từ 'issues' cần một TÍNH TỪ để bổ nghĩa. Danh từ gốc 'politics' → tính từ 'political' (thêm hậu tố -al). ✗ politics = danh từ; ✗ politically = trạng từ; ✗ politicize = động từ (chính trị hóa) — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-390","cat":"adj","base":"CONSTITUTION","q":"Freedom of speech is a ___ (CONSTITUTION) right in most countries.","options":["constitutional","constitution","constitutionally","constitute"],"correct":0,"answer":"constitutional","vi":"CONSTITUTION (hiến pháp - danh từ) → constitutional — thuộc về hiến pháp (tính từ).","explanation":"Sau mạo từ 'a' và trước danh từ 'right' cần một TÍNH TỪ. Danh từ gốc 'constitution' → tính từ 'constitutional' (thêm hậu tố -al). ✗ constitution = danh từ; ✗ constitutionally = trạng từ; ✗ constitute = động từ (cấu thành) — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-391","cat":"adj","base":"GOVERN","q":"The policy change was a purely ___ (GOVERN) decision, not a private company's choice.","options":["govern","governmental","government","governance"],"correct":1,"answer":"governmental","vi":"GOVERN (cai trị/quản lý - động từ) → governmental — thuộc về chính phủ (tính từ).","explanation":"Sau trạng từ 'purely' và trước danh từ 'decision' cần một TÍNH TỪ. Động từ gốc 'govern' → danh từ 'government' (thêm hậu tố -ment) → tính từ 'governmental' (thêm hậu tố -al). ✗ govern = động từ; ✗ government = danh từ (chính phủ); ✗ governance = danh từ (sự quản trị) — đều sai vì không phải tính từ."},
  {"type":"mcq","id":"wf-392","cat":"adv","base":"DIPLOMATIC","q":"The two leaders handled the border dispute ___ (DIPLOMATIC) to avoid conflict.","options":["diplomatic","diplomacy","diplomatically","diplomat"],"correct":2,"answer":"diplomatically","vi":"DIPLOMATIC (mang tính ngoại giao - tính từ) → diplomatically — một cách khéo léo/ngoại giao (trạng từ).","explanation":"Bổ nghĩa cho động từ 'handled' cần một TRẠNG TỪ. Tính từ gốc 'diplomatic' → trạng từ 'diplomatically' (thêm hậu tố -ly). ✗ diplomatic = tính từ; ✗ diplomacy = danh từ (ngành ngoại giao); ✗ diplomat = danh từ (nhà ngoại giao) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-393","cat":"adv","base":"RESPONSIBLE","q":"Every citizen should vote ___ (RESPONSIBLE) rather than following the crowd blindly.","options":["responsible","responsibility","irresponsible","responsibly"],"correct":3,"answer":"responsibly","vi":"RESPONSIBLE (có trách nhiệm - tính từ) → responsibly — một cách có trách nhiệm (trạng từ).","explanation":"Bổ nghĩa cho động từ 'vote' cần một TRẠNG TỪ. Tính từ gốc 'responsible' → trạng từ 'responsibly' (thêm hậu tố -ly). ✗ responsible = tính từ; ✗ responsibility = danh từ (trách nhiệm); ✗ irresponsible = tính từ (vô trách nhiệm, tiền tố phủ định ir-) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-394","cat":"adv","base":"FAIR","q":"Every defendant has the right to be treated ___ (FAIR) by the court.","options":["fairly","fair","fairness","unfair"],"correct":0,"answer":"fairly","vi":"FAIR (công bằng - tính từ) → fairly — một cách công bằng (trạng từ).","explanation":"Bổ nghĩa cho động từ bị động 'be treated' cần một TRẠNG TỪ. Tính từ gốc 'fair' → trạng từ 'fairly' (thêm hậu tố -ly). ✗ fair = tính từ; ✗ fairness = danh từ (sự công bằng); ✗ unfair = tính từ (bất công, tiền tố phủ định un-) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-395","cat":"adv","base":"LAW","q":"Police officers must always act ___ (LAW) when arresting a suspect.","options":["law","lawfully","lawful","unlawful"],"correct":1,"answer":"lawfully","vi":"LAW (luật pháp - danh từ) → lawfully — một cách hợp pháp (trạng từ).","explanation":"Bổ nghĩa cho động từ 'act' cần một TRẠNG TỪ. Danh từ gốc 'law' → tính từ 'lawful' rồi thêm '-ly' thành trạng từ 'lawfully'. ✗ law = danh từ; ✗ lawful = tính từ (hợp pháp); ✗ unlawful = tính từ (bất hợp pháp, tiền tố phủ định un-) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-396","cat":"adv","base":"OFFICIAL","q":"The new traffic law was ___ (OFFICIAL) passed by the National Assembly last week.","options":["official","officiate","officially","officialdom"],"correct":2,"answer":"officially","vi":"OFFICIAL (chính thức - tính từ) → officially — một cách chính thức (trạng từ).","explanation":"Bổ nghĩa cho động từ bị động 'was passed' cần một TRẠNG TỪ. Tính từ gốc 'official' → trạng từ 'officially' (thêm hậu tố -ly). ✗ official = tính từ; ✗ officiate = động từ (chủ trì/thực hiện nhiệm vụ chính thức); ✗ officialdom = danh từ (giới quan chức) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-397","cat":"adv","base":"PUBLIC","q":"The minister ___ (PUBLIC) apologized for the policy failure.","options":["public","publicize","publicity","publicly"],"correct":3,"answer":"publicly","vi":"PUBLIC (công khai - tính từ) → publicly — một cách công khai (trạng từ).","explanation":"Bổ nghĩa cho động từ 'apologized' cần một TRẠNG TỪ. Tính từ gốc 'public' → trạng từ 'publicly' (thêm hậu tố -ly). ✗ public = tính từ/danh từ; ✗ publicize = động từ (công khai hóa, quảng bá); ✗ publicity = danh từ (sự công khai/quảng cáo) — đều sai vì không phải trạng từ."},
  {"type":"mcq","id":"wf-398","cat":"verb","base":"NATION","q":"The new government decided to ___ (NATION) all foreign-owned banks.","options":["nationalize","nation","national","nationally"],"correct":0,"answer":"nationalize","vi":"NATION (quốc gia - danh từ) → nationalize — quốc hữu hóa (động từ).","explanation":"Sau 'to' (động từ nguyên mẫu) cần một ĐỘNG TỪ. Danh từ gốc 'nation' → động từ 'nationalize' (thêm hậu tố -ize). ✗ nation = danh từ; ✗ national = tính từ (thuộc quốc gia); ✗ nationally = trạng từ (trên phạm vi quốc gia) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-399","cat":"verb","base":"AUTHORITY","q":"Only the mayor can ___ (AUTHORITY) the use of public funds for this project.","options":["authority","authorize","authoritative","authoritatively"],"correct":1,"answer":"authorize","vi":"AUTHORITY (quyền lực/thẩm quyền - danh từ) → authorize — cho phép, ủy quyền (động từ).","explanation":"Sau động từ khiếm khuyết 'can' cần một ĐỘNG TỪ nguyên mẫu. Danh từ gốc 'authority' → động từ 'authorize' (thêm hậu tố -ize). ✗ authority = danh từ; ✗ authoritative = tính từ (có thẩm quyền); ✗ authoritatively = trạng từ (một cách có thẩm quyền) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-400","cat":"verb","base":"LIBERTY","q":"Soldiers were sent to ___ (LIBERTY) the hostages held by the rebels.","options":["liberty","liberal","liberate","liberally"],"correct":2,"answer":"liberate","vi":"LIBERTY (tự do - danh từ) → liberate — giải phóng (động từ).","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Danh từ gốc 'liberty' → động từ 'liberate' (thêm hậu tố -ate). ✗ liberty = danh từ; ✗ liberal = tính từ (phóng khoáng/tự do); ✗ liberally = trạng từ (một cách rộng rãi/tự do) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-401","cat":"verb","base":"CRIMINAL","q":"Several countries have moved to ___ (CRIMINAL) hate speech online.","options":["criminal","criminally","crime","criminalize"],"correct":3,"answer":"criminalize","vi":"CRIMINAL (thuộc về tội phạm - tính từ) → criminalize — hình sự hóa (động từ).","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ gốc 'criminal' → động từ 'criminalize' (thêm hậu tố -ize). ✗ criminal = tính từ/danh từ (tội phạm); ✗ criminally = trạng từ (về mặt hình sự); ✗ crime = danh từ (tội ác) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-402","cat":"verb","base":"LEGAL","q":"Some city councils have voted to ___ (LEGAL) street vending in certain areas.","options":["legalize","legal","legally","legality"],"correct":0,"answer":"legalize","vi":"LEGAL (hợp pháp - tính từ) → legalize — hợp pháp hóa (động từ).","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ gốc 'legal' → động từ 'legalize' (thêm hậu tố -ize). ✗ legal = tính từ; ✗ legally = trạng từ (một cách hợp pháp); ✗ legality = danh từ (tính hợp pháp) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-403","cat":"verb","base":"EQUAL","q":"The reform bill seeks to ___ (EQUAL) pay between male and female workers.","options":["equal","equalize","equally","equality"],"correct":1,"answer":"equalize","vi":"EQUAL (bình đẳng - tính từ) → equalize — làm cho bình đẳng/cân bằng (động từ).","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ gốc 'equal' → động từ 'equalize' (thêm hậu tố -ize). ✗ equal = tính từ; ✗ equally = trạng từ (một cách bình đẳng); ✗ equality = danh từ (sự bình đẳng) — đều sai vì không phải động từ."},
  {"type":"mcq","id":"wf-404","cat":"noun","base":"ARRIVE","q":"The exact time of ___ (ARRIVE) at the airport was announced on the screen.","options":["arrive","arriving","arrival","arrived"],"correct":2,"answer":"arrival","vi":"ARRIVE (đến nơi - động từ) → arrival - sự đến nơi (danh từ)","explanation":"Sau cụm giới từ 'the time of' cần một DANH TỪ làm tân ngữ. Động từ 'arrive' thêm hậu tố '-al' → danh từ 'arrival'. ✗ arrive = động từ nguyên mẫu; ✗ arriving = dạng V-ing (động từ); ✗ arrived = dạng quá khứ/phân từ (động từ) — đều sai vì sau giới từ 'of' cần danh từ, không phải động từ."},
  {"type":"mcq","id":"wf-405","cat":"noun","base":"DEPART","q":"Please be at the gate thirty minutes before ___ (DEPART).","options":["depart","departing","departed","departure"],"correct":3,"answer":"departure","vi":"DEPART (khởi hành - động từ) → departure - sự khởi hành (danh từ)","explanation":"Sau giới từ 'before' cần một DANH TỪ. Động từ 'depart' thêm hậu tố '-ure' → danh từ 'departure'. ✗ depart = động từ; ✗ departing = V-ing (động từ); ✗ departed = quá khứ/phân từ (động từ) — đều sai vì sau giới từ không dùng động từ."},
  {"type":"mcq","id":"wf-406","cat":"noun","base":"CONVENIENT","q":"Traveling by subway offers great ___ (CONVENIENT) for people who live far from their workplace.","options":["convenience","convenient","conveniently","inconvenient"],"correct":0,"answer":"convenience","vi":"CONVENIENT (thuận tiện - tính từ) → convenience - sự thuận tiện (danh từ)","explanation":"Sau tính từ 'great' và làm tân ngữ của động từ 'offers', cần một DANH TỪ. Tính từ 'convenient' đổi '-t' thành '-ce' → danh từ 'convenience'. ✗ convenient = tính từ; ✗ conveniently = trạng từ; ✗ inconvenient = tính từ mang nghĩa trái nghĩa — đều không phải danh từ."},
  {"type":"mcq","id":"wf-407","cat":"noun","base":"NAVIGATE","q":"Modern ships rely on satellite systems for accurate ___ (NAVIGATE) across the ocean.","options":["navigate","navigation","navigational","navigating"],"correct":1,"answer":"navigation","vi":"NAVIGATE (điều hướng - động từ) → navigation - sự điều hướng (danh từ)","explanation":"Sau tính từ 'accurate' và là tân ngữ của giới từ 'for', cần một DANH TỪ. Động từ 'navigate' đổi '-e' thành '-ion' → danh từ 'navigation'. ✗ navigate = động từ; ✗ navigational = tính từ; ✗ navigating = V-ing (động từ) — đều sai vì vị trí này cần danh từ."},
  {"type":"mcq","id":"wf-408","cat":"noun","base":"MAINTAIN","q":"Regular ___ (MAINTAIN) can help vehicles run smoothly and avoid breakdowns.","options":["maintain","maintaining","maintenance","maintained"],"correct":2,"answer":"maintenance","vi":"MAINTAIN (bảo dưỡng - động từ) → maintenance - sự bảo dưỡng (danh từ)","explanation":"Sau tính từ 'Regular' và đóng vai trò chủ ngữ của câu, cần một DANH TỪ. Động từ 'maintain' đổi thành 'maintenance' (danh từ). ✗ maintain = động từ; ✗ maintaining = V-ing (động từ); ✗ maintained = quá khứ/phân từ (động từ) — đều sai vì chủ ngữ câu cần danh từ."},
  {"type":"mcq","id":"wf-409","cat":"adj","base":"ECONOMY","q":"Motorbikes are considered more ___ (ECONOMY) than cars because they consume less fuel.","options":["economy","economically","economize","economical"],"correct":3,"answer":"economical","vi":"ECONOMY (nền kinh tế/sự tiết kiệm - danh từ) → economical - tiết kiệm (tính từ)","explanation":"Sau động từ 'to be' (are) và trạng từ so sánh 'more', cần một TÍNH TỪ. Danh từ 'economy' bỏ đuôi '-y' và thêm hậu tố '-ical' → tính từ 'economical'. ✗ economy = danh từ; ✗ economically = trạng từ; ✗ economize = động từ — đều sai vì sau 'more' cần tính từ."},
  {"type":"mcq","id":"wf-410","cat":"adj","base":"CROWD","q":"Public buses become extremely ___ (CROWD) during rush hour, making it hard to find a seat.","options":["crowd","crowded","crowding","crowds"],"correct":1,"answer":"crowded","vi":"CROWD (đám đông - danh từ/động từ) → crowded - đông đúc, chật chội (tính từ)","explanation":"Sau động từ nối 'become' cần một TÍNH TỪ bổ nghĩa cho chủ ngữ. Danh từ/động từ 'crowd' thêm '-ed' → tính từ 'crowded'. ✗ crowd = danh từ/động từ; ✗ crowding = V-ing (động từ); ✗ crowds = danh từ số nhiều — đều không phải tính từ."},
  {"type":"mcq","id":"wf-411","cat":"adv","base":"SMOOTH","q":"The new highway allows traffic to flow ___ (SMOOTH) even during holidays.","options":["smooth","smoothness","smoothly","smoothing"],"correct":2,"answer":"smoothly","vi":"SMOOTH (êm, trơn tru - tính từ) → smoothly - một cách êm ả, trôi chảy (trạng từ)","explanation":"Sau động từ 'flow' cần một TRẠNG TỪ chỉ cách thức. Tính từ 'smooth' thêm '-ly' → trạng từ 'smoothly'. ✗ smooth = tính từ (hoặc động từ); ✗ smoothness = danh từ; ✗ smoothing = V-ing (động từ) — đều không phải trạng từ."},
  {"type":"mcq","id":"wf-412","cat":"verb","base":"ELECTRIC","q":"Many countries are working to ___ (ELECTRIC) their railway networks to cut carbon emissions.","options":["electric","electricity","electrical","electrify"],"correct":3,"answer":"electrify","vi":"ELECTRIC (thuộc về điện - tính từ) → electrify - điện khí hóa (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ. Tính từ 'electric' đổi đuôi '-ic' thành '-ify' → động từ 'electrify'. ✗ electric = tính từ; ✗ electricity = danh từ; ✗ electrical = tính từ (dạng khác) — đều không phải động từ."},
  {"type":"mcq","id":"wf-413","cat":"verb","base":"REGULAR","q":"The city needs stricter laws to ___ (REGULAR) the number of private cars on the road.","options":["regulate","regular","regulation","regularly"],"correct":0,"answer":"regulate","vi":"REGULAR (đều đặn/thông thường - tính từ) → regulate - quản lý, điều tiết (động từ)","explanation":"Sau 'to' cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'regular' đổi thành động từ 'regulate'. ✗ regular = tính từ; ✗ regulation = danh từ; ✗ regularly = trạng từ — đều không phải động từ."},
  {"type":"mcq","id":"wf-414","cat":"noun","base":"DESCRIBE","q":"The witness gave the police a detailed ___ (DESCRIBE) of the man she had seen.","options":["descriptive","description","describe","descriptively"],"correct":1,"answer":"description","vi":"DESCRIBE (miêu tả) → description — bản miêu tả (danh từ)","explanation":"Sau tính từ 'detailed' và làm tân ngữ của động từ 'gave' nên cần một DANH TỪ. Động từ 'describe' → danh từ 'description' (bỏ 'e', thêm '-tion'). ✗ descriptive = tính từ; ✗ describe = động từ; ✗ descriptively = trạng từ — đều sai vị trí vì không đứng sau tính từ để làm tân ngữ."},
  {"type":"mcq","id":"wf-415","cat":"noun","base":"PRONOUNCE","q":"Her English ___ (PRONOUNCE) has improved a lot since she moved to Australia.","options":["pronounce","pronounced","pronunciation","pronounceable"],"correct":2,"answer":"pronunciation","vi":"PRONOUNCE (phát âm) → pronunciation — cách phát âm (danh từ)","explanation":"Đứng sau danh từ 'English' và làm chủ ngữ của 'has improved' nên cần DANH TỪ. Động từ 'pronounce' → danh từ 'pronunciation' (lưu ý mất chữ 'o', không phải 'pronounciation'). ✗ pronounce = động từ; ✗ pronounced = tính từ (nghĩa 'rõ rệt'); ✗ pronounceable = tính từ (nghĩa 'có thể phát âm được') — đều sai vị trí."},
  {"type":"mcq","id":"wf-416","cat":"noun","base":"TRANSLATE","q":"The ___ (TRANSLATE) of idioms from English to Vietnamese is often difficult because of cultural differences.","options":["translatable","translate","untranslatable","translation"],"correct":3,"answer":"translation","vi":"TRANSLATE (dịch) → translation — sự dịch thuật (danh từ)","explanation":"Sau mạo từ 'The' và làm chủ ngữ của 'is' nên cần DANH TỪ. Động từ 'translate' → danh từ 'translation' (thêm '-ion'). ✗ translatable = tính từ (có thể dịch được); ✗ translate = động từ; ✗ untranslatable = tính từ phủ định (không thể dịch được) — đều sai vị trí."},
  {"type":"mcq","id":"wf-417","cat":"adj","base":"EXPRESS","q":"Body language can be just as ___ (EXPRESS) as spoken words when people communicate.","options":["expressive","expression","express","expressively"],"correct":0,"answer":"expressive","vi":"EXPRESS (diễn đạt) → expressive — giàu sức biểu cảm (tính từ)","explanation":"Sau động từ 'be' (can be...as) cần một TÍNH TỪ làm bổ ngữ. Động từ 'express' → tính từ 'expressive' (thêm '-ive'). ✗ expression = danh từ; ✗ express = động từ; ✗ expressively = trạng từ — đều sai vị trí vì không thể làm bổ ngữ của 'be'."},
  {"type":"mcq","id":"wf-418","cat":"adj","base":"GRAMMAR","q":"There are several ___ (GRAMMAR) mistakes in your essay that you need to correct.","options":["grammar","grammatical","grammatically","grammarian"],"correct":1,"answer":"grammatical","vi":"GRAMMAR (ngữ pháp) → grammatical — thuộc về ngữ pháp (tính từ)","explanation":"Sau 'several' và trước danh từ 'mistakes' cần TÍNH TỪ bổ nghĩa cho danh từ. Danh từ 'grammar' → tính từ 'grammatical' (thêm '-ical'). ✗ grammar = danh từ (từ gốc); ✗ grammatically = trạng từ; ✗ grammarian = danh từ (người nghiên cứu ngữ pháp) — đều sai vị trí vì không thể đứng trước danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-419","cat":"adj","base":"CORRECT","q":"Since Tom never studies grammar rules, most of the sentences he writes are ___ (CORRECT).","options":["correction","correctly","incorrect","correctness"],"correct":2,"answer":"incorrect","vi":"CORRECT (đúng/sửa) → incorrect — không đúng, sai (tính từ, thêm tiền tố phủ định in-)","explanation":"Sau động từ 'are' cần TÍNH TỪ làm bổ ngữ; ngữ cảnh 'never studies grammar rules' cho biết nghĩa PHỦ ĐỊNH, nên tính từ 'correct' phải thêm tiền tố phủ định 'in-' thành 'incorrect'. ✗ correction = danh từ (sự sửa chữa); ✗ correctly = trạng từ; ✗ correctness = danh từ (tính đúng đắn) — cả ba đều là danh từ/trạng từ, không thể làm tính từ bổ ngữ cho 'are'."},
  {"type":"mcq","id":"wf-420","cat":"adj","base":"SIGNIFY","q":"Making eye contact is a ___ (SIGNIFY) part of communication in Western culture.","options":["significant","significance","significantly","signify"],"correct":0,"answer":"significant","vi":"SIGNIFY (biểu thị) → significant — quan trọng, có ý nghĩa (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'part' cần TÍNH TỪ. Động từ 'signify' → tính từ 'significant' (đổi đuôi). ✗ significance = danh từ; ✗ significantly = trạng từ; ✗ signify = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-421","cat":"adv","base":"EDUCATE","q":"___ (EDUCATE) speaking, children who read every day tend to have a larger vocabulary.","options":["education","educationally","educational","educate"],"correct":1,"answer":"educationally","vi":"EDUCATE (giáo dục) → educationally — về mặt giáo dục (trạng từ)","explanation":"Cụm '___ speaking' (giống 'generally speaking') cần TRẠNG TỪ đứng đầu câu bổ nghĩa cho 'speaking'. Động từ 'educate' → trạng từ 'educationally'. ✗ education = danh từ; ✗ educational = tính từ; ✗ educate = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-422","cat":"adv","base":"CONVERSE","q":"He can speak ___ (CONVERSE) in French, but he struggles to write formal essays in the language.","options":["conversation","conversational","conversationally","converse"],"correct":2,"answer":"conversationally","vi":"CONVERSE (trò chuyện) → conversationally — theo kiểu trò chuyện (trạng từ)","explanation":"Bổ nghĩa cho động từ 'speak' nên cần TRẠNG TỪ. Động từ 'converse' → trạng từ 'conversationally'. ✗ conversation = danh từ; ✗ conversational = tính từ; ✗ converse = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-423","cat":"adv","base":"CRITICIZE","q":"Good readers learn to think ___ (CRITICIZE) about everything they read instead of believing it blindly.","options":["criticism","critical","criticize","critically"],"correct":3,"answer":"critically","vi":"CRITICIZE (phê bình) → critically — một cách phê phán, phân tích (trạng từ)","explanation":"Bổ nghĩa cho động từ 'think' nên cần TRẠNG TỪ. Động từ 'criticize' → trạng từ 'critically' (qua tính từ critical + -ly). ✗ criticism = danh từ; ✗ critical = tính từ; ✗ criticize = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-424","cat":"adv","base":"DEFINE","q":"You should ___ (DEFINE) check your spelling before submitting your essay.","options":["definitely","definition","definite","define"],"correct":0,"answer":"definitely","vi":"DEFINE (định nghĩa) → definitely — chắc chắn (trạng từ)","explanation":"Đứng giữa động từ khiếm khuyết 'should' và động từ chính 'check' nên cần TRẠNG TỪ. Từ gốc 'define' → tính từ 'definite' → trạng từ 'definitely'. ✗ definition = danh từ; ✗ definite = tính từ; ✗ define = động từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-425","cat":"verb","base":"CLEAR","q":"Could you please ___ (CLEAR) what this idiom means? I don't quite understand it.","options":["clarity","clarify","clear","clearly"],"correct":1,"answer":"clarify","vi":"CLEAR (rõ ràng) → clarify — làm rõ, giải thích rõ (động từ)","explanation":"Sau 'Could you please' cần ĐỘNG TỪ nguyên mẫu. Tính từ 'clear' → động từ 'clarify' (thêm '-ify'). ✗ clarity = danh từ; ✗ clear = tính từ; ✗ clearly = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-426","cat":"verb","base":"EMPHASIS","q":"In her speech, the teacher wanted to ___ (EMPHASIS) the importance of reading books every day.","options":["emphasis","emphatic","emphasize","emphatically"],"correct":2,"answer":"emphasize","vi":"EMPHASIS (sự nhấn mạnh) → emphasize — nhấn mạnh (động từ)","explanation":"Sau 'to' cần ĐỘNG TỪ nguyên mẫu. Danh từ 'emphasis' → động từ 'emphasize' (đổi đuôi '-is' thành '-ize'). ✗ emphasis = danh từ (dạng gốc); ✗ emphatic = tính từ; ✗ emphatically = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-427","cat":"verb","base":"SYMBOL","q":"In this novel, red is often used to ___ (SYMBOL) passion and danger.","options":["symbol","symbolic","symbolically","symbolize"],"correct":3,"answer":"symbolize","vi":"SYMBOL (biểu tượng) → symbolize — tượng trưng cho (động từ)","explanation":"Sau 'to' (trong cụm 'used to ___') cần ĐỘNG TỪ. Danh từ 'symbol' → động từ 'symbolize' (thêm '-ize'). ✗ symbol = danh từ; ✗ symbolic = tính từ; ✗ symbolically = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-428","cat":"verb","base":"IDENTITY","q":"Before you translate a sentence, you should first ___ (IDENTITY) its subject and main verb.","options":["identify","identity","identical","identically"],"correct":0,"answer":"identify","vi":"IDENTITY (danh tính/bản chất) → identify — xác định, nhận diện (động từ)","explanation":"Sau 'should first' (động từ khiếm khuyết) cần ĐỘNG TỪ nguyên mẫu. Danh từ 'identity' → động từ 'identify' (đổi đuôi '-ity' thành '-ify'). ✗ identity = danh từ (dạng gốc); ✗ identical = tính từ (giống hệt); ✗ identically = trạng từ — đều sai vị trí."},
  {"type":"mcq","id":"wf-429","cat":"adj","base":"ENTERTAIN","q":"The clown's tricks at the birthday party were incredibly ___ (ENTERTAIN) for the children.","options":["entertainment","entertaining","entertain","entertainingly"],"correct":1,"answer":"entertaining","vi":"ENTERTAIN (giải trí, làm vui - động từ) → entertaining - mang tính giải trí, thú vị (tính từ)","explanation":"Sau động từ liên kết 'were' và trạng từ 'incredibly' cần một TÍNH TỪ làm bổ ngữ. Động từ 'entertain' → tính từ 'entertaining' (thêm đuôi -ing). ✗ entertainment = danh từ (sự giải trí); ✗ entertain = động từ nguyên mẫu; ✗ entertainingly = trạng từ (một cách thú vị) — cả ba đều sai vì vị trí sau 'were incredibly' cần tính từ, không phải danh từ, động từ hay trạng từ."},
  {"type":"mcq","id":"wf-430","cat":"noun","base":"AMUSE","q":"Children spend hours playing video games purely for ___ (AMUSE).","options":["amusing","amuse","amusingly","amusement"],"correct":3,"answer":"amusement","vi":"AMUSE (làm vui thích - động từ) → amusement - sự vui thích, giải trí (danh từ)","explanation":"Sau giới từ 'for' cần một DANH TỪ làm tân ngữ. Động từ 'amuse' → danh từ 'amusement' (thêm -ment). ✗ amusing = tính từ (gây thích thú, dùng cho vật/sự việc); ✗ amuse = động từ nguyên mẫu; ✗ amusingly = trạng từ (một cách thú vị) — đều sai vì sau giới từ chỉ có thể là danh từ, không phải tính từ, động từ hay trạng từ."},
  {"type":"mcq","id":"wf-431","cat":"adj","base":"ENJOY","q":"Camping by the lake is such an ___ (ENJOY) experience for the whole family.","options":["enjoyable","enjoyment","enjoyably","enjoy"],"correct":0,"answer":"enjoyable","vi":"ENJOY (thích, tận hưởng - động từ) → enjoyable - thú vị, đáng tận hưởng (tính từ)","explanation":"Sau mạo từ 'an' và trước danh từ 'experience' cần một TÍNH TỪ bổ nghĩa cho danh từ đó. Động từ 'enjoy' → tính từ 'enjoyable' (thêm -able). ✗ enjoyment = danh từ (sự tận hưởng); ✗ enjoyably = trạng từ (một cách thú vị); ✗ enjoy = động từ nguyên mẫu — đều sai vì không thể đứng giữa mạo từ và danh từ để bổ nghĩa."},
  {"type":"mcq","id":"wf-432","cat":"noun","base":"RELAX","q":"After a stressful week, a weekend at the spa offers total ___ (RELAX).","options":["relax","relaxation","relaxing","relaxingly"],"correct":1,"answer":"relaxation","vi":"RELAX (thư giãn - động từ) → relaxation - sự thư giãn (danh từ)","explanation":"Sau tính từ 'total' và làm tân ngữ của động từ 'offers' cần một DANH TỪ. Động từ 'relax' → danh từ 'relaxation' (thêm -ation). ✗ relax = động từ nguyên mẫu; ✗ relaxing = tính từ (gây thư giãn); ✗ relaxingly = trạng từ — đều sai vì vị trí này cần danh từ làm tân ngữ, đứng sau tính từ 'total'."},
  {"type":"mcq","id":"wf-433","cat":"adj","base":"FASCINATE","q":"The deep sea is a ___ (FASCINATE) subject for documentary filmmakers.","options":["fascination","fascinate","fascinating","fascinatingly"],"correct":2,"answer":"fascinating","vi":"FASCINATE (làm say mê - động từ) → fascinating - hấp dẫn, làm say mê (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'subject' cần một TÍNH TỪ. Động từ 'fascinate' → tính từ 'fascinating' (thêm -ing). ✗ fascination = danh từ (sự say mê); ✗ fascinate = động từ nguyên mẫu; ✗ fascinatingly = trạng từ — đều sai vì vị trí này cần tính từ đứng trước danh từ 'subject'."},
  {"type":"mcq","id":"wf-434","cat":"noun","base":"BORE","q":"Many teenagers say that doing nothing all summer leads to ___ (BORE).","options":["boring","bore","boringly","boredom"],"correct":3,"answer":"boredom","vi":"BORE (làm chán - động từ) → boredom - sự buồn chán (danh từ)","explanation":"Sau giới từ 'to' (trong 'leads to') cần một DANH TỪ làm tân ngữ. Động từ 'bore' → danh từ 'boredom' (thêm -dom). ✗ boring = tính từ (gây chán, dùng cho vật/sự việc); ✗ bore = động từ nguyên mẫu; ✗ boringly = trạng từ — đều sai vì sau giới từ cần danh từ, không phải tính từ, động từ hay trạng từ."},
  {"type":"mcq","id":"wf-435","cat":"adv","base":"INTEREST","q":"The tour guide explained the castle's history so ___ (INTEREST) that no one wanted to leave.","options":["interestingly","interesting","interested","interest"],"correct":0,"answer":"interestingly","vi":"INTEREST (sự thích thú - danh từ/động từ) → interestingly - một cách thú vị (trạng từ)","explanation":"Cấu trúc 'so ___ that' ở đây bổ nghĩa cho động từ 'explained' (cách người hướng dẫn kể chuyện), nên cần một TRẠNG TỪ. Danh từ/động từ 'interest' → trạng từ 'interestingly' (thêm -ly vào 'interesting'). ✗ interesting = tính từ (thú vị, dùng cho vật/sự việc); ✗ interested = tính từ (cảm thấy thích thú, dùng cho người); ✗ interest = danh từ/động từ nguyên mẫu — đều sai vì đây cần trạng từ bổ nghĩa cho động từ 'explained'."},
  {"type":"mcq","id":"wf-436","cat":"adj","base":"PERFORM","q":"Music, dance, and drama are all examples of the ___ (PERFORM) arts.","options":["performance","performing","performer","perform"],"correct":1,"answer":"performing","vi":"PERFORM (biểu diễn - động từ) → performing - (thuộc về) biểu diễn (tính từ, trong cụm 'performing arts')","explanation":"Trước danh từ 'arts' cần một TÍNH TỪ để bổ nghĩa, ở đây là cụm cố định 'the performing arts' (nghệ thuật biểu diễn: âm nhạc, múa, kịch...). Động từ 'perform' → tính từ 'performing' (dạng V-ing dùng như tính từ). ✗ performance = danh từ (buổi biểu diễn); ✗ performer = danh từ (người biểu diễn); ✗ perform = động từ nguyên mẫu — đều sai vì không thể đứng ngay trước danh từ 'arts' để bổ nghĩa như tính từ."},
  {"type":"mcq","id":"wf-437","cat":"verb","base":"FANTASY","q":"Many kids like to ___ (FANTASY) about winning a video game championship.","options":["fantasy","fantastic","fantasize","fantastically"],"correct":2,"answer":"fantasize","vi":"FANTASY (trí tưởng tượng - danh từ) → fantasize - tưởng tượng, mơ mộng (động từ)","explanation":"Sau 'to' trong cụm 'like to + V' cần một ĐỘNG TỪ nguyên mẫu. Danh từ 'fantasy' → động từ 'fantasize' (thêm -ize). ✗ fantasy = danh từ; ✗ fantastic = tính từ (tuyệt vời); ✗ fantastically = trạng từ — đều sai vì sau 'to' trong cấu trúc này cần động từ."},
  {"type":"mcq","id":"wf-438","cat":"verb","base":"SOCIAL","q":"Young people often go to clubs and parties to ___ (SOCIAL) with friends during the weekend.","options":["social","society","socially","socialize"],"correct":3,"answer":"socialize","vi":"SOCIAL (thuộc về xã hội - tính từ) → socialize - giao lưu, kết bạn (động từ)","explanation":"Sau 'to' trong cụm 'go... to + V' (đi đâu đó để làm gì) cần một ĐỘNG TỪ nguyên mẫu. Tính từ 'social' → động từ 'socialize' (thêm -ize). ✗ social = tính từ; ✗ society = danh từ (xã hội); ✗ socially = trạng từ (về mặt xã hội) — đều sai vì sau 'to' cần động từ."},
  {"type":"mcq","id":"wf-439","cat":"verb","base":"DRAMA","q":"Filmmakers often ___ (DRAMA) real-life events to make documentaries more exciting to watch.","options":["dramatize","drama","dramatic","dramatically"],"correct":0,"answer":"dramatize","vi":"DRAMA (kịch - danh từ) → dramatize - kịch tính hóa, chuyển thể thành kịch (động từ)","explanation":"Chủ ngữ 'Filmmakers' cùng trạng từ 'often' cần một ĐỘNG TỪ chính ở dạng nguyên mẫu (thì hiện tại đơn, chủ ngữ số nhiều nên không thêm -s). Danh từ 'drama' → động từ 'dramatize' (thêm -ize). ✗ drama = danh từ; ✗ dramatic = tính từ (kịch tính); ✗ dramatically = trạng từ (một cách kịch tính) — đều sai vì vị trí này cần động từ chính của câu."},
  {"type":"mcq","id":"wf-440","cat":"verb","base":"CAPTIVE","q":"The magician's incredible tricks ___ (CAPTIVE) the entire audience from start to finish.","options":["captive","captivating","captivate","captivity"],"correct":2,"answer":"captivate","vi":"CAPTIVE (bị giam giữ, mê hoặc - tính từ/danh từ) → captivate - mê hoặc, thu hút (động từ)","explanation":"Chủ ngữ số nhiều 'tricks' cần một ĐỘNG TỪ chính ở thì hiện tại đơn (không thêm -s). Tính từ/danh từ 'captive' → động từ 'captivate' (thêm -ate). ✗ captive = tính từ/danh từ (bị giam giữ/tù nhân); ✗ captivating = tính từ (mê hoặc, hấp dẫn); ✗ captivity = danh từ (sự giam cầm) — đều sai vì vị trí này cần động từ chính của câu."},
  {"type":"mcq","id":"wf-441","cat":"adv","base":"ADMIRE","q":"The crowd watched the acrobat's daring stunt ___ (ADMIRE), clapping loudly at the end.","options":["admire","admiration","admirable","admiringly"],"correct":3,"answer":"admiringly","vi":"ADMIRE (ngưỡng mộ - động từ) → admiringly - với vẻ ngưỡng mộ (trạng từ)","explanation":"Động từ 'watched' cần một TRẠNG TỪ bổ nghĩa cho cách thức xem. Động từ 'admire' → trạng từ 'admiringly' (thêm -ing rồi -ly). ✗ admire = động từ nguyên mẫu; ✗ admiration = danh từ (sự ngưỡng mộ); ✗ admirable = tính từ (đáng ngưỡng mộ) — đều sai vì đây cần trạng từ bổ nghĩa cho động từ 'watched'."},
  {"type":"mcq","id":"wf-442","cat":"adv","base":"IMAGINE","q":"The children played ___ (IMAGINE), turning cardboard boxes into spaceships and castles.","options":["imaginatively","imagine","imagination","imaginative"],"correct":0,"answer":"imaginatively","vi":"IMAGINE (tưởng tượng - động từ) → imaginatively - một cách sáng tạo, giàu trí tưởng tượng (trạng từ)","explanation":"Động từ 'played' cần một TRẠNG TỪ bổ nghĩa cho cách thức chơi. Động từ 'imagine' → trạng từ 'imaginatively' (qua tính từ 'imaginative' rồi thêm -ly). ✗ imagine = động từ nguyên mẫu; ✗ imagination = danh từ (trí tưởng tượng); ✗ imaginative = tính từ (giàu trí tưởng tượng) — đều sai vì cần trạng từ bổ nghĩa cho động từ 'played'."},
  {"type":"mcq","id":"wf-443","cat":"adv","base":"CREATE","q":"The street performer juggled five flaming torches ___ (CREATE), keeping the crowd entertained for an hour.","options":["create","creatively","creation","creative"],"correct":1,"answer":"creatively","vi":"CREATE (sáng tạo - động từ) → creatively - một cách sáng tạo (trạng từ)","explanation":"Động từ 'juggled' cần một TRẠNG TỪ bổ nghĩa cho cách thức biểu diễn. Động từ 'create' → trạng từ 'creatively' (qua tính từ 'creative' rồi thêm -ly). ✗ create = động từ nguyên mẫu; ✗ creation = danh từ (sự sáng tạo); ✗ creative = tính từ (sáng tạo) — đều sai vì cần trạng từ bổ nghĩa cho động từ 'juggled'."},
  {"type":"mcq","id":"wf-444","cat":"noun","base":"CONFIDENT","q":"___ is one of the most important qualities for a successful public speaker. (CONFIDENT)","options":["confide","confident","Confidence","confidently"],"correct":2,"answer":"Confidence","vi":"confidence (n): sự tự tin","explanation":"Đầu câu, từ cần điền làm CHỦ NGỮ đứng trước động từ 'is' → cần DANH TỪ. confident → confidence (đổi đuôi tính từ -ent thành danh từ -ence). ✗ confide = động từ; ✗ confident = tính từ; ✗ confidently = trạng từ."},
  {"type":"mcq","id":"wf-445","cat":"adj","base":"SYMPATHY","q":"She gave her friend a ___ look after hearing the sad news. (SYMPATHY)","options":["sympathy","sympathize","sympathetically","sympathetic"],"correct":3,"answer":"sympathetic","vi":"sympathetic (adj): (biết) thông cảm","explanation":"Sau mạo từ 'a' và trước danh từ 'look' cần TÍNH TỪ bổ nghĩa. sympathy → sympathetic (đổi đuôi -y thành -etic). ✗ sympathy = danh từ; ✗ sympathize = động từ; ✗ sympathetically = trạng từ."},
  {"type":"mcq","id":"wf-446","cat":"adv","base":"TOLERANT","q":"The teacher listened ___ to the students' different opinions. (TOLERANT)","options":["tolerantly","tolerate","tolerance","tolerant"],"correct":0,"answer":"tolerantly","vi":"tolerantly (adv): một cách khoan dung","explanation":"Sau động từ 'listened' cần TRẠNG TỪ bổ nghĩa cho cách thức lắng nghe. tolerant → tolerantly (thêm hậu tố -ly). ✗ tolerate = động từ; ✗ tolerance = danh từ; ✗ tolerant = tính từ."},
  {"type":"mcq","id":"wf-447","cat":"verb","base":"ADMIRABLE","q":"Many people ___ her courage and determination. (ADMIRABLE)","options":["admiration","admire","admirable","admirably"],"correct":1,"answer":"admire","vi":"admire (v): ngưỡng mộ","explanation":"Sau chủ ngữ số nhiều 'Many people', câu cần ĐỘNG TỪ làm vị ngữ chính trước tân ngữ 'her courage'. admirable → admire (bỏ hậu tố tính từ -able, dùng động từ gốc). ✗ admiration = danh từ; ✗ admirable = tính từ; ✗ admirably = trạng từ."},
  {"type":"mcq","id":"wf-448","cat":"noun","base":"DETERMINED","q":"Her ___ to succeed impressed all her teachers. (DETERMINED)","options":["determine","determined","determination","determinedly"],"correct":2,"answer":"determination","vi":"determination (n): sự quyết tâm","explanation":"Sau tính từ sở hữu 'Her', từ cần điền làm CHỦ NGỮ của câu (trước động từ 'impressed') → cần DANH TỪ. determined → determination (đổi đuôi -ed thành -ation). ✗ determine = động từ; ✗ determined = tính từ; ✗ determinedly = trạng từ."},
  {"type":"mcq","id":"wf-449","cat":"adj","base":"RELIANCE","q":"A ___ friend is always there for you when you need help. (RELIANCE)","options":["rely","reliance","reliably","reliable"],"correct":3,"answer":"reliable","vi":"reliable (adj): đáng tin cậy","explanation":"Sau mạo từ 'A' và trước danh từ 'friend' cần TÍNH TỪ bổ nghĩa. reliance → reliable (đổi đuôi -ance thành -able). ✗ rely = động từ; ✗ reliance = danh từ; ✗ reliably = trạng từ."},
  {"type":"mcq","id":"wf-450","cat":"adv","base":"PERSISTENT","q":"He worked ___ on the project until it was finally finished. (PERSISTENT)","options":["persist","persistently","persistence","persistent"],"correct":1,"answer":"persistently","vi":"persistently (adv): một cách kiên trì","explanation":"Sau động từ 'worked' cần TRẠNG TỪ bổ nghĩa cho cách thức làm việc. persistent → persistently (thêm hậu tố -ly). ✗ persist = động từ; ✗ persistence = danh từ; ✗ persistent = tính từ."},
  {"type":"mcq","id":"wf-451","cat":"verb","base":"DEVOTED","q":"Good parents always ___ time and love to their children. (DEVOTED)","options":["devotion","devoted","devote","devotedly"],"correct":2,"answer":"devote","vi":"devote (v): dành trọn/cống hiến","explanation":"Sau trạng từ tần suất 'always' và chủ ngữ số nhiều 'Good parents', câu cần ĐỘNG TỪ chính. devoted → devote (bỏ hậu tố tính từ -ed, dùng động từ gốc). ✗ devotion = danh từ; ✗ devoted = tính từ; ✗ devotedly = trạng từ."},
  {"type":"mcq","id":"wf-452","cat":"noun","base":"ENCOURAGING","q":"The coach's constant ___ helped the team win the match. (ENCOURAGING)","options":["encourage","encouraging","encouragingly","encouragement"],"correct":3,"answer":"encouragement","vi":"encouragement (n): sự khích lệ","explanation":"Sau tính từ 'constant' và sở hữu cách 'The coach's', từ cần điền làm CHỦ NGỮ → cần DANH TỪ. encouraging → encouragement (đổi đuôi -ing thành -ement). ✗ encourage = động từ; ✗ encouraging = tính từ; ✗ encouragingly = trạng từ."},
  {"type":"mcq","id":"wf-453","cat":"adj","base":"IMAGINATION","q":"The little boy is very ___ and often invents his own stories. (IMAGINATION)","options":["imaginative","imagine","imagination","imaginatively"],"correct":0,"answer":"imaginative","vi":"imaginative (adj): giàu trí tưởng tượng","explanation":"Sau trạng từ chỉ mức độ 'very' và động từ 'to be' (is) cần TÍNH TỪ. imagination → imaginative (đổi đuôi -ation thành -ative). ✗ imagine = động từ; ✗ imagination = danh từ; ✗ imaginatively = trạng từ."},
  {"type":"mcq","id":"wf-454","cat":"adv","base":"CREATIVE","q":"She always solves problems ___, finding solutions no one else thinks of. (CREATIVE)","options":["create","creatively","creativity","creative"],"correct":1,"answer":"creatively","vi":"creatively (adv): một cách sáng tạo","explanation":"Sau cụm động từ 'solves problems' cần TRẠNG TỪ bổ nghĩa cho cách thức giải quyết. creative → creatively (thêm hậu tố -ly). ✗ create = động từ; ✗ creativity = danh từ; ✗ creative = tính từ."},
  {"type":"mcq","id":"wf-455","cat":"verb","base":"COOPERATION","q":"Team members should ___ with each other to finish the project on time. (COOPERATION)","options":["cooperation","cooperative","cooperate","cooperatively"],"correct":2,"answer":"cooperate","vi":"cooperate (v): hợp tác","explanation":"Sau động từ khuyết thiếu 'should' cần ĐỘNG TỪ nguyên mẫu. cooperation → cooperate (bỏ hậu tố danh từ -ion, dùng động từ gốc). ✗ cooperation = danh từ; ✗ cooperative = tính từ; ✗ cooperatively = trạng từ."},
  {"type":"mcq","id":"wf-456","cat":"noun","base":"ENERGETIC","q":"Even after a long day at school, she still had enough ___ to help her brother with his homework. (ENERGETIC)","options":["energize","energetic","energetically","energy"],"correct":3,"answer":"energy","vi":"energy (n): năng lượng","explanation":"Sau tính từ chỉ số lượng 'enough' cần DANH TỪ. energetic → energy (đổi đuôi -etic thành -y). ✗ energize = động từ; ✗ energetic = tính từ; ✗ energetically = trạng từ."},
  {"type":"mcq","id":"wf-457","cat":"adj","base":"APPRECIATION","q":"She gave an ___ smile when her classmates helped her carry the heavy books. (APPRECIATION)","options":["appreciative","appreciate","appreciation","appreciatively"],"correct":0,"answer":"appreciative","vi":"appreciative (adj): biết ơn/trân trọng","explanation":"Sau mạo từ 'an' và trước danh từ 'smile' cần TÍNH TỪ. appreciation → appreciative (đổi đuôi -ation thành -ative). ✗ appreciate = động từ; ✗ appreciation = danh từ; ✗ appreciatively = trạng từ."},
  {"type":"mcq","id":"wf-458","cat":"adv","base":"OBEDIENT","q":"The dog followed its owner ___ without any hesitation. (OBEDIENT)","options":["obey","obediently","obedience","obedient"],"correct":1,"answer":"obediently","vi":"obediently (adv): một cách ngoan ngoãn/vâng lời","explanation":"Sau động từ 'followed' cần TRẠNG TỪ bổ nghĩa cho cách thức. obedient → obediently (thêm hậu tố -ly). ✗ obey = động từ; ✗ obedience = danh từ; ✗ obedient = tính từ."},
  {"type":"mcq","id":"wf-459","cat":"verb","base":"INSPIRATION","q":"Great teachers always ___ their students to dream big and work hard. (INSPIRATION)","options":["inspiration","inspiring","inspire","inspiringly"],"correct":2,"answer":"inspire","vi":"inspire (v): truyền cảm hứng","explanation":"Sau trạng từ 'always' và chủ ngữ số nhiều 'Great teachers', câu cần ĐỘNG TỪ chính. inspiration → inspire (bỏ hậu tố danh từ -ation, dùng động từ gốc). ✗ inspiration = danh từ; ✗ inspiring = tính từ; ✗ inspiringly = trạng từ."},
  {"type":"mcq","id":"wf-460","cat":"noun","base":"CONSIDERATE","q":"He always shows great ___ for other people's feelings. (CONSIDERATE)","options":["consideration","consider","considerate","considerately"],"correct":0,"answer":"consideration","vi":"consideration (n): sự quan tâm/chu đáo","explanation":"Sau tính từ 'great' và động từ 'shows', vị trí cần DANH TỪ làm tân ngữ. considerate → consideration (đổi đuôi -ate thành -ation). ✗ consider = động từ; ✗ considerate = tính từ; ✗ considerately = trạng từ."},
  {"type":"mcq","id":"wf-461","cat":"adj","base":"FORGIVENESS","q":"My grandmother has a very ___ nature and never holds a grudge against anyone. (FORGIVENESS)","options":["forgive","forgiving","forgiveness","forgivingly"],"correct":1,"answer":"forgiving","vi":"forgiving (adj): (có lòng) khoan dung, dễ tha thứ","explanation":"Sau trạng từ 'very' và trước danh từ 'nature' cần TÍNH TỪ. forgiveness → forgiving (đổi đuôi -eness thành -ing). ✗ forgive = động từ; ✗ forgiveness = danh từ; ✗ forgivingly = trạng từ."},
  {"type":"mcq","id":"wf-462","cat":"adv","base":"ENTHUSIASTIC","q":"The new student joined every school activity ___. (ENTHUSIASTIC)","options":["enthuse","enthusiasm","enthusiastically","enthusiastic"],"correct":2,"answer":"enthusiastically","vi":"enthusiastically (adv): một cách nhiệt tình","explanation":"Cuối câu, từ cần điền bổ nghĩa cho động từ 'joined' → cần TRẠNG TỪ. enthusiastic → enthusiastically (thêm hậu tố -ally). ✗ enthuse = động từ; ✗ enthusiasm = danh từ; ✗ enthusiastic = tính từ."},
  {"type":"mcq","id":"wf-463","cat":"verb","base":"EXCITEMENT","q":"Her cheerful personality can easily ___ everyone in the room. (EXCITEMENT)","options":["excitement","excited","excitedly","excite"],"correct":3,"answer":"excite","vi":"excite (v): làm phấn khích","explanation":"Sau trợ động từ khuyết thiếu 'can' cần ĐỘNG TỪ nguyên mẫu làm vị ngữ chính. excitement → excite (bỏ hậu tố danh từ -ment, dùng động từ gốc). ✗ excitement = danh từ; ✗ excited = tính từ; ✗ excitedly = trạng từ."},
  {"type":"mcq","id":"wf-464","cat":"noun","base":"ATTRACTIVE","q":"Her warm smile was the main ___ that made everyone like her instantly. (ATTRACTIVE)","options":["attraction","attract","attractive","attractively"],"correct":0,"answer":"attraction","vi":"attraction (n): sức hút/điều thu hút","explanation":"Sau tính từ 'main' và động từ 'was', vị trí cần DANH TỪ làm bổ ngữ chủ ngữ. attractive → attraction (đổi đuôi -ive thành -ion). ✗ attract = động từ; ✗ attractive = tính từ; ✗ attractively = trạng từ."},
  {"type":"mcq","id":"wf-465","cat":"adj","base":"FASCINATION","q":"Everyone finds him ___ because of the interesting stories he always tells. (FASCINATION)","options":["fascinate","fascinating","fascination","fascinatingly"],"correct":1,"answer":"fascinating","vi":"fascinating (adj): hấp dẫn, cuốn hút","explanation":"Trong cấu trúc 'find + tân ngữ + tính từ', sau tân ngữ 'him' cần TÍNH TỪ. fascination → fascinating (đổi đuôi -ion thành -ing). ✗ fascinate = động từ; ✗ fascination = danh từ; ✗ fascinatingly = trạng từ."},
  {"type":"mcq","id":"wf-466","cat":"adv","base":"FLEXIBILITY","q":"A good leader should be able to think ___ when plans change suddenly. (FLEXIBILITY)","options":["flex","flexibility","flexibly","flexible"],"correct":2,"answer":"flexibly","vi":"flexibly (adv): một cách linh hoạt","explanation":"Sau động từ 'think' cần TRẠNG TỪ bổ nghĩa cho cách thức suy nghĩ. flexibility → flexibly (đổi đuôi -ility thành -ly). ✗ flex = động từ; ✗ flexibility = danh từ; ✗ flexible = tính từ."},
  {"type":"mcq","id":"wf-467","cat":"verb","base":"FLATTERY","q":"He always tries to ___ his boss in order to get a promotion. (FLATTERY)","options":["flattery","flattering","flatteringly","flatter"],"correct":3,"answer":"flatter","vi":"flatter (v): nịnh hót/tâng bốc","explanation":"Sau 'to' trong cấu trúc động từ nguyên mẫu 'tries to...' cần ĐỘNG TỪ. flattery → flatter (bỏ hậu tố danh từ -y, dùng động từ gốc). ✗ flattery = danh từ; ✗ flattering = tính từ; ✗ flatteringly = trạng từ."},
  {"type":"mcq","id":"wf-468","cat":"noun","base":"OBSERVE","q":"The students wrote down their ___ (OBSERVE) after watching the plant grow for two weeks.","options":["observations","observant","observantly","observe"],"correct":0,"answer":"observations","vi":"quan sát (danh từ) – sự quan sát","explanation":"Sau tính từ sở hữu 'their' cần một DANH TỪ làm tân ngữ cho 'wrote down' (số nhiều vì có nhiều lần quan sát trong hai tuần). observe (quan sát, động từ) → observation (thêm đuôi -ation, danh từ: sự quan sát) → observations (số nhiều). ✗ observant = tính từ (tinh ý, hay để ý); ✗ observantly = trạng từ; ✗ observe = động từ nguyên mẫu, không thể đứng sau 'their'."},
  {"type":"mcq","id":"wf-469","cat":"adj","base":"MEASURE","q":"Scientists need results that are ___ (MEASURE) so that other researchers can check them.","options":["measurement","measurable","measurably","measure"],"correct":1,"answer":"measurable","vi":"có thể đo được (tính từ)","explanation":"Sau động từ 'to be' (are) cần TÍNH TỪ bổ nghĩa cho chủ ngữ 'results'. measure (đo lường, động từ) → measurable (thêm đuôi -able, tính từ: có thể đo được). ✗ measurement = danh từ số ít (phép đo) không hợp với chủ ngữ số nhiều 'results'; ✗ measurably = trạng từ, không đứng sau 'be' làm bổ ngữ; ✗ measure = động từ."},
  {"type":"mcq","id":"wf-470","cat":"adv","base":"CONCLUDE","q":"The data ___ (CONCLUDE) proved that the new drug was effective.","options":["conclusion","conclusive","conclude","conclusively"],"correct":3,"answer":"conclusively","vi":"một cách chắc chắn, dứt khoát (trạng từ)","explanation":"Vị trí giữa chủ ngữ 'the data' và động từ 'proved' cần TRẠNG TỪ bổ nghĩa cho động từ. conclude (kết luận, động từ) → conclusive (thêm đuôi -ive, tính từ) → conclusively (thêm đuôi -ly, trạng từ). ✗ conclusion = danh từ, chen vào giữa chủ ngữ và động từ sẽ khiến câu thiếu động từ chính; ✗ conclusive = tính từ, không thể đứng trước động từ mà không có 'to be'; ✗ conclude = động từ, không thể có hai động từ liền nhau."},
  {"type":"mcq","id":"wf-471","cat":"adj","base":"DESCRIBE","q":"The textbook gives a very ___ (DESCRIBE) account of how volcanoes form.","options":["descriptive","description","descriptively","describe"],"correct":0,"answer":"descriptive","vi":"mang tính miêu tả (tính từ)","explanation":"Sau trạng từ chỉ mức độ 'very' và trước danh từ 'account' cần TÍNH TỪ ('very' chỉ bổ nghĩa cho tính từ/trạng từ). describe (miêu tả, động từ) → descriptive (thêm đuôi -ive, tính từ: mang tính miêu tả). ✗ description = danh từ, 'very' không thể đứng trước danh từ; ✗ descriptively = trạng từ, cũng không đứng trước danh từ; ✗ describe = động từ."},
  {"type":"mcq","id":"wf-472","cat":"adj","base":"DEFINE","q":"Before the experiment starts, the teacher gives very ___ (DEFINE) instructions for every group to follow exactly.","options":["definition","definite","definitely","define"],"correct":1,"answer":"definite","vi":"rõ ràng, xác định (tính từ)","explanation":"Sau trạng từ chỉ mức độ 'very' và trước danh từ 'instructions' cần TÍNH TỪ ('very' chỉ đứng trước tính từ/trạng từ, không đứng trước danh từ). define (định nghĩa/xác định, động từ) → definite (thêm đuôi -ite, tính từ: rõ ràng, cụ thể, dứt khoát). ✗ definition = danh từ (định nghĩa), không thể đứng sau 'very'; ✗ definitely = trạng từ, không thể đứng trước danh từ 'instructions'; ✗ define = động từ."},
  {"type":"mcq","id":"wf-473","cat":"adv","base":"PREDICT","q":"In this experiment, the metal expands ___ (PREDICT) whenever it is heated.","options":["prediction","predictable","predictably","predict"],"correct":2,"answer":"predictably","vi":"một cách có thể đoán trước (trạng từ)","explanation":"Cần TRẠNG TỪ bổ nghĩa cho động từ nội động từ 'expands' (không có tân ngữ theo sau). predict (dự đoán, động từ) → predictable (thêm đuôi -able, tính từ) → predictably (thêm đuôi -ly, trạng từ). ✗ prediction = danh từ, 'expand' không nhận tân ngữ kiểu này; ✗ predictable = tính từ, không thể đứng ngay sau động từ mà không có 'to be'; ✗ predict = động từ, không thể có hai động từ liền nhau."},
  {"type":"mcq","id":"wf-474","cat":"adj","base":"IDENTIFY","q":"Under the microscope, the cells showed a highly ___ (IDENTIFY) pattern that matched the textbook diagram.","options":["identification","identifiably","identify","identifiable"],"correct":3,"answer":"identifiable","vi":"có thể nhận biết được (tính từ)","explanation":"Sau trạng từ chỉ mức độ 'highly' và trước danh từ 'pattern' cần TÍNH TỪ ('highly' chỉ bổ nghĩa cho tính từ, không đứng trước danh từ). identify (nhận dạng, động từ) → identifiable (thêm đuôi -able, tính từ: có thể nhận ra). ✗ identification = danh từ (sự nhận dạng); ✗ identifiably = trạng từ, không đứng trước danh từ; ✗ identify = động từ."},
  {"type":"mcq","id":"wf-475","cat":"adj","base":"COMPARE","q":"The two test results are ___ (COMPARE), so the scientists can analyze them side by side.","options":["comparable","comparison","comparably","compare"],"correct":0,"answer":"comparable","vi":"có thể so sánh được (tính từ)","explanation":"Sau động từ 'to be' (are) cần TÍNH TỪ bổ nghĩa cho chủ ngữ 'the two test results'. compare (so sánh, động từ) → comparable (thêm đuôi -able, tính từ: có thể so sánh). ✗ comparison = danh từ số ít, không khớp chủ ngữ số nhiều và không hợp nghĩa làm bổ ngữ 'are'; ✗ comparably = trạng từ; ✗ compare = động từ."},
  {"type":"mcq","id":"wf-476","cat":"verb","base":"EVALUATE","q":"Every year, the committee ___ (EVALUATE) the safety of new chemical products before they reach the market.","options":["evaluation","evaluates","evaluative","evaluatively"],"correct":1,"answer":"evaluates","vi":"đánh giá (động từ)","explanation":"Câu cần một ĐỘNG TỪ chính (theo sau là tân ngữ 'the safety'); chủ ngữ số ít 'the committee' + 'every year' (thói quen lặp lại) nên chia thì hiện tại đơn, thêm 's'. evaluate (đánh giá) → evaluates. ✗ evaluation = danh từ, không thể làm vị ngữ chính của câu; ✗ evaluative = tính từ; ✗ evaluatively = trạng từ — cả hai đều khiến câu thiếu động từ."},
  {"type":"mcq","id":"wf-477","cat":"noun","base":"INTERPRET","q":"Two scientists studying the same data can give a completely different ___ (INTERPRET) of what it means.","options":["interpretive","interpretively","interpretation","interpret"],"correct":2,"answer":"interpretation","vi":"sự diễn giải (danh từ)","explanation":"Sau tính từ 'different' và mạo từ 'a' cần DANH TỪ làm tân ngữ của 'give'. interpret (diễn giải, động từ) → interpretation (thêm đuôi -ation, danh từ: sự diễn giải). ✗ interpretive = tính từ, không thể làm tân ngữ; ✗ interpretively = trạng từ; ✗ interpret = động từ nguyên mẫu."},
  {"type":"mcq","id":"wf-478","cat":"verb","base":"DEMONSTRATE","q":"In yesterday's class, the teacher ___ (DEMONSTRATE) how to use a microscope correctly.","options":["demonstration","demonstrative","demonstratively","demonstrated"],"correct":3,"answer":"demonstrated","vi":"minh họa, trình bày (động từ)","explanation":"Câu cần ĐỘNG TỪ chính, và có 'yesterday' chỉ thời gian quá khứ nên chia ở thì quá khứ đơn. demonstrate (minh họa) → demonstrated. ✗ demonstration = danh từ (buổi trình bày), không thể làm vị ngữ chính; ✗ demonstrative = tính từ; ✗ demonstratively = trạng từ."},
  {"type":"mcq","id":"wf-479","cat":"noun","base":"VERIFY","q":"Before publishing the results, the team carried out a careful ___ (VERIFY) of every number in the report.","options":["verification","verifiable","verifiably","verify"],"correct":0,"answer":"verification","vi":"sự xác minh (danh từ)","explanation":"Sau mạo từ 'a' và tính từ 'careful' cần DANH TỪ làm tân ngữ của 'carried out'. verify (xác minh, động từ) → verification (thêm đuôi -ation, danh từ: sự xác minh). ✗ verifiable = tính từ (có thể xác minh); ✗ verifiably = trạng từ; ✗ verify = động từ, không thể đứng sau 'a careful'."},
  {"type":"mcq","id":"wf-480","cat":"verb","base":"INVENT","q":"In 1879, Thomas Edison ___ (INVENT) a practical electric light bulb that could be produced cheaply.","options":["invention","inventive","invented","inventively"],"correct":2,"answer":"invented","vi":"phát minh (động từ)","explanation":"Câu cần ĐỘNG TỪ chính, và mốc thời gian quá khứ 'In 1879' yêu cầu chia ở thì quá khứ đơn. invent (phát minh) → invented. ✗ invention = danh từ (phát minh, sáng chế); ✗ inventive = tính từ; ✗ inventively = trạng từ — cả ba đều không thể làm vị ngữ chính của câu."},
  {"type":"mcq","id":"wf-481","cat":"verb","base":"PRODUCE","q":"This factory ___ (PRODUCE) thousands of solar panels every month.","options":["production","productive","productively","produces"],"correct":3,"answer":"produces","vi":"sản xuất (động từ)","explanation":"Câu cần ĐỘNG TỪ chính; chủ ngữ số ít 'this factory' cùng 'every month' (sự việc lặp lại) chia ở thì hiện tại đơn, thêm 's'. produce (sản xuất) → produces. ✗ production = danh từ (sự sản xuất); ✗ productive = tính từ; ✗ productively = trạng từ — không thể làm vị ngữ chính."},
  {"type":"mcq","id":"wf-482","cat":"noun","base":"PERSUADE","q":"The team won the debate through clever ___ (PERSUADE) rather than solid evidence.","options":["persuasion","persuasive","persuasively","persuade"],"correct":0,"answer":"persuasion","vi":"sự thuyết phục (danh từ)","explanation":"Sau giới từ 'through' và tính từ 'clever' cần DANH TỪ làm tân ngữ của giới từ. persuade (thuyết phục, động từ) → persuasion (thêm đuôi -sion, danh từ: sự thuyết phục). ✗ persuasive = tính từ, không thể làm tân ngữ của giới từ một mình; ✗ persuasively = trạng từ; ✗ persuade = động từ, không thể đứng sau giới từ 'through'."},
  {"type":"mcq","id":"wf-483","cat":"adv","base":"INFORM","q":"The chart presents the survey results ___ (INFORM), helping readers understand the trend quickly.","options":["information","informatively","informative","inform"],"correct":1,"answer":"informatively","vi":"một cách có tính thông tin (trạng từ)","explanation":"Cần TRẠNG TỪ bổ nghĩa cho động từ 'presents' (đứng sau tân ngữ 'the survey results'). inform (thông báo, động từ) → informative (thêm đuôi -ive, tính từ) → informatively (thêm đuôi -ly, trạng từ). ✗ information = danh từ (thông tin), không thể ghép trực tiếp sau danh từ khác mà không có giới từ; ✗ informative = tính từ, không bổ nghĩa được cho động từ ở đây; ✗ inform = động từ."},
  {"type":"mcq","id":"wf-484","cat":"verb","base":"COMMUNICATE","q":"A single bee ___ (COMMUNICATE) the location of food to the rest of the hive through a special dance.","options":["communication","communicative","communicates","communicatively"],"correct":2,"answer":"communicates","vi":"giao tiếp, truyền đạt (động từ)","explanation":"Câu cần ĐỘNG TỪ chính có tân ngữ 'the location'; chủ ngữ số ít 'a single bee' diễn tả sự thật hiển nhiên nên chia hiện tại đơn, thêm 's'. communicate (giao tiếp) → communicates. ✗ communication = danh từ (sự giao tiếp); ✗ communicative = tính từ; ✗ communicatively = trạng từ — không thể làm vị ngữ chính."},
  {"type":"mcq","id":"wf-485","cat":"noun","base":"HYPOTHESIZE","q":"The students tested their ___ (HYPOTHESIZE) by running the same experiment three times.","options":["hypothetical","hypothetically","hypothesize","hypothesis"],"correct":3,"answer":"hypothesis","vi":"giả thuyết (danh từ)","explanation":"Sau tính từ sở hữu 'their' cần DANH TỪ làm tân ngữ của 'tested'. hypothesize (đưa ra giả thuyết, động từ) → hypothesis (danh từ: giả thuyết). ✗ hypothetical = tính từ (mang tính giả định), không thể làm tân ngữ một mình; ✗ hypothetically = trạng từ; ✗ hypothesize = động từ nguyên mẫu, không thể đứng sau 'their'."},
  {"type":"mcq","id":"wf-486","cat":"verb","base":"INVESTIGATE","q":"The research team ___ (INVESTIGATE) the cause of the coral reef's decline for over a year.","options":["investigated","investigation","investigative","investigatively"],"correct":0,"answer":"investigated","vi":"điều tra, nghiên cứu (động từ)","explanation":"Câu cần ĐỘNG TỪ chính có tân ngữ 'the cause'; khoảng thời gian đã hoàn tất 'for over a year' đi cùng ngữ cảnh tường thuật nên chia ở thì quá khứ đơn. investigate (điều tra) → investigated. ✗ investigation = danh từ (cuộc điều tra); ✗ investigative = tính từ; ✗ investigatively = trạng từ — không thể làm vị ngữ chính của câu."},
  {"type":"mcq","id":"wf-487","cat":"adj","base":"ILLUSTRATE","q":"The diagram provides a truly ___ (ILLUSTRATE) example of how the water cycle works.","options":["illustration","illustrative","illustratively","illustrate"],"correct":1,"answer":"illustrative","vi":"có tính minh họa (tính từ)","explanation":"Sau trạng từ chỉ mức độ 'truly' và trước danh từ 'example' cần TÍNH TỪ ('truly' chỉ bổ nghĩa cho tính từ, không đứng trước danh từ). illustrate (minh họa, động từ) → illustrative (thêm đuôi -ive, tính từ: có tính minh họa). ✗ illustration = danh từ (hình minh họa), không thể đứng sau 'truly'; ✗ illustratively = trạng từ, cũng không đứng trước danh từ; ✗ illustrate = động từ."},
  {"type":"mcq","id":"wf-488","cat":"noun","base":"DEEP","q":"Scientists measured the ___ of the ocean trench using sonar technology. (DEEP)","options":["deep","deeply","depth","deepen"],"correct":2,"answer":"depth","vi":"độ sâu (danh từ)","explanation":"Sau 'the' và trước cụm giới từ 'of the ocean trench' cần DANH TỪ làm tân ngữ của 'measured'. deep → depth (hậu tố -th). ✗ deep = tính từ; ✗ deeply = trạng từ; ✗ deepen = động từ."},
  {"type":"mcq","id":"wf-489","cat":"noun","base":"WIDE","q":"The engineers calculated the exact ___ of the new bridge before construction began. (WIDE)","options":["wide","widely","widen","width"],"correct":3,"answer":"width","vi":"chiều rộng (danh từ)","explanation":"Sau tính từ 'exact' và trước 'of' cần DANH TỪ. wide → width (hậu tố -th). ✗ wide = tính từ; ✗ widely = trạng từ; ✗ widen = động từ."},
  {"type":"mcq","id":"wf-490","cat":"noun","base":"STABLE","q":"Political ___ is essential for a country's economic growth and development. (STABLE)","options":["stable","stability","stably","stabilize"],"correct":1,"answer":"stability","vi":"sự ổn định (danh từ)","explanation":"Sau tính từ 'Political' và làm chủ ngữ của động từ 'is' cần DANH TỪ. stable → stability (hậu tố -ity). ✗ stable = tính từ; ✗ stably = trạng từ; ✗ stabilize = động từ."},
  {"type":"mcq","id":"wf-491","cat":"noun","base":"INTENSE","q":"The ___ of the storm increased rapidly as it approached the coastline. (INTENSE)","options":["intense","intensely","intensity","intensify"],"correct":2,"answer":"intensity","vi":"cường độ (danh từ)","explanation":"Sau 'The' và làm chủ ngữ của động từ 'increased' cần DANH TỪ. intense → intensity (hậu tố -ity). ✗ intense = tính từ; ✗ intensely = trạng từ; ✗ intensify = động từ."},
  {"type":"mcq","id":"wf-492","cat":"verb","base":"LENGTH","q":"The government decided to ___ the school year by two weeks. (LENGTH)","options":["length","long","lengthwise","lengthen"],"correct":3,"answer":"lengthen","vi":"kéo dài (động từ)","explanation":"Sau 'to' cần ĐỘNG TỪ nguyên mẫu. length → lengthen (hậu tố -en). ✗ length = danh từ; ✗ long = tính từ (gốc của 'length'); ✗ lengthwise = trạng từ (theo chiều dài)."},
  {"type":"mcq","id":"wf-493","cat":"adj","base":"VARY","q":"The museum displays artifacts from ___ periods of ancient history. (VARY)","options":["various","vary","variety","variously"],"correct":0,"answer":"various","vi":"đa dạng, khác nhau (tính từ)","explanation":"Trước danh từ 'periods' cần TÍNH TỪ bổ nghĩa. vary → various (hậu tố -ous). ✗ vary = động từ; ✗ variety = danh từ; ✗ variously = trạng từ."},
  {"type":"mcq","id":"wf-494","cat":"adj","base":"PROGRESS","q":"The school adopted a ___ teaching method that focuses on student creativity. (PROGRESS)","options":["progress","progressive","progression","progressively"],"correct":1,"answer":"progressive","vi":"tiến bộ (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'teaching method' cần TÍNH TỪ. progress → progressive (hậu tố -ive). ✗ progress = danh từ/động từ; ✗ progression = danh từ; ✗ progressively = trạng từ."},
  {"type":"mcq","id":"wf-495","cat":"adj","base":"ADAPT","q":"Cats are highly ___ animals that can survive in many different environments. (ADAPT)","options":["adapt","adaptation","adaptable","adaptably"],"correct":2,"answer":"adaptable","vi":"dễ thích nghi (tính từ)","explanation":"Sau trạng từ 'highly' và trước danh từ 'animals' cần TÍNH TỪ. adapt → adaptable (hậu tố -able). ✗ adapt = động từ; ✗ adaptation = danh từ; ✗ adaptably = trạng từ."},
  {"type":"mcq","id":"wf-496","cat":"adj","base":"BENEFIT","q":"Regular reading has a ___ impact on children's language development. (BENEFIT)","options":["benefit","beneficially","beneficiary","beneficial"],"correct":3,"answer":"beneficial","vi":"có lợi (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'impact' cần TÍNH TỪ. benefit → beneficial (hậu tố -ial). ✗ benefit = danh từ/động từ; ✗ beneficially = trạng từ; ✗ beneficiary = danh từ (người thụ hưởng)."},
  {"type":"mcq","id":"wf-497","cat":"adv","base":"DRAMATIC","q":"The city's population has ___ increased over the past two decades. (DRAMATIC)","options":["dramatically","drama","dramatize","dramatic"],"correct":0,"answer":"dramatically","vi":"một cách kịch tính, mạnh mẽ (trạng từ)","explanation":"Đứng giữa trợ động từ 'has' và phân từ 'increased' để bổ nghĩa cho động từ cần TRẠNG TỪ. dramatic → dramatically (hậu tố -ly). ✗ drama = danh từ; ✗ dramatize = động từ; ✗ dramatic = tính từ."},
  {"type":"mcq","id":"wf-498","cat":"adv","base":"CONSIDER","q":"Traffic congestion has ___ improved since the new metro line began operating. (CONSIDER)","options":["consider","considerably","consideration","considerable"],"correct":1,"answer":"considerably","vi":"đáng kể (trạng từ)","explanation":"Đứng giữa 'has' và phân từ 'improved' cần TRẠNG TỪ. consider → considerable → considerably (hậu tố -ly). ✗ consider = động từ; ✗ consideration = danh từ; ✗ considerable = tính từ."},
  {"type":"mcq","id":"wf-499","cat":"adv","base":"EFFECT","q":"The new policy has ___ reduced traffic congestion in the city center. (EFFECT)","options":["effect","effective","effectively","effectiveness"],"correct":2,"answer":"effectively","vi":"một cách hiệu quả (trạng từ)","explanation":"Đứng giữa 'has' và phân từ 'reduced' cần TRẠNG TỪ bổ nghĩa cho động từ. effect → effective → effectively (hậu tố -ly). ✗ effect = danh từ; ✗ effective = tính từ; ✗ effectiveness = danh từ."},
  {"type":"mcq","id":"wf-500","cat":"adv","base":"RAPID","q":"The country's economy has been ___ transforming since the reforms began. (RAPID)","options":["rapid","rapidity","rapidness","rapidly"],"correct":3,"answer":"rapidly","vi":"nhanh chóng (trạng từ)","explanation":"Đứng giữa 'has been' và danh động từ 'transforming' cần TRẠNG TỪ bổ nghĩa cho động từ. rapid → rapidly (hậu tố -ly). ✗ rapid = tính từ; ✗ rapidity = danh từ; ✗ rapidness = danh từ."},
  {"id":"wft-1","type":"text","cat":"noun","base":"EDUCATE","q":"Every child deserves a good ___ (EDUCATE), no matter where they live.","answer":"education","accept":["education"],"vi":"EDUCATE (giáo dục - động từ) → education — nền giáo dục (danh từ)","explanation":"Sau tính từ 'good' và đóng vai trò tân ngữ của động từ 'deserves' cần một DANH TỪ. EDUCATE (động từ) → education (thêm hậu tố -ion, danh từ: nền giáo dục)."},
  {"id":"wft-2","type":"text","cat":"noun","base":"CREATIVE","q":"The company organizes workshops to encourage ___ (CREATIVE) among its young employees.","answer":"creativity","accept":["creativity"],"vi":"CREATIVE (sáng tạo - tính từ) → creativity — sự sáng tạo (danh từ)","explanation":"Sau động từ 'encourage' cần một DANH TỪ làm tân ngữ. CREATIVE (tính từ) → creativity (thêm hậu tố -ity, danh từ: sự sáng tạo)."},
  {"id":"wft-3","type":"text","cat":"adj","base":"COMPETE","q":"The job market for graduates has become extremely ___ (COMPETE) in recent years.","answer":"competitive","accept":["competitive"],"vi":"COMPETE (cạnh tranh - động từ) → competitive — mang tính cạnh tranh (tính từ)","explanation":"Sau động từ liên kết 'become' và trạng từ 'extremely' cần một TÍNH TỪ làm bổ ngữ. COMPETE (động từ) → competitive (thêm hậu tố -itive, tính từ: mang tính cạnh tranh)."},
  {"id":"wft-4","type":"text","cat":"adv","base":"PATIENT","q":"She waited ___ (PATIENT) in the corridor until the doctor called her name.","answer":"patiently","accept":["patiently"],"vi":"PATIENT (kiên nhẫn - tính từ) → patiently — một cách kiên nhẫn (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho động từ 'waited' nên phải là một TRẠNG TỪ. PATIENT (tính từ) → patiently (thêm hậu tố -ly, trạng từ: một cách kiên nhẫn)."},
  {"id":"wft-5","type":"text","cat":"verb","base":"EXAMINATION","q":"The doctor will ___ (EXAMINATION) your throat carefully before giving a diagnosis.","answer":"examine","accept":["examine"],"vi":"EXAMINATION (kỳ thi, sự kiểm tra - danh từ) → examine — kiểm tra, khảo sát (động từ)","explanation":"Ngay sau trợ động từ 'will' cần một ĐỘNG TỪ nguyên mẫu. EXAMINATION (danh từ) → examine (bỏ hậu tố -ation, động từ: kiểm tra, khảo sát)."},
  {"id":"wft-6","type":"text","cat":"adv","base":"MEDICINE","q":"This new treatment has not yet been ___ (MEDICINE) proven to cure the disease.","answer":"medically","accept":["medically"],"vi":"MEDICINE (y học/thuốc - danh từ) → medically — về mặt y khoa (trạng từ)","explanation":"Từ cần điền bổ nghĩa cho phân từ 'proven' (đứng giữa 'been' và 'proven') nên phải là một TRẠNG TỪ. MEDICINE (danh từ) → medically (thêm hậu tố -ally, trạng từ: về mặt y khoa)."},
  {"id":"wft-7","type":"text","cat":"verb","base":"INFECTION","q":"Dirty water can easily ___ (INFECTION) an open wound if it is not cleaned properly.","answer":"infect","accept":["infect"],"vi":"INFECTION (sự nhiễm trùng - danh từ) → infect — làm nhiễm trùng (động từ)","explanation":"Sau trợ động từ 'can' (dù có trạng từ 'easily' xen giữa) cần một ĐỘNG TỪ nguyên mẫu. INFECTION (danh từ) → infect (bỏ hậu tố -ion, động từ: làm nhiễm trùng)."},
  {"id":"wft-8","type":"text","cat":"verb","base":"OPERATION","q":"The surgeon will ___ (OPERATION) on the patient's knee early tomorrow morning.","answer":"operate","accept":["operate"],"vi":"OPERATION (ca phẫu thuật - danh từ) → operate — phẫu thuật/vận hành (động từ)","explanation":"Ngay sau trợ động từ 'will' cần một ĐỘNG TỪ nguyên mẫu. OPERATION (danh từ) → operate (bỏ hậu tố -ion, động từ: phẫu thuật)."},
  {"id":"wft-9","type":"text","cat":"verb","base":"DANGER","q":"Illegal hunting continues to ___ (DANGER) many rare animal species around the world.","answer":"endanger","accept":["endanger"],"vi":"DANGER (sự nguy hiểm - danh từ) → endanger — gây nguy hiểm cho (động từ)","explanation":"Ngay sau 'to' (to-infinitive, sau động từ 'continues') cần một ĐỘNG TỪ nguyên mẫu. DANGER (danh từ) → endanger (thêm tiền tố en-, động từ: gây nguy hiểm cho)."},
  {"id":"wft-10","type":"text","cat":"adj","base":"ALLERGY","q":"My younger brother is ___ (ALLERGY) to peanuts, so he never eats them.","answer":"allergic","accept":["allergic"],"vi":"ALLERGY (dị ứng - danh từ) → allergic — bị dị ứng (tính từ)","explanation":"Sau động từ 'to be' (is) cần một TÍNH TỪ làm bổ ngữ chủ ngữ. ALLERGY (danh từ) → allergic (thêm hậu tố -ic, tính từ: bị dị ứng)."},
  {"id":"wft-11","type":"text","cat":"adv","base":"DANGER","q":"The teenagers were riding their motorbikes ___ (DANGER) through the crowded market, scaring several pedestrians.","answer":"dangerously","accept":["dangerously"],"vi":"DANGER (sự nguy hiểm) → dangerously – một cách nguy hiểm (trạng từ)","explanation":"Từ cần điền đứng sau động từ 'riding' và bổ nghĩa cho cách thức thực hiện hành động (đi xe như thế nào) → cần TRẠNG TỪ. danger (danh từ) → dangerous (tính từ, thêm -ous) → dangerously (trạng từ, thêm -ly)."},
  {"id":"wft-12","type":"text","cat":"noun","base":"DESTROY","q":"The fire spread so quickly that it left a trail of ___ (DESTROY) across the entire neighborhood.","answer":"destruction","accept":["destruction"],"vi":"DESTROY (phá hủy) → destruction – sự phá hủy (danh từ)","explanation":"Từ cần điền đứng sau giới từ 'of' (a trail of...) và làm tân ngữ của giới từ đó → cần DANH TỪ. destroy (động từ) → destruction (danh từ, dạng biến đổi bất quy tắc: destr-oy → destr-uction)."},
  {"id":"wft-13","type":"text","cat":"adv","base":"NATURE","q":"Even after years abroad, he still speaks his mother tongue so ___ (NATURE) that no one can tell he ever left.","answer":"naturally","accept":["naturally"],"vi":"NATURE (tự nhiên) → naturally – một cách tự nhiên (trạng từ)","explanation":"Từ cần điền đứng ngay sau 'so' và bổ nghĩa cho động từ 'speaks' trong cấu trúc 'so + trạng từ + that' (nói theo cách như thế nào) → cần TRẠNG TỪ. nature (danh từ) → natural (tính từ, thêm -al) → naturally (trạng từ, thêm -ly)."},
  {"id":"wft-14","type":"text","cat":"adj","base":"HARM","q":"Doctors say that too much sun exposure can be ___ (HARM) to young children's skin.","answer":"harmful","accept":["harmful"],"vi":"HARM (sự nguy hại) → harmful – có hại (tính từ)","explanation":"Từ cần điền đứng sau động từ liên kết 'be' (can be) và bổ nghĩa cho chủ ngữ 'too much sun exposure' → cần TÍNH TỪ. harm (danh từ) → harmful (tính từ, thêm -ful)."},
  {"id":"wft-15","type":"text","cat":"verb","base":"WARM","q":"Global ___ (WARM) is causing sea levels to rise and ice caps to melt faster than ever before.","answer":"warming","accept":["warming"],"vi":"WARM (ấm) → warming – sự nóng lên (danh động từ/V-ing)","explanation":"Từ cần điền kết hợp với 'Global' tạo thành cụm chủ ngữ đứng trước động từ 'is causing' → cần dạng V-ing (danh động từ, chức năng như danh từ). warm (tính từ) → warming (thêm -ing)."},
  {"id":"wft-16","type":"text","cat":"noun","base":"COMMUNICATE","q":"Clear ___ (COMMUNICATE) between doctors and patients reduces the risk of medical mistakes.","answer":"communication","accept":["communication"],"vi":"COMMUNICATE (giao tiếp) → communication — sự giao tiếp (danh từ)","explanation":"Từ cần điền đứng sau tính từ 'Clear' và làm chủ ngữ của động từ 'reduces' → cần DANH TỪ. communicate (động từ) → communication (danh từ, đổi đuôi -ate thành -ation)."},
  {"id":"wft-17","type":"text","cat":"adj","base":"RELY","q":"Before buying a laptop, you should check reviews to find a ___ (RELY) brand that will last for years.","answer":"reliable","accept":["reliable"],"vi":"RELY (tin cậy vào) → reliable — đáng tin cậy (tính từ)","explanation":"Từ cần điền đứng sau mạo từ 'a' và trước danh từ 'brand' → cần TÍNH TỪ. rely (động từ) → reliable (tính từ, bỏ 'y' và thêm '-iable')."},
  {"id":"wft-18","type":"text","cat":"adv","base":"EFFICIENT","q":"The factory has redesigned its production line to run more ___ (EFFICIENT) and save energy.","answer":"efficiently","accept":["efficiently"],"vi":"EFFICIENT (hiệu quả) → efficiently — một cách hiệu quả (trạng từ)","explanation":"Từ cần điền đứng sau 'more' và bổ nghĩa cho động từ 'run' (chạy theo cách nào) → cần TRẠNG TỪ. efficient (tính từ) → efficiently (trạng từ, thêm -ly)."},
  {"id":"wft-19","type":"text","cat":"verb","base":"MODERN","q":"The city council plans to ___ (MODERN) the public transport system within the next five years.","answer":"modernize","accept":["modernize","modernise"],"vi":"MODERN (hiện đại) → modernize — hiện đại hóa (động từ)","explanation":"Từ cần điền đứng ngay sau 'to' (động từ nguyên mẫu có to) và có tân ngữ 'the public transport system' theo sau → cần ĐỘNG TỪ. modern (tính từ) → modernize (động từ, thêm -ize, biến thể Anh-Anh: -ise)."},
  {"id":"wft-20","type":"text","cat":"noun","base":"MANAGE","q":"Poor time ___ (MANAGE) is one of the main reasons students feel stressed before exams.","answer":"management","accept":["management"],"vi":"MANAGE (quản lý) → management — sự quản lý (danh từ)","explanation":"Từ cần điền đứng sau cụm 'Poor time' và làm chủ ngữ của động từ 'is' → cần DANH TỪ. manage (động từ) → management (danh từ, thêm -ment)."},
  {"id":"wft-21","type":"text","cat":"adj","base":"SKILL","q":"She is a very ___ (SKILL) carpenter who has been in the trade for over twenty years.","answer":"skilled","accept":["skilled"],"vi":"SKILL (kỹ năng - danh từ) → skilled — lành nghề, có tay nghề (tính từ)","explanation":"Sau 'very' và trước danh từ 'carpenter' cần TÍNH TỪ để mô tả đặc điểm. SKILL (kỹ năng - danh từ) → skilled (thêm đuôi -ed) — lành nghề, có tay nghề."},
  {"id":"wft-22","type":"text","cat":"verb","base":"STRONG","q":"Regular exercise can ___ (STRONG) your muscles and improve your overall health.","answer":"strengthen","accept":["strengthen"],"vi":"STRONG (mạnh - tính từ) → strengthen — làm mạnh lên, củng cố (động từ)","explanation":"Sau động từ khiếm khuyết 'can' và trước tân ngữ 'your muscles' cần ĐỘNG TỪ nguyên mẫu. STRONG (mạnh - tính từ) → strengthen (thêm đuôi -en) — làm mạnh lên, củng cố."},
  {"id":"wft-23","type":"text","cat":"noun","base":"HOSPITABLE","q":"The local people are famous for their warm ___ (HOSPITABLE) towards visitors.","answer":"hospitality","accept":["hospitality"],"vi":"HOSPITABLE (hiếu khách - tính từ) → hospitality — lòng hiếu khách, sự mến khách (danh từ)","explanation":"Sau tính từ sở hữu 'their' và tính từ 'warm' cần DANH TỪ làm tân ngữ của giới từ 'for'. HOSPITABLE (hiếu khách - tính từ) → hospitality (đổi đuôi -able thành -ality) — lòng hiếu khách."},
  {"id":"wft-24","type":"text","cat":"adj","base":"FORGET","q":"Our trip to the mountains was an absolutely ___ (FORGET) experience.","answer":"unforgettable","accept":["unforgettable"],"vi":"FORGET (quên - động từ) → unforgettable — không thể quên, đáng nhớ (tính từ)","explanation":"Sau 'absolutely' và trước danh từ 'experience' cần TÍNH TỪ. FORGET (quên - động từ) → unforgettable (thêm tiền tố un- và hậu tố -able) — không thể quên, đáng nhớ."},
  {"id":"wft-25","type":"text","cat":"adv","base":"CONVENIENCE","q":"The new supermarket is ___ (CONVENIENCE) located near our house.","answer":"conveniently","accept":["conveniently"],"vi":"CONVENIENCE (sự tiện lợi - danh từ) → conveniently — một cách tiện lợi (trạng từ)","explanation":"Đứng giữa động từ 'is' và động từ phân từ 'located', bổ nghĩa cho cách thức, cần TRẠNG TỪ. CONVENIENCE (sự tiện lợi - danh từ) → conveniently (thêm đuôi -ly) — một cách tiện lợi."},
  {"id":"wft-26","type":"text","cat":"verb","base":"ACTIVE","q":"You need to press this button to ___ (ACTIVE) the alarm system.","answer":"activate","accept":["activate"],"vi":"ACTIVE (năng động, đang hoạt động - tính từ) → activate — kích hoạt (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu) và trước tân ngữ 'the alarm system' cần ĐỘNG TỪ. ACTIVE (năng động - tính từ) → activate (thêm đuôi -ate) — kích hoạt."},
  {"id":"wft-27","type":"text","cat":"noun","base":"PREDICT","q":"Nobody could make an accurate ___ (PREDICT) about the match's result.","answer":"prediction","accept":["prediction"],"vi":"PREDICT (dự đoán) → prediction — dự đoán, lời tiên đoán (danh từ)","explanation":"Sau mạo từ 'an' và tính từ 'accurate' cần DANH TỪ làm tân ngữ của 'make'. PREDICT (dự đoán - động từ) → prediction (thêm đuôi -ion) — dự đoán, lời tiên đoán."},
  {"id":"wft-28","type":"text","cat":"adv","base":"SIGNIFICANT","q":"The number of students has ___ (SIGNIFICANT) increased over the past five years.","answer":"significantly","accept":["significantly"],"vi":"SIGNIFICANT (đáng kể) → significantly — một cách đáng kể (trạng từ)","explanation":"Đứng giữa trợ động từ 'has' và động từ phân từ 'increased', bổ nghĩa mức độ, cần TRẠNG TỪ. SIGNIFICANT (đáng kể - tính từ) → significantly (thêm đuôi -ly) — một cách đáng kể."},
  {"id":"wft-29","type":"text","cat":"verb","base":"THEORY","q":"Scientists ___ (THEORY) that climate change is linked to human activities.","answer":"theorize","accept":["theorize","theorise"],"vi":"THEORY (lý thuyết) → theorize — đưa ra giả thuyết, lý luận rằng (động từ)","explanation":"Sau chủ ngữ 'Scientists', làm vị ngữ chính của câu (theo sau là mệnh đề 'that'), cần ĐỘNG TỪ. THEORY (lý thuyết - danh từ) → theorize (thêm đuôi -ize) — đưa ra giả thuyết, lý luận rằng."},
  {"id":"wft-30","type":"text","cat":"adj","base":"BEAUTY","q":"The garden looked absolutely ___ (BEAUTY) after the spring rain.","answer":"beautiful","accept":["beautiful"],"vi":"BEAUTY (vẻ đẹp - danh từ) → beautiful — đẹp (tính từ)","explanation":"Sau động từ liên kết 'looked' và trạng từ 'absolutely', bổ nghĩa cho chủ ngữ 'the garden', cần TÍNH TỪ. BEAUTY (vẻ đẹp - danh từ) → beautiful (thêm đuôi -ful) — đẹp."},
  {"id":"wft-31","type":"text","cat":"adj","base":"DRAMA","q":"The ending of the movie was so ___ (DRAMA) that everyone in the theater gasped in surprise.","answer":"dramatic","accept":["dramatic"],"vi":"DRAMA (kịch, tuồng - danh từ) → dramatic — đầy kịch tính (tính từ)","explanation":"Sau 'so' và trước mệnh đề 'that' cần TÍNH TỪ để miêu tả tính chất của sự việc (cấu trúc so + adj + that). DRAMA (danh từ) → dramatic (thêm đuôi -ic), nghĩa là đầy kịch tính."},
  {"id":"wft-32","type":"text","cat":"adv","base":"PERFECT","q":"She practiced for months and finally played the piece ___ (PERFECT) at the concert.","answer":"perfectly","accept":["perfectly"],"vi":"PERFECT (hoàn hảo - tính từ) → perfectly — một cách hoàn hảo (trạng từ)","explanation":"Từ đứng sau tân ngữ 'the piece', bổ nghĩa cho cách thức thực hiện động từ 'played', nên cần TRẠNG TỪ. PERFECT (tính từ) → perfectly (thêm đuôi -ly), nghĩa là một cách hoàn hảo."},
  {"id":"wft-33","type":"text","cat":"noun","base":"INSPIRE","q":"The volunteer's kindness was a real source of ___ (INSPIRE) for everyone in the village.","answer":"inspiration","accept":["inspiration"],"vi":"INSPIRE (truyền cảm hứng - động từ) → inspiration — nguồn cảm hứng (danh từ)","explanation":"Sau giới từ 'of' cần DANH TỪ. INSPIRE (động từ) → inspiration (thêm đuôi -ation), nghĩa là nguồn cảm hứng."},
  {"id":"wft-34","type":"text","cat":"adv","base":"FLEXIBLE","q":"In this job, you need to be able to adapt and respond ___ (FLEXIBLE) whenever the schedule suddenly changes.","answer":"flexibly","accept":["flexibly"],"vi":"FLEXIBLE (linh hoạt/dẻo dai) → flexibly — một cách linh hoạt (trạng từ)","explanation":"Từ đứng sau động từ 'respond', bổ nghĩa cho cách thức phản ứng, nên cần TRẠNG TỪ. FLEXIBLE (tính từ) → flexibly (bỏ -e, thêm -ly), nghĩa là một cách linh hoạt."},
  {"id":"wft-35","type":"text","cat":"noun","base":"MOTIVATE","q":"Without enough ___ (MOTIVATE), it is very difficult to keep studying English every day.","answer":"motivation","accept":["motivation"],"vi":"MOTIVATE (thúc đẩy, tạo động lực) → motivation — động lực (danh từ)","explanation":"Sau 'enough' cần DANH TỪ làm trung tâm cụm danh từ (enough + N). MOTIVATE (động từ) → motivation (thêm đuôi -ation), nghĩa là động lực."},
  {"id":"wft-36","type":"text","cat":"verb","base":"INTENSE","q":"Experts predict that competition among tech companies will ___ (INTENSE) sharply over the next five years.","answer":"intensify","accept":["intensify"],"vi":"INTENSE (mãnh liệt/dữ dội) → intensify — làm cho mạnh mẽ/dữ dội hơn (động từ)","explanation":"Sau trợ động từ 'will' cần ĐỘNG TỪ nguyên mẫu. INTENSE (tính từ) → intensify (thêm đuôi -ify), nghĩa là làm cho mạnh mẽ/dữ dội hơn."},
  {"id":"wft-37","type":"text","cat":"adv","base":"CONSISTENT","q":"The young player performed so ___ (CONSISTENT) during the season that fans could never tell whether he would score or fail.","answer":"inconsistently","accept":["inconsistently"],"vi":"CONSISTENT (đều đặn/nhất quán) → inconsistently — một cách thiếu đều đặn, thất thường (trạng từ, tiền tố phủ định in-)","explanation":"Từ bổ nghĩa cho động từ 'performed' nên cần TRẠNG TỪ; mệnh đề sau 'that' (fans không thể đoán được anh ấy sẽ ghi bàn hay thất bại) cho thấy phong độ THẤT THƯỜNG nên phải thêm tiền tố phủ định in-. CONSISTENT (tính từ) → inconsistently (in- + consistent + -ly), nghĩa là một cách thiếu đều đặn, thất thường."},
  {"id":"wft-38","type":"text","cat":"noun","base":"DIGEST","q":"Chewing your food slowly helps to speed up the process of ___ (DIGEST) in the body.","answer":"digestion","accept":["digestion"],"vi":"DIGEST (tiêu hóa - động từ) → digestion – sự tiêu hóa (danh từ)","explanation":"Sau giới từ 'of' cần DANH TỪ. DIGEST (động từ) → digestion (thêm đuôi -ion), nghĩa là sự tiêu hóa."},
  {"id":"wft-39","type":"text","cat":"adj","base":"HYGIENE","q":"Restaurants must keep their kitchens ___ (HYGIENE) at all times to avoid food poisoning.","answer":"hygienic","accept":["hygienic"],"vi":"HYGIENE (vệ sinh) → hygienic – hợp vệ sinh (tính từ)","explanation":"Sau tân ngữ 'kitchens' làm bổ ngữ cho động từ 'keep' (cấu trúc keep + O + adj) nên cần TÍNH TỪ. HYGIENE (danh từ) → hygienic (thêm đuôi -ic), nghĩa là hợp vệ sinh."},
  {"id":"wft-40","type":"text","cat":"verb","base":"SEASONING","q":"My mother always likes to ___ (SEASONING) the soup with a little pepper and salt before serving.","answer":"season","accept":["season"],"vi":"SEASONING (gia vị) → season – nêm gia vị (động từ)","explanation":"Sau 'to' (dấu hiệu động từ nguyên mẫu) cần ĐỘNG TỪ. SEASONING (danh từ, gia vị) → season (bỏ đuôi -ing, dùng dạng động từ gốc), nghĩa là nêm gia vị."},
  {"id":"wft-41","type":"text","cat":"adv","base":"BITTER","q":"After losing the match, he complained ___ (BITTER) about the referee's decisions.","answer":"bitterly","accept":["bitterly"],"vi":"BITTER (đắng, cay đắng) → bitterly – một cách gay gắt (trạng từ)","explanation":"Từ 'complained' là động từ, chỗ trống đứng sau nó để bổ nghĩa cho CÁCH THỨC phàn nàn nên cần TRẠNG TỪ. BITTER (tính từ) → bitterly (thêm đuôi -ly), nghĩa là một cách gay gắt, cay đắng."},
  {"id":"wft-42","type":"text","cat":"noun","base":"FASCINATE","q":"Ever since she was a child, she has had a deep ___ (FASCINATE) with outer space.","answer":"fascination","accept":["fascination"],"vi":"FASCINATE (làm say mê) → fascination — sự say mê (danh từ)","explanation":"Chỗ trống đứng sau tính từ 'deep' và trước giới từ 'with', đóng vai trò tân ngữ của động từ 'has had' nên cần DANH TỪ. FASCINATE (động từ) → fascination (thêm đuôi -ation), nghĩa là sự say mê."},
  {"id":"wft-43","type":"text","cat":"noun","base":"ENCOURAGE","q":"The coach's words of ___ (ENCOURAGE) helped the team believe in themselves.","answer":"encouragement","accept":["encouragement"],"vi":"ENCOURAGE (khích lệ) → encouragement — sự khích lệ (danh từ)","explanation":"Sau giới từ 'of' cần một DANH TỪ để tạo thành cụm cố định 'words of encouragement' (những lời khích lệ). ENCOURAGE (động từ) → encouragement (thêm đuôi -ment), nghĩa là sự khích lệ."},
  {"id":"wft-44","type":"text","cat":"noun","base":"TERRIFY","q":"The villagers ran away in ___ (TERRIFY) when they saw the fire spreading.","answer":"terror","accept":["terror"],"vi":"TERRIFY (làm kinh hoàng) → terror — nỗi kinh hoàng (danh từ)","explanation":"Sau giới từ 'in' cần DANH TỪ để tạo cụm cố định 'in terror' (trong nỗi kinh hoàng). TERRIFY (động từ) chuyển thành TERROR (danh từ tương ứng, không theo hậu tố thông thường), nghĩa là nỗi kinh hoàng."},
  {"id":"wft-45","type":"text","cat":"noun","base":"TIRE","q":"A feeling of ___ (TIRE) swept over him after the long journey.","answer":"tiredness","accept":["tiredness"],"vi":"TIRE (làm mệt) → tiredness — cảm giác mệt mỏi (danh từ)","explanation":"Chỗ trống đứng sau giới từ 'of', bổ nghĩa cho danh từ 'feeling' trong cụm chủ ngữ 'A feeling of...', nên cần DANH TỪ. TIRE (động từ) → tiredness (thêm đuôi -ness), nghĩa là cảm giác mệt mỏi."},
  {"id":"wft-46","type":"text","cat":"adj","base":"INFORM","q":"The teacher gave us a very ___ (INFORM) lecture about climate change.","answer":"informative","accept":["informative"],"vi":"INFORM (thông báo) → informative - giàu thông tin, bổ ích (tính từ)","explanation":"Chỗ trống đứng sau trạng từ 'very' và trước danh từ 'lecture' nên cần TÍNH TỪ để bổ nghĩa cho danh từ đó. INFORM (động từ) → informative (thêm đuôi -ative), nghĩa là giàu thông tin, bổ ích."},
  {"id":"wft-47","type":"text","cat":"noun","base":"POPULAR","q":"The singer's ___ (POPULAR) grew rapidly after her new song was released.","answer":"popularity","accept":["popularity"],"vi":"POPULAR (phổ biến) → popularity - sự phổ biến (danh từ)","explanation":"Chỗ trống đứng sau sở hữu cách 'singer's' và làm CHỦ NGỮ của động từ 'grew' nên cần DANH TỪ. POPULAR (tính từ) → popularity (thêm đuôi -ity), nghĩa là sự phổ biến."},
  {"id":"wft-48","type":"text","cat":"noun","base":"ADVERTISE","q":"We saw an interesting ___ (ADVERTISE) for a new smartphone on TV last night.","answer":"advertisement","accept":["advertisement"],"vi":"ADVERTISE (quảng cáo - động từ) → advertisement - mẩu quảng cáo (danh từ)","explanation":"Chỗ trống đứng sau mạo từ 'an' và tính từ 'interesting', làm tân ngữ của động từ 'saw' nên cần DANH TỪ. ADVERTISE (động từ) → advertisement (thêm đuôi -ment), nghĩa là mẩu quảng cáo."},
  {"id":"wft-49","type":"text","cat":"noun","base":"SUBSCRIBE","q":"My brother bought a monthly ___ (SUBSCRIBE) to that sports magazine.","answer":"subscription","accept":["subscription"],"vi":"SUBSCRIBE (đăng ký - động từ) → subscription - sự đăng ký (danh từ)","explanation":"Chỗ trống đứng sau mạo từ 'a' và tính từ 'monthly', làm tân ngữ của động từ 'bought' nên cần DANH TỪ. SUBSCRIBE (động từ) → subscription (đổi đuôi -e thành -tion), nghĩa là sự đăng ký."},
  {"id":"wft-50","type":"text","cat":"verb","base":"LARGE","q":"The photographer decided to ___ (LARGE) the photo so everyone could see the details.","answer":"enlarge","accept":["enlarge"],"vi":"LARGE (lớn) → enlarge – mở rộng, làm to hơn (động từ)","explanation":"Chỗ trống đứng sau 'to' (dạng nguyên mẫu, theo sau 'decided to') nên cần ĐỘNG TỪ. LARGE (tính từ) → enlarge (thêm tiền tố en-), nghĩa là mở rộng, làm to hơn."},
  {"id":"wft-51","type":"text","cat":"adj","base":"FINANCE","q":"The company is facing serious ___ (FINANCE) difficulties this year.","answer":"financial","accept":["financial"],"vi":"FINANCE (tài chính) → financial – thuộc về tài chính (tính từ)","explanation":"Vị trí: đứng ngay trước danh từ 'difficulties' (sau tính từ 'serious') nên cần TÍNH TỪ để cùng bổ nghĩa cho danh từ đó. Cấu tạo từ: finance (danh từ) → financial (thêm hậu tố -al để tạo tính từ), nghĩa là 'thuộc về tài chính'."},
  {"id":"wft-52","type":"text","cat":"adv","base":"LEGAL","q":"The contract was ___ (LEGAL) binding on all parties involved.","answer":"legally","accept":["legally"],"vi":"LEGAL (hợp pháp) → legally – một cách hợp pháp (trạng từ)","explanation":"Vị trí: đứng ngay trước tính từ 'binding' để bổ nghĩa cho tính từ đó nên cần TRẠNG TỪ. Cấu tạo từ: legal (tính từ) → legally (thêm hậu tố -ly), nghĩa 'về mặt pháp lý, một cách hợp pháp' (cụm cố định 'legally binding' = có hiệu lực pháp lý)."},
  {"id":"wft-53","type":"text","cat":"adv","base":"TRADITION","q":"___ (TRADITION), rice has been the staple food of people in this region.","answer":"traditionally","accept":["traditionally"],"vi":"TRADITION (truyền thống) → traditionally — theo truyền thống (trạng từ)","explanation":"Vị trí: đứng đầu câu, có dấu phẩy ngay sau, bổ nghĩa cho cả mệnh đề phía sau nên cần TRẠNG TỪ. Cấu tạo từ: tradition (danh từ) → traditionally (thêm hậu tố -ly), nghĩa 'theo truyền thống, xưa nay'."},
  {"id":"wft-54","type":"text","cat":"adv","base":"GRADUAL","q":"The weather is ___ (GRADUAL) improving after several days of heavy rain.","answer":"gradually","accept":["gradually"],"vi":"GRADUAL (dần dần - tính từ gốc) → gradually — một cách dần dần (trạng từ)","explanation":"Vị trí: đứng giữa trợ động từ 'is' và động từ dạng V-ing 'improving', bổ nghĩa cho động từ nên cần TRẠNG TỪ. Cấu tạo từ: gradual (tính từ) → gradually (thêm hậu tố -ly), nghĩa 'một cách dần dần, từ từ'."},
  {"id":"wft-55","type":"text","cat":"adv","base":"EVENT","q":"After months of searching, the police ___ (EVENT) found the missing documents.","answer":"eventually","accept":["eventually"],"vi":"EVENT (sự kiện) → eventually — cuối cùng, rốt cuộc (trạng từ)","explanation":"Vị trí: đứng ngay trước động từ 'found', bổ nghĩa cho hành động của động từ nên cần TRẠNG TỪ. Cấu tạo từ: event (danh từ) → eventual (tính từ, thêm hậu tố -ual) → eventually (thêm tiếp -ly để tạo trạng từ), nghĩa 'cuối cùng, rốt cuộc'."},
  {"id":"wft-56","type":"text","cat":"verb","base":"SYMBOL","q":"In many cultures, the white dove is used to ___ (SYMBOL) peace.","answer":"symbolize","accept":["symbolize","symbolise"],"vi":"SYMBOL (biểu tượng - danh từ gốc) → symbolize — tượng trưng cho (động từ)","explanation":"Vị trí: đứng ngay sau 'to' (động từ nguyên mẫu, bổ ngữ của 'is used to') nên cần ĐỘNG TỪ. Cấu tạo từ: symbol (danh từ) → symbolize (thêm hậu tố -ize để tạo động từ), nghĩa 'tượng trưng cho'. (symbolise là biến thể chính tả Anh-Anh, cũng được chấp nhận.)"},
  {"id":"wft-57","type":"text","cat":"adj","base":"SOCIETY","q":"Teenagers nowadays often face a lot of ___ (SOCIETY) pressure from their friends.","answer":"social","accept":["social"],"vi":"SOCIETY (xã hội - danh từ) → social - thuộc về xã hội (tính từ)","explanation":"Vị trí: đứng ngay trước danh từ 'pressure' nên cần TÍNH TỪ để bổ nghĩa cho danh từ đó. Cấu tạo từ: society (danh từ) → social (tính từ cùng gốc 'soci-', thêm hậu tố -al), nghĩa 'thuộc về xã hội'."},
  {"id":"wft-58","type":"text","cat":"adv","base":"FORMAL","q":"The two governments ___ (FORMAL) agreed to sign the trade agreement next week.","answer":"formally","accept":["formally"],"vi":"FORMAL (chính thức - tính từ) → formally - một cách chính thức (trạng từ)","explanation":"Vị trí: đứng ngay trước động từ 'agreed', bổ nghĩa cho động từ nên cần TRẠNG TỪ. Cấu tạo từ: formal (tính từ) → formally (thêm hậu tố -ly), nghĩa 'một cách chính thức'."},
  {"id":"wft-59","type":"text","cat":"noun","base":"ADAPT","q":"The novel's ___ (ADAPT) into a successful film surprised many critics.","answer":"adaptation","accept":["adaptation"],"vi":"ADAPT (thích nghi) → adaptation — sự chuyển thể (danh từ)","explanation":"Vị trí: đứng sau sở hữu cách 'novel's' và làm chủ ngữ của động từ 'surprised' nên cần DANH TỪ. Cấu tạo từ: adapt (động từ) → adaptation (thêm hậu tố -ation), nghĩa 'sự chuyển thể' (ở đây là việc chuyển tiểu thuyết thành phim)."},
  {"id":"wft-60","type":"text","cat":"adj","base":"POLLUTE","q":"Fish cannot survive in such a heavily ___ (POLLUTE) river.","answer":"polluted","accept":["polluted"],"vi":"POLLUTE (làm ô nhiễm) → polluted — bị ô nhiễm (tính từ)","explanation":"Vị trí: đứng sau trạng từ 'heavily' và trước danh từ 'river' nên cần TÍNH TỪ (dạng phân từ quá khứ mang nghĩa bị động, 'bị ô nhiễm'). Cấu tạo từ: pollute (động từ) → polluted (thêm hậu tố -ed), nghĩa 'bị ô nhiễm'."},
  {"id":"wft-61","type":"text","cat":"noun","base":"GENEROUS","q":"His ___ (GENEROUS) helped many poor families in the area survive the flood.","answer":"generosity","accept":["generosity"],"vi":"GENEROUS (hào phóng - tính từ) → generosity — lòng hào phóng (danh từ)","explanation":"Sau tính từ sở hữu 'His' và đóng vai trò chủ ngữ của câu (chỗ cần một sự vật/khái niệm) phải là DANH TỪ. generous → generosity (bỏ đuôi -ous, thêm đuôi -ity)."},
  {"id":"wft-62","type":"text","cat":"adj","base":"AFFECTION","q":"She gave her children a very ___ (AFFECTION) hug before they left for school.","answer":"affectionate","accept":["affectionate"],"vi":"AFFECTION (tình cảm - danh từ) → affectionate — trìu mến, yêu thương (tính từ)","explanation":"Đứng sau trạng từ 'very' và trước danh từ 'hug' cần TÍNH TỪ để bổ nghĩa cho danh từ đó. affection → affectionate (thêm đuôi -ate)."},
  {"id":"wft-63","type":"text","cat":"adv","base":"RESPECT","q":"The students listened ___ (RESPECT) while the teacher was explaining the new lesson.","answer":"respectfully","accept":["respectfully"],"vi":"RESPECT (sự tôn trọng - danh từ/động từ) → respectfully — một cách tôn trọng, lễ phép (trạng từ)","explanation":"Bổ nghĩa cho động từ 'listened' (chỉ cách thức hành động) cần TRẠNG TỪ. respect → respectful → respectfully (thêm đuôi -ful rồi -ly)."},
  {"id":"wft-64","type":"text","cat":"verb","base":"UNITY","q":"The two neighboring countries agreed to ___ (UNITY) their efforts against climate change.","answer":"unite","accept":["unite"],"vi":"UNITY (sự đoàn kết - danh từ) → unite — đoàn kết, gắn kết (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu có 'to') cần ĐỘNG TỪ. unity → unite (bỏ đuôi -ity, dùng dạng động từ gốc)."},
  {"id":"wft-65","type":"text","cat":"verb","base":"MODERN","q":"The old textile factory has been completely ___ (MODERN) with advanced machines.","answer":"modernized","accept":["modernized","modernised"],"vi":"MODERN (hiện đại - tính từ) → modernized — được hiện đại hóa (động từ, dạng bị động)","explanation":"Sau 'has been' (thì hiện tại hoàn thành, dạng bị động) cần ĐỘNG TỪ ở dạng quá khứ phân từ. modern → modernize/modernise → modernized/modernised (thêm đuôi -ize/-ise rồi -d)."},
  {"id":"wft-66","type":"text","cat":"verb","base":"BEAUTY","q":"The local authorities plan to ___ (BEAUTY) the riverside area with flowers and trees.","answer":"beautify","accept":["beautify"],"vi":"BEAUTY (vẻ đẹp - danh từ) → beautify — làm đẹp (động từ)","explanation":"Sau 'to' (động từ nguyên mẫu) cần ĐỘNG TỪ. beauty → beautify (thêm đuôi -ify)."},
  {"id":"wft-67","type":"text","cat":"verb","base":"DEVELOP","q":"Vietnam's economy has ___ (DEVELOP) rapidly over the past two decades.","answer":"developed","accept":["developed"],"vi":"DEVELOP (phát triển - động từ) → developed — đã phát triển (động từ, quá khứ phân từ)","explanation":"Sau 'has' (thì hiện tại hoàn thành) cần ĐỘNG TỪ ở dạng quá khứ phân từ. develop → developed (thêm đuôi -ed)."},
  {"id":"wft-68","type":"text","cat":"verb","base":"PREVENTION","q":"Wearing a helmet can ___ (PREVENTION) serious head injuries in traffic accidents.","answer":"prevent","accept":["prevent"],"vi":"PREVENTION (sự phòng ngừa) → prevent — ngăn ngừa, phòng tránh (động từ)","explanation":"Sau động từ khuyết thiếu 'can' cần ĐỘNG TỪ nguyên mẫu (không 'to'). prevention → prevent (bỏ đuôi -ion, dùng dạng động từ gốc)."},
  {"id":"wft-69","type":"text","cat":"noun","base":"SURVIVE","q":"Clean water and food are essential for the ___ (SURVIVE) of wild animals in the forest.","answer":"survival","accept":["survival"],"vi":"SURVIVE (sống sót - động từ) → survival — sự sống sót (danh từ)","explanation":"Sau mạo từ 'the' và làm tân ngữ của giới từ 'for' cần DANH TỪ. survive → survival (bỏ 'e', thêm đuôi -al)."},
  {"id":"wft-70","type":"text","cat":"adv","base":"GUARD","q":"He answered the journalist's questions rather ___ (GUARD), avoiding anything controversial.","answer":"guardedly","accept":["guardedly"],"vi":"GUARD (canh gác, bảo vệ) → guardedly — một cách thận trọng, dè dặt (trạng từ)","explanation":"Bổ nghĩa cho động từ 'answered' (chỉ cách thức trả lời) cần TRẠNG TỪ. guard → guarded → guardedly (thêm đuôi -ed rồi -ly)."},
  {"id":"wft-71","type":"text","cat":"adj","base":"AMBITION","q":"He is a very ___ (AMBITION) young man who dreams of becoming a CEO one day.","answer":"ambitious","accept":["ambitious"],"vi":"AMBITION (tham vọng, hoài bão) → ambitious — đầy tham vọng, hoài bão (tính từ)","explanation":"Trước danh từ 'young man' (và sau trạng từ 'very') cần TÍNH TỪ để bổ nghĩa cho danh từ. ambition (danh từ: tham vọng) → ambitious (thêm hậu tố -ous: đầy tham vọng)."},
  {"id":"wft-72","type":"text","cat":"adj","base":"COURAGE","q":"The soldier performed a ___ (COURAGE) act by rescuing his friend from the burning building.","answer":"courageous","accept":["courageous"],"vi":"COURAGE (lòng can đảm) → courageous — can đảm, dũng cảm (tính từ)","explanation":"Sau mạo từ 'a' và trước danh từ 'act' cần TÍNH TỪ để bổ nghĩa cho danh từ đó. courage (danh từ: lòng can đảm) → courageous (thêm hậu tố -ous: can đảm, dũng cảm)."},
  {"id":"wft-73","type":"text","cat":"verb","base":"GLORY","q":"Many war movies tend to ___ (GLORY) violence instead of showing its true horrors.","answer":"glorify","accept":["glorify"],"vi":"GLORY (vinh quang) → glorify — tôn vinh, ca ngợi (động từ)","explanation":"Sau 'to' trong cấu trúc 'tend to + V (nguyên mẫu)' cần một ĐỘNG TỪ. glory (danh từ: vinh quang) → glorify (thêm hậu tố -ify: tôn vinh, ca ngợi)."},
  {"id":"wft-74","type":"text","cat":"adj","base":"SATISFY","q":"Many customers were completely ___ (SATISFY) with the slow service at the restaurant.","answer":"dissatisfied","accept":["dissatisfied"],"vi":"SATISFY (làm hài lòng) → dissatisfied — không hài lòng (tính từ, thêm dis-)","explanation":"Sau động từ 'to be' (were) và bổ nghĩa cho chủ ngữ 'customers' cần TÍNH TỪ. satisfy (động từ: làm hài lòng) → dissatisfied (thêm tiền tố dis- và hậu tố -ed: không hài lòng)."},
  {"id":"wft-75","type":"text","cat":"noun","base":"APPEAR","q":"Her sudden ___ (APPEAR) at the meeting surprised everyone in the room.","answer":"appearance","accept":["appearance"],"vi":"APPEAR (trông có vẻ - động từ) → appearance — vẻ ngoài, diện mạo (danh từ)","explanation":"Đứng sau tính từ sở hữu 'Her' và tính từ 'sudden', đóng vai trò chủ ngữ của câu, nên cần DANH TỪ. appear (động từ: xuất hiện) → appearance (thêm hậu tố -ance: sự xuất hiện)."},
  {"id":"wft-76","type":"text","cat":"adv","base":"COMPARE","q":"This new smartphone is ___ (COMPARE) cheaper than last year's flagship model.","answer":"comparatively","accept":["comparatively"],"vi":"COMPARE (so sánh - động từ) → comparatively — tương đối, so ra thì (trạng từ)","explanation":"Bổ nghĩa cho tính từ so sánh 'cheaper' cần TRẠNG TỪ. compare (động từ: so sánh) → comparatively (thêm hậu tố -ly: tương đối, so ra thì)."},
  {"id":"wft-77","type":"text","cat":"noun","base":"ELECT","q":"The presidential ___ (ELECT) will be held early next year.","answer":"election","accept":["election"],"vi":"ELECT (bầu cử - động từ) → election — cuộc bầu cử (danh từ)","explanation":"Sau tính từ 'presidential' và làm chủ ngữ của câu (trước 'will be held') cần DANH TỪ. elect (động từ: bầu cử) → election (thêm hậu tố -ion: cuộc bầu cử)."},
  {"id":"wft-78","type":"text","cat":"noun","base":"ENFORCE","q":"Strict ___ (ENFORCE) of traffic laws has helped reduce accidents in the city.","answer":"enforcement","accept":["enforcement"],"vi":"ENFORCE (thực thi - động từ) → enforcement — sự thực thi (danh từ)","explanation":"Sau tính từ 'Strict' và làm chủ ngữ của câu cần DANH TỪ. enforce (động từ: thực thi) → enforcement (thêm hậu tố -ment: sự thực thi)."},
  {"id":"wft-79","type":"text","cat":"adj","base":"GOVERN","q":"The new education policy was approved by a ___ (GOVERN) committee last week.","answer":"governmental","accept":["governmental"],"vi":"GOVERN (cai trị/quản lý - động từ) → governmental — thuộc về chính phủ (tính từ)","explanation":"Trước danh từ 'committee' (sau mạo từ 'a') cần TÍNH TỪ để bổ nghĩa cho danh từ đó. govern (động từ: cai trị, quản lý) → governmental (thêm hậu tố -al: thuộc về chính phủ)."},
  {"id":"wft-80","type":"text","cat":"adv","base":"OFFICIAL","q":"The new school year will ___ (OFFICIAL) begin next Monday.","answer":"officially","accept":["officially"],"vi":"OFFICIAL (chính thức - tính từ) → officially — một cách chính thức (trạng từ)","explanation":"Đứng giữa trợ động từ 'will' và động từ chính 'begin', bổ nghĩa cho động từ, cần TRẠNG TỪ. official (tính từ: chính thức) → officially (thêm hậu tố -ly: một cách chính thức)."},
  {"id":"wft-81","type":"text","cat":"verb","base":"CRIMINAL","q":"The government plans to ___ (CRIMINAL) the possession of illegal weapons.","answer":"criminalize","accept":["criminalize","criminalise"],"vi":"CRIMINAL (thuộc về tội phạm - tính từ) → criminalize — hình sự hóa (động từ)","explanation":"Sau \"to\" (động từ nguyên mẫu, sau động từ \"plans\") cần ĐỘNG TỪ làm tân ngữ hành động. criminal → criminalize (thêm hậu tố -ize để tạo động từ nghĩa \"hình sự hóa\")."},
  {"id":"wft-82","type":"text","cat":"noun","base":"CONVENIENT","q":"For the ___ (CONVENIENT) of all passengers, the airport now provides free Wi-Fi in every terminal.","answer":"convenience","accept":["convenience"],"vi":"CONVENIENT (thuận tiện - tính từ) → convenience - sự thuận tiện (danh từ)","explanation":"Sau giới từ \"for\" và mạo từ \"the\" cần DANH TỪ (làm tân ngữ của giới từ). convenient → convenience (bỏ đuôi tính từ -ent, thêm -ence để tạo danh từ \"sự thuận tiện\")."},
  {"id":"wft-83","type":"text","cat":"adv","base":"SMOOTH","q":"The new manager explained the plan so clearly that the meeting went ___ (SMOOTH).","answer":"smoothly","accept":["smoothly"],"vi":"SMOOTH (êm, trơn tru - tính từ) → smoothly - một cách êm ả, trôi chảy (trạng từ)","explanation":"Bổ nghĩa cho động từ \"went\" (diễn tả cách thức sự việc diễn ra) cần TRẠNG TỪ. smooth → smoothly (thêm hậu tố -ly để tạo trạng từ \"một cách êm ả, trôi chảy\")."},
  {"id":"wft-84","type":"text","cat":"noun","base":"TRANSLATE","q":"Her ___ (TRANSLATE) of the ancient poem was praised by critics around the world.","answer":"translation","accept":["translation"],"vi":"TRANSLATE (dịch) → translation — sự dịch thuật (danh từ)","explanation":"Sau tính từ sở hữu \"Her\" cần DANH TỪ làm chủ ngữ của câu. translate → translation (thêm hậu tố -ion để tạo danh từ \"sự dịch thuật, bản dịch\")."},
  {"id":"wft-85","type":"text","cat":"adv","base":"EDUCATE","q":"The charity focuses on helping children who are ___ (EDUCATE) disadvantaged gain access to books.","answer":"educationally","accept":["educationally"],"vi":"EDUCATE (giáo dục) → educationally — về mặt giáo dục (trạng từ)","explanation":"Bổ nghĩa cho tính từ \"disadvantaged\" cần TRẠNG TỪ. educate → educational → educationally (thêm hậu tố -ly để tạo trạng từ \"về mặt giáo dục\")."},
  {"id":"wft-86","type":"text","cat":"verb","base":"EMPHASIS","q":"In her speech, the principal wanted to ___ (EMPHASIS) the value of honesty.","answer":"emphasize","accept":["emphasize","emphasise"],"vi":"EMPHASIS (sự nhấn mạnh) → emphasize — nhấn mạnh (động từ)","explanation":"Sau \"to\" (động từ nguyên mẫu, sau động từ \"wanted\") cần ĐỘNG TỪ có tân ngữ đi kèm. emphasis → emphasize (đổi đuôi danh từ -is thành -ize để tạo động từ \"nhấn mạnh\")."},
  {"id":"wft-87","type":"text","cat":"adj","base":"ENJOY","q":"The trip to the mountains was one of the most ___ (ENJOY) experiences of my childhood.","answer":"enjoyable","accept":["enjoyable"],"vi":"ENJOY (thích, tận hưởng - động từ) → enjoyable - thú vị, đáng tận hưởng (tính từ)","explanation":"Đứng trước danh từ \"experiences\" (sau \"most\") cần TÍNH TỪ. enjoy → enjoyable (thêm hậu tố -able để tạo tính từ \"thú vị, đáng tận hưởng\")."},
  {"id":"wft-88","type":"text","cat":"noun","base":"PERFORM","q":"Critics said the young actor's ___ (PERFORM) in the final scene was unforgettable.","answer":"performance","accept":["performance"],"vi":"PERFORM (biểu diễn - động từ) → performance - buổi biểu diễn, sự thể hiện (danh từ)","explanation":"Sau tính từ sở hữu \"actor's\" cần DANH TỪ làm chủ ngữ của mệnh đề. perform → performance (thêm hậu tố -ance để tạo danh từ \"buổi biểu diễn, sự thể hiện\")."},
  {"id":"wft-89","type":"text","cat":"adv","base":"ADMIRE","q":"The coach smiled ___ (ADMIRE) as his students crossed the finish line together.","answer":"admiringly","accept":["admiringly"],"vi":"ADMIRE (ngưỡng mộ - động từ) → admiringly - với vẻ ngưỡng mộ (trạng từ)","explanation":"Bổ nghĩa cho động từ \"smiled\" cần TRẠNG TỪ. admire → admiring → admiringly (thêm hậu tố -ly để tạo trạng từ \"với vẻ ngưỡng mộ\")."},
  {"id":"wft-90","type":"text","cat":"adv","base":"TOLERANT","q":"Even when the child made mistakes, the teacher responded ___ (TOLERANT) and calmly.","answer":"tolerantly","accept":["tolerantly"],"vi":"TOLERANT (khoan dung - tính từ) → tolerantly — một cách khoan dung (trạng từ)","explanation":"Bổ nghĩa cho động từ \"responded\", song song với trạng từ \"calmly\", cần TRẠNG TỪ. tolerant → tolerantly (thêm hậu tố -ly để tạo trạng từ \"một cách khoan dung\")."},
  {"id":"wft-91","type":"text","cat":"noun","base":"DEVOTE","q":"Her ___ (DEVOTE) to helping poor children has inspired many people in the village.","answer":"devotion","accept":["devotion"],"vi":"DEVOTE (cống hiến - động từ) → devotion — sự tận tụy, cống hiến (danh từ)","explanation":"Sau tính từ sở hữu 'Her' và trước giới từ 'to' cần DANH TỪ làm chủ ngữ của câu. devote (động từ) → devotion (thêm hậu tố -ion) — sự cống hiến, tận tụy."},
  {"id":"wft-92","type":"text","cat":"noun","base":"ENERGETIC","q":"Solar panels convert sunlight into ___ (ENERGETIC) that we can use at home.","answer":"energy","accept":["energy"],"vi":"ENERGETIC (tràn đầy năng lượng - tính từ) → energy — năng lượng (danh từ)","explanation":"Sau giới từ 'into' cần DANH TỪ làm tân ngữ. energetic (tính từ) → energy (bỏ hậu tố tính từ, dùng danh từ gốc) — năng lượng."},
  {"id":"wft-93","type":"text","cat":"adj","base":"FORGIVE","q":"My grandmother is a very ___ (FORGIVE) person who never holds a grudge against anyone.","answer":"forgiving","accept":["forgiving"],"vi":"FORGIVE (tha thứ - động từ) → forgiving — có lòng khoan dung (tính từ)","explanation":"Sau trạng từ 'very' và trước danh từ 'person' cần TÍNH TỪ bổ nghĩa cho danh từ đó. forgive (động từ) → forgiving (thêm hậu tố -ing) — có lòng khoan dung."},
  {"id":"wft-94","type":"text","cat":"noun","base":"FLEXIBLE","q":"The new work schedule offers employees a great deal of ___ (FLEXIBLE) in choosing their working hours.","answer":"flexibility","accept":["flexibility"],"vi":"FLEXIBLE (linh hoạt - tính từ) → flexibility — sự linh hoạt (danh từ)","explanation":"Sau cụm 'a great deal of' (một lượng lớn) cần DANH TỪ. flexible (tính từ) → flexibility (đổi đuôi -ible thành -ibility) — sự linh hoạt."},
  {"id":"wft-95","type":"text","cat":"adj","base":"DESCRIBE","q":"The travel writer is famous for her ___ (DESCRIBE) style, which brings every scene to life.","answer":"descriptive","accept":["descriptive"],"vi":"DESCRIBE (miêu tả - động từ) → descriptive — mang tính miêu tả (tính từ)","explanation":"Sau tính từ sở hữu 'her' và trước danh từ 'style' cần TÍNH TỪ bổ nghĩa cho 'style'. describe (động từ) → descriptive (thêm hậu tố -ive) — mang tính miêu tả."},
  {"id":"wft-96","type":"text","cat":"noun","base":"EVALUATE","q":"Teachers carry out a careful ___ (EVALUATE) of each student's progress at the end of the term.","answer":"evaluation","accept":["evaluation"],"vi":"EVALUATE (đánh giá - động từ) → evaluation — sự đánh giá (danh từ)","explanation":"Sau tính từ 'careful' và trước giới từ 'of' cần DANH TỪ (tân ngữ của 'carry out'). evaluate (động từ) → evaluation (thêm hậu tố -ion) — sự đánh giá."},
  {"id":"wft-97","type":"text","cat":"noun","base":"PRODUCE","q":"The factory has increased its ___ (PRODUCE) of electric cars over the past two years.","answer":"production","accept":["production"],"vi":"PRODUCE (sản xuất - động từ) → production — sự sản xuất (danh từ)","explanation":"Sau tính từ sở hữu 'its' cần DANH TỪ làm tân ngữ của 'increased'. produce (động từ) → production (thêm hậu tố -tion) — sự sản xuất."},
  {"id":"wft-98","type":"text","cat":"noun","base":"INVESTIGATE","q":"The police launched a thorough ___ (INVESTIGATE) into the mysterious disappearance of the jewels.","answer":"investigation","accept":["investigation"],"vi":"INVESTIGATE (điều tra - động từ) → investigation — cuộc điều tra (danh từ)","explanation":"Sau tính từ 'thorough' và trước giới từ 'into' cần DANH TỪ (tân ngữ của 'launched'). investigate (động từ) → investigation (thêm hậu tố -ion) — cuộc điều tra."},
  {"id":"wft-99","type":"text","cat":"noun","base":"INTENSE","q":"Scientists were surprised by the ___ (INTENSE) of the storm that hit the coast last night.","answer":"intensity","accept":["intensity"],"vi":"INTENSE (mãnh liệt - tính từ) → intensity — cường độ (danh từ)","explanation":"Sau mạo từ 'the' và trước giới từ 'of' cần DANH TỪ. intense (tính từ) → intensity (đổi đuôi -e thành -ity) — cường độ."},
  {"id":"wft-100","type":"text","cat":"adj","base":"BENEFIT","q":"Regular exercise is extremely ___ (BENEFIT) to both physical and mental health.","answer":"beneficial","accept":["beneficial"],"vi":"BENEFIT (lợi ích) → beneficial — có lợi (tính từ)","explanation":"Sau động từ liên kết 'is' (và trạng từ 'extremely') cần TÍNH TỪ làm vị ngữ. benefit (danh từ/động từ) → beneficial (thêm hậu tố -ial) — có lợi."}
];

if (typeof module !== 'undefined' && module.exports) { module.exports = { WORDFORM_QUESTIONS }; }
